    #region Interfaces
    ///////////////////////////////////////////////////////////////////////////////
    // ISubscriber methods
    public void Notify(Subject subject, FileSystemEventArgs e)
    {
        try
        {
            if (m_subscriber_delegate == null)
            {
                m_subscriber_delegate = new SubscriberDelegate(SubscriberDelegateMethod);
            }

            if (this.InvokeRequired)
            {
                this.BeginInvoke(m_subscriber_delegate, new object[] { subject, e });
            }
            else
            {
                m_subscriber_delegate(subject, e);
            }
        }
        catch
        {
            // handle exception later ... }
        }
    }
    private SubscriberDelegate m_subscriber_delegate = null;
    private delegate void SubscriberDelegate(Subject subject, FileSystemEventArgs e);
    private void SubscriberDelegateMethod(Subject subject, FileSystemEventArgs e)
    {
        if (m_client != null)
        {
            switch (subject)
            {
                case Subject.LanguageSystem:
                    {
                        if (Directory.Exists(Globals.LANGUAGES_FOLDER))
                        {
                            string l_backup = l;
                            LoadLanguageNames(Globals.LANGUAGES_FOLDER);
                            PopulateLanguageComboBox();
                            l = l_backup;

                            if (L != null)
                            {
                                L.Clear();
                                LoadLanguage(l);

                                if (m_english_to_native_language_names != null)
                                {
                                    string english_language_name = l;
                                    string english_native_language_name = null;
                                    if (m_english_to_native_language_names.ContainsKey(english_language_name))
                                    {
                                        string native_name = m_english_to_native_language_names[english_language_name];
                                        english_native_language_name = english_language_name + LANGUAGE_SEPARATOR + native_name;
                                    }
                                    else
                                    {
                                        english_native_language_name = DEFAULT_LANGUAGE + LANGUAGE_SEPARATOR + DEFAULT_LANGUAGE;
                                    }
                                    if (this.LanguageComboBox.Items.Contains(english_native_language_name))
                                    {
                                        this.LanguageComboBox.SelectedItem = english_native_language_name;
                                    }
                                }
                            }

                            // stop watching files for changeds AFTER they are closed
                            // but there is no event for file closed/closing
                            //m_client.UnwatchFolder(Globals.LANGUAGES_FOLDER, "*.txt");
                        }
                    }
                    break;
                case Subject.SimplificationSystem:
                    {
                        if (Directory.Exists(Globals.RULES_FOLDER))
                        {
                            if (TextModeComboBox.SelectedItem != null)
                            {
                                string text_mode_backup = TextModeComboBox.SelectedItem.ToString();
                                PopulateTextModeComboBox();
                                if (TextModeComboBox.Items.Contains(text_mode_backup))
                                {
                                    TextModeComboBox.SelectedItem = text_mode_backup;
                                }
                                else
                                {
                                    if (TextModeComboBox.Items.Count > 0)
                                    {
                                        TextModeComboBox.SelectedIndex = 0;
                                    }
                                    else
                                    {
                                        MessageBox.Show(L[l]["Add"] + " " + L[l]["Letter simplification system"], Application.ProductName);
                                    }
                                }
                            }

                            // stop watching files for changeds AFTER they are closed
                            // but there is no event for file closed/closing
                            //m_client.UnwatchFolder(Globals.RULES_FOLDER, "*.txt");
                        }
                    }
                    break;
                case Subject.NumerologySystem:
                    {
                        if (Directory.Exists(Globals.VALUES_FOLDER))
                        {
                            //PopulateNumerologySystemComboBox();
                            NumerologySystemComboBox_SelectedIndexChanged(null, null);

                            // stop watching files for changeds AFTER they are closed
                            // but there is no event for file closed/closing
                            //m_client.UnwatchFolder(Globals.VALUES_FOLDER, "*.txt");
                        }
                    }
                    break;
                case Subject.DNASequenceSystem:
                    {
                        if (Directory.Exists(Globals.VALUES_FOLDER))
                        {
                            //PopulateNumerologySystemComboBox();
                            DNASequenceSystemComboBox_SelectedIndexChanged(null, null);

                            // stop watching files for changeds AFTER they are closed
                            // but there is no event for file closed/closing
                            //m_client.UnwatchFolder(Globals.VALUES_FOLDER, "*DNA.txt");
                        }
                    }
                    break;
                case Subject.InterestingNumbers:
                    {
                        if (Directory.Exists(Globals.NUMBERS_FOLDER))
                        {
                            UpdateBackColors();

                            // stop watching files for changeds AFTER they are closed
                            // but there is no event for file closed/closing
                            //m_client.UnwatchFolder(Globals.NUMBERS_FOLDER, Globals.INTERESTING_NUMBERS_FILENAME);
                        }
                    }
                    break;
                default:
                    break;
            }
        }
    }
