    private Dictionary<string, string> m_english_to_native_language_names = new Dictionary<string, string>();
    private void LoadNativeLanguageNames(string english_language_name)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (Directory.Exists(Globals.LANGUAGES_FOLDER))
            {
                if (m_english_to_native_language_names != null)
                {
                    m_english_to_native_language_names.Clear();

                    string path = Globals.LANGUAGES_FOLDER + Path.DirectorySeparatorChar + english_language_name + ".txt";
                    List<string> lines = FileHelper.LoadLines(path);
                    if (lines.Count > 0)
                    {
                        foreach (string line in lines)
                        {
                            string[] parts = line.Split('\t');
                            if (parts.Length == 2)
                            {
                                if ((parts[0].Length > 0) && (parts[1].Length > 0))
                                {
                                    m_english_to_native_language_names.Add(parts[0], parts[1]);
                                }
                            }
                        }
                    }
                    else
                    {
                        path = Globals.LANGUAGES_FOLDER + Path.DirectorySeparatorChar + DEFAULT_LANGUAGE + ".txt";
                        if (File.Exists(path))
                        {
                            LoadLanguage(DEFAULT_LANGUAGE);
                        }
                        else
                        {
                            MessageBox.Show("File not found " + path, Application.ProductName);
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private Dictionary<string, Dictionary<string, string>> L = new Dictionary<string, Dictionary<string, string>>();
    private string l = DEFAULT_LANGUAGE;
    private string previous_l = String.Empty;
    private List<string> m_english_language_names = new List<string>();
    private void InstallLanguages()
    {
        if (Directory.Exists(Globals.LANGUAGES_FOLDER))
        {
            LoadLanguageNames(Globals.LANGUAGES_FOLDER);
            PopulateLanguageComboBox();

            foreach (string english_language_name in m_english_language_names)
            {
                LoadLanguage(english_language_name);
            }
        }
    }
    private void LoadLanguageNames(string languages_folder)
    {
        if (m_english_language_names != null)
        {
            m_english_language_names.Clear();

            DirectoryInfo folder = new DirectoryInfo(languages_folder);
            if (folder != null)
            {
                FileInfo[] files = folder.GetFiles("*.txt");
                if ((files != null) && (files.Length > 0))
                {
                    foreach (FileInfo file in files)
                    {
                        if (!String.IsNullOrEmpty(file.Name))
                        {
                            int pos = file.Name.IndexOf(file.Extension);
                            if (pos > -1)
                            {
                                string english_language_name = file.Name.Remove(pos);
                                if (!String.IsNullOrEmpty(english_language_name))
                                {
                                    if (english_language_name == "metadata")
                                    {
                                        LoadNativeLanguageNames(english_language_name);
                                    }
                                    else
                                    {
                                        m_english_language_names.Add(english_language_name);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    private void PopulateLanguageComboBox()
    {
        try
        {
            for (int i = 0; i < 3; i++)
                LanguageComboBox.SelectedIndexChanged -= new System.EventHandler(LanguageComboBox_SelectedIndexChanged);
            LanguageComboBox.BeginUpdate();
            LanguageComboBox.Sorted = true;

            if (m_english_language_names != null)
            {
                if (m_english_to_native_language_names != null)
                {
                    LanguageComboBox.Items.Clear();
                    foreach (string english_language_name in m_english_language_names)
                    {
                        if (m_english_to_native_language_names.ContainsKey(english_language_name))
                        {
                            string native_labguage_name = m_english_to_native_language_names[english_language_name];
                            LanguageComboBox.Items.Add(english_language_name + LANGUAGE_SEPARATOR + native_labguage_name);
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            LanguageComboBox.EndUpdate();
            LanguageComboBox.SelectedIndexChanged += new System.EventHandler(LanguageComboBox_SelectedIndexChanged);
        }
    }
    private void LanguageComboBox_SelectedIndexChanged(object sender, EventArgs e)
    {
        if (LanguageComboBox.SelectedIndex > -1)
        {
            string item = LanguageComboBox.SelectedItem.ToString();
            int index = item.IndexOf(LANGUAGE_SEPARATOR);
            if (index > -1)
            {
                previous_l = l;
                l = item.Substring(0, index);
                if (!String.IsNullOrEmpty(l))
                {
                    string flags_folder = Globals.LANGUAGES_FOLDER + Path.DirectorySeparatorChar + "Flags";
                    LanguageLabel.Image = new Bitmap(flags_folder + Path.DirectorySeparatorChar + l + ".png");
                    LoadLanguage(l);
                    WordPartGrammar.Language = L[l];
                }
            }
        }
    }
    private void LoadLanguage(string english_language_name)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (Directory.Exists(Globals.LANGUAGES_FOLDER))
            {
                if (L != null)
                {
                    if (m_english_to_native_language_names != null)
                    {
                        string english_native_language_name = null;
                        if (m_english_to_native_language_names.ContainsKey(english_language_name))
                        {
                            string native_name = m_english_to_native_language_names[english_language_name];
                            english_native_language_name = english_language_name + LANGUAGE_SEPARATOR + native_name;
                        }
                        else
                        {
                            english_native_language_name = DEFAULT_LANGUAGE + LANGUAGE_SEPARATOR + DEFAULT_LANGUAGE;
                        }
                    }

                    Dictionary<string, string> language_entries = new Dictionary<string, string>();
                    List<Control> controls = GetDescendentControls(this);

                    string path = Globals.LANGUAGES_FOLDER + Path.DirectorySeparatorChar + english_language_name + ".txt";
                    List<string> lines = FileHelper.LoadLines(path);
                    if (lines.Count > 0)
                    {
                        foreach (string line in lines)
                        {
                            string[] parts = line.Split('\t');
                            if (parts.Length >= 2)
                            {
                                if (parts[0] == "Dictionary")
                                {
                                    if (parts.Length > 2)
                                    {
                                        if ((parts[1].Length > 0) && (parts[2].Length > 0))
                                        {
                                            if (!language_entries.ContainsKey(parts[1]))
                                            {
                                                language_entries.Add(parts[1], parts[2]);
                                            }
                                        }
                                    }
                                }
                                else
                                {
                                    foreach (Control control in controls)
                                    {
                                        if (parts[0] == control.Name)
                                        {
                                            // set Text
                                            if (parts.Length > 2)
                                            {
                                                if (parts[2].Length > 0)
                                                {
                                                    control.Text = parts[2];
                                                }
                                            }

                                            // set ToolTip
                                            if (parts.Length > 4)
                                            {
                                                if (parts[4].Length > 0)
                                                {
                                                    if (control is TabPage)
                                                    {
                                                        (control as TabPage).ToolTipText = parts[4];
                                                    }
                                                    else
                                                    {
                                                        ToolTip.SetToolTip(control, parts[4]);
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }

                        if (L.ContainsKey(english_language_name))
                        {
                            L[english_language_name] = language_entries;
                        }
                        else
                        {
                            L.Add(english_language_name, language_entries);
                        }
                        previous_l = english_language_name;
                        l = english_language_name;
                        //ToolTip.SetToolTip(this.LanguageLabel, L[l]["Edit"]); // moved to LanguageLabel_MouseHover

                        UpdateHeaderLabel();
                        PopulateChaptersListBox();
                        DisplayChapterRevelationInfo();


                        ToolTip.SetToolTip(this.UserRatioPresetLabel, L[l]["Default ratio"]);
                        UpdateUserRatioScopeLabel();
                        UpdateUserRatioDelimiterLabel();
                        UpdateUserRatioTypeLabel();

                        UpdateFindByNumbersResultType();
                        UpdateDistancesOptions();
                        foreach (Control control in controls)
                        {
                            if (control.Name.Contains("ComparisonOperator"))
                            {
                                if (control.Text.Length > 0)
                                {
                                    ToolTip.SetToolTip(control, L[l][control.Text]);
                                }
                            }
                            else if (control.Name.Contains("NumberType"))
                            {
                                if (control.Text.Length > 0)
                                {
                                    int remainder;
                                    if (int.TryParse(control.Text, out remainder))
                                    {
                                        ToolTip.SetToolTip(control, L[l]["remainder"]);
                                    }
                                    else
                                    {
                                        ToolTip.SetToolTip(control, L[l][control.Text]);
                                    }
                                }
                            }
                        }

                        if (m_client != null)
                        {
                            ToolTip.SetToolTip(this.CalculationModeLabel, L[l][m_client.CalculationMode.ToString()]);
                        }

                        ToolTip.SetToolTip(this.NumberKindIndexTextBox, L[l][m_number_kind.ToString() + " number index"]);
                        if (ChapterSortComboBox.SelectedItem != null)
                            ToolTip.SetToolTip(this.ChapterSortComboBox, L[l][ChapterSortComboBox.SelectedItem.ToString()]);
                        ToolTip.SetToolTip(this.ChapterSortLabel, L[l][Chapter.CompareOrder.ToString()]);

                        if (ChapterSelectionComboBox.SelectedItem != null)
                        {
                            ToolTip.SetToolTip(this.ChapterSelectionComboBox, L[l][(m_chapter_selection.ToString() + " " + "chapter" +
                                (((m_chapter_selection.ToString() == "Any") || (m_chapter_selection.ToString() == "Key")) ? "" : "s"))]);
                        }

                        if (m_found_verses_displayed)
                        {
                            if (m_word_wrap_search_textbox)
                            {
                                ToolTip.SetToolTip(this.WordWrapLabel, L[l]["Unwrap"]);
                            }
                            else
                            {
                                ToolTip.SetToolTip(this.WordWrapLabel, L[l]["Wrap"]);
                            }
                        }
                        else
                        {
                            if (m_word_wrap_main_textbox)
                            {
                                ToolTip.SetToolTip(this.WordWrapLabel, L[l]["Unwrap"]);
                            }
                            else
                            {
                                ToolTip.SetToolTip(this.WordWrapLabel, L[l]["Wrap"]);
                            }
                        }

                        if (m_word_wrap_translation_textbox)
                        {
                            ToolTip.SetToolTip(this.TranslationWordWrapLabel, L[l]["Unwrap"]);
                        }
                        else
                        {
                            ToolTip.SetToolTip(this.TranslationWordWrapLabel, L[l]["Wrap"]);
                        }

                        if (m_find_by_phrase_letter_frequency)
                        {
                            ToolTip.SetToolTip(this.LetterFrequencyPositionSumLabel, L[l]["<-- letter frequency concatenation"]);
                            ToolTip.SetToolTip(this.LetterFrequencyDistanceSumLabel, L[l]["--> letter frequency concatenation"]);
                        }
                        else
                        {
                            ToolTip.SetToolTip(this.LetterFrequencyPositionSumLabel, L[l]["Sum of letter position sums"]);
                            ToolTip.SetToolTip(this.LetterFrequencyDistanceSumLabel, L[l]["Sum of letter distance sums"]);
                        }

                        if (m_include_diacritics == true)
                        {
                            ToolTip.SetToolTip(this.LetterFrequencyWithDiacriticsCheckBox, L[l]["with diacritics"]);
                        }
                        else if (m_include_diacritics == null)
                        {
                            ToolTip.SetToolTip(this.LetterFrequencyWithDiacriticsCheckBox, L[l]["diacritics only"]);
                        }
                        else if (m_include_diacritics == false)
                        {
                            ToolTip.SetToolTip(this.LetterFrequencyWithDiacriticsCheckBox, L[l]["no diacritics"]);
                        }

                        int pos = ValueLabel.Text.IndexOf(" ");
                        string text = ValueLabel.Text.Substring(pos + 1).Trim();
                        if (L[l].ContainsKey(text))
                        {
                            text = L[l][text];
                        }
                        else // reverse dictionary
                        {
                            foreach (string key in L[l].Keys)
                            {
                                if (L[previous_l].ContainsKey(key))
                                {
                                    if (text == L[previous_l][key])
                                    {
                                        text = L[l][key];
                                        break;
                                    }
                                }
                            }
                        }
                        if (m_show_add_controls)
                        {
                            //ValueLabel.Text = "-- " + text;
                            ValueLabel.Text = "-- " + L[l]["Value"];
                            ToolTip.SetToolTip(this.ValueLabel, L[l]["Hide value-added positions and distances"]);
                        }
                        else
                        {
                            //ValueLabel.Text = "+ " + text;
                            ValueLabel.Text = "+ " + L[l]["Value"];
                            ToolTip.SetToolTip(this.ValueLabel, L[l]["Show value-added positions and distances"]);
                        }

                        if (m_client != null)
                        {
                            if (m_client.NumerologySystem != null)
                            {
                                ToolTip.SetToolTip(this.AddToLetterLNumberCheckBox, L[l]["Add letter number in word to letter value"]);
                                ToolTip.SetToolTip(this.AddToLetterWNumberCheckBox, (m_client.NumerologySystem.AbsolutePositions) ? L[l]["Add letter number in verse to letter value"] : L[l]["Add word number in verse to letter value"]);
                                ToolTip.SetToolTip(this.AddToLetterVNumberCheckBox, (m_client.NumerologySystem.AbsolutePositions) ? L[l]["Add letter number in chapter to letter value"] : L[l]["Add verse number in chapter to letter value"]);
                                ToolTip.SetToolTip(this.AddToLetterCNumberCheckBox, (m_client.NumerologySystem.AbsolutePositions) ? L[l]["Add letter number in book to letter value"] : L[l]["Add chapter number in book to letter value"]);
                                ToolTip.SetToolTip(this.AddToLetterLDistanceCheckBox, L[l]["Add the number of letters to the same letter to letter value"]);
                                ToolTip.SetToolTip(this.AddToLetterWDistanceCheckBox, L[l]["Add the number of words to the same letter to letter value"]);
                                ToolTip.SetToolTip(this.AddToLetterVDistanceCheckBox, L[l]["Add the number of verses to the same letter to letter value"]);
                                ToolTip.SetToolTip(this.AddToLetterCDistanceCheckBox, L[l]["Add the number of chapters to the same letter to letter value"]);
                                ToolTip.SetToolTip(this.AddToWordWNumberCheckBox, L[l]["Add word number in verse to word value"]);
                                ToolTip.SetToolTip(this.AddToWordVNumberCheckBox, (m_client.NumerologySystem.AbsolutePositions) ? L[l]["Add word number in chapter to word value"] : L[l]["Add verse number in chapter to word value"]);
                                ToolTip.SetToolTip(this.AddToWordCNumberCheckBox, (m_client.NumerologySystem.AbsolutePositions) ? L[l]["Add word number in book to word value"] : L[l]["Add chapter number in book to word value"]);
                                ToolTip.SetToolTip(this.AddToWordWDistanceCheckBox, L[l]["Add the number of words to the same word to word value"]);
                                ToolTip.SetToolTip(this.AddToWordVDistanceCheckBox, L[l]["Add the number of verses to the same word to word value"]);
                                ToolTip.SetToolTip(this.AddToWordCDistanceCheckBox, L[l]["Add the number of chapters to the same word to word value"]);
                                ToolTip.SetToolTip(this.AddToVerseVNumberCheckBox, L[l]["Add verse number in chapter to verse value"]);
                                ToolTip.SetToolTip(this.AddToVerseCNumberCheckBox, (m_client.NumerologySystem.AbsolutePositions) ? L[l]["Add verse number in book to verse value"] : L[l]["Add chapter number in book to verse value"]);
                                ToolTip.SetToolTip(this.AddToVerseVDistanceCheckBox, L[l]["Add the number of verses to the same verse to verse value"]);
                                ToolTip.SetToolTip(this.AddToVerseCDistanceCheckBox, L[l]["Add the number of chapters to the same verse to verse value"]);
                                ToolTip.SetToolTip(this.AddToChapterCNumberCheckBox, L[l]["Add chapter number in book to chapter value"]);
                                AddToLetterLNumberCheckBox.Text = (m_client.NumerologySystem.AbsolutePositions) ? "Lw" : "L";
                                AddToLetterWNumberCheckBox.Text = (m_client.NumerologySystem.AbsolutePositions) ? "Lv" : "W";
                                AddToLetterVNumberCheckBox.Text = (m_client.NumerologySystem.AbsolutePositions) ? "Lc" : "V";
                                AddToLetterCNumberCheckBox.Text = (m_client.NumerologySystem.AbsolutePositions) ? "Lb" : "C";
                                AddToLetterLDistanceCheckBox.Text = "∆L";
                                AddToLetterWDistanceCheckBox.Text = "∆W";
                                AddToLetterVDistanceCheckBox.Text = "∆V";
                                AddToLetterCDistanceCheckBox.Text = "∆C";
                                AddToWordWNumberCheckBox.Text = (m_client.NumerologySystem.AbsolutePositions) ? "Wv" : "W";
                                AddToWordVNumberCheckBox.Text = (m_client.NumerologySystem.AbsolutePositions) ? "Wc" : "V";
                                AddToWordCNumberCheckBox.Text = (m_client.NumerologySystem.AbsolutePositions) ? "Wb" : "C";
                                AddToWordWDistanceCheckBox.Text = "∆W";
                                AddToWordVDistanceCheckBox.Text = "∆V";
                                AddToWordCDistanceCheckBox.Text = "∆C";
                                AddToVerseVNumberCheckBox.Text = (m_client.NumerologySystem.AbsolutePositions) ? "Vc" : "V";
                                AddToVerseCNumberCheckBox.Text = (m_client.NumerologySystem.AbsolutePositions) ? "Vb" : "C";
                                AddToVerseVDistanceCheckBox.Text = "∆V";
                                AddToVerseCDistanceCheckBox.Text = "∆C";
                                AddToChapterCNumberCheckBox.Text = (m_client.NumerologySystem.AbsolutePositions) ? "Cb" : "C";
                            }
                        }

                        UpdateEmlaaeiLabel();

                        LetterFrequencyColumnHeader.Text = L[l]["Freq"];

                        m_note_writing_instruction = L[l]["write a note for "];
                        //BookmarkTextBox.Text = L[l]["Search by equations"] + "\t" + "C: C + Vs = 114";
                        BookmarkTextBox.Text = "Vc = 114";
                        DisplayNoteWritingInstruction();

                        long value = Radix.Decode(ValueTextBox.Text, m_radix);
                        UpdateValueNavigator(value);

                        RegisterContextMenus();
                        SetToolTipPlayerVerseSilenceGapTrackBar();
                        SetToolTipPlayerSelectionSilenceGapTrackBar();

                        UpdateNumberTypeLabelTooltips();

                        PopulateFindByGrammarListBox();

                        UpdateUserTextValueLabel();
                        UpdateUserTextTextBoxContent();

                        SetupToolTips();
                    }
                    else
                    {
                        path = Globals.LANGUAGES_FOLDER + Path.DirectorySeparatorChar + DEFAULT_LANGUAGE + ".txt";
                        if (File.Exists(path))
                        {
                            LoadLanguage(DEFAULT_LANGUAGE);
                        }
                        else
                        {
                            MessageBox.Show("File not found " + path, Application.ProductName);
                        }
