    private void SetupToolTips()
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        try
        {
            SetFindByEquationsToolTip(BookmarkTextBox);

            ToolTip.SetToolTip(this.FontLabel, L[l]["Font"]);
            ToolTip.SetToolTip(this.ResearchMethodRunButton, L[l]["Run"]);
            ToolTip.SetToolTip(this.InspectChaptersLabel, L[l]["Inspect chapters"]);
            ToolTip.SetToolTip(this.InspectResultsLabel, L[l]["Inspect results"]);
            ToolTip.SetToolTip(this.PlayerPlayLabel, L[l]["Play"]);
            ToolTip.SetToolTip(this.PlayerPreviousLabel, L[l]["Previous verse"]);
            ToolTip.SetToolTip(this.PlayerNextLabel, L[l]["Next verse"]);
            ToolTip.SetToolTip(this.PlayerStopLabel, L[l]["Stop"]);
            ToolTip.SetToolTip(this.PlayerRepeatLabel, L[l]["Repeat verse"]);
            ToolTip.SetToolTip(this.PlayerRepeatAllLabel, L[l]["Repeat selection"]);
            ToolTip.SetToolTip(this.PlayerRepeatCounterLabel, L[l]["Verse repetitions"]);
