    private void LanguageLabel_MouseHover(object sender, EventArgs e)
    {
        if (ModifierKeys == Keys.Control)
        {
            ToolTip.SetToolTip(this.LanguageLabel, L[l]["Edit"]);
        }
        else
        {
            ToolTip.SetToolTip(this.LanguageLabel, l);
        }
    }
    private void LanguageLabel_Click(object sender, EventArgs e)
    {
        if (ModifierKeys == Keys.Control)
        {
            if (Directory.Exists(Globals.VALUES_FOLDER))
            {
                if (m_client != null)
                {
                    m_client.WatchFolder(Globals.LANGUAGES_FOLDER, "*.txt");

                    if (LanguageComboBox.SelectedIndex != -1)
                    {
                        if (!String.IsNullOrEmpty(l))
                        {
                            string path = Globals.LANGUAGES_FOLDER + Path.DirectorySeparatorChar + l + ".txt";
                            FileHelper.DisplayFile(path);
                        }
                    }
                }
            }
        }
        else
        {
            int index = LanguageComboBox.SelectedIndex;
            if (index >= 0)
            {
                if (ModifierKeys == Keys.Shift)
                {
                    index--;
                    if (index < 0)
                    {
                        index = LanguageComboBox.Items.Count - 1;
                    }
                }
                else
                {
                    index++;
                    if (index >= LanguageComboBox.Items.Count)
                    {
                        index = 0;
                    }
                }

                LanguageComboBox.SelectedIndex = index;
            }
        }
    }
