    private void MainForm_Load(object sender, EventArgs e)
    {
        bool splash_screen_done = false;
        try
        {
            SplashForm splash_form = new SplashForm();
            if (splash_form != null)
            {
                ThreadPool.QueueUserWorkItem(delegate
                {
                    using (splash_form)
                    {
                        splash_form.Show();
                        splash_form.WindowState = FormWindowState.Normal;
                        splash_form.Activate();    // bring to foreground
                        while (!splash_screen_done)
                        {
                            Application.DoEvents();
                        }
                        splash_form.Close();
                    }
                }, null);

                //splash_form.Version += " - " + Globals.SHORT_VERSION;
                splash_form.Version += "  |  " + Globals.RELEASE_EDITION;

                splash_form.Information = "Loading grammar information ...";
                PopulateFindByGrammarListBox();
                splash_form.Progress = 10;
                Thread.Sleep(100);

                string numerology_system_name = LoadNumerologySystemName();
                m_client = new Client(numerology_system_name);
                if (m_client != null)
                {
                    if (m_client.NumerologySystem != null)
                    {
                        // do this first to avoid long startup in Windows 10/11
                        m_client.Unsubscribe(Subject.LanguageSystem, this);
                        m_client.Unsubscribe(Subject.SimplificationSystem, this);
                        m_client.Unsubscribe(Subject.NumerologySystem, this);
                        m_client.Unsubscribe(Subject.DNASequenceSystem, this);
                        m_client.Unsubscribe(Subject.InterestingNumbers, this);

                        LoadApplicationFolders();

                        splash_form.Information = "Loading research methods ...";
                        LoadResearchMethods();
                        splash_form.Progress = 20;
                        Thread.Sleep(100);

                        LoadEmlaaeiBismWawShaddaOptions();
                        splash_form.Information = "Building book ...";
                        string text_mode = m_client.NumerologySystem.TextMode;
                        m_client.BuildSimplifiedBook(text_mode, m_with_diacritics, m_with_bism_Allah, m_waw_as_word, m_shadda_as_letter, m_hamza_above_horizontal_line_as_letter, m_elf_above_horizontal_line_as_letter, m_yaa_above_horizontal_line_as_letter, m_noon_above_horizontal_line_as_letter, m_emlaaei_text);
                        UpdateFindByTextControls();
                        splash_form.Progress = 40;
                        Thread.Sleep(100);

                        if (m_client.Book != null)
                        {
                            UpdateNumericMinMax();

                            splash_form.Information = "Loading translation info ...";
                            PopulateTranslatorsCheckedListBox();
                            PopulateTranslatorComboBox();
                            PopulateTranslatorsComboBox();
                            splash_form.Progress = 50;
                            Thread.Sleep(100);

                            splash_form.Information = "Loading recitation info ...";
                            PopulateRecitationsCheckedListBox();
                            PopulateReciterComboBox();
                            splash_form.Progress = 60;
                            Thread.Sleep(100);

                            splash_form.Information = "Loading chapter names ...";
                            PopulateChapterComboBox();
                            PopulateChaptersListBox();
                            PopulateChapterSelectionComboBox();
                            splash_form.Progress = 63;
                            Thread.Sleep(100);

                            splash_form.Information = "Loading sequence systems ...";
                            PopulateSymmetryTypeComboBox();
                            PopulatePiephiDigitsTypeComboBox();
                            PopulateCVWLSequenceTypeComboBox();
                            PopulateValuesSequenceScopeComboBox();
                            PopulateDNASequenceSystemComboBox();
                            splash_form.Progress = 65;
                            Thread.Sleep(100);

                            //splash_form.Information = "Loading application settings ...";
                            if (Globals.EDITION == Edition.BigNumbers)
                            {
                                splash_form.Information = "Generating prime and composite numbers ...";
                            }
                            else
                            {
                                splash_form.Information = "Loading prime and composite numbers ...";
                            }
                            LoadApplicationSettings();
                            splash_form.Progress = 70;
                            Thread.Sleep(100);

                            splash_form.Information = "Loading letter-value systems ...";
                            PopulateTextModeComboBox();
                            splash_form.Information = "Updating letter-value systems ...";
                            UpdateNumerologySystemComboBoxs();
                            splash_form.Progress = 80;
                            Thread.Sleep(100);

                            splash_form.Information = "Loading bookmarks and notes ...";
                            m_client.LoadBookmarks();
                            UpdateBookmarkButtons();
                            splash_form.Progress = 85;
                            Thread.Sleep(100);

                            splash_form.Information = "Loading user history ...";
                            m_client.LoadHistoryItems();
                            UpdateBrowseHistoryButtons();
                            splash_form.Progress = 90;
                            Thread.Sleep(100);

                            splash_form.Information = "Loading help messages ...";
                            if (m_client.HelpMessages != null)
                            {
                                if (m_client.HelpMessages.Count > 0)
                                {
                                    HelpMessageLabel.Text = m_client.HelpMessages[0];
                                }
                            }
                            splash_form.Progress = 99;
                            Thread.Sleep(100);

                            if (ReciterComboBox.SelectedItem != null)
                            {
                                RecitationGroupBox.Text = ReciterComboBox.SelectedItem.ToString() + "                                 ";
                            }
                            ToolTip.SetToolTip(this.PlayerVolumeTrackBar, (m_audio_volume / (1000 / PlayerVolumeTrackBar.Maximum)).ToString() + "%");

                            PopulateChapterSortComboBox();

                            // must be before DisplaySelection for Verse.IncludeNumber to take effect
                            ApplyWordWrapSettings();

                            // prepare before Shown
                            if ((m_information_box_top > 0) && (m_translation_box_width > 0))
                            {
                                this.ClientSplitContainer.SplitterDistance = m_information_box_top;
                                this.TabControl.SelectedIndex = m_information_page_index;
                                this.TranslationSplitContainer.SplitterDistance = m_translation_box_width;
                            }

                            m_player_looping = !m_player_looping;
                            PlayerRepeatLabel_Click(null, null);
                            m_player_looping_all = !m_player_looping_all;
                            PlayerRepeatAllLabel_Click(null, null);

                            UpdateTextModeOptions();

                            splash_form.Information = "Calculating selection values ...";

                            // refresh chapter compare method/order/pin_chapter1
                            m_client.Book.SortChapters(m_chapter_compare_by, m_chapter_compare_order, m_pin_chapter1, m_client.NumerologySystem.AddDistancesWithinChapters, m_with_diacritics);
                            UpdateChapterSortControls();

                            if (m_client.Selection == null)
                            {
                                m_client.Selection = new Selection(m_client.Book, SelectionScope.Chapter, new List<int>() { 0 });
                            }
                            if (m_client.Selection != null)
                            {
                                if ((Chapter.CompareBy == ChapterCompareBy.Compilation) && (Chapter.CompareOrder == ChapterCompareOrder.Ascending))
                                {
                                    DisplaySelection(false);
                                }
                                else
                                {
                                    DisplaySortedChapters();
                                }
                                splash_form.Progress = 100;
                                Thread.Sleep(100);
                            }
                            UpdateSearchScopeLabels();

                            if (
                                 (m_text_display_mode == TextDisplayMode.None) ||
                                 (m_text_display_mode == TextDisplayMode.TranslationOnly)
                               )
                            {
                                // fill MainTextBox.Text with anything,
                                // don't leave empty to allow live statistics
                                MainTextBox.Text = "Fast Mode";
                                MainTextBox.Refresh();

                                WordFrequencyListBoxLabel.Visible = false;
                                WordFrequencyListBox.Visible = false;
                                WordFrequencyWithDiacriticsCheckBox.Visible = false;

                                GenerateSentencesLabel.Visible = false;
                                GenerateSentencesDuplicateLettersCheckBox.Visible = false;
                                GenerateSentencesLabel.Refresh();
                                GenerateSentencesDuplicateLettersCheckBox.Refresh();
                            }
                        }

                        DeficientNumbersLabel.BackColor = Numbers.NUMBER_KIND_BACKCOLORS[0];
                        PerfectNumbersLabel.BackColor = Numbers.NUMBER_KIND_BACKCOLORS[1];
                        AbundantNumbersLabel.BackColor = Numbers.NUMBER_KIND_BACKCOLORS[2];

                        InterestingNumbersEditLabel.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                        InspectCarmichaelNumbersLabel.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    }

                    // do this last to avoid long startup in Windows 10/11
                    m_client.Subscribe(Subject.LanguageSystem, this);
                    m_client.Subscribe(Subject.SimplificationSystem, this);
                    m_client.Subscribe(Subject.NumerologySystem, this);
                    m_client.Subscribe(Subject.DNASequenceSystem, this);
                    m_client.Subscribe(Subject.InterestingNumbers, this);
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            splash_screen_done = true;
            Thread.Sleep(100);  // prevent race-condition to allow splashform.Close()
        }
    }
    private void MainForm_Shown(object sender, EventArgs e)
    {
        CreateNumerologyValueLabels();
        DisplayNumerologyValues();

        CreateValuesSequenceLabels();
        DisplayValuesSequence();

        VersionLabel.Text = Globals.SHORT_VERSION;

        DivisorValueDownLabel.ForeColor = Numbers.DIVISOR_COLOR;
        DivisorValueLabel.ForeColor = Numbers.DIVISOR_COLOR;
        DivisorValueUpLabel.ForeColor = Numbers.DIVISOR_COLOR;

        // WARNING: updates m_font BUT loses the font face in right-to-left RichTextBox
        //SetFontSize(m_font_size);
        // update ZoomFactor instead
        UpdateZoomFactor();

        // setup C V W L start for distance caluclations
        MainTextBox.AlignToStart();
        Verse verse = GetCurrentVerse();
        if (verse != null)
        {
            if (verse.Chapter != null)
            {
                m_clicked_chapter = verse.Chapter;
                m_clicked_chapter_number = verse.Chapter.SortedNumber;
            }

            m_clicked_verse = verse;
            m_clicked_verse_number = verse.Number;

            if (verse.Words.Count > 0)
            {
                Word word = verse.Words[0];
                if (word != null)
                {
                    m_clicked_word = word;
                    m_clicked_word_number = word.Number;
                    if (word.Letters.Count > 0)
                    {
                        Letter letter = word.Letters[0];
                        if (letter != null)
                        {
                            m_clicked_letter = letter;
                            m_clicked_letter_number = letter.Number;
                        }
                    }
                }
            }
        }

        UserRatioPresetLabel.Visible = false;
        UserRatioNumericUpDown.Visible = false;
        UserRatioScopeLabel.Visible = false;
        UserRatioDelimiterLabel.Visible = true;
        UserRatioTypeLabel.Visible = false;
        UserRatioLengthLabel.Visible = false;

        if (Globals.EDITION == Edition.BigNumbers)
        {
            this.ShowInTaskbar = false;
            NotifyIcon.Visible = true;
        }

        //if (Environment.UserName != "Prime")
        //{
        //    // first launch
        //    if (!File.Exists(m_ini_filename))
        //    {
        //        VersionLabel_Click(null, null);
        //    }
        //}

        // start user at chapter list box
        ChaptersListBox.Focus();

        this.Activate();    // bring to foreground
    }
    private void MainForm_KeyDown(object sender, KeyEventArgs e)
    {
        if (e.KeyCode == Keys.Enter)
        {
            if (UserRatioNumericUpDown.Focused)
            {
                UserRatioNumericUpDown_KeyDown(sender, e);
                e.Handled = true;
            }
            else if (WordFrequencyListBox.Focused)
            {
                WordFrequencyListBox_DoubleClick(null, null);
                e.Handled = true;
            }
            else
            {
                e.Handled = false;
            }
        }
        else if (e.KeyCode == Keys.Tab)
        {
            e.Handled = false;
        }
        else if (e.KeyCode == Keys.Escape)
        {
            EscapeLabel_Click(null, null);
        }
        else if (e.Control && (e.KeyCode == Keys.D0)) // Default Zoom 
        {
            m_text_zoom_factor = DEFAULT_TEXT_ZOOM_FACTOR;
            m_graphics_zoom_factor = DEFAULT_GRAPHICS_ZOOM_FACTOR;
            UpdateZoomFactor();
            e.Handled = true;
        }
        else if (e.Control && (e.KeyCode == Keys.Add)) // Zoom In
        {
            ZoomInLabel_Click(null, null);
            e.Handled = true;
        }
        else if (e.Control && (e.KeyCode == Keys.Zoom)) // Zoom In
        {
            ZoomInLabel_Click(null, null);
            e.Handled = true;
        }
        else if (e.Control && (e.KeyCode == Keys.Oemplus)) // Zoom In
        {
            ZoomInLabel_Click(null, null);
            e.Handled = true;
        }
        else if (e.Control && (e.KeyCode == Keys.Subtract)) // Zoom Out
        {
            ZoomOutLabel_Click(null, null);
            e.Handled = true;
        }
        else if (e.Control && (e.KeyCode == Keys.OemMinus)) // Zoom Out
        {
            ZoomOutLabel_Click(null, null);
            e.Handled = true;
        }
        else if (e.Control && (e.KeyCode == Keys.Down)) // Redo
        {
            RedoGotoVerse();
        }
        else if (e.Control && (e.KeyCode == Keys.Up)) // Undo
        {
            UndoGotoVerse();
        }
        else if (e.Control && (e.KeyCode == Keys.A)) // SelectAll chapters
        {
            if (ChaptersListBox.Focused)
            {
                for (int i = 0; i < 3; i++)
                    ChaptersListBox.SelectedIndexChanged -= new System.EventHandler(ChaptersListBox_SelectedIndexChanged);
                for (int i = 0; i < ChaptersListBox.Items.Count - 1; i++)
                {
                    ChaptersListBox.SelectedIndices.Add(i);
                }
                ChaptersListBox.SelectedIndexChanged += new System.EventHandler(ChaptersListBox_SelectedIndexChanged);
                ChaptersListBox.SelectedIndices.Add(ChaptersListBox.Items.Count - 1);
            }
            else if (WordFrequencyListBox.Focused)
            {
                for (int i = 0; i < 3; i++)
                    WordFrequencyListBox.SelectedIndexChanged -= new System.EventHandler(WordFrequencyListBox_SelectedIndexChanged);
                for (int i = 0; i < WordFrequencyListBox.Items.Count - 1; i++)
                {
                    WordFrequencyListBox.SelectedIndices.Add(i);
                }
                WordFrequencyListBox.SelectedIndexChanged += new System.EventHandler(WordFrequencyListBox_SelectedIndexChanged);
                WordFrequencyListBox.SelectedIndices.Add(WordFrequencyListBox.Items.Count - 1);
            }
            else
            {
                e.Handled = false;
            }
        }
        else
        {
            if (!e.Alt && !e.Control && !e.Shift)
            {
                if ((e.KeyCode == Keys.Back) || (e.KeyCode == Keys.BrowserBack))
                {
                    if (m_active_textbox != null)
                    {
                        if (
                            ((m_active_textbox.Focused) && (m_translation_readonly)) ||
                            (BrowseHistoryBackwardButton.Focused) ||
                            (BrowseHistoryForwardButton.Focused) ||
                            (BrowseHistoryCounterLabel.Focused)
                           )
                        {
                            BrowseHistoryBackwardButton_Click(null, null);
                            e.Handled = true; // stop annoying beep due to parent not having an AcceptButton
                        }
                    }
                }
                else if ((e.KeyCode == Keys.BrowserForward))
                {
                    if (m_active_textbox != null)
                    {
                        if (
                            ((m_active_textbox.Focused) && (m_translation_readonly)) ||
                            (BrowseHistoryBackwardButton.Focused) ||
                            (BrowseHistoryForwardButton.Focused) ||
                            (BrowseHistoryCounterLabel.Focused)
                           )
                        {
                            BrowseHistoryForwardButton_Click(null, null);
                            e.Handled = true; // stop annoying beep due to parent not having an AcceptButton
                        }
                    }
                }
                else if (e.KeyCode == Keys.F1)
                {
                    //HelpMessageLabel.BringToFront();
                }
                else if (e.KeyCode == Keys.F2)
                {
                    //HelpMessageLabel.SendToBack();
                }
                else if (e.KeyCode == Keys.F3)
                {
                    if (m_found_verses_displayed)
                    {
                        SelectNextFoundMatch();
                    }
                    else
                    {
                        BookmarkForwardButton_Click(null, null);
                    }
                }
                else if (e.KeyCode == Keys.F4)
                {
                    if (m_active_textbox != null)
                    {
                        if (m_active_textbox.Focused)
                        {
                            DoFindRelatedWords(m_active_textbox);
                        }
                    }
                }
                else if (e.KeyCode == Keys.F5)
                {
                    if (m_active_textbox != null)
                    {
                        if (m_active_textbox.Focused)
                        {
                            DoFindRelatedVerses(m_active_textbox);
                        }
                    }
                }
                else if (e.KeyCode == Keys.F6)
                {
                    if (m_active_textbox != null)
                    {
                        if (m_active_textbox.Focused)
                        {
                            DoFindSimilarVerses(m_active_textbox);
                        }
                    }
                }
                else if (e.KeyCode == Keys.F7)
                {
                    if (m_active_textbox != null)
                    {
                        if (m_active_textbox.Focused)
                        {
                            DoFindSameText(m_active_textbox);
                        }
                    }
                }
                else if (e.KeyCode == Keys.F8)
                {
                    if (m_active_textbox != null)
                    {
                        if (m_active_textbox.Focused)
                        {
                            DoFindSameHarakat(m_active_textbox);
                        }
                    }
                }
                else if (e.KeyCode == Keys.F9)
                {
                    if (m_active_textbox != null)
                    {
                        if (m_active_textbox.Focused)
                        {
                            DoFindSameValue(m_active_textbox);
                        }
                    }
                }
                else if (e.KeyCode == Keys.F11)
                {
                    if (this.WindowState != FormWindowState.Maximized)
                    {
                        this.WindowState = FormWindowState.Maximized;
                        this.FormBorderStyle = FormBorderStyle.None;
                    }
                    else
                    {
                        this.WindowState = FormWindowState.Normal;
                        this.FormBorderStyle = FormBorderStyle.Sizable;
                    }
                }
                else if (e.KeyCode == Keys.F12)
                {
                    ToggleWordWrap();
                }
                else
                {
                    // let editor process key
                }
            }
            else if (!e.Alt && !e.Control && e.Shift)
            {
                if ((e.KeyCode == Keys.Back) || (e.KeyCode == Keys.BrowserBack))
                {
                    if (m_active_textbox != null)
                    {
                        if (
                            ((m_active_textbox.Focused) && (m_translation_readonly)) ||
                            (BrowseHistoryBackwardButton.Focused) ||
                            (BrowseHistoryForwardButton.Focused) ||
                            (BrowseHistoryCounterLabel.Focused)
                           )
                        {
                            BrowseHistoryForwardButton_Click(null, null);
                            e.Handled = true; // stop annoying beep due to parent not having an AcceptButton
                        }
                    }
                }
                else if ((e.KeyCode == Keys.BrowserForward))
                {
                    if (m_active_textbox != null)
                    {
                        if (
                            ((m_active_textbox.Focused) && (m_translation_readonly)) ||
                            (BrowseHistoryBackwardButton.Focused) ||
                            (BrowseHistoryForwardButton.Focused) ||
                            (BrowseHistoryCounterLabel.Focused)
                           )
                        {
                            BrowseHistoryBackwardButton_Click(null, null);
                            e.Handled = true; // stop annoying beep due to parent not having an AcceptButton
                        }
                    }
                }
                else if (e.KeyCode == Keys.F1)
                {
                }
                else if (e.KeyCode == Keys.F2)
                {
                }
                else if (e.KeyCode == Keys.F3)
                {
                    if (m_found_verses_displayed)
                    {
                        SelectPreviousFoundMatch();
                    }
                    else
                    {
                        BookmarkBackwardButton_Click(null, null);
                    }
                }
                else if (e.KeyCode == Keys.F4)
                {
                }
                else if (e.KeyCode == Keys.F5)
                {
                }
                else if (e.KeyCode == Keys.F6)
                {
                }
                else if (e.KeyCode == Keys.F7)
                {
                }
                else if (e.KeyCode == Keys.F8)
                {
                }
                else if (e.KeyCode == Keys.F9)
                {
                }
                else if (e.KeyCode == Keys.F10)
                {
