                else if (e.KeyCode == Keys.F11)
                {
                }
                else if (e.KeyCode == Keys.F12)
                {
                }
                else
                {
                    // let editor process key
                }
            }
        }
    }
    private bool m_was_maximized = false;
    private void MainForm_Resize(object sender, EventArgs e)
    {
        if (this.WindowState == FormWindowState.Minimized)
        {
            if (Globals.EDITION == Edition.BigNumbers)
            {
                this.Visible = false; // send to system try instead of minimize
            }
        }
        else
        {
            m_was_maximized = this.WindowState == FormWindowState.Maximized;
        }

        ArrangeNumerologyValueLabels();

        if (PictureBox.Visible)
        {
            RedrawImage();
        }
        else
        {
            if (m_player != null)
            {
                if (m_player.Closed)
                {
                    Verse verse = GetCurrentVerse();
                    if (verse != null)
                    {
                        if (m_active_textbox != null)
                        {
                            try
                            {
                                for (int i = 0; i < 3; i++)
                                    m_active_textbox.TextChanged -= new System.EventHandler(MainTextBox_TextChanged);
                                for (int i = 0; i < 3; i++)
                                    m_active_textbox.SelectionChanged -= new System.EventHandler(MainTextBox_SelectionChanged);
                                m_active_textbox.BeginUpdate();

                                int start = m_active_textbox.SelectionStart;
                                int length = m_active_textbox.SelectionLength;
                                m_active_textbox.AlignToLineStart();
                                m_active_textbox.Select(start, length);
                                m_active_textbox.Refresh();
                            }
                            catch (Exception ex)
                            {
                                MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
                            }
                            finally
                            {
                                m_active_textbox.EndUpdate();
                                m_active_textbox.SelectionChanged += new System.EventHandler(MainTextBox_SelectionChanged);
                                m_active_textbox.TextChanged += new System.EventHandler(MainTextBox_TextChanged);
                            }
                        }
                    }
                }
            }
        }
    }
    private void MainForm_FormClosing(object sender, FormClosingEventArgs e)
    {
        if (Globals.EDITION == Edition.BigNumbers)
        {
            // prevent user from closing from the X close button
            if (e.CloseReason == CloseReason.UserClosing)
            {
                e.Cancel = true;
                this.Visible = false;
            }
        }
    }
    private void MainForm_FormClosed(object sender, FormClosedEventArgs e)
    {
        CloseApplication();
    }
    private void CloseApplication()
    {
        try
        {
            if (m_client != null)
            {
                m_client.UnwatchFolder(Globals.LANGUAGES_FOLDER, "*.txt");
                m_client.UnwatchFolder(Globals.RULES_FOLDER, "*.txt");
                m_client.UnwatchFolder(Globals.VALUES_FOLDER, "*.txt");
                m_client.UnwatchFolder(Globals.VALUES_FOLDER, "*DNA.txt");
                m_client.UnwatchFolder(Globals.NUMBERS_FOLDER, Globals.INTERESTING_NUMBERS_FILENAME);
            }

            // save current note (if any)
            BookmarkTextBox_Leave(null, null);

            if (m_client != null)
            {
                // save bookmarks of all texts of current client
                m_client.SaveBookmarks();

                // save user history
                m_client.SaveHistoryItems();
            }

            // save application options
            SaveApplicationOptions();

            PlayerStopLabel_Click(null, null);

            // remove icon from tray
            if (NotifyIcon != null)
            {
                NotifyIcon.Visible = false;
            }

            if (DivisorUpTimer != null)
            {
                DivisorUpTimer.Dispose();
            }
            if (DivisorDownTimer != null)
            {
                DivisorDownTimer.Dispose();
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
    }
    private void NotifyIcon_MouseClick(object sender, MouseEventArgs e)
    {
        if (e.Button == MouseButtons.Left)
        {
            if (this.Visible == true)
            {
                this.Visible = false;
            }
            else
            {
                this.Visible = true;
                if (this.WindowState == FormWindowState.Minimized)
                {
                    if (m_was_maximized)
                    {
                        this.WindowState = FormWindowState.Maximized;
                    }
                    else
                    {
                        this.WindowState = FormWindowState.Normal;
                    }
                }
                this.Activate();    // bring to foreground
                this.BringToFront();
            }
        }
    }
