    private void EscapeLabel_Click(object sender, EventArgs e)
    {
        if (LanguageComboBox.DroppedDown)
        {
            LanguageComboBox.DroppedDown = false;
        }
        else if (NumerologySystemComboBox.DroppedDown)
        {
            NumerologySystemComboBox.DroppedDown = false;
        }
        else if (ResearchMethodsComboBox.DroppedDown)
        {
            ResearchMethodsComboBox.DroppedDown = false;
        }
        else if (ChapterSortComboBox.DroppedDown)
        {
            ChapterSortComboBox.DroppedDown = false;
        }
        else if (TranslatorComboBox.DroppedDown)
        {
            TranslatorComboBox.DroppedDown = false;
        }
        else if (ReciterComboBox.DroppedDown)
        {
            ReciterComboBox.DroppedDown = false;
        }
        else if (BookmarkTextBox.Focused)
        {
            //BookmarkTextBox.Text = null;
        }
        else if (TranslatorsCheckedListBox.Visible)
        {
            TranslationCancelSettingsLabel_Click(null, null);
        }
        else if (RecitationsDownloadGroupBox.Visible)
        {
            RecitationsCancelSettingsLabel_Click(null, null);
        }
        else if ((TranslationTextBox.Focused) || (TranslationsTextBox.Focused))
        {
            DisplayTranslations(new List<Verse>(m_translated_verses));
        }
        else if (!m_translation_readonly)
        {
            TranslationEditSaveLabel_Click(null, null);
        }
        else if (PictureBox.Visible)
        {
            HidePictureBox();
        }
        else if ((LetterFrequencyListView.Focused) && (LetterFrequencyListView.SelectedIndices.Count > 0))
        {
            LetterFrequencyListView.SelectedIndices.Clear();
        }
        else if (ScriptTextBox.Visible)
        {
            CloseScript();
        }
        else if (UserTextTextBox.Focused)
        {
            // let UserTextTextBox handle it
        }
        else
        {
            if (m_found_verses_displayed)
            {
                if (m_client.FilterChapters != null)
                {
                    DisplayAllChaptersSearchResults();
                }
                else
                {
                    SwitchActiveTextBox();
                }
            }
            else
            {
                SwitchActiveTextBox();
            }
        }
    }
    private void DisplayAllChaptersSearchResults()
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                // clear to go back to main results
                m_client.FilterChapters = null;
                ChaptersListBox.SelectedIndices.Clear();

                if (!String.IsNullOrEmpty(m_header_label_info))
                {
                    int pos = m_header_label_info.IndexOf(" of ");
                    if (pos > -1)
                    {
                        m_header_label_info = m_header_label_info.Substring(pos + 4);
                    }
                }

                if (m_search_type == SearchType.Grammar)
                {
                    if (m_client.FoundWords != null)
                    {
                        DisplayFoundWords(FINDBYGRAMMAR_MATCH_COLOR, false);
                    }
                }
                else if (m_search_type == SearchType.Repetition)
                {
                    if (m_client.FoundWords != null)
                    {
                        DisplayFoundWords(FINDBYREPETITION_MATCH_COLOR, false);
                    }
                }
                else if (m_search_type == SearchType.Text)
                {
                    if (m_client.FoundLetters != null)
                    {
                        DisplayFoundLetters(FINDBYTEXT_MATCH_COLOR, false);
                    }
                    else if (m_client.FoundWords != null)
                    {
                        DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, false);
                    }
                    else //if (m_client.FoundVerses != null)
                    {
                        DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                    }
                }
                else if (m_search_type == SearchType.Numbers)
                {
                    switch (m_numbers_result_type)
                    {
                        case NumbersResultType.Verses:
                            DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                            break;
                        case NumbersResultType.VerseRanges:
                            DisplayFoundVerseRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.VerseSets:
                            DisplayFoundVerseSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;

                        case NumbersResultType.Chapters:
                            DisplayFoundChapters(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.ChapterRanges:
                            DisplayFoundChapterRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.ChapterSets:
                            DisplayFoundChapterSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;

                        case NumbersResultType.Pages:
                            DisplayFoundPages(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.PageRanges:
                            DisplayFoundPageRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.PageSets:
                            DisplayFoundPageSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;

                        case NumbersResultType.Stations:
                            DisplayFoundStations(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.StationRanges:
                            DisplayFoundStationRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.StationSets:
                            DisplayFoundStationSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;

                        case NumbersResultType.Parts:
                            DisplayFoundParts(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.PartRanges:
                            DisplayFoundPartRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.PartSets:
                            DisplayFoundPartSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;

                        case NumbersResultType.Groups:
                            DisplayFoundGroups(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.GroupRanges:
                            DisplayFoundGroupRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.GroupSets:
                            DisplayFoundGroupSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;

                        case NumbersResultType.Halfs:
                            DisplayFoundHalfs(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.HalfRanges:
                            DisplayFoundHalfRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.HalfSets:
                            DisplayFoundHalfSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;

                        case NumbersResultType.Quarters:
                            DisplayFoundQuarters(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.QuarterRanges:
                            DisplayFoundQuarterRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.QuarterSets:
                            DisplayFoundQuarterSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;

                        case NumbersResultType.Bowings:
                            DisplayFoundBowings(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.BowingRanges:
                            DisplayFoundBowingRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;
                        case NumbersResultType.BowingSets:
                            DisplayFoundBowingSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                            break;

                        default:
                            DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                            break;
                    }
                }
                else
                {
                    DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void ShowHideGenerateSentences()
    {
        if (m_active_textbox.SelectionLength > 0)
        {
            GenerateSentencesLabel.Visible = ((Globals.EDITION == Edition.Ultimate) || (Globals.EDITION == Edition.BigNumbers));
            GenerateSentencesDuplicateLettersCheckBox.Visible = ((Globals.EDITION == Edition.Ultimate) || (Globals.EDITION == Edition.BigNumbers));
            GenerateSentencesLabel.Refresh();
            GenerateSentencesDuplicateLettersCheckBox.Refresh();
        }
        else
        {
            GenerateSentencesLabel.Visible = false;
            GenerateSentencesDuplicateLettersCheckBox.Visible = false;
            GenerateSentencesLabel.Refresh();
            GenerateSentencesDuplicateLettersCheckBox.Refresh();
        }
    }
    private void SwitchActiveTextBox()
    {
        if (m_active_textbox != null)
        {
            if (m_found_verses_displayed)
            {
                SwitchToMainTextBox();
            }
            else
            {
                if (m_current_drawing_type != DrawingType.None)
                {
                    SwitchToPictureBox();
                }
                else
                {
                    SwitchToSearchResultTextBox();
                }
            }

            PlayerStopLabel_Click(null, null);

            if (m_active_textbox.SelectionLength > 0)
            {
                DisplayWordFrequencies();
                this.AcceptButton = null;  // prevent stealing focus by this.AcceptButton = FindByTextButton;
            }
            else
            {
                WordFrequencyListBoxLabel.Visible = false;
                WordFrequencyListBox.Visible = false;
                WordFrequencyWithDiacriticsCheckBox.Visible = false;
            }

            ShowHideGenerateSentences();

            List<Verse> verses = GetCurrentVerses();
            if (verses != null)
            {
                DisplayTranslations(verses);
                DisplaySymmetry();
                DisplayPiephiDigits();
                DisplayCVWLSequence();
                DisplayValuesSequence();
                DisplayDNASequence();
            }
            else
            {
                TranslationTextBox.Text = null;
                TranslationTextBox.Refresh();
                TranslationsTextBox.Text = null;
                TranslationsTextBox.Refresh();

                m_translation_readonly = true;
                UpdateTranslationReadOnly();
                TranslationEditSaveLabel.Enabled = false;
            }

            m_current_letter = GetLetterAtCursor();
            m_current_word = GetWordAtCursor();
            m_current_verse = GetCurrentVerse();
            m_current_chapter = GetCurrentChapter();
            if (m_current_verse != null)
            {
                if (m_current_letter == null)
                {
                    m_current_letter = m_current_verse.Letters[m_current_verse.Letters.Count - 1];
                }
                if (m_current_word == null)
                {
                    m_current_word = m_current_verse.Words[m_current_verse.Words.Count - 1];
                }
            }
            if (m_current_word != null)
            {
                this.Text = GetCurrentWordDetails(m_current_word);
            }
            m_clicked_chapter = m_current_chapter;
            m_clicked_verse = m_current_verse;
            m_clicked_word = m_current_word;
            m_clicked_letter = m_current_letter;
            UpdateHeaderLabel();

            m_active_textbox.Refresh();
            m_active_textbox.Focus();
        }
    }
