    private void DoFindRelatedWords(object sender)
    {
        if (m_emlaaei_text)
            return;

        if (sender is TextBoxBase)
        {
            string text = (sender as TextBoxBase).SelectedText;
            if (text.Length == 0) // no selection, get word under mouse pointer
            {
                m_current_word = GetWordAtCursor();
                if (m_current_word != null)
                {
                    DoFindRelatedWords(m_current_word);
                }
            }
            else
            {
                DoFindRelatedWords(text);
            }
        }
    }
    private void DoFindRelatedWords(Word word)
    {
        if (m_emlaaei_text)
            return;

        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                FindByRoot(word);
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void DoFindRelatedWords(string text)
    {
        if (m_emlaaei_text)
            return;

        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    char[] separators = { ' ', '\n' };
                    string[] words = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);

                    string roots = "";
                    foreach (string word in words)
                    {
                        roots += m_client.Book.GetBestRoot(word) + " ";
                    }
                    if (roots.Length > 0)
                    {
                        roots = roots.Remove(roots.Length - 1, 1);
                    }

                    FindByRoot(roots);
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void DoFindRelatedVerses(object sender)
    {
        m_search_type = SearchType.Text;

        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                ClearFoundMatches();

                Verse verse = GetCurrentVerse();
                if (verse != null)
                {
                    if (verse.Chapter != null)
                    {
                        m_client.FindRelatedVerses(verse);
                        if (m_client.FoundVerses != null)
                        {
                            string text = " to verse " + verse.Chapter.Name + " " + verse.NumberInChapter + " ";
                            int verse_count = m_client.FoundVerses.Count;
                            m_header_label_info = verse_count + ((verse_count == 1) ? " " + L[l]["verse"] : " " + L[l]["verses"]) + " " + L[l]["with"] + " " + L[l]["similar words"] + text + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];

                            DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, true);
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
