    private void DoFindSameValue(object sender)
    {
        if (sender is TextBoxBase)
        {
            long value;
            if (long.TryParse(ValueTextBox.Text, out value))
            {
                DoFindSameValue(value);
            }
        }
    }
    private void DoFindSameValue(long value)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                ClearFoundMatches();

                List<Phrase> phrases = new List<Phrase>();
                string text = "value" + "" + "=" + value.ToString();

                NumberQuery query = new NumberQuery();
                query.Value = value;

                int match_count = m_client.FindSentences(query);
                if (match_count > 0)
                {
                    if (m_client.FoundPhrases != null)
                    {
                        phrases.InsertRange(0, new List<Phrase>(m_client.FoundPhrases));
                    }
                }

                if (m_client.FoundVerses != null)
                {
                    m_client.FoundPhrases = phrases;
                    m_header_label_info = match_count + ((match_count == 1) ? " " + L[l]["match"] : " " + L[l]["matches"]) + " " + L[l]["in"] + " " + m_client.FoundVerses.Count + ((m_client.FoundVerses.Count == 1) ? " " + L[l]["verse"] : " " + L[l]["verses"]) + " " + L[l]["with"] + " " + text + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                    DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, true);
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    public List<Verse> GetVerses(List<Phrase> phrases)
    {
        List<Verse> result = new List<Verse>();
        if (phrases != null)
        {
            foreach (Phrase phrase in phrases)
            {
                if (phrase != null)
                {
                    if (!result.Contains(phrase.Verse))
                    {
                        result.Add(phrase.Verse);
                    }
                }
            }
        }
        return result;
    }
    private void RegisterContextMenu(Control control)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if ((control is TextBoxBase) || (control is PictureBoxEx))
        {
            ContextMenu ContextMenu = new ContextMenu();
            if ((control != MainTextBox) && (control != SearchResultTextBox))
            {
                MenuItem EditUndoMenuItem = new MenuItem(L[l]["Undo"] + "\t\tCtrl+Z");
                EditUndoMenuItem.Click += new System.EventHandler(MenuItem_Undo);
                ContextMenu.MenuItems.Add(EditUndoMenuItem);

                MenuItem MenuItemSeparator1 = new MenuItem("-");
                ContextMenu.MenuItems.Add(MenuItemSeparator1);

                MenuItem EditCutMenuItem = new MenuItem(L[l]["Cut"] + "\t\tCtrl+X");
                EditCutMenuItem.Click += new System.EventHandler(MenuItem_Cut);
                ContextMenu.MenuItems.Add(EditCutMenuItem);

                MenuItem EditCopyMenuItem = new MenuItem(L[l]["Copy"] + "\t\tCtrl+C");
                EditCopyMenuItem.Click += new System.EventHandler(MenuItem_Copy);
                ContextMenu.MenuItems.Add(EditCopyMenuItem);

                MenuItem EditPasteMenuItem = new MenuItem(L[l]["Paste"] + "\t\tCtrl+V");
                EditPasteMenuItem.Click += new System.EventHandler(MenuItem_Paste);
                ContextMenu.MenuItems.Add(EditPasteMenuItem);

                MenuItem MenuItemSeparator2 = new MenuItem("-");
                ContextMenu.MenuItems.Add(MenuItemSeparator2);

                MenuItem EditSelectAllMenuItem = new MenuItem(L[l]["Select All"] + "\tCtrl+A");
                EditSelectAllMenuItem.Click += new System.EventHandler(MenuItem_SelectAll);
                ContextMenu.MenuItems.Add(EditSelectAllMenuItem);
            }
            else
            {
                MenuItem EditCopyMenuItem = new MenuItem(L[l]["Copy"] + "\t\tCtrl+C");
                EditCopyMenuItem.Click += new System.EventHandler(MenuItem_Copy);
                ContextMenu.MenuItems.Add(EditCopyMenuItem);

                MenuItem EditCopyVersesMenuItem = new MenuItem(L[l]["Copy Verse"] + "\t\tCtrl+D");
                EditCopyVersesMenuItem.Click += new System.EventHandler(MenuItem_CopyVerses);
                ContextMenu.MenuItems.Add(EditCopyVersesMenuItem);

                MenuItem EditGenerateSentencesMenuItem = new MenuItem(L[l]["Generate Sentences"] + "\t\tCtrl+G");
                EditGenerateSentencesMenuItem.Click += new System.EventHandler(MenuItem_GenerateSentences);
                if ((Globals.EDITION == Edition.Ultimate) || (Globals.EDITION == Edition.BigNumbers))
                    ContextMenu.MenuItems.Add(EditGenerateSentencesMenuItem);

                MenuItem MenuItemSeparator1 = new MenuItem("-");
                ContextMenu.MenuItems.Add(MenuItemSeparator1);

                MenuItem FindRelatedWordsMenuItem = new MenuItem(L[l]["Related Words"] + "\tF4");
                FindRelatedWordsMenuItem.Click += new System.EventHandler(MenuItem_RelatedWords);
                ContextMenu.MenuItems.Add(FindRelatedWordsMenuItem);

                MenuItem FindRelatedVersesMenuItem = new MenuItem(L[l]["Related Verses"] + "\tF5");
                FindRelatedVersesMenuItem.Click += new System.EventHandler(MenuItem_RelatedVerses);
                ContextMenu.MenuItems.Add(FindRelatedVersesMenuItem);

                MenuItem FindSimilarVersesMenuItem = new MenuItem(L[l]["Similar Verses"] + "\tF6");
                FindSimilarVersesMenuItem.Click += new System.EventHandler(MenuItem_SimilarVerses);
                ContextMenu.MenuItems.Add(FindSimilarVersesMenuItem);

                MenuItem MenuItemSeparator2 = new MenuItem("-");
                ContextMenu.MenuItems.Add(MenuItemSeparator2);

                MenuItem FindSameTextMenuItem = new MenuItem(L[l]["Same Text"] + "\tF7");
                FindSameTextMenuItem.Click += new System.EventHandler(MenuItem_SameText);
                ContextMenu.MenuItems.Add(FindSameTextMenuItem);

                MenuItem FindSameHarakatMenuItem = new MenuItem(L[l]["Same Harakat"] + "\tF8");
                FindSameHarakatMenuItem.Click += new System.EventHandler(MenuItem_SameHarakat);
                ContextMenu.MenuItems.Add(FindSameHarakatMenuItem);

                MenuItem FindSameValueMenuItem = new MenuItem(L[l]["Same Value"] + "\tF9");
                FindSameValueMenuItem.Click += new System.EventHandler(MenuItem_SameValue);
                ContextMenu.MenuItems.Add(FindSameValueMenuItem);
            }

            ContextMenu.Popup += new System.EventHandler(ContextMenu_Popup);
            ContextMenu.Collapse += new System.EventHandler(ContextMenu_Collapse);

            control.ContextMenu = ContextMenu;
        }
    }
