    private void LoadResearchMethods()
    {
        if (Globals.EDITION == Edition.Standard)
        {
            ResearchMethodsComboBox.Items.Clear();
            ResearchMethodsComboBox.Items.Add("Start with Shift for " + Edition.Research + " Edition");
            ResearchMethodsComboBox.Items.Add("Start with Ctrl for " + Edition.Ultimate + " Edition");
            ResearchMethodsComboBox.Items.Add("Start with Shift+Ctrl for " + Edition.BigNumbers + " Edition");
            if (ResearchMethodsComboBox.Items.Count > 0)
            {
                ResearchMethodsComboBox.SelectedIndex = 0;
            }

            ResearchMethodParameterTextBox.Visible = false;
            ResearchMethodRunButton.Visible = false;
        }
        else
        {
            ResearchMethodParameterTextBox.Visible = true;
            ResearchMethodRunButton.Visible = true;

            try
            {
                for (int i = 0; i < 3; i++)
                    ResearchMethodsComboBox.SelectedIndexChanged -= new System.EventHandler(ResearchMethodsComboBox_SelectedIndexChanged);

                AppDomain domain = AppDomain.CurrentDomain;
                if (domain != null)
                {
                    //????? dynamic loading of DLL library is dangerous!!!
                    m_research_assembly = domain.Load(m_research_assembly_name);
                    //// instead add it to References in QuranCode project
                    //// and find it in loaded assemblies and extract its research methods
                    //Assembly[] assembly_array = domain.GetAssemblies();
                    //foreach (Assembly assembly in assembly_array)
                    //{
                    //    if (assembly.FullName.StartsWith(m_research_assembly_name))
                    //    {
                    //        m_research_assembly = assembly;
                    //        break;
                    //    }
                    //}

                    if (m_research_assembly != null)
                    {
                        Type class_type = m_research_assembly.GetType(m_research_assembly_name);
                        if (class_type != null)
                        {
                            MethodInfo[] method_infos = null;
                            if (Globals.EDITION == Edition.Standard)
                            {
                                method_infos = null;
                            }
                            else if (Globals.EDITION == Edition.Research)
                            {
                                method_infos = class_type.GetMethods(BindingFlags.Static | BindingFlags.Public);
                            }
                            else if (Globals.EDITION == Edition.Ultimate)
                            {
                                method_infos = class_type.GetMethods(BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
                            }
                            else if (Globals.EDITION == Edition.BigNumbers)
                            {
                                method_infos = class_type.GetMethods(BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
                            }

                            if (method_infos != null)
                            {
                                ResearchMethodsComboBox.Items.Clear();
                                foreach (MethodInfo method_info in method_infos)
                                {
                                    string method_name = method_info.Name;
                                    ParameterInfo[] parameters = method_info.GetParameters();
                                    if ((parameters.Length == 3) &&
                                        (parameters[0].ParameterType == typeof(Client)) &&
                                        (parameters[1].ParameterType == typeof(string)) &&
                                        (parameters[2].ParameterType == typeof(bool)))
                                    {
                                        ResearchMethodsComboBox.Items.Add(method_name);
                                    }
                                }
                            }
                        }

                        if (ResearchMethodsComboBox.Items.Count > 0)
                        {
                            ResearchMethodsComboBox.SelectedItem = "AllahWords";
                            ResearchMethodsComboBox_SelectedIndexChanged(null, null);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
            }
            finally
            {
                ResearchMethodsComboBox.SelectedIndexChanged += new System.EventHandler(ResearchMethodsComboBox_SelectedIndexChanged);
            }
        }
    }
    private object RunResearchMethod()
    {
        if (m_client != null)
        {
            if (m_client.Selection != null)
            {
                if (m_client.NumerologySystem != null)
                {
                    if (ResearchMethodsComboBox.SelectedIndex > -1)
                    {
                        if (ResearchMethodsComboBox.SelectedItem != null)
                        {
                            string method_name = ResearchMethodsComboBox.SelectedItem.ToString();
                            string param = ResearchMethodParameterTextBox.Text;
                            if (!string.IsNullOrEmpty(method_name))
                            {
                                string result = InvokeResearchMethod(method_name, m_client, param, m_found_verses_displayed);
                                if (result != null)
                                {
                                    string filename = m_client.NumerologySystem.Name + "_" + method_name + "_" + ((!String.IsNullOrEmpty(param)) ? param.ToString() + "_" : "") + DateTime.Now.ToString("yyyyMMdd_hhmmss") + ".txt";
                                    if (Directory.Exists(Globals.RESEARCH_FOLDER))
                                    {
                                        string path = Globals.RESEARCH_FOLDER + Path.DirectorySeparatorChar + filename;
                                        FileHelper.SaveText(path, result);
                                        if (result.Length <= (64 * 1024 * 1024)) // 64 Mb
                                        {
                                            FileHelper.DisplayFile(path);
                                        }
                                        else
                                        {
                                            try
                                            {
                                                System.Diagnostics.Process.Start(Globals.RESEARCH_FOLDER);
                                            }
                                            catch (Exception ex)
                                            {
                                                MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        return null;
    }
    private string InvokeResearchMethod(string method_name, Client client, string param, bool in_search_result)
    {
        try
        {
            if (m_research_assembly != null)
            {
                Type assembly_type = m_research_assembly.GetType(m_research_assembly_name);
                if (assembly_type != null)
                {
                    MethodInfo method_info = assembly_type.GetMethod(method_name, BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
                    if (method_info != null)
                    {
                        object[] parameters = { client, param, in_search_result };
                        object obj = method_info.Invoke(null, parameters);
                        if (obj != null)
                        {
                            return obj.ToString();
                        }
                        return null;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        return null;
    }
    private void ResearchMethodsComboBox_SelectedIndexChanged(object sender, EventArgs e)
    {
        if (ResearchMethodsComboBox.SelectedItem != null)
        {
            string method_name = ResearchMethodsComboBox.SelectedItem.ToString();
            ToolTip.SetToolTip(this.ResearchMethodsComboBox, method_name);

            ResearchMethodParameterTextBox.BringToFront();
            if ((method_name.Contains("ByX")) || (method_name.Contains("WithX")))
            {
                ResearchMethodParameterTextBox.Text = "7";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "X");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if ((method_name.Contains("ByXY")) || (method_name.Contains("WithXY")))
            {
                ResearchMethodParameterTextBox.Text = "7,29";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "X,Y");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if ((method_name.Contains("ByXYZ")) || (method_name.Contains("WithXYZ")))
            {
                ResearchMethodParameterTextBox.Text = "7,29,139";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "X,Y,Z");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("AtPositions"))
            {
                ResearchMethodParameterTextBox.Text = "3,5";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "pos1,pos2");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if ((method_name.Contains("Repeated")) && (!method_name.Contains("Consecutive")))
            {
                ResearchMethodParameterTextBox.Text = "0";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Gap");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.EndsWith("Sound"))
            {
                ResearchMethodParameterTextBox.Text = "1433";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Hz");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.EndsWith("Few"))
            {
                ResearchMethodParameterTextBox.Text = "10000";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Number of required matches");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("31Verses"))
            {
                ResearchMethodParameterTextBox.Text = "0";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Positions and Distances\r\n0: Each verse separately\r\n1: All verses as one long text");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if ((method_name.Contains("TwoVerses")) || (method_name.Contains("TwinVerses")))
            {
                ResearchMethodParameterTextBox.Text = "All";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "All | P | AP | XP | C | AC | XC");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name == "nWords_kLetters")
            {
                ResearchMethodParameterTextBox.Text = "7,29";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "words,letters");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name == "nVerses_kWords")
            {
                ResearchMethodParameterTextBox.Text = "7,29";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "verses,words");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name == "nChapters_kVerses")
            {
                ResearchMethodParameterTextBox.Text = "7,29";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "chapters,verses");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("WithText"))
            {
                ResearchMethodParameterTextBox.Text = "مستقيم";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Text");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("Pivot"))
            {
                ResearchMethodParameterTextBox.Text = "16";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Pivot");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("Polygon"))
            {
                ResearchMethodParameterTextBox.Text = "3";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Regular polygon sides");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("Platonic"))
            {
                ResearchMethodParameterTextBox.Text = "4";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Platonic solid faces (4, 6, 8, 12, 20)");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name == "LetterFrequencySums")
            {
                ResearchMethodParameterTextBox.Text = "";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Phrase");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("InterestingVerses"))
            {
                ResearchMethodParameterTextBox.Text = "114, 6236";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Interesting number");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("MatchVerses"))
            {
                ResearchMethodParameterTextBox.Text = "3,4,5,6,7";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Indexes");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("Ranges"))
            {
                ResearchMethodParameterTextBox.Text = "5";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Range length");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("Sets"))
            {
                ResearchMethodParameterTextBox.Text = "2";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Set length");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else if (method_name.Contains("Index"))
            {
                ResearchMethodParameterTextBox.Text = "0";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, "Target difference");
                ResearchMethodParameterTextBox.Visible = true;
            }
            else // method doesn't need parameters
            {
                ResearchMethodParameterTextBox.Text = "";
                ToolTip.SetToolTip(this.ResearchMethodParameterTextBox, null);
                ResearchMethodParameterTextBox.Visible = false;
            }

            // must be done at end so we can trim Research methods
            //ToolTip.SetToolTip(this.ResearchMethodsComboBox, method_name);
        }
    }
