    private void ScriptCompileLabel_Click(object sender, EventArgs e)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            string source_code = ScriptTextBox.Text;
            if (source_code.Length > 0)
            {
                CompilerResults compiler_results = ScriptRunner.CompileCode(source_code);
                ScriptOutputTextBox.Text = "";
                if (compiler_results != null)
                {
                    if ((compiler_results.Errors.HasWarnings) || (compiler_results.Errors.HasErrors))
                    {
                        if (compiler_results.Errors.HasWarnings)
                        {
                            foreach (CompilerError error in compiler_results.Errors)
                            {
                                if (error.IsWarning)
                                {
                                    ScriptOutputTextBox.Text += ("Warning at line " + error.Line + ": " + error.ErrorText) + "\r\n";
                                }
                            }
                        }

                        ScriptOutputTextBox.Text += "\r\n";
                        if (compiler_results.Errors.HasErrors)
                        {
                            foreach (CompilerError error in compiler_results.Errors)
                            {
                                if (!error.IsWarning)
                                {
                                    ScriptOutputTextBox.Text += ("Error at line " + error.Line + ": " + error.ErrorText) + "\r\n";
                                }
                            }
                        }
                    }
                    else
                    {
                        m_compiled_assembly = compiler_results.CompiledAssembly;
                        if (m_compiled_assembly != null)
                        {
                            ScriptOutputTextBox.Text = "Script was compiled successfully.";
                            ScriptOutputTextBox.Refresh();
                        }
                    }

                    // in all cases, clear for next complation run
                    compiler_results.Errors.Clear();
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            if (sender != ScriptRunLabel)
                this.Cursor = Cursors.Default;
        }
    }
    private void ScriptRunLabel_Click(object sender, EventArgs e)
    {
        ScriptCompileLabel_Click(sender, e);

        // FIX: prevent race condition
        Thread.Sleep(10);

        if (sender != ScriptRunLabel)
            this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_compiled_assembly != null)
            {
                object[] args = new object[] { m_client, null };
                object result = ScriptRunner.Run(m_compiled_assembly, args, this.m_permission_set);
                if (result is bool)
                {
                    if ((bool)result == true)
                    {
                        int verse_count = m_client.FoundVerses.Count;
                        m_header_label_info = verse_count + ((verse_count == 1) ? " " + L[l]["verse"] : " " + L[l]["verses"]);
                        DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, true);

                        CloseScript();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void CloseScript()
    {
        if (ScriptTextBox.Visible)
        {
            ScriptTextBox.SendToBack();
            ScriptTextBox.Visible = false;
            ScriptOutputGroupBox.Visible = false;
            ScriptCompileLabel.Visible = false;
            ScriptRunLabel.Visible = false;
            ScriptOpenLabel.Visible = false;
            ScriptSaveLabel.Visible = false;
            ScriptSaveAsLabel.Visible = false;
            WordWrapLabel.Visible = true;
            InspectResultsLabel.Visible = true;

            UserRatioPresetLabel.Visible = (m_active_textbox == MainTextBox) && (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioNumericUpDown.Visible = (m_active_textbox == MainTextBox) && (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioScopeLabel.Visible = (m_active_textbox == MainTextBox) && (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioDelimiterLabel.Visible = true;
            UserRatioTypeLabel.Visible = (m_active_textbox == MainTextBox) && (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioLengthLabel.Visible = (m_active_textbox == MainTextBox) && (m_user_ratio_delimiter != UserRatioDelimiter.None);

            GenerateSentencesLabel.Visible = (m_active_textbox.SelectionLength > 0) && ((Globals.EDITION == Edition.Ultimate) || (Globals.EDITION == Edition.BigNumbers));
            GenerateSentencesDuplicateLettersCheckBox.Visible = (m_active_textbox != null) && (m_active_textbox.SelectionLength > 0) && ((Globals.EDITION == Edition.Ultimate) || (Globals.EDITION == Edition.BigNumbers));
        }
    }
