    private void BuildFonts(string fonts_folder)
    {
        if (m_quran_fonts == null)
        {
            m_quran_fonts = new List<Font>();
        }

        if (m_quran_fonts != null)
        {
            m_quran_fonts.Clear();

            DirectoryInfo folder = new DirectoryInfo(fonts_folder);
            if (folder != null)
            {
                FileInfo[] files = folder.GetFiles("*.*");
                if ((files != null) && (files.Length > 0))
                {
                    foreach (FileInfo file in files)
                    {
                        try
                        {
                            if (!String.IsNullOrEmpty(file.FullName))
                            {
                                Font font = FontBuilder.Build(file.FullName, DEFAULT_QURAN_FONT_SIZE * ((file.Name.Contains("Mushaf")) ? 1.33F : 1));
                                Thread.Sleep(100); // time to refresh Windows resources
                                if (font != null)
                                {
                                    m_quran_fonts.Add(font);
                                }
                            }
                        }
                        catch
                        {
                            // skip non-conformant font
                        }
                    }
                }
            }

            //???m_quran_fonts.Add(new Font("Andalus", 17.0F, FontStyle.Regular));
            m_quran_fonts.Add(new Font("Arial", 14.0F, FontStyle.Regular));
            m_quran_fonts.Add(new Font("Tahoma", 12.0F, FontStyle.Regular));
            m_quran_fonts.Add(new Font("Courier New", 11.0F, FontStyle.Bold));

            //// add system fonts
            //using (InstalledFontCollection fontsCollection = new InstalledFontCollection())
            //{
            //    FontFamily[] fontFamilies = fontsCollection.Families;
            //    foreach (FontFamily family in fontFamilies)
            //    {
            //        try
            //        {
            //            m_quran_fonts.Add(new Font(family.Name, 12.0F, FontStyle.Bold));
            //        }
            //        catch
            //        {
            //            // skip non-conformant font
            //        }
            //    }
            //}
        }
    }
    private void PopulateFontComboBox()
    {
        try
        {
            for (int i = 0; i < 3; i++)
                FontComboBox.SelectedIndexChanged -= new System.EventHandler(FontComboBox_SelectedIndexChanged);
            FontComboBox.BeginUpdate();

            if (m_quran_fonts != null)
            {
                FontComboBox.Items.Clear();
                foreach (Font quran_font in m_quran_fonts)
                {
                    FontComboBox.Items.Add(quran_font.Name);
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            FontComboBox.EndUpdate();
            FontComboBox.SelectedIndexChanged += new System.EventHandler(FontComboBox_SelectedIndexChanged);
        }
    }
    private void FontComboBox_SelectedIndexChanged(object sender, EventArgs e)
    {
        if (FontComboBox.SelectedIndex > -1)
        {
            ApplyFont(FontComboBox.SelectedIndex);
        }
    }
