    private Letter m_current_letter = null;
    private Word m_current_word = null;
    private Verse m_current_verse = null;
    private Chapter m_current_chapter = null;
    private void MainTextBox_TextChanged(object sender, EventArgs e)
    {
        if (
             ((sender != null) && (sender == m_active_textbox)) &&
             (
               (m_active_textbox.Focused) ||
               (ChaptersListBox.Focused) ||
               (ChapterComboBox.Focused) ||
               (ChapterVerseNumericUpDown.Focused) ||
               (ChapterWordNumericUpDown.Focused) ||
               (ChapterLetterNumericUpDown.Focused) ||
               (PageNumericUpDown.Focused) ||
               (StationNumericUpDown.Focused) ||
               (PartNumericUpDown.Focused) ||
               (GroupNumericUpDown.Focused) ||
               (HalfNumericUpDown.Focused) ||
               (QuarterNumericUpDown.Focused) ||
               (BowingNumericUpDown.Focused) ||
               (WordNumericUpDown.Focused) ||
               (LetterNumericUpDown.Focused) ||
               (FoundMatchesNumericUpDown.Focused)
             )
           )
        {
            m_current_letter = GetLetterAtCursor();
            m_current_word = GetWordAtCursor();
            m_current_verse = GetCurrentVerse();
            m_current_chapter = GetCurrentChapter();
            if (m_current_verse != null)
            {
                if (m_current_letter == null)
                {
                    m_current_letter = m_current_verse.Letters[m_current_verse.Letters.Count - 1];
                }
                if (m_current_word == null)
                {
                    m_current_word = m_current_verse.Words[m_current_verse.Words.Count - 1];
                }
            }
            if (m_current_word != null)
            {
                this.Text = GetCurrentWordDetails(m_current_word);
            }
            m_clicked_chapter = m_current_chapter;
            m_clicked_verse = m_current_verse;
            m_clicked_word = m_current_word;
            m_clicked_letter = m_current_letter;
            UpdateHeaderLabel();

            m_current_verses = GetDisplayedVerses();

            CalculateCurrentValue();

            BuildLetterFrequencies();
            DisplayLetterFrequencies();
        }
    }
    private void MainTextBox_SelectionChanged(object sender, EventArgs e)
    {
        if (
             ((sender != null) && (sender == m_active_textbox)) &&
             (
               ((m_active_textbox.Focused) && (!String.IsNullOrEmpty(m_active_textbox.Text))) ||
               (ChapterWordNumericUpDown.Focused) ||
               (ChapterLetterNumericUpDown.Focused) ||
               (WordNumericUpDown.Focused) ||
               (LetterNumericUpDown.Focused)
             )
           )
        {
            if (m_client != null)
            {
                m_usertext_mode = false;
                m_selection_mode = false;

                m_current_letter = GetLetterAtCursor();
                m_current_word = GetWordAtCursor();
                m_current_verse = GetVerseAtCursor();
                m_current_chapter = GetCurrentChapter();
                if (m_current_verse != null)
                {
                    if (m_current_letter == null)
                    {
                        m_current_letter = m_current_verse.Letters[m_current_verse.Letters.Count - 1];
                    }
                    if (m_current_word == null)
                    {
                        m_current_word = m_current_verse.Words[m_current_verse.Words.Count - 1];
                    }
                }
                if (m_current_word != null)
                {
                    this.Text = GetCurrentWordDetails(m_current_word);
                }
                m_clicked_chapter = m_current_chapter;
                m_clicked_verse = m_current_verse;
                m_clicked_word = m_current_word;
                m_clicked_letter = m_current_letter;

                /////?????
                if (m_current_verse != null)
                {
                    CurrentVerseIndex = GetVerseIndex(m_current_verse);
                    UpdatePlayerButtons(m_current_verse);
                }

                UpdateHeaderLabel();

                CalculateCurrentValue();

                BuildLetterFrequencies();
                DisplayLetterFrequencies();

                DisplayCurrentPositions();

                if (m_active_textbox.SelectionLength > 0)
                {
                    DisplayWordFrequencies();
                    this.AcceptButton = null;  // prevent stealing focus by this.AcceptButton = FindByTextButton;
                }
                else
                {
                    WordFrequencyListBoxLabel.Visible = false;
                    WordFrequencyListBox.Visible = false;
                    WordFrequencyWithDiacriticsCheckBox.Visible = false;
                }

                ShowHideGenerateSentences();

                List<Verse> verses = GetCurrentVerses();
                if (verses != null)
                {
                    DisplayTranslations(verses);
                    DisplaySymmetry();
                    DisplayPiephiDigits();
                    DisplayCVWLSequence();
                    DisplayValuesSequence();
                    DisplayDNASequence();
                }
                else
                {
                    TranslationTextBox.Text = null;
                    TranslationTextBox.Refresh();
                    TranslationsTextBox.Text = null;
                    TranslationsTextBox.Refresh();

                    m_translation_readonly = true;
                    UpdateTranslationReadOnly();
                    TranslationEditSaveLabel.Enabled = false;
                }
            }
        }
    }
    private void MainTextBox_KeyDown(object sender, KeyEventArgs e)
    {
        if ((e.Control) && (e.KeyCode == Keys.A))
        {
            if (m_active_textbox != null)
            {
                CalculateAndDisplayCounts();
                CalculateValueAndDisplayFactors();
            }
        }
        else if ((e.Control) && (e.KeyCode == Keys.C))
        {
            MenuItem_Copy(sender, e);
        }
        else if ((e.Control) && (e.KeyCode == Keys.D))
        {
            MenuItem_CopyVerses(sender, e);
        }
        else if ((e.Control) && (e.KeyCode == Keys.V))
        {
            MenuItem_Paste(sender, e);
        }
        else if ((e.Control) && (e.KeyCode == Keys.G))
        {
            MenuItem_GenerateSentences(sender, e);
        }
        else if ((e.Control) && (e.KeyCode == Keys.Space))
        {
            PlayerStopLabel_Click(null, null);
            e.Handled = true; // suppress annoying beep due to parent not having an AcceptButton
            e.SuppressKeyPress = true; // suppress annoying beep due to parent not having an AcceptButton
        }
        else if (e.KeyCode == Keys.Space)
        {
            PlayerPlayLabel_Click(null, null);  // pause/resume
            e.Handled = true; // suppress annoying beep due to parent not having an AcceptButton
            e.SuppressKeyPress = true; // suppress annoying beep due to parent not having an AcceptButton
        }
        else if ((e.Control) && (e.KeyCode == Keys.Down))
        {
            //PlayerNextLabel_Click(null, null);
            //e.Handled = true; // suppress annoying beep due to parent not having an AcceptButton
            //e.SuppressKeyPress = true; // suppress annoying beep due to parent not having an AcceptButton
        }
        else if ((e.Control) && (e.KeyCode == Keys.Up))
        {
            //PlayerPreviousLabel_Click(null, null);
            //e.Handled = true; // suppress annoying beep due to parent not having an AcceptButton
            //e.SuppressKeyPress = true; // suppress annoying beep due to parent not having an AcceptButton
        }

        if ((m_active_textbox.SelectionLength == 0) &&
             (
               ((m_active_textbox.GetLineFromCharIndex(m_active_textbox.SelectionStart) == 0) && (e.KeyCode == Keys.Up)) ||
               ((m_active_textbox.GetLineFromCharIndex(m_active_textbox.SelectionStart) == m_active_textbox.GetLineFromCharIndex(m_active_textbox.TextLength)) && (e.KeyCode == Keys.Down)) ||
               ((m_active_textbox.SelectionStart == 0) && (e.KeyCode == Keys.Right || e.KeyCode == Keys.PageUp || e.KeyCode == Keys.Home)) ||
               ((m_active_textbox.SelectionStart == m_active_textbox.TextLength) && (e.KeyCode == Keys.Left || e.KeyCode == Keys.PageDown || e.KeyCode == Keys.End))
             )
           )
        {
            e.Handled = true; // suppress annoying beep due to parent not having an AcceptButton
            e.SuppressKeyPress = true; // suppress annoying beep due to parent not having an AcceptButton
        }

        UpdateMouseCursor();
    }
