    private void MainTextBox_MouseLeave(object sender, EventArgs e)
    {
        // stop cursor flicker
        if (m_active_textbox != null)
        {
            if (m_active_textbox.Cursor != Cursors.Default)
            {
                m_active_textbox.Cursor = Cursors.Default;
            }
        }
    }
    private void MainTextBox_MouseDown(object sender, MouseEventArgs e)
    {
        if (e.Button == MouseButtons.Left)
        {
            if (ModifierKeys == Keys.Control)
            {
                // go to related words to word under mouse pointer
                FindRelatedWords(m_current_word);
            }
        }
        else if (e.Button == MouseButtons.Right)
        {
            // in case we come from UserTextTextBox
            if (m_active_textbox != null)
            {
                m_active_textbox.Focus();
                MainTextBox_SelectionChanged(m_active_textbox, null);

                // set cursor at mouse RIGHT-click location so we know which word to get related words for
                m_current_letter = GetLetterAtPointer(e);
                if (m_current_letter != null)
                {
                    m_current_word = m_current_letter.Word;
                    if (m_current_word != null)
                    {
                        m_current_verse = m_current_word.Verse;
                        if (m_current_verse != null)
                        {
                            m_current_chapter = m_current_verse.Chapter;
                        }
                    }
                }

                // if right-click outside selected text
                int start = m_active_textbox.GetCharIndexFromPosition(e.Location);
                if (
                     (start <= m_active_textbox.SelectionStart)
                     ||
                     (start > (m_active_textbox.SelectionStart + m_active_textbox.SelectionLength))
                   )
                {
                    m_active_textbox.Select(start, 0);
                }
            }
        }
    }
    private void MainTextBox_MouseMove(object sender, MouseEventArgs e)
    {
        // stop flickering
        if (
            (Math.Abs(m_previous_location.X - e.X) < 8)
            &&
            (Math.Abs(m_previous_location.Y - e.Y) < 8)
           )
        {
            return;
        }
        m_previous_location = e.Location;

        UpdateMouseCursor();

        // BuildPiephiDigits() uses m_current_letter.
        // DO NOT update with mouse move, only with mouse click
        Letter letter = GetLetterAtPointer(e);
        if (letter != null)
        {
            Word word = letter.Word;
            if (word != null)
            {
                this.Text = GetCurrentWordDetails(word);
            }
        }
    }
    private void MainTextBox_MouseUp(object sender, MouseEventArgs e)
    {
        // calculate the C V W L distances
        int chapter_number = ChapterComboBox.SelectedIndex + 1;
        int verse_number = (int)VerseNumericUpDown.Value;
        int word_number = (int)WordNumericUpDown.Value;
        int letter_number = (int)LetterNumericUpDown.Value;

        m_clicked_chapter_distance = chapter_number - m_clicked_chapter_number;
        m_clicked_verse_distance = verse_number - m_clicked_verse_number;
        m_clicked_word_distance = word_number - m_clicked_word_number;
        m_clicked_letter_distance = letter_number - m_clicked_letter_number;

        ChapterDiffTextBox.Text = m_clicked_chapter_distance.ToString();
        VerseDiffTextBox.Text = m_clicked_verse_distance.ToString();
        WordDiffTextBox.Text = m_clicked_word_distance.ToString();
        LetterDiffTextBox.Text = m_clicked_letter_distance.ToString();
        ChapterDiffTextBox.ForeColor = Numbers.GetNumberTypeColor(m_clicked_chapter_distance);
        VerseDiffTextBox.ForeColor = Numbers.GetNumberTypeColor(m_clicked_verse_distance);
        WordDiffTextBox.ForeColor = Numbers.GetNumberTypeColor(m_clicked_word_distance);
        LetterDiffTextBox.ForeColor = Numbers.GetNumberTypeColor(m_clicked_letter_distance);
        ChapterDiffTextBox.BackColor = (Numbers.Compare((int)m_clicked_chapter_distance, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Control;
        if (m_clicked_chapter_distance.IsInteresting())
            ChapterDiffTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
        if (m_clicked_chapter_distance.IsCarmichaelX())
            ChapterDiffTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
        if (m_clicked_chapter_distance.IsCarmichael())
            ChapterDiffTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
        VerseDiffTextBox.BackColor = (Numbers.Compare((int)m_clicked_verse_distance, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Control;
        if (m_clicked_verse_distance.IsInteresting())
            VerseDiffTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
        if (m_clicked_verse_distance.IsCarmichaelX())
            VerseDiffTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
        if (m_clicked_verse_distance.IsCarmichael())
            VerseDiffTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
        WordDiffTextBox.BackColor = (Numbers.Compare((int)m_clicked_word_distance, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Control;
        if (m_clicked_word_distance.IsInteresting())
            WordDiffTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
        if (m_clicked_word_distance.IsCarmichaelX())
            WordDiffTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
        if (m_clicked_word_distance.IsCarmichael())
            WordDiffTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
        LetterDiffTextBox.BackColor = (Numbers.Compare((int)m_clicked_letter_distance, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Control;
        if (m_clicked_letter_distance.IsInteresting())
            LetterDiffTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
        if (m_clicked_letter_distance.IsCarmichaelX())
            LetterDiffTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
        if (m_clicked_letter_distance.IsCarmichael())
            LetterDiffTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
        ChapterDiffTextBox.Refresh();
        VerseDiffTextBox.Refresh();
        WordDiffTextBox.Refresh();
        LetterDiffTextBox.Refresh();

        // backup info
        m_clicked_chapter_number = chapter_number;
        m_clicked_verse_number = verse_number;
        m_clicked_word_number = word_number;
        m_clicked_letter_number = letter_number;

        // use for distances in UpdateHeaderLabel()
        m_clicked_chapter = m_current_chapter;
        m_clicked_verse = m_current_verse;
        m_clicked_word = m_current_word;
        m_clicked_letter = m_current_letter;

        DisplayRelatedWordsInformation(m_clicked_word);
        DisplayGrammarInformation(m_clicked_word);

        Verse verse = GetCurrentVerse();
        if (verse != null)
        {
            m_player_looping_i = 0;

            // selected verses are dealt with by CalculateAndDisplayCounts 
        }
    }
