    private void MainTextBox_DoubleClick(object sender, EventArgs e)
    {
        try
        {
            for (int i = 0; i < 3; i++)
                MainTextBox.TextChanged -= new System.EventHandler(MainTextBox_TextChanged);
            for (int i = 0; i < 3; i++)
                MainTextBox.SelectionChanged -= new System.EventHandler(MainTextBox_SelectionChanged);
            MainTextBox.BeginUpdate();

            if (ModifierKeys == Keys.None)
            {
                // double clicking search result, takes us back to Main text displaying the whole chapter of the double-clicked verse
                if (m_found_verses_displayed)
                {
                    Verse verse = GetCurrentVerse();
                    if (verse != null)
                    {
                        GotoVerse(verse);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            MainTextBox.EndUpdate();
            MainTextBox.SelectionChanged += new System.EventHandler(MainTextBox_SelectionChanged);
            MainTextBox.TextChanged += new System.EventHandler(MainTextBox_TextChanged);
        }
    }
