    private void MainTextBox_MouseWheel(object sender, MouseEventArgs e)
    {
        if (ModifierKeys == Keys.Control)
        {
            if (e.Delta > 0)
            {
                ZoomInLabel_Click(null, null);
            }
            else
            {
                ZoomOutLabel_Click(null, null);
            }
        }
