    private void UpdateZoomFactor()
    {
        ZoomInLabel.Enabled = (m_text_zoom_factor <= (m_max_zoom_factor - m_zoom_factor_increment + Numbers.ERROR_MARGIN));
        ZoomOutLabel.Enabled = (m_text_zoom_factor >= (m_min_zoom_factor + m_zoom_factor_increment - Numbers.ERROR_MARGIN));

        bool can_zoom_in = m_text_zoom_factor <= (m_max_zoom_factor - m_zoom_factor_increment + Numbers.ERROR_MARGIN);
        bool can_zoom_out = m_text_zoom_factor >= (m_min_zoom_factor + m_zoom_factor_increment - Numbers.ERROR_MARGIN);
        if (can_zoom_in)
        {
            // zoom in
            m_text_zoom_factor += m_zoom_factor_increment;
            MainTextBox.ZoomFactor = m_text_zoom_factor;
            SearchResultTextBox.ZoomFactor = m_text_zoom_factor;
            // zoom out
            m_text_zoom_factor -= m_zoom_factor_increment;
            MainTextBox.ZoomFactor = m_text_zoom_factor;
            SearchResultTextBox.ZoomFactor = m_text_zoom_factor;
        }
        else if (can_zoom_out)
        {
            // zoom out
            m_text_zoom_factor -= m_zoom_factor_increment;
            MainTextBox.ZoomFactor = m_text_zoom_factor;
            SearchResultTextBox.ZoomFactor = m_text_zoom_factor;
            // zoom in
            m_text_zoom_factor += m_zoom_factor_increment;
            MainTextBox.ZoomFactor = m_text_zoom_factor;
            SearchResultTextBox.ZoomFactor = m_text_zoom_factor;
        }
        else
        {
            MainTextBox.ZoomFactor = m_text_zoom_factor;
            SearchResultTextBox.ZoomFactor = m_text_zoom_factor;
        }
    }
    private void ZoomInLabel_Click(object sender, EventArgs e)
    {
        if (PictureBox.Visible)
        {
            if (m_drawing_shape == DrawingShape.Lines)
                return;

            if (m_graphics_zoom_factor <= (m_max_zoom_factor - m_zoom_factor_increment + Numbers.ERROR_MARGIN))
            {
                PictureBox.ZoomIn();
                m_graphics_zoom_factor = PictureBox.ZoomFactor;
            }
            // re-check same condition after zoom_factor update
            ZoomInLabel.Enabled = (m_graphics_zoom_factor <= (m_max_zoom_factor - m_zoom_factor_increment + Numbers.ERROR_MARGIN));
            ZoomOutLabel.Enabled = true;

            RedrawImage();
        }
        else
        {
            if (m_text_zoom_factor <= (m_max_zoom_factor - m_zoom_factor_increment + Numbers.ERROR_MARGIN))
            {
                m_text_zoom_factor += m_zoom_factor_increment;

                MainTextBox.ZoomFactor = m_text_zoom_factor;
                SearchResultTextBox.ZoomFactor = m_text_zoom_factor;
                if (m_active_textbox != null)
                {
                    int selection_start = m_active_textbox.SelectionStart;
                    int selection_kength = m_active_textbox.SelectionLength;
                    if (selection_kength > 0)
                    {
                        m_active_textbox.SelectionStart = selection_start;
                        m_active_textbox.SelectionLength = selection_kength;
                    }
                }
            }
            // re-check same condition after zoom_factor update
            ZoomInLabel.Enabled = (m_text_zoom_factor <= (m_max_zoom_factor - m_zoom_factor_increment + Numbers.ERROR_MARGIN));
            ZoomOutLabel.Enabled = true;
        }
    }
    private void ZoomOutLabel_Click(object sender, EventArgs e)
    {
        if (PictureBox.Visible)
        {
            if (m_drawing_shape == DrawingShape.Lines)
                return;

            if (m_graphics_zoom_factor >= (m_min_zoom_factor + m_zoom_factor_increment - Numbers.ERROR_MARGIN))
            {
                PictureBox.ZoomOut();
                m_graphics_zoom_factor = PictureBox.ZoomFactor;
            }
            // re-check same condition after zoom_factor update
            ZoomOutLabel.Enabled = (m_graphics_zoom_factor >= (m_min_zoom_factor + m_zoom_factor_increment - Numbers.ERROR_MARGIN));
            ZoomInLabel.Enabled = true;
            RedrawImage();
        }
        else
        {
            if (m_text_zoom_factor >= (m_min_zoom_factor + m_zoom_factor_increment - Numbers.ERROR_MARGIN))
            {
                m_text_zoom_factor -= m_zoom_factor_increment;

                MainTextBox.ZoomFactor = m_text_zoom_factor;
                SearchResultTextBox.ZoomFactor = m_text_zoom_factor;
                if (m_active_textbox != null)
                {
                    int selection_start = m_active_textbox.SelectionStart;
                    int selection_kength = m_active_textbox.SelectionLength;
                    if (selection_kength > 0)
                    {
                        m_active_textbox.SelectionStart = selection_start;
                        m_active_textbox.SelectionLength = selection_kength;
                    }
                }
            }
            // re-check same condition after zoom_factor update
            ZoomOutLabel.Enabled = (m_text_zoom_factor >= (m_min_zoom_factor + m_zoom_factor_increment - Numbers.ERROR_MARGIN));
            ZoomInLabel.Enabled = true;
        }
    }
