    private string RemoveDuplicateLetters(string text)
    {
        if (String.IsNullOrEmpty(text))
            return "";

        string result = "";
        foreach (char c in text)
        {
            if (!result.Contains(c.ToString()))
            {
                result += c + " ";
            }
        }
        if (result.Length > 0)
        {
            result = result.Remove(result.Length - 1, 1);
        }

        return result;
    }
    private void GenerateAnagrams()
    {
        if (!String.IsNullOrEmpty(m_current_text))
        {
            string path = Globals.DATA_FOLDER + Path.DirectorySeparatorChar + "quran-words-" + m_client.NumerologySystem.TextMode + ".txt";
            if (!File.Exists(path))
            {
                Dictionary<string, int> word_frequency_dictionary = new Dictionary<string, int>();
                if (word_frequency_dictionary != null)
                {
                    foreach (Chapter chapter in m_client.Book.Chapters)
                    {
                        foreach (Verse verse in chapter.Verses)
                        {
                            foreach (Word word in verse.Words)
                            {
                                string word_text = word.Text.Simplify29();
                                if (word_frequency_dictionary.ContainsKey(word_text))
                                {
                                    word_frequency_dictionary[word_text]++;
                                }
                                else
                                {
                                    word_frequency_dictionary.Add(word_text, 1);
                                }
                            }
                        }
                    }

                    // sort dictionary by frequency
                    List<KeyValuePair<string, int>> list = new List<KeyValuePair<string, int>>(word_frequency_dictionary);
                    if (list != null)
                    {
                        list.Sort(
                            delegate (KeyValuePair<string, int> firstPair, KeyValuePair<string, int> nextPair)
                            {
                                return nextPair.Value.CompareTo(firstPair.Value);
                            }
                        );

                        StringBuilder str = new StringBuilder();
                        foreach (KeyValuePair<string, int> pair in list)
                        {
                            str.AppendLine(pair.Key.ToString());
                        }
                        FileHelper.SaveText(path, str.ToString());
                    }
                }
            }

            if (File.Exists(path))
            {
                string text = m_current_text.Simplify29();
                if (!GenerateSentencesDuplicateLettersCheckBox.Checked)
                {
                    text = RemoveDuplicateLetters(text);
                }
                List<string> sentences = Anagrams.GenerateAnagrams(path, text);
                sentences.Sort();

                if (Directory.Exists(Globals.STATISTICS_FOLDER))
                {
                    path = Globals.STATISTICS_FOLDER + Path.DirectorySeparatorChar + text + ".txt";
                    if (sentences != null)
                    {
                        using (StreamWriter writer = new StreamWriter(path, false, Encoding.Unicode))
                        {
                            writer.WriteLine("{0} sentences from {1}", sentences.Count, m_current_text);
                            writer.WriteLine("---------------------");
                            foreach (string sentence in sentences)
                            {
                                writer.WriteLine(sentence);
                            }
                        }

                        // show file content after save
                        FileHelper.DisplayFile(path);
                    }
                }
            }
        }
    }
