    private void UpdateWordWrapLabel(bool word_wrap)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (word_wrap)
        {
            if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "text_wrap.png"))
            {
                WordWrapLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "text_wrap.png");
            }
            ToolTip.SetToolTip(this.WordWrapLabel, L[l]["Unwrap"]);
        }
        else
        {
            if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "text_unwrap.png"))
            {
                WordWrapLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "text_unwrap.png");
            }
            ToolTip.SetToolTip(this.WordWrapLabel, L[l]["Wrap"]);
        }
        WordWrapLabel.Refresh();
    }
