    private int m_previous_index = -1;
    private void ChaptersListBox_MouseMove(object sender, MouseEventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (m_client != null)
        {
            if (m_client.Book != null)
            {
                int index = ChaptersListBox.IndexFromPoint(e.Location);
                if (index != m_previous_index)
                {
                    m_previous_index = index;
                    if ((index >= 0) && (index < m_client.Book.Chapters.Count))
                    {
                        Chapter chapter = m_client.Book.Chapters[index];
                        if (chapter != null)
                        {
                            int match_count = 0;
                            if (m_matches_per_chapter != null)
                            {
                                if ((index >= 0) && (index < m_matches_per_chapter.Length))
                                {
                                    match_count = m_matches_per_chapter[index];
                                }
                            }

                            string revelation_place = "";
                            switch (chapter.RevelationPlace)
                            {
                                case RevelationPlace.Makkah:
                                    revelation_place = L[l]["Makkah"];
                                    break;
                                case RevelationPlace.Medina:
                                    revelation_place = L[l]["Medina"];
                                    break;
                                default:
                                    revelation_place = "";
                                    break;
                            }

                            if (chapter.Verses != null)
                            {
                                if (chapter.Verses.Count > 2)
                                {
                                    ToolTip.SetToolTip(this.ChaptersListBox,
                                        chapter.TransliteratedName + " - " + chapter.EnglishName + " - " + chapter.Name + "\r\n" +
                                        L[l]["Number"] + "\t\t" + chapter.SortedNumber.ToString() + "\r\n" +
                                        L[l]["Revelation"] + "\t" + ((revelation_place.IsArabic()) ? "\t" : "") + chapter.RevelationOrder.ToString() + " - " + revelation_place + "\r\n" +
                                        L[l]["Verses"] + "\t\t" + chapter.Verses.Count.ToString() + "\r\n" +
                                        L[l]["Words"] + "\t\t" + chapter.Words.Count.ToString() + "\r\n" +
                                        L[l]["Letters"] + "\t\t" + chapter.Letters.Count.ToString() + "\r\n" +
                                        L[l]["Unique"] + "\t\t" + chapter.UniqueLetters.Count.ToString() + "\r\n" +
                                        (m_found_verses_displayed ? (L[l]["Matches"] + "\t\t" + match_count.ToString() + "\r\n") : "") + "\r\n" +
                                        chapter.Verses[0].Text + ((index == 41) ? ("\r\n" + chapter.Verses[1].Text) : "")
                                    );
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    private void ChaptersListBox_SelectedIndexChanged(object sender, EventArgs e)
    {
        if (sender == ChaptersListBox)
        {
            PlayerStopLabel_Click(null, null);

            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    if (m_found_verses_displayed)
                    {
                        // set chapter filter
                        List<Chapter> chapters = new List<Chapter>();
                        foreach (int index in ChaptersListBox.SelectedIndices)
                        {
                            chapters.Add(m_client.Book.Chapters[index]);
                        }
                        m_client.FilterChapters = chapters;

                        if (!String.IsNullOrEmpty(m_header_label_info))
                        {
                            int pos = m_header_label_info.IndexOf(" of ");
                            if (pos > -1)
                            {
                                m_header_label_info = m_header_label_info.Substring(pos + 4);
                            }
                            int selected_chapters_match_count = 0;
                            foreach (int index in ChaptersListBox.SelectedIndices)
                            {
                                if (m_matches_per_chapter != null)
                                {
                                    if ((index >= 0) && (index < m_matches_per_chapter.Length))
                                    {
                                        selected_chapters_match_count += m_matches_per_chapter[index];
                                    }
                                }
                            }
                            m_header_label_info = selected_chapters_match_count + " of " + m_header_label_info;
                        }

                        if (m_search_type == SearchType.Grammar)
                        {
                            if (m_client.FoundWords != null)
                            {
                                DisplayFoundWords(FINDBYGRAMMAR_MATCH_COLOR, false);
                            }
                        }
                        else if (m_search_type == SearchType.Repetition)
                        {
                            if (m_client.FoundWords != null)
                            {
                                DisplayFoundWords(FINDBYREPETITION_MATCH_COLOR, false);
                            }
                        }
                        else if (m_search_type == SearchType.Text)
                        {
                            if (m_client.FoundLetters != null)
                            {
                                DisplayFoundLetters(FINDBYTEXT_MATCH_COLOR, false);
                            }
                            else if (m_client.FoundWords != null)
                            {
                                DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, false);
                            }
                            else //if (m_client.FoundVerses != null)
                            {
                                DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                            }
                        }
                        else if (m_search_type == SearchType.Numbers)
                        {
                            switch (m_numbers_result_type)
                            {
                                case NumbersResultType.Letters:
                                    DisplayFoundLetters(FINDBYTEXT_MATCH_COLOR, false);
                                    break;
                                case NumbersResultType.LetterRanges:
                                    DisplayFoundLetterRanges(FINDBYTEXT_MATCH_COLOR, false);
                                    break;
                                case NumbersResultType.LetterSets:
                                    DisplayFoundLetterSets(FINDBYTEXT_MATCH_COLOR, false);
                                    break;

                                case NumbersResultType.Words:
                                    DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, false);
                                    break;
                                case NumbersResultType.WordRanges:
                                    DisplayFoundWordRanges(FINDBYTEXT_MATCH_COLOR, false);
                                    break;
                                case NumbersResultType.WordSets:
                                    DisplayFoundWordSets(FINDBYTEXT_MATCH_COLOR, false);
                                    break;

                                case NumbersResultType.Verses:
                                    DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                                    break;
                                case NumbersResultType.VerseRanges:
                                    DisplayFoundVerseRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.VerseSets:
                                    DisplayFoundVerseSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;

                                case NumbersResultType.Chapters:
                                    DisplayFoundChapters(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.ChapterRanges:
                                    DisplayFoundChapterRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.ChapterSets:
                                    DisplayFoundChapterSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;

                                case NumbersResultType.Pages:
                                    DisplayFoundPages(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.PageRanges:
                                    DisplayFoundPageRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.PageSets:
                                    DisplayFoundPageSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;

                                case NumbersResultType.Stations:
                                    DisplayFoundStations(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.StationRanges:
                                    DisplayFoundStationRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.StationSets:
                                    DisplayFoundStationSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;

                                case NumbersResultType.Parts:
                                    DisplayFoundParts(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.PartRanges:
                                    DisplayFoundPartRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.PartSets:
                                    DisplayFoundPartSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;

                                case NumbersResultType.Groups:
                                    DisplayFoundGroups(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.GroupRanges:
                                    DisplayFoundGroupRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.GroupSets:
                                    DisplayFoundGroupSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;

                                case NumbersResultType.Halfs:
                                    DisplayFoundHalfs(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.HalfRanges:
                                    DisplayFoundHalfRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.HalfSets:
                                    DisplayFoundHalfSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;

                                case NumbersResultType.Quarters:
                                    DisplayFoundQuarters(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.QuarterRanges:
                                    DisplayFoundQuarterRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.QuarterSets:
                                    DisplayFoundQuarterSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;

                                case NumbersResultType.Bowings:
                                    DisplayFoundBowings(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.BowingRanges:
                                    DisplayFoundBowingRanges(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;
                                case NumbersResultType.BowingSets:
                                    DisplayFoundBowingSets(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    break;

                                default:
                                    DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                                    break;
                            }
                        }
                        else if (m_search_type == SearchType.Similarity)
                        {
                            DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                        }
                        else if (m_search_type == SearchType.Frequency)
                        {
                            switch (m_frequency_result_type)
                            {
                                case FrequencyResultType.Words:
                                    {
                                        DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, false);
                                    }
                                    break;
                                case FrequencyResultType.Sentences:
                                    {
                                        DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                                    }
                                    break;
                                case FrequencyResultType.Verses:
                                    {
                                        DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                                    }
                                    break;
                                case FrequencyResultType.Chapters:
                                    {
                                        DisplayFoundChapters(FINDBYGROUP_COLOR_1, FINDBYGROUP_COLOR_2, false);
                                    }
                                    break;
                            }
                        }
                        else
                        {
                            DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                        }
                    }
                    else
                    {
                        UpdateClientSelectionFromChaptersListBox();
                        if (ChapterSelectionComboBox.Items.Count > 0)
                        {
                            ChapterSelectionComboBox.SelectedIndex = 0;
                        }

                        if (PictureBox.Visible)
                        {
                            RedrawImage();
                        }
                        else
                        {
                            DisplaySelection(true);
                        }
                    }

                    ChaptersListBox.Focus();
                }
            }
        }
    }

    private bool m_pin_chapter1 = false;
    private ChapterCompareBy m_chapter_compare_by = ChapterCompareBy.Compilation;
    private ChapterCompareOrder m_chapter_compare_order = ChapterCompareOrder.Ascending;
    private void PinChapter1CheckBox_CheckStateChanged(object sender, EventArgs e)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    if (m_client.Selection != null)
                    {
                        // backup selection verses
                        List<Verse> backup_verses = new List<Verse>();
                        if (m_client.Selection.Scope == SelectionScope.Verse)
                        {
                            if (m_client.Selection.Indexes != null)
                            {
                                foreach (int index in m_client.Selection.Indexes)
                                {
                                    if ((index >= 0) && (index < m_client.Book.Verses.Count))
                                    {
                                        backup_verses.Add(m_client.Book.Verses[index]);
                                    }
                                }
                            }
                        }

                        m_pin_chapter1 = PinChapter1CheckBox.Checked;
                        m_client.Book.SortChapters(m_chapter_compare_by, m_chapter_compare_order, m_pin_chapter1, m_client.NumerologySystem.AddDistancesWithinChapters, m_with_diacritics);

                        // restore selection verses
                        if (m_client.Selection.Scope == SelectionScope.Verse)
                        {
                            if (m_client.Selection.Indexes != null)
                            {
                                List<int> verse_indexes = new List<int>();
                                foreach (Verse verse in backup_verses)
                                {
                                    verse_indexes.Add(verse.Number - 1);
                                }
                                m_client.Selection = new Selection(m_client.Book, SelectionScope.Verse, verse_indexes);
                            }
                        }

                        // display chapters in new order
                        DisplaySortedChapters();
                    }
                }
            }
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void ChapterSortComboBox_SelectedIndexChanged(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    if (m_client.Selection != null)
                    {
                        // backup selection
                        List<Verse> backup_verses = new List<Verse>();
                        if (m_client.Selection.Scope == SelectionScope.Verse)
                        {
                            if (m_client.Selection.Indexes != null)
                            {
                                foreach (int index in m_client.Selection.Indexes)
                                {
                                    if ((index >= 0) && (index < m_client.Book.Verses.Count))
                                    {
                                        backup_verses.Add(m_client.Book.Verses[index]);
                                    }
                                }
                            }
                        }

                        // do chapter sorting
                        string selected_item_text = ChapterSortComboBox.SelectedItem.ToString();
                        ToolTip.SetToolTip(this.ChapterSortComboBox, L[l][selected_item_text]);
                        if (selected_item_text.Contains(" + "))
                            selected_item_text = selected_item_text.Replace(" + ", "Plus");
                        if (selected_item_text.Contains(" - "))
                            selected_item_text = selected_item_text.Replace(" - ", "Minus");
                        if (selected_item_text.Contains(" × "))
                            selected_item_text = selected_item_text.Replace(" × ", "Multiply");
                        if (selected_item_text.Contains(" ÷ "))
                            selected_item_text = selected_item_text.Replace(" ÷ ", "Divide");
                        m_chapter_compare_by = (ChapterCompareBy)Enum.Parse(typeof(ChapterCompareBy), selected_item_text.Substring(3));
                        m_client.Book.SortChapters(m_chapter_compare_by, m_chapter_compare_order, m_pin_chapter1, m_client.NumerologySystem.AddDistancesWithinChapters, m_with_diacritics);

                        PinChapter1CheckBox.Visible = ((Chapter.CompareBy != ChapterCompareBy.Compilation) && (Chapter.CompareBy != ChapterCompareBy.Revelation));

                        // restore selection
                        if (m_client.Selection.Scope == SelectionScope.Verse)
                        {
                            if (m_client.Selection.Indexes != null)
                            {
                                List<int> verse_indexes = new List<int>();
                                foreach (Verse verse in backup_verses)
                                {
                                    verse_indexes.Add(verse.Number - 1);
                                }
                                m_client.Selection = new Selection(m_client.Book, SelectionScope.Verse, verse_indexes);
                            }
                        }

                        // display chapters in new order
                        DisplaySortedChapters();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
