    private void UpdateChapterSortControls()
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        this.Cursor = Cursors.WaitCursor;
        try
        {
            for (int i = 0; i < 3; i++)
                PinChapter1CheckBox.CheckStateChanged -= new System.EventHandler(PinChapter1CheckBox_CheckStateChanged);
            for (int i = 0; i < 3; i++)
                ChapterSortComboBox.SelectedIndexChanged -= new System.EventHandler(ChapterSortComboBox_SelectedIndexChanged);
            for (int i = 0; i < 3; i++)
                ChapterSortLabel.Click -= new System.EventHandler(ChapterSortLabel_Click);

            string selected_item_text = "By " + Chapter.CompareBy.ToString();
            ToolTip.SetToolTip(this.ChapterSortComboBox, L[l][selected_item_text]);
            if (selected_item_text.Contains("Plus"))
                selected_item_text = selected_item_text.Replace("Plus", " + ");
            if (selected_item_text.Contains("Minus"))
                selected_item_text = selected_item_text.Replace("Minus", " - ");
            if (selected_item_text.Contains("Multiply"))
                selected_item_text = selected_item_text.Replace("Multiply", " × ");
            if (selected_item_text.Contains("Divide"))
                selected_item_text = selected_item_text.Replace("Divide", " ÷ ");
            ChapterSortComboBox.SelectedItem = selected_item_text;

            PinChapter1CheckBox.Checked = Chapter.PinChapter1;
            PinChapter1CheckBox.Visible = ((Chapter.CompareBy != ChapterCompareBy.Compilation) && (Chapter.CompareBy != ChapterCompareBy.Revelation));

            if (Chapter.CompareOrder == ChapterCompareOrder.Ascending)
            {
                if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "arrow_up.png"))
                {
                    ChapterSortLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "arrow_up.png");
                    ToolTip.SetToolTip(this.ChapterSortLabel, L[l]["Ascending"]);
                }
            }
            else
            {
                if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "arrow_down.png"))
                {
                    ChapterSortLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "arrow_down.png");
                    ToolTip.SetToolTip(this.ChapterSortLabel, L[l]["Descending"]);
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            ChapterSortLabel.Click += new System.EventHandler(ChapterSortLabel_Click);
            PinChapter1CheckBox.CheckStateChanged += new System.EventHandler(PinChapter1CheckBox_CheckStateChanged);
            ChapterSortComboBox.SelectedIndexChanged += new System.EventHandler(ChapterSortComboBox_SelectedIndexChanged);
            this.Cursor = Cursors.Default;
        }
    }
