    private void InspectChaptersLabel_Click(object sender, EventArgs e)
    {
        if (m_client != null)
        {
            if (WordFrequencyListBox.Visible)
            {
                InspectWordFrequencies();
            }
            else
            {
                List<Chapter> chapters = null;
                if (m_found_verses_displayed)
                {
                    if (m_client.Book != null)
                    {
                        chapters = m_client.Book.GetChapters(m_client.FoundVerses);
                    }
                }
                else
                {
                    if (m_client.Selection != null)
                    {
                        chapters = m_client.Selection.Chapters;
                    }
                }

                string result = null;
                if (chapters != null)
                {
                    result = DisplayInformationWithMatches(chapters);
                }

                StringBuilder str = new StringBuilder();
                foreach (Chapter chapter in chapters)
                {
                    str.Append("." + chapter.SortedNumber);
                }
                if (str.Length > MAX_SCOPE_TEXT_LENGTH)
                {
                    str.Remove(MAX_SCOPE_TEXT_LENGTH, str.Length - MAX_SCOPE_TEXT_LENGTH);
                    int pos = str.ToString().LastIndexOf('.');
                    if (pos > -1)
                    {
                        str.Remove(pos, str.Length - pos);
                    }

                    if (str[str.Length - 1] == '.')
                    {
                        str.Append("..");
                    }
                    else
                    {
                        str.Append("...");
                    }
                }

                if (m_client.NumerologySystem != null)
                {
                    string filename = m_client.NumerologySystem.Name + "_" + "Chapters" + m_chapter_compare_by.ToString() + m_chapter_compare_order.ToString() + str.ToString() + ".txt";
                    if (Directory.Exists(Globals.STATISTICS_FOLDER))
                    {
                        string path = Globals.STATISTICS_FOLDER + Path.DirectorySeparatorChar + filename;
                        FileHelper.SaveText(path, result);
                        FileHelper.DisplayFile(path);
                    }
                }
            }
        }
    }
