    private void PlayerPlayLabel_Click(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        try
        {
            if (m_player != null)
            {
                //m_break_playing = false;
                PlayerStopLabel.Enabled = true;
                PlayerStopLabel.Refresh();

                if ((m_player.Closed) || (m_player.Stopped) || (m_player.Paused))
                {
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "player_pause.png"))
                    {
                        PlayerPlayLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "player_pause.png");
                    }
                    ToolTip.SetToolTip(this.PlayerPlayLabel, L[l]["Pause"]);
                    PlayerPlayLabel.Refresh();

                    if ((m_player.Closed) || (m_player.Stopped))
                    {
                        m_break_playing = false;
                        PlayFromCurrentVerse();
                    }
                    else if (m_player.Paused)
                    {
                        m_player.Play(); // resume
                    }
                }
                else if (m_player.Playing)
                {
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "player_play.png"))
                    {
                        PlayerPlayLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "player_play.png");
                    }
                    ToolTip.SetToolTip(this.PlayerPlayLabel, L[l]["Play"]);
                    PlayerPlayLabel.Refresh();

                    m_player.Pause(); // pause play
                }
            }
        }
        catch
        {
            PlayerStopLabel_Click(null, null);
        }
    }
