    private void DownloadVerseAudioFile(Verse verse)
    {
        if (verse == null)
        {
            m_audio_filepath = Globals.AUDIO_FOLDER + Path.DirectorySeparatorChar + "audhubillah" + "." + RecitationInfo.FileType;
        }
        else // mirror remote_folder locally
        {
            string audio_folder = Globals.AUDIO_FOLDER + Path.DirectorySeparatorChar + m_reciter;
            if (!Directory.Exists(audio_folder)) // create to fill with downloaded files
            {
                Directory.CreateDirectory(audio_folder);
            }

            string audio_path = null;
            if (verse.Chapter != null)
            {
                audio_path = verse.Chapter.Number.ToString("000") + verse.NumberInChapter.ToString("000") + "." + RecitationInfo.FileType;

                if (Directory.Exists(audio_folder))
                {
                    m_audio_filepath = audio_folder + Path.DirectorySeparatorChar + verse.Chapter.Number.ToString("000") + Path.DirectorySeparatorChar + audio_path;
                }
                if (!File.Exists(m_audio_filepath)) // if no local audio file, find it in external filepath
                {
                    audio_folder = Globals.EXTERNAL_AUDIO_FOLDER + Path.DirectorySeparatorChar + m_reciter;
                    if (Directory.Exists(audio_folder))
                    {
                        m_audio_filepath = audio_folder + Path.DirectorySeparatorChar + verse.Chapter.Number.ToString("000") + Path.DirectorySeparatorChar + audio_path;
                    }
                    if (!File.Exists(m_audio_filepath)) // if no external audio file, download it
                    {
                        DownloadAudioFile(audio_path);
                    }
                }
            }
        }
    }
    private void DownloadAudioFile(string audio_path)
    {
        try
        {
            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    if (m_client.Book.RecitationInfos != null)
                    {
                        string recitation_url = null;
                        foreach (string key in m_client.Book.RecitationInfos.Keys)
                        {
                            if (m_client.Book.RecitationInfos[key].Folder == m_reciter)
                            {
                                recitation_url = RecitationInfo.UrlPrefix + m_client.Book.RecitationInfos[key].Url + "/" + audio_path;
                                break;
                            }
                        }

                        Downloader.Download(recitation_url, m_audio_filepath);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
    }
    private string GetVerseAudioFilename(int verse_index)
    {
        if (m_client != null)
        {
            if (m_client.Book != null)
            {
                if (m_client.Book.Verses != null)
                {
                    if ((verse_index >= 0) && (verse_index < m_client.Book.Verses.Count))
                    {
                        Verse verse = m_client.Book.Verses[verse_index];
                        if (verse != null)
                        {
                            if (verse.Chapter != null)
                            {
                                return (verse.Chapter.Number.ToString("000") + verse.NumberInChapter.ToString("000") + "." + RecitationInfo.FileType);
                            }
                        }
                    }
                }
            }
        }
        return "000000.mp3";
    }
    private string GetVerseAudioFilepath(int verse_index)
    {
        if (m_client != null)
        {
            if (m_client.Book != null)
            {
                if (m_client.Book.Verses != null)
                {
                    if ((verse_index >= 0) && (verse_index < m_client.Book.Verses.Count))
                    {
                        Verse verse = m_client.Book.Verses[verse_index];
                        if (verse != null)
                        {
                            if (verse.Chapter != null)
                            {
                                return (verse.Chapter.Number.ToString("000") + "/" + verse.Chapter.Number.ToString("000") + verse.NumberInChapter.ToString("000") + "." + RecitationInfo.FileType);
                            }
                        }
                    }
                }
            }
        }
        return "000/000000.mp3";
    }
