    private void TranslationApplySettingsLabel_Click(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        TranslatorsCheckedListBox.Visible = !TranslatorsCheckedListBox.Visible;
        TranslationCancelSettingsLabel.Visible = TranslatorsCheckedListBox.Visible;

        if (TranslatorsCheckedListBox.Visible)
        {
            TranslatorsCheckedListBox.BringToFront();
            TranslationCancelSettingsLabel.BringToFront();

            if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "apply.png"))
            {
                TranslationApplySettingsLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "apply.png");
            }
            ToolTip.SetToolTip(this.TranslationApplySettingsLabel, L[l]["Download translations"]);
        }
        else // download any newly checked translation(s)
        {
            TranslatorsCheckedListBox.SendToBack();
            TranslationCancelSettingsLabel.SendToBack();

            if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "settings.png"))
            {
                TranslationApplySettingsLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "settings.png");
            }
            ToolTip.SetToolTip(this.TranslationApplySettingsLabel, L[l]["Add/Remove translations"]);

            int index_of_first_new_translation = DownloadTranslations();
            if ((index_of_first_new_translation >= 0) && (index_of_first_new_translation < TranslatorComboBox.Items.Count))
            {
                TranslatorComboBox.SelectedIndex = index_of_first_new_translation;
            }

            this.AcceptButton = null;
        }
    }
    private void TranslationCancelSettingsLabel_Click(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        TranslatorsCheckedListBox.Visible = false;
        TranslatorsCheckedListBox.SendToBack();
        TranslationCancelSettingsLabel.SendToBack();
        TranslationCancelSettingsLabel.Visible = false;

        if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "settings.png"))
        {
            TranslationApplySettingsLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "settings.png");
        }
        ToolTip.SetToolTip(this.TranslationApplySettingsLabel, L[l]["Add/Remove translations"]);

        // remove any new user checkes 
        PopulateTranslatorsCheckedListBox();

        this.AcceptButton = null;
    }
    private bool m_show_all_translations = true;
    private void AllTranslatorsCheckBox_CheckedChanged(object sender, EventArgs e)
    {
        m_show_all_translations = AllTranslatorsCheckBox.Checked;

        TranslationsTextBox.WordWrap = m_word_wrap_translation_textbox && !m_show_all_translations;
        TranslatorsComboBox.Enabled = !m_show_all_translations;
        TranslatorComboBox_SelectedIndexChanged(null, null);
        ApplyTranslationFontAndColor();
