    private List<Verse> GetSearchScopeVerses()
    {
        List<Verse> result = null;
        switch (m_client.SearchScope)
        {
            case SearchScope.Book:
                {
                    if (m_client.Book != null)
                    {
                        result = m_client.Book.Verses;
                    }
                }
                break;
            case SearchScope.Selection:
                {
                    if (m_client.Selection != null)
                    {
                        result = m_client.Selection.Verses;
                    }
                }
                break;
            case SearchScope.Result:
                {
                    result = m_client.FoundVerses;
                }
                break;
        }
        return result;
    }
    private string GetWordInformation(Word word)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return null;

        if (m_emlaaei_text)
            return null;

        if (m_client != null)
        {
            if (word != null)
            {
                StringBuilder roots = new StringBuilder();
                if (word.Roots != null)
                {
                    if (word.Roots.Count > 0)
                    {
                        foreach (string root in word.Roots)
                        {
                            roots.Append(root + " | ");
                        }
                        roots.Remove(roots.Length - 3, 3);
                    }
                }

                return
                    word.Transliteration + SPACE_GAP +
                    word.Text + SPACE_GAP +
                    word.Meaning + SPACE_GAP +
                    roots + "\r\n" +
                    L[l]["Chapter"] + "  " + word.Verse.Chapter.Number /*+ " " + L[l][word.Verse.Chapter.Name]*/ + SPACE_GAP +
                    L[l]["Verse"] + "  " + word.Verse.NumberInChapter /*+ "-" + word.Verse.Number*/ + SPACE_GAP +
                    L[l]["Word"] + "  " + word.NumberInVerse /*+ "-" + word.NumberInChapter + "-" + word.Number*/ + SPACE_GAP +
                    ((m_current_letter != null) ? ("\t" + m_current_letter.Text + SPACE_GAP + SPACE_GAP) : "") +
                    word.Occurrence.ToString() + "/" + word.Frequency.ToString() + SPACE_GAP +
                    m_client.CalculateValue(word).ToString();
            }
        }
        return null;
    }
    private string GetRelatedWordsInformation(Word word)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return null;

        if (m_emlaaei_text)
            return null;

        if (word != null)
        {
            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    string result = null;
                    int words_per_line = 0;
                    int max_words_per_line = 10;
                    Dictionary<Word, int> related_words_dictionary = m_client.Book.GetRelatedWords(word);
                    if (related_words_dictionary != null)
                    {
                        StringBuilder str = new StringBuilder();
                        if (related_words_dictionary.Count > 0)
                        {
                            Dictionary<string, int> unique_related_words_dictionary = m_client.Book.GetUniqueRelatedWords(word);
                            if (unique_related_words_dictionary != null)
                            {
                                str.AppendLine(related_words_dictionary.Count.ToString() + " (" + unique_related_words_dictionary.Count.ToString() + ")" + "  " + L[l]["related words"] + ": " + word.Root);

                                foreach (string text in unique_related_words_dictionary.Keys)
                                {
                                    words_per_line++;
                                    str.Append(unique_related_words_dictionary[text] + " " + text + (((words_per_line % max_words_per_line) == 0) ? "\r\n" : "\t"));
                                }
                                if (str.Length > 1)
                                {
                                    str.Remove(str.Length - 1, 1); // \t
                                }
                                str.AppendLine();

                                result = str.ToString();
                            }
                        }
                    }
                    return result;
                }
            }
        }
        return null;
    }
    private string GetCurrentWordDetails(Word word)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return null;

        string result = "";

        if (m_client != null)
        {
            if (word != null)
            {
                // in all cases
                result = Application.ProductName + " | ";

                string word_info = null; //GetWordInformation(word);
                if (ModifierKeys == Keys.Control)
                {
                    word_info = GetWordInformation(word);

                    word_info += "\r\n\r\n";
                    word_info += GetGrammarInformation(word);

                    word_info += "\r\n\r\n";
                    word_info += GetRelatedWordsInformation(word);
                }
                ToolTip.SetToolTip(this.m_active_textbox, word_info);

                // display word info at application caption
                result +=
                (
                    L[l]["Chapter"] + " " + word.Verse.Chapter.SortedNumber + SPACE_GAP +
                    L[l]["Verse"] + " " + word.Verse.NumberInChapter + "-" + word.Verse.Number + SPACE_GAP +
                    L[l]["Word"] + " " + word.NumberInVerse + "-" + word.NumberInChapter + "-" + word.Number + SPACE_GAP +
                    word.Transliteration + SPACE_GAP +
                    word.Text + SPACE_GAP +
                    word.Meaning + SPACE_GAP +
                    word.Root + SPACE_GAP +
                    word.Occurrence.ToString() + "/" + word.Frequency.ToString() + SPACE_GAP +
                    m_client.CalculateValue(word).ToString()
                );
            }
        }

        return result;
    }
    private string GetRelatedVersesInformation(Word word)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return null;

        if (m_emlaaei_text)
            return null;

        if (word != null)
        {
            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    string result = null;
                    List<Verse> related_verses = m_client.Book.GetRelatedVerses(word);
                    if (related_verses != null)
                    {
                        StringBuilder str = new StringBuilder();
                        str.AppendLine(related_verses.Count.ToString() + "  " + L[l]["related verses"] + ":");

                        foreach (Verse related_verse in related_verses)
                        {
                            str.AppendLine(related_verse.Text);
                        }
                        str.AppendLine();

                        result = str.ToString();
                    }
                    return result;
                }
            }
        }
        return null;
    }
    private void DisplayRelatedWordsInformation(Word word)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (m_emlaaei_text)
            return;

        if (
             (m_text_display_mode == TextDisplayMode.Both) ||
             (m_text_display_mode == TextDisplayMode.TranslationOnly)
           )
        {
            if (
                (TabControl.SelectedTab == TranslationTabPage) ||
