    private bool m_piephi_digits_right_to_left = false;
    private enum PiephiDigitsType
    {
        pi,
        e,
        phi,
        pi_e,
        pi_phi,
        e_phi,
        pi_e_phi
    };
    private void PopulatePiephiDigitsTypeComboBox()
    {
        PiephiDigitsTypeComboBox.Items.Clear();
        try
        {
            for (int i = 0; i < 3; i++)
                PiephiDigitsTypeComboBox.SelectedIndexChanged -= new System.EventHandler(PiephiDigitsTypeComboBox_SelectedIndexChanged);

            PiephiDigitsTypeComboBox.BeginUpdate();
            PiephiDigitsTypeComboBox.Items.Clear();
            foreach (PiephiDigitsType item in Enum.GetValues(typeof(PiephiDigitsType)))
            {
                PiephiDigitsTypeComboBox.Items.Add(item + " digits");
            }
            if (PiephiDigitsTypeComboBox.Items.Count > 0)
            {
                PiephiDigitsTypeComboBox.SelectedIndex = 0;
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            PiephiDigitsTypeComboBox.EndUpdate();
            PiephiDigitsTypeComboBox.SelectedIndexChanged += new System.EventHandler(PiephiDigitsTypeComboBox_SelectedIndexChanged);
        }
    }
