    private void PiephiDigitsTypeComboBox_SelectedIndexChanged(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (
             (m_text_display_mode == TextDisplayMode.Both) ||
             (m_text_display_mode == TextDisplayMode.TranslationOnly)
           )
        {
            if (TabControl.SelectedTab == PiephiDigitsTabPage)
            {
                if (PiephiDigitsTypeComboBox.SelectedItem != null)
                {
                    PiephiDigitsType piephi_digits_type = (PiephiDigitsType)Enum.Parse(typeof(PiephiDigitsType), PiephiDigitsTypeComboBox.SelectedItem.ToString().Replace(" digits", ""));
                    //if (!String.IsNullOrEmpty(m_current_text))
                    {
                        long total_value = 0L;

                        string text = BuildPiephiDigits(piephi_digits_type, m_current_text);
                        if (!String.IsNullOrEmpty(text))
                        {
                            text = text.Replace("\r", "");

                            StringBuilder str = new StringBuilder();
                            char[] separators = { '\n' };
                            string[] lines = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
                            foreach (string line in lines)
                            {
                                long value = 0L;
                                string[] parts = line.Split();
                                foreach (string part in parts)
                                {
                                    long number = 0L;
                                    if (long.TryParse(part, out number))
                                    {
                                        value += number;
                                    }
                                    else
                                    {
                                        // number is too large ... break
                                        value = 0L;
                                        break;
                                    }
                                }
                                str.AppendLine(line + "\t" + value.ToString() + ((m_piephi_digits_show_factors) ? ("\t" + Numbers.FactorizeToString(value)) : ""));
                                total_value += value;
                            }
                            str.AppendLine(L[l]["Total"] + "\t" + total_value.ToString() + ((m_piephi_digits_show_factors) ? ("\t" + Numbers.FactorizeToString(total_value)) : ""));

                            PiephiDigitsTextBox.Text = str.ToString();
                        }

                        FactorizeValue(total_value, piephi_digits_type.ToString());
                    }
                }
            }
        }
    }
