    private string BuildPiephiDigits(PiephiDigitsType piephi_digits_type, string text)
    {
        if (String.IsNullOrEmpty(text))
            return null;

        // if some text is selected then digit_shift = m_current_letter (not GetLetterAtCursor),
        // else                          digit_shift = first letter in line
        int digit_shift = 0;
        if (!m_piephi_start_from_first_digit)
        {
            if (m_active_textbox != null)
            {
                if (m_active_textbox.SelectionLength > 0)
                {
                    if (m_current_letter != null)
                    {
                        digit_shift = m_current_letter.Number - 1;
                    }
                }
                else // current line text
                {
                    if (m_current_letter != null)
                    {
                        if (m_current_letter.Word != null)
                        {
                            Verse verse = m_current_letter.Word.Verse;
                            if (verse != null)
                            {
                                digit_shift = verse.Words[0].Letters[0].Number - 1;
                            }
                        }
                    }
                }
            }
        }

        StringBuilder str = new StringBuilder();
        if (m_client != null)
        {
            if (m_client.NumerologySystem != null)
            {
                if (m_client.Selection != null)
                {
                    text = text.Replace("\r", "");
                    text = text.Replace("\t", "");
                    text = text.Replace("_", "");
                    text = text.Replace(Constants.ORNATE_RIGHT_PARENTHESIS, "");
                    text = text.Replace(Constants.ORNATE_LEFT_PARENTHESIS, "");
                    foreach (char character in Constants.INDIAN_DIGITS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    foreach (char character in Constants.ARABIC_DIGITS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    foreach (char character in Constants.SYMBOLS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    foreach (char character in Constants.STOPMARKS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    foreach (char character in Constants.QURANMARKS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    text = text.Replace("\n ", "\n"); // quran marks
                    text = text.Replace(" \n", "\n"); // sijood marks
                    if (!m_with_diacritics)
                    {
                        text = text.Simplify(m_client.NumerologySystem.TextMode);
                    }
                    while (text.Contains("  "))
                    {
                        text = text.Replace("  ", " ");
                    }
                    text = text.Trim();

                    char[] separators = { '\n' };
                    string[] lines = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);

                    int[] values = null;
                    switch (piephi_digits_type)
                    {
                        case PiephiDigitsType.pi:
                            {
                                values = Numbers.PiDigits;
                            }
                            break;
                        case PiephiDigitsType.e:
                            {
                                values = Numbers.EDigits;
                            }
                            break;
                        case PiephiDigitsType.phi:
                            {
                                values = Numbers.PhiDigits;
                            }
                            break;
                        case PiephiDigitsType.pi_e:
                            {
                                values = Numbers.PiEDigits;
                            }
                            break;
                        case PiephiDigitsType.pi_phi:
                            {
                                values = Numbers.PiPhiDigits;
                            }
                            break;
                        case PiephiDigitsType.e_phi:
                            {
                                values = Numbers.EPhiDigits;
                            }
                            break;
                        case PiephiDigitsType.pi_e_phi:
                            {
                                values = Numbers.PiEPhiDigits;
                            }
                            break;
                        default:
                            break;
                    }

                    if (values != null)
                    {
                        long value = 0L;
                        int i = digit_shift;

                        if (m_piephi_digits_right_to_left)
                        {
                            int pos = 0;
                            foreach (string line in lines)
                            {
                                string[] word_texts = line.Split(' ');
                                foreach (string word_text in word_texts)
                                {
                                    // base-10 digit places
                                    int place_value = 1;
                                    foreach (char c in word_text)
                                    {
                                        if ((i >= 0) && (i < values.Length))
                                        {
                                            value += values[i] * place_value;
                                            str.Insert(pos, values[i].ToString());
                                            i++;
                                            place_value *= 10;
                                        }
                                    }
                                    str.Insert(pos, " ");
                                }
                                str.Remove(pos, 1); // first " " in line
                                str.AppendLine();
                                pos = str.Length;
                            }
                        }
                        else
                        {
                            foreach (string line in lines)
                            {
                                string[] word_texts = line.Split(' ');
                                foreach (string word_text in word_texts)
                                {
                                    // base-10 digit places
                                    int place_value = (int)Math.Pow(10, word_text.Length - 1);
                                    foreach (char c in word_text)
                                    {
                                        if ((i >= 0) && (i < values.Length))
                                        {
                                            value += values[i] * place_value;
                                            str.Append(values[i].ToString());
                                            i++;
                                            place_value /= 10;
                                        }
                                    }
                                    str.Append(" ");
                                }
                                str.Remove(str.Length - 1, 1); // last " "
                                str.AppendLine();
                            }
                        }
                    }
                }
            }
        }
        return str.ToString().Trim();
    }
