    private void DisplayMathsChapterSumRatios(List<Verse> verses)
    {
        if ((TabControl.SelectedTab == MathsTabPage) || (TabControl.SelectedTab == DistancesTabPage))
        {
            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    if (verses != null)
                    {
                        m_maths_verses = verses;

                        List<Chapter> chapters = m_client.Book.GetChapters(m_maths_verses);
                        if (chapters != null)
                        {
                            Dictionary<long, long> frequencies = new Dictionary<long, long>();
                            if (frequencies != null)
                            {
                                frequencies.Clear();
                                foreach (Chapter chapter in chapters)
                                {
                                    long n = chapter.SortedNumber;
                                    if (frequencies.ContainsKey(n))
                                    {
                                        frequencies[n]++;
                                    }
                                    else
                                    {
                                        frequencies.Add(n, 1);
                                    }
                                }
                                long dC = 0; // duplicate
                                long uC = 0; // unique
                                foreach (long n in frequencies.Keys)
                                {
                                    if (frequencies[n] > 1)
                                    {
                                        dC += n * frequencies[n];
                                    }
                                    else
                                    {
                                        uC += n;
                                    }
                                }
                                double duC = 0.0D; // ratio
                                if (uC != 0)
                                    duC = (double)dC / (double)uC;
                                MathsChaptersCDUSumTextBox.Text = duC.ToString("0.00000");
                                MathsChaptersCDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duC);
                                if (duC.IsInteresting())
                                    MathsChaptersCDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                                if (duC.IsCarmichaelX())
                                    MathsChaptersCDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                                if (duC.IsCarmichael())
                                    MathsChaptersCDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                                ToolTip.SetToolTip(this.MathsChaptersCDUSumTextBox, dC.ToString() + "/" + uC.ToString());

                                frequencies.Clear();
                                foreach (Chapter chapter in chapters)
                                {
                                    long n = chapter.Verses.Count;
                                    if (frequencies.ContainsKey(n))
                                    {
                                        frequencies[n]++;
                                    }
                                    else
                                    {
                                        frequencies.Add(n, 1);
                                    }
                                }
                                long dV = 0; // duplicate
                                long uV = 0; // unique
                                foreach (long n in frequencies.Keys)
                                {
                                    if (frequencies[n] > 1)
                                    {
                                        dV += n * frequencies[n];
                                    }
                                    else
                                    {
                                        uV += n;
                                    }
                                }
                                double duV = 0.0D; // ratio
                                if (uV != 0)
                                    duV = (double)dV / (double)uV;
                                MathsChaptersVDUSumTextBox.Text = duV.ToString("0.00000");
                                MathsChaptersVDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duV);
                                if (duV.IsInteresting())
                                    MathsChaptersVDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                                if (duV.IsCarmichaelX())
                                    MathsChaptersVDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                                if (duV.IsCarmichael())
                                    MathsChaptersVDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                                ToolTip.SetToolTip(this.MathsChaptersVDUSumTextBox, dV.ToString() + "/" + uV.ToString());

                                frequencies.Clear();
                                foreach (Chapter chapter in chapters)
                                {
                                    long n = chapter.SortedNumber + chapter.Verses.Count;
                                    if (frequencies.ContainsKey(n))
                                    {
                                        frequencies[n]++;
                                    }
                                    else
                                    {
                                        frequencies.Add(n, 1);
                                    }
                                }
                                long dCPlusV = 0; // duplicate
                                long uCPlusV = 0; // unique
                                foreach (long n in frequencies.Keys)
                                {
                                    if (frequencies[n] > 1)
                                    {
                                        dCPlusV += n * frequencies[n];
                                    }
                                    else
                                    {
                                        uCPlusV += n;
                                    }
                                }
                                double duCPlusV = 0.0D; // ratio
                                if (uCPlusV != 0)
                                    duCPlusV = (double)dCPlusV / (double)uCPlusV;
                                MathsChaptersCPlusVDUSumTextBox.Text = duCPlusV.ToString("0.00000");
                                MathsChaptersCPlusVDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duCPlusV);
                                if (duCPlusV.IsInteresting())
                                    MathsChaptersCPlusVDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                                if (duCPlusV.IsCarmichaelX())
                                    MathsChaptersCPlusVDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                                if (duCPlusV.IsCarmichael())
                                    MathsChaptersCPlusVDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                                ToolTip.SetToolTip(this.MathsChaptersCPlusVDUSumTextBox, dCPlusV.ToString() + "/" + uCPlusV.ToString());

                                frequencies.Clear();
                                foreach (Chapter chapter in chapters)
                                {
                                    long n = m_maths_abs_cminusv ? Math.Abs(chapter.SortedNumber - chapter.Verses.Count) : (chapter.SortedNumber - chapter.Verses.Count);
                                    if (frequencies.ContainsKey(n))
                                    {
                                        frequencies[n]++;
                                    }
                                    else
                                    {
                                        frequencies.Add(n, 1);
                                    }
                                }
                                long dCMinusV = 0; // duplicate
                                long uCMinusV = 0; // unique
                                foreach (long n in frequencies.Keys)
                                {
                                    if (frequencies[n] > 1)
                                    {
                                        dCMinusV += n * frequencies[n];
                                    }
                                    else
                                    {
                                        uCMinusV += n;
                                    }
                                }
                                double duCMinusV = 0.0D; // ratio
                                if (uCMinusV != 0)
                                    duCMinusV = (double)dCMinusV / (double)uCMinusV;
                                MathsChaptersCMinusVDUSumTextBox.Text = duCMinusV.ToString("0.00000");
                                MathsChaptersCMinusVDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duCMinusV);
                                if (duCMinusV.IsInteresting())
                                    MathsChaptersCMinusVDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                                if (duCMinusV.IsCarmichaelX())
                                    MathsChaptersCMinusVDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                                if (duCMinusV.IsCarmichael())
                                    MathsChaptersCMinusVDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                                ToolTip.SetToolTip(this.MathsChaptersCMinusVDUSumTextBox, dCMinusV.ToString() + "/" + uCMinusV.ToString());

                                frequencies.Clear();
                                foreach (Chapter chapter in chapters)
                                {
                                    long n = chapter.SortedNumber * chapter.Verses.Count;
                                    if (frequencies.ContainsKey(n))
                                    {
                                        frequencies[n]++;
                                    }
                                    else
                                    {
                                        frequencies.Add(n, 1);
                                    }
                                }
                                long dCMultiplyV = 0; // duplicate
                                long uCMultiplyV = 0; // unique
                                foreach (long n in frequencies.Keys)
                                {
                                    if (frequencies[n] > 1)
                                    {
                                        dCMultiplyV += n * frequencies[n];
                                    }
                                    else
                                    {
                                        uCMultiplyV += n;
                                    }
                                }
                                double duCMultiplyV = 0.0D; // ratio
                                if (uCMultiplyV != 0)
                                    duCMultiplyV = (double)dCMultiplyV / (double)uCMultiplyV;
                                MathsChaptersCMultiplyVDUSumTextBox.Text = duCMultiplyV.ToString("0.00000");
                                MathsChaptersCMultiplyVDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duCMultiplyV);
                                if (duCMultiplyV.IsInteresting())
                                    MathsChaptersCMultiplyVDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                                if (duCMultiplyV.IsCarmichaelX())
                                    MathsChaptersCMultiplyVDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                                if (duCMultiplyV.IsCarmichael())
                                    MathsChaptersCMultiplyVDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                                ToolTip.SetToolTip(this.MathsChaptersCMultiplyVDUSumTextBox, dCMultiplyV.ToString() + "/" + uCMultiplyV.ToString());

                                frequencies.Clear();
                                foreach (Chapter chapter in chapters)
                                {
                                    long n = m_maths_vdividec ? ((long)((double)chapter.Verses.Count / (double)chapter.SortedNumber)) : ((long)((double)chapter.SortedNumber / (double)chapter.Verses.Count));
                                    if (frequencies.ContainsKey(n))
                                    {
                                        frequencies[n]++;
                                    }
                                    else
                                    {
                                        frequencies.Add(n, 1);
                                    }
                                }
                                long dCDivideV = 0; // duplicate
                                long uCDivideV = 0; // unique
                                foreach (long n in frequencies.Keys)
                                {
                                    if (frequencies[n] > 1)
                                    {
                                        dCDivideV += n * frequencies[n];
                                    }
                                    else
                                    {
                                        uCDivideV += n;
                                    }
                                }
                                double duCDivideV = 0.0D; // ratio
                                if (uCDivideV != 0)
                                    duCDivideV = (double)dCDivideV / (double)uCDivideV;
                                MathsChaptersCDivideVDUSumTextBox.Text = duCDivideV.ToString("0.00000");
                                MathsChaptersCDivideVDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duCDivideV);
                                if (duCDivideV.IsInteresting())
                                    MathsChaptersCDivideVDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                                if (duCDivideV.IsCarmichaelX())
                                    MathsChaptersCDivideVDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                                if (duCDivideV.IsCarmichael())
                                    MathsChaptersCDivideVDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                                ToolTip.SetToolTip(this.MathsChaptersCDivideVDUSumTextBox, dCDivideV.ToString() + "/" + uCDivideV.ToString());
                            }
                        }
                    }
                }
            }
        }
    }
    private void DisplayMathsVerseSums(List<Verse> verses)
    {
        if ((TabControl.SelectedTab == MathsTabPage) || (TabControl.SelectedTab == DistancesTabPage))
        {
            if (verses != null)
            {
                m_maths_verses = verses;

                long C = 0;  // all
                long oC = 0; // odd
                long eC = 0; // even
                long pC = 0; // prime
                long cC = 0; // composite
                long V = 0;
                long oV = 0;
                long eV = 0;
                long pV = 0;
                long cV = 0;
                long CPlusV = 0;
                long oCPlusV = 0;
                long eCPlusV = 0;
                long pCPlusV = 0;
                long cCPlusV = 0;
                long CMinusV = 0;
                long oCMinusV = 0;
                long eCMinusV = 0;
                long pCMinusV = 0;
                long cCMinusV = 0;
                long CMultiplyV = 0;
                long oCMultiplyV = 0;
                long eCMultiplyV = 0;
                long pCMultiplyV = 0;
                long cCMultiplyV = 0;
                double CDivideV = 0;
                double oCDivideV = 0;
                double eCDivideV = 0;
                double pCDivideV = 0;
                double cCDivideV = 0;
                foreach (Verse verse in m_maths_verses)
                {
                    long chapter_number = verse.Chapter.SortedNumber;
                    long verse_number = verse.NumberInChapter;
                    long cplusv = chapter_number + verse_number;
                    long cminusv = m_maths_abs_cminusv ? Math.Abs(chapter_number - verse_number) : (chapter_number - verse_number);
                    long cmultiplyv = chapter_number * verse_number;
                    double cdividev = m_maths_vdividec ? ((double)verse_number / (double)chapter_number) : ((double)chapter_number / (double)verse_number);

                    C += chapter_number;
                    if (Numbers.IsOdd(chapter_number))
                    {
                        oC += chapter_number;
                    }
                    else
                    {
                        eC += chapter_number;
                    }
                    if (Numbers.IsPrime(chapter_number))
                    {
                        pC += chapter_number;
                    }
                    else if (Numbers.IsComposite(chapter_number))
                    {
                        cC += chapter_number;
                    }
                    else //if (chapter_number == 1)
                    {
                    }

                    V += verse_number;
                    if (Numbers.IsOdd(verse_number))
                    {
                        oV += verse_number;
                    }
                    else
                    {
                        eV += verse_number;
                    }
                    if (Numbers.IsPrime(verse_number))
                    {
                        pV += verse_number;
                    }
                    else if (Numbers.IsComposite(verse_number))
                    {
                        cV += verse_number;
                    }
                    else //if (verse_count == 1)
                    {
                    }

                    CPlusV += cplusv;
                    if (Numbers.IsOdd(cplusv))
                    {
                        oCPlusV += cplusv;
                    }
                    else
                    {
                        eCPlusV += cplusv;
                    }
                    if (Numbers.IsPrime(cplusv))
                    {
                        pCPlusV += cplusv;
                    }
                    else if (Numbers.IsComposite(cplusv))
                    {
                        cCPlusV += cplusv;
                    }
                    else //if (cplusv == 1)
                    {
                    }

                    CMinusV += cminusv;
                    if (Numbers.IsOdd(cminusv))
                    {
                        oCMinusV += cminusv;
                    }
                    else
                    {
                        eCMinusV += cminusv;
                    }
                    if (Numbers.IsPrime(cminusv))
                    {
                        pCMinusV += cminusv;
                    }
                    else if (Numbers.IsComposite(cminusv))
                    {
                        cCMinusV += cminusv;
                    }
                    else //if (cminusv == 1)
                    {
                    }

                    CMultiplyV += cmultiplyv;
                    if (Numbers.IsOdd(cmultiplyv))
                    {
                        oCMultiplyV += cmultiplyv;
                    }
                    else
                    {
                        eCMultiplyV += cmultiplyv;
                    }
                    if (Numbers.IsPrime(cmultiplyv))
                    {
                        pCMultiplyV += cmultiplyv;
                    }
                    else if (Numbers.IsComposite(cmultiplyv))
                    {
                        cCMultiplyV += cmultiplyv;
                    }
                    else //if (cmultiplyv == 1)
                    {
                    }

                    CDivideV += cdividev;
                    if (Numbers.IsOdd((long)cdividev))
                    {
                        oCDivideV += cdividev;
                    }
                    else
                    {
                        eCDivideV += cdividev;
                    }
                    if (Numbers.IsPrime((long)cdividev))
                    {
                        pCDivideV += cdividev;
                    }
                    else if (Numbers.IsComposite((long)cdividev))
                    {
                        cCDivideV += cdividev;
                    }
                    else //if (cdividev == 1)
                    {
                    }
                }
                MathsVersesCSumTextBox.Text = C.ToString();
                MathsVersesCOddSumTextBox.Text = oC.ToString();
                MathsVersesCEvenSumTextBox.Text = eC.ToString();
                MathsVersesCPrimeSumTextBox.Text = pC.ToString();
                MathsVersesCCompositeSumTextBox.Text = cC.ToString();
                MathsVersesVSumTextBox.Text = V.ToString();
                MathsVersesVOddSumTextBox.Text = oV.ToString();
                MathsVersesVEvenSumTextBox.Text = eV.ToString();
                MathsVersesVPrimeSumTextBox.Text = pV.ToString();
                MathsVersesVCompositeSumTextBox.Text = cV.ToString();
                MathsVersesCPlusVSumTextBox.Text = CPlusV.ToString();
                MathsVersesCPlusVOddSumTextBox.Text = oCPlusV.ToString();
                MathsVersesCPlusVEvenSumTextBox.Text = eCPlusV.ToString();
                MathsVersesCPlusVPrimeSumTextBox.Text = pCPlusV.ToString();
                MathsVersesCPlusVCompositeSumTextBox.Text = cCPlusV.ToString();
                MathsVersesCMinusVSumTextBox.Text = CMinusV.ToString();
                MathsVersesCMinusVOddSumTextBox.Text = oCMinusV.ToString();
                MathsVersesCMinusVEvenSumTextBox.Text = eCMinusV.ToString();
                MathsVersesCMinusVPrimeSumTextBox.Text = pCMinusV.ToString();
                MathsVersesCMinusVCompositeSumTextBox.Text = cCMinusV.ToString();
