                MathsVersesCDivideVCompositeSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)cCDivideV);

                MathsVersesCSumTextBox.BackColor = (Numbers.Compare(C, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Window;
