    private void DisplayMathsVerseSumRatios(List<Verse> verses)
    {
        if ((TabControl.SelectedTab == MathsTabPage) || (TabControl.SelectedTab == DistancesTabPage))
        {
            if (verses != null)
            {
                m_maths_verses = verses;

                Dictionary<long, long> frequencies = new Dictionary<long, long>();
                if (frequencies != null)
                {
                    frequencies.Clear();
                    foreach (Verse verse in m_maths_verses)
                    {
                        long n = verse.Chapter.SortedNumber;
                        if (frequencies.ContainsKey(n))
                        {
                            frequencies[n]++;
                        }
                        else
                        {
                            frequencies.Add(n, 1);
                        }
                    }
                    long dC = 0; // duplicate
                    long uC = 0; // unique
                    foreach (long n in frequencies.Keys)
                    {
                        if (frequencies[n] > 1)
                        {
                            dC += n * frequencies[n];
                        }
                        else
                        {
                            uC += n;
                        }
                    }
                    double duC = 0.0D; // ratio
                    if (uC != 0)
                        duC = (double)dC / (double)uC;
                    MathsVersesCDUSumTextBox.Text = duC.ToString("0.00000");
                    MathsVersesCDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duC);
                    if (duC.IsInteresting())
                        MathsVersesCDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (duC.IsCarmichaelX())
                        MathsVersesCDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (duC.IsCarmichael())
                        MathsVersesCDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    ToolTip.SetToolTip(this.MathsVersesCDUSumTextBox, dC.ToString() + "/" + uC.ToString());

                    frequencies.Clear();
                    foreach (Verse verse in m_maths_verses)
                    {
                        long n = verse.NumberInChapter;
                        if (frequencies.ContainsKey(n))
                        {
                            frequencies[n]++;
                        }
                        else
                        {
                            frequencies.Add(n, 1);
                        }
                    }
                    long dV = 0; // duplicate
                    long uV = 0; // unique
                    foreach (long n in frequencies.Keys)
                    {
                        if (frequencies[n] > 1)
                        {
                            dV += n * frequencies[n];
                        }
                        else
                        {
                            uV += n;
                        }
                    }
                    double duV = 0.0D; // ratio
                    if (uV != 0)
                        duV = (double)dV / (double)uV;
                    MathsVersesVDUSumTextBox.Text = duV.ToString("0.00000");
                    MathsVersesVDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duV);
                    if (duV.IsInteresting())
                        MathsVersesVDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (duV.IsCarmichaelX())
                        MathsVersesVDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (duV.IsCarmichael())
                        MathsVersesVDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    ToolTip.SetToolTip(this.MathsVersesVDUSumTextBox, dV.ToString() + "/" + uV.ToString());

                    frequencies.Clear();
                    foreach (Verse verse in m_maths_verses)
                    {
                        long n = verse.Chapter.SortedNumber + verse.NumberInChapter;
                        if (frequencies.ContainsKey(n))
                        {
                            frequencies[n]++;
                        }
                        else
                        {
                            frequencies.Add(n, 1);
                        }
                    }
                    long dCPlusV = 0; // duplicate
                    long uCPlusV = 0; // unique
                    foreach (long n in frequencies.Keys)
                    {
                        if (frequencies[n] > 1)
                        {
                            dCPlusV += n * frequencies[n];
                        }
                        else
                        {
                            uCPlusV += n;
                        }
                    }
                    double duCPlusV = 0.0D; // ratio
                    if (uCPlusV != 0)
                        duCPlusV = (double)dCPlusV / (double)uCPlusV;
                    MathsVersesCPlusVDUSumTextBox.Text = duCPlusV.ToString("0.00000");
                    MathsVersesCPlusVDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duCPlusV);
                    if (duCPlusV.IsInteresting())
                        MathsVersesCPlusVDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (duCPlusV.IsCarmichaelX())
                        MathsVersesCPlusVDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (duCPlusV.IsCarmichael())
                        MathsVersesCPlusVDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    ToolTip.SetToolTip(this.MathsVersesCPlusVDUSumTextBox, dCPlusV.ToString() + "/" + uCPlusV.ToString());

                    frequencies.Clear();
                    foreach (Verse verse in m_maths_verses)
                    {
                        long n = m_maths_abs_cminusv ? Math.Abs(verse.Chapter.SortedNumber - verse.NumberInChapter) : (verse.Chapter.SortedNumber - verse.NumberInChapter);
                        if (frequencies.ContainsKey(n))
                        {
                            frequencies[n]++;
                        }
                        else
                        {
                            frequencies.Add(n, 1);
                        }
                    }
                    long dCMinusV = 0; // duplicate
                    long uCMinusV = 0; // unique
                    foreach (long n in frequencies.Keys)
                    {
                        if (frequencies[n] > 1)
                        {
                            dCMinusV += n * frequencies[n];
                        }
                        else
                        {
                            uCMinusV += n;
                        }
                    }
                    double duCMinusV = 0.0D; // ratio
                    if (uCMinusV != 0)
                        duCMinusV = (double)dCMinusV / (double)uCMinusV;
                    MathsVersesCMinusVDUSumTextBox.Text = duCMinusV.ToString("0.00000");
                    MathsVersesCMinusVDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duCMinusV);
                    if (duCMinusV.IsInteresting())
                        MathsVersesCMinusVDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (duCMinusV.IsCarmichaelX())
                        MathsVersesCMinusVDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (duCMinusV.IsCarmichael())
                        MathsVersesCMinusVDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    ToolTip.SetToolTip(this.MathsVersesCMinusVDUSumTextBox, dCMinusV.ToString() + "/" + uCMinusV.ToString());

                    frequencies.Clear();
                    foreach (Verse verse in m_maths_verses)
                    {
                        long n = verse.Chapter.SortedNumber * verse.NumberInChapter;
                        if (frequencies.ContainsKey(n))
                        {
                            frequencies[n]++;
                        }
                        else
                        {
                            frequencies.Add(n, 1);
                        }
                    }
                    long dCMultiplyV = 0; // duplicate
                    long uCMultiplyV = 0; // unique
                    foreach (long n in frequencies.Keys)
                    {
                        if (frequencies[n] > 1)
                        {
                            dCMultiplyV += n * frequencies[n];
                        }
                        else
                        {
                            uCMultiplyV += n;
                        }
                    }
                    double duCMultiplyV = 0.0D; // ratio
                    if (uCMultiplyV != 0)
                        duCMultiplyV = (double)dCMultiplyV / (double)uCMultiplyV;
                    MathsVersesCMultiplyVDUSumTextBox.Text = duCMultiplyV.ToString("0.00000");
                    MathsVersesCMultiplyVDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duCMultiplyV);
                    if (duCMultiplyV.IsInteresting())
                        MathsVersesCMultiplyVDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (duCMultiplyV.IsCarmichaelX())
                        MathsVersesCMultiplyVDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (duCMultiplyV.IsCarmichael())
                        MathsVersesCMultiplyVDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    ToolTip.SetToolTip(this.MathsVersesCMultiplyVDUSumTextBox, dCMultiplyV.ToString() + "/" + uCMultiplyV.ToString());

                    frequencies.Clear();
                    foreach (Verse verse in m_maths_verses)
                    {
                        long n = m_maths_vdividec ? ((long)((double)verse.NumberInChapter / (double)verse.Chapter.SortedNumber)) : ((long)((double)verse.Chapter.SortedNumber / (double)verse.NumberInChapter));
                        if (frequencies.ContainsKey(n))
                        {
                            frequencies[n]++;
                        }
                        else
                        {
                            frequencies.Add(n, 1);
                        }
                    }
                    long dCDivideV = 0; // duplicate
                    long uCDivideV = 0; // unique
                    foreach (long n in frequencies.Keys)
                    {
                        if (frequencies[n] > 1)
                        {
                            dCDivideV += n * frequencies[n];
                        }
                        else
                        {
                            uCDivideV += n;
                        }
                    }
                    double duCDivideV = 0.0D; // ratio
                    if (uCDivideV != 0)
                        duCDivideV = (double)dCDivideV / (double)uCDivideV;
                    MathsVersesCDivideVDUSumTextBox.Text = duCDivideV.ToString("0.00000");
                    MathsVersesCDivideVDUSumTextBox.ForeColor = Numbers.GetNumberTypeColor((long)duCDivideV);
                    if (duCDivideV.IsInteresting())
                        MathsVersesCDivideVDUSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (duCDivideV.IsCarmichaelX())
                        MathsVersesCDivideVDUSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (duCDivideV.IsCarmichael())
                        MathsVersesCDivideVDUSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    ToolTip.SetToolTip(this.MathsVersesCDivideVDUSumTextBox, dCDivideV.ToString() + "/" + uCDivideV.ToString());
                }
            }
        }
