                        {
                            if (v_frequencies[n] > 1)
                            {
                                dV += n * v_frequencies[n];
                            }
                            else
                            {
                                uV += n;
                            }
                        }
                        if (uV != 0)
                            duV = (double)dV / (double)uV;
