            case NumberScope.NumberInChapter:
                {
                    long n = word.NumberInChapter;
                    long z = word.Verse.Chapter.Words.Count;
                    result = (((z * (z + 1)) / 2) - ((n * (n + 1)) / 2));

                    result += GetDistancesWordAfterChapterRunningTotal(word.Verse.Chapter);
