    private void R2L_Sum_____wNumber_x_wLetters(string text, StringBuilder str)
    {
        if (m_selection_mode)
        {
            foreach (Verse verse in m_client.Selection.Verses)
            {
                str.Append(verse.Number.ToString() + "\t");
                int pos = str.Length;

                long sum = 0L;
                foreach (Word word in verse.Words)
                {
                    int result = word.NumberInVerse * word.Letters.Count;
                    str.Append(result.ToString() + "+");
                    sum += result;
                }
                if (str.Length > 1)
                {
                    str.Remove(str.Length - 1, 1);
                }

                str.Insert(pos, sum.ToString() + "\t");
                str.AppendLine(m_cvwl_sequence_show_factors ? ("\t" + Numbers.FactorizeToString(sum)) : "");
            }
        }
        else
        {
            char[] separators = { '\n' };
            string[] lines = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
            for (int i = 0; i < lines.Length; i++)
            {
                str.Append((i + 1).ToString() + "\t");
                int pos = str.Length;

                long sum = 0L;
                string[] parts = lines[i].Split(' ');
                for (int j = 0; j < parts.Length; j++)
                {
                    int result = (j + 1) * parts[j].Length;
                    str.Append(result.ToString() + "+");
                    sum += result;
                }
                if (str.Length > 1)
                {
                    str.Remove(str.Length - 1, 1);
                }

                str.Insert(pos, sum.ToString() + "\t");
                str.AppendLine(m_cvwl_sequence_show_factors ? ("\t" + Numbers.FactorizeToString(sum)) : "");
            }
        }
    }
