    private void R2L__________________wLetters(string text, StringBuilder str)
    {
        if (m_selection_mode)
        {
            int start = 0;
            foreach (Verse verse in m_client.Selection.Verses)
            {
                foreach (Word word in verse.Words)
                {
                    str.Insert(start, word.Letters.Count.ToString());
                }
                str.AppendLine();
                if (!m_active_textbox.WordWrap)
                    start = str.Length;
            }
        }
        else
        {
            int start = 0;
            char[] separators = { '\n' };
            string[] lines = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
            foreach (string line in lines)
            {
                string[] words = line.Split(' ');
                foreach (string word in words)
                {
                    if (word.Length > 0)
                    {
                        str.Insert(start, word.Length.ToString());
                    }
                }
                str.AppendLine();
                if (!m_active_textbox.WordWrap)
                    start = str.Length;
            }
        }
    }
