                str.AppendLine();
            }
        }
        else
        {
            char[] separators = { '\n' };
            string[] lines = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
            foreach (string line in lines)
            {
                string[] words = line.Split(' ');
                foreach (string word in words)
                {
                    if (word.Length > 0)
                    {
                        str.Append(word.Length);
                    }
                }
                str.AppendLine();
            }
        }
    }
