    #endregion
    #region Values Sequence
    ///////////////////////////////////////////////////////////////////////////////
    private int m_values_sequence_radix = Numbers.DEFAULT_RADIX;
    private enum ValuesSequenceScope
    {
        TextValues,
        LetterValues,
        WordValues,
        VerseValues,
        ChapterValues,
        LetterValue_x_NumberInWord,
        LetterValue_x_NumberInVerse,
        LetterValue_x_NumberInChapter,
        LetterValue_x_LetterNumber,
        WordValue_x_NumberInVerse,
        WordValue_x_NumberInChapter,
        WordValue_x_WordNumber,
        VerseValue_x_NumberInChapter,
        VerseValue_x_VerseNumber,
        ChapterValue_x_ChapterNumber
    };
    private void PopulateValuesSequenceScopeComboBox()
    {
        ValuesSequenceScopeComboBox.Items.Clear();
        try
        {
            for (int i = 0; i < 3; i++)
                ValuesSequenceScopeComboBox.SelectedIndexChanged -= new System.EventHandler(ValuesSequenceScopeComboBox_SelectedIndexChanged);

            ValuesSequenceScopeComboBox.BeginUpdate();
            ValuesSequenceScopeComboBox.Items.Clear();
            foreach (ValuesSequenceScope item in Enum.GetValues(typeof(ValuesSequenceScope)))
            {
                ValuesSequenceScopeComboBox.Items.Add(item);
            }
            if (ValuesSequenceScopeComboBox.Items.Count > 0)
            {
                ValuesSequenceScopeComboBox.SelectedIndex = 0;
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            ValuesSequenceScopeComboBox.EndUpdate();
            ValuesSequenceScopeComboBox.SelectedIndexChanged += new System.EventHandler(ValuesSequenceScopeComboBox_SelectedIndexChanged);
        }
    }
    private void ValuesSequenceScopeComboBox_SelectedIndexChanged(object sender, EventArgs e)
    {
        if (
             (m_text_display_mode == TextDisplayMode.Both) ||
             (m_text_display_mode == TextDisplayMode.TranslationOnly)
           )
        {
            if (ValuesSequenceScopeComboBox.SelectedItem != null)
            {
                ValuesSequenceScope values_sequence_scope = (ValuesSequenceScope)Enum.Parse(typeof(ValuesSequenceScope), ValuesSequenceScopeComboBox.SelectedItem.ToString());
                //if (!String.IsNullOrEmpty(m_current_text))
                {
                    ValuesSequenceTextBox.Text = BuildValuesSequence(values_sequence_scope, m_current_text);
                }
            }
        }
    }
    private void ValuesSequenceRadixNumericUpDown_ValueChanged(object sender, EventArgs e)
    {
        m_values_sequence_radix = (int)ValuesSequenceRadixNumericUpDown.Value;
        DisplayValuesSequence();
    }
    private void ValuesSequenceRadixNumericUpDown_TextChanged(object sender, EventArgs e)
    {
        if (m_client == null)
            return; // delay Numbers' constructor until after splash screen

        m_values_sequence_radix = (int)ValuesSequenceRadixNumericUpDown.Value;
        ValuesSequenceRadixNumericUpDown.ForeColor = Numbers.GetNumberTypeColor(((long)ValuesSequenceRadixNumericUpDown.Value));
        ValuesSequenceRadixNumericUpDown.Refresh();
    }
    private string BuildValuesSequence(ValuesSequenceScope values_sequence_scope, string text)
    {
        if (text == null)
            return null; // allow empty but not null

        StringBuilder str = new StringBuilder();

        if (m_client != null)
        {
            if (m_client.NumerologySystem != null)
            {
                if (m_client.Selection != null)
                {
                    text = text.Replace("\r", "");
                    text = text.Replace("\t", "");
                    text = text.Replace("_", "");
                    text = text.Replace(Constants.ORNATE_RIGHT_PARENTHESIS, "");
                    text = text.Replace(Constants.ORNATE_LEFT_PARENTHESIS, "");
                    foreach (char character in Constants.INDIAN_DIGITS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    foreach (char character in Constants.ARABIC_DIGITS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    foreach (char character in Constants.SYMBOLS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    foreach (char character in Constants.STOPMARKS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    foreach (char character in Constants.QURANMARKS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    text = text.Replace("\n ", "\n"); // quran marks
                    text = text.Replace(" \n", "\n"); // sijood marks
                    if (!m_with_diacritics)
                    {
                        text = text.Simplify(m_client.NumerologySystem.TextMode);
                    }
                    while (text.Contains("  "))
                    {
                        text = text.Replace("  ", " ");
                    }
                    text = text.Trim();

                    if (ValuesSequencePanel != null)
                        ValuesSequencePanel.Visible = false;
                    ValuesSequenceUserTextBox.Visible = false;
                    ValuesSequenceDirectionLabel.Visible = true;
                    ValuesSequenceRadixLabel.Visible = true;
                    ValuesSequenceRadixNumericUpDown.Visible = true;
                    if (m_values_sequence_right_to_left)
                    {
                        switch (values_sequence_scope)
                        {
                            case ValuesSequenceScope.TextValues:
                                {
                                    R2L_TextValues(text);
                                    if (ValuesSequencePanel != null)
                                        ValuesSequencePanel.Visible = true;
                                    ValuesSequenceUserTextBox.Visible = true;
                                    ValuesSequenceDirectionLabel.Visible = false;
                                    ValuesSequenceRadixLabel.Visible = false;
                                    ValuesSequenceRadixNumericUpDown.Visible = false;
                                }
                                break;
                            case ValuesSequenceScope.LetterValues:
                                {
                                    R2L_LetterValues(text, str);
                                }
                                break;
                            case ValuesSequenceScope.WordValues:
                                {
                                    R2L_WordValues(text, str);
                                }
                                break;
                            case ValuesSequenceScope.VerseValues:
                                {
                                    R2L_VerseValues(text, str);
                                }
                                break;
                            case ValuesSequenceScope.ChapterValues:
                                {
                                    R2L_ChapterValues(text, str);
                                }
                                break;
                            case ValuesSequenceScope.LetterValue_x_NumberInWord:
                                {
                                    R2L_LetterValue_x_NumberInWord(text, str);
                                }
                                break;
                            case ValuesSequenceScope.LetterValue_x_NumberInVerse:
                                {
                                    R2L_LetterValue_x_NumberInVerse(text, str);
                                }
                                break;
                            case ValuesSequenceScope.LetterValue_x_NumberInChapter:
                                {
                                    R2L_LetterValue_x_NumberInChapter(text, str);
                                }
                                break;
                            case ValuesSequenceScope.LetterValue_x_LetterNumber:
                                {
                                    R2L_LetterValue_x_LetterNumber(text, str);
                                }
                                break;
                            case ValuesSequenceScope.WordValue_x_NumberInVerse:
                                {
                                    R2L_WordValue_x_NumberInVerse(text, str);
                                }
                                break;
                            case ValuesSequenceScope.WordValue_x_NumberInChapter:
                                {
                                    R2L_WordValue_x_NumberInChapter(text, str);
                                }
                                break;
                            case ValuesSequenceScope.WordValue_x_WordNumber:
                                {
                                    R2L_WordValue_x_WordNumber(text, str);
                                }
                                break;
                            case ValuesSequenceScope.VerseValue_x_NumberInChapter:
                                {
                                    R2L_VerseValue_x_NumberInChapter(text, str);
                                }
                                break;
                            case ValuesSequenceScope.VerseValue_x_VerseNumber:
                                {
                                    R2L_VerseValue_x_VerseNumber(text, str);
                                }
                                break;
                            case ValuesSequenceScope.ChapterValue_x_ChapterNumber:
                                {
                                    R2L_ChapterValue_x_ChapterNumber(text, str);
                                }
                                break;
                            default:
                                break;
                        }
                    }
                    else
                    {
                        switch (values_sequence_scope)
                        {
                            case ValuesSequenceScope.TextValues:
                                {
                                    L2R_TextValues(text);
                                    if (ValuesSequencePanel != null)
                                        ValuesSequencePanel.Visible = true;
                                    ValuesSequenceUserTextBox.Visible = true;
                                    ValuesSequenceDirectionLabel.Visible = false;
                                    ValuesSequenceRadixLabel.Visible = false;
                                    ValuesSequenceRadixNumericUpDown.Visible = false;
                                }
                                break;
                            case ValuesSequenceScope.LetterValues:
                                {
                                    L2R_LetterValues(text, str);
                                }
                                break;
                            case ValuesSequenceScope.WordValues:
                                {
                                    L2R_WordValues(text, str);
                                }
                                break;
                            case ValuesSequenceScope.VerseValues:
                                {
                                    L2R_VerseValues(text, str);
                                }
                                break;
                            case ValuesSequenceScope.ChapterValues:
                                {
                                    L2R_ChapterValues(str);
                                }
                                break;
                            case ValuesSequenceScope.LetterValue_x_NumberInWord:
                                {
                                    L2R_LetterValue_x_NumberInWord(text, str);
                                }
                                break;
                            case ValuesSequenceScope.LetterValue_x_NumberInVerse:
                                {
                                    L2R_LetterValue_x_NumberInVerse(text, str);
                                }
                                break;
                            case ValuesSequenceScope.LetterValue_x_NumberInChapter:
                                {
                                    L2R_LetterValue_x_NumberInChapter(text, str);
                                }
                                break;
                            case ValuesSequenceScope.LetterValue_x_LetterNumber:
                                {
                                    L2R_LetterValue_x_LetterNumber(text, str);
                                }
                                break;
                            case ValuesSequenceScope.WordValue_x_NumberInVerse:
                                {
                                    L2R_WordValue_x_NumberInVerse(text, str);
                                }
                                break;
                            case ValuesSequenceScope.WordValue_x_NumberInChapter:
                                {
                                    L2R_WordValue_x_NumberInChapter(text, str);
                                }
                                break;
                            case ValuesSequenceScope.WordValue_x_WordNumber:
                                {
                                    L2R_WordValue_x_WordNumber(text, str);
                                }
                                break;
                            case ValuesSequenceScope.VerseValue_x_NumberInChapter:
                                {
                                    L2R_VerseValue_x_NumberInChapter(text, str);
                                }
                                break;
                            case ValuesSequenceScope.VerseValue_x_VerseNumber:
                                {
                                    L2R_VerseValue_x_VerseNumber(text, str);
                                }
                                break;
                            case ValuesSequenceScope.ChapterValue_x_ChapterNumber:
                                {
                                    L2R_ChapterValue_x_ChapterNumber(text, str);
                                }
                                break;
                            default:
                                break;
                        }
                    }
                }
            }
        }
        return str.ToString().Trim();
    }

    private void R2L_TextValues(string text)
    {
        DisplayValuesSequence(text);
    }
    private void R2L_LetterValues(string text, StringBuilder str)
    {
        int line_start = 0;
        foreach (char c in text)
        {
            if (c == '\n')
            {
                str.AppendLine();
                line_start = str.Length;
            }
            else if (c == ' ')
            {
                str.Insert(line_start, " ");
            }
            else
            {
                str.Insert(line_start, " ");
                long value = m_client.CalculateValue(c);
                str.Insert(line_start, Radix.Encode(value, m_values_sequence_radix).PadLeft((m_values_sequence_radix > 2) ? 0 : 8, '0'));
            }
        }
    }
    private void R2L_WordValues(string text, StringBuilder str)
    {
        int line_start = 0;
        char[] separators = { '\n' };
        string[] lines = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
        foreach (string line in lines)
        {
            string[] word_texts = line.Split(' ');
            foreach (string word_text in word_texts)
            {
                long value = m_client.CalculateValue(word_text);
                str.Insert(line_start, Radix.Encode(value, m_values_sequence_radix).PadLeft((m_values_sequence_radix > 2) ? 0 : 16, '0'));
                str.Insert(line_start, " ");
            }
            str.Remove(line_start, 1); // last " "
            str.AppendLine();
            line_start = str.Length;
        }
    }
    private void R2L_VerseValues(string text, StringBuilder str)
    {
        char[] separators = { '\n' };
        string[] lines = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
        foreach (string line in lines)
        {
            long value = m_client.CalculateValue(line);
            str.AppendLine(Radix.Encode(value, m_values_sequence_radix).PadLeft((m_values_sequence_radix > 2) ? 0 : 32, '0'));
        }
    }
    private void R2L_ChapterValues(string text, StringBuilder str)
    {
        if (m_client.Book != null)
        {
            foreach (Chapter chapter in m_client.Selection.Chapters)
            {
                long value = m_client.CalculateValue(chapter);
                str.AppendLine(Radix.Encode(value, m_values_sequence_radix).PadLeft((m_values_sequence_radix > 2) ? 0 : 64, '0'));
            }
        }
    }
    private void R2L_LetterValue_x_NumberInWord(string text, StringBuilder str)
    {
        long total = 0L;
        long sum = 0L;
        if (m_selection_mode)
        {
            foreach (Verse verse in m_client.Selection.Verses)
            {
                str.Append(verse.Number.ToString() + "\t");
                int pos = str.Length;

                sum = 0;
                foreach (Word word in verse.Words)
                {
                    foreach (Letter letter in word.Letters)
                    {
                        long result = m_client.CalculateValue(letter) * letter.NumberInWord;
                        str.Append(Radix.Encode(result, m_values_sequence_radix) + "+");
                        sum += result;
                        total += result;
                    }
                }
                str.Remove(str.Length - 1, 1);
                str.Insert(pos, Radix.Encode(sum, m_values_sequence_radix) + "\t");
                str.AppendLine();
            }
            str.AppendLine("Total" + "\t" + Radix.Encode(total, m_values_sequence_radix));
        }
        else
        {
            int line = 0;
            int line_start = 0;
            int number_in_word = 0;
            for (int i = 0; i < text.Length; i++)
            {
                if (text[i] == '\n')
                {
                    str.Remove(str.Length - 1, 1);
                    str.Insert(line_start, (++line).ToString() + "\t" + Radix.Encode(sum, m_values_sequence_radix) + "\t");
                    sum = 0L;

                    str.AppendLine();
                    line_start = str.Length;
                    number_in_word = 0;
                }
                else if (text[i] == ' ')
                {
                    number_in_word = 0;
                }
                else
                {
                    number_in_word++;
                    long result = m_client.CalculateValue(text[i]) * number_in_word;
                    str.Append(Radix.Encode(result, m_values_sequence_radix) + "+");
                    sum += result;
                    total += result;
                }
            }
            // last line
            str.Remove(str.Length - 1, 1);
            str.Insert(line_start, (++line).ToString() + "\t" + Radix.Encode(sum, m_values_sequence_radix) + "\t");

            str.AppendLine();
            str.AppendLine("Total" + "\t" + Radix.Encode(total, m_values_sequence_radix));
        }
    }
