    private void L2R_TextValues(string text)
    {
        DisplayValuesSequence(text);
    }
    private void L2R_LetterValues(string text, StringBuilder str)
    {
        foreach (char c in text)
        {
            if (c == '\n')
            {
                str.Remove(str.Length - 1, 1); // last " "
                str.AppendLine();
            }
            else if (c == ' ')
            {
                str.Append(" ");
            }
            else
            {
                long value = m_client.CalculateValue(c);
                str.Append(Radix.Encode(value, m_values_sequence_radix).PadLeft((m_values_sequence_radix > 2) ? 0 : 8, '0'));
                str.Append(" ");
            }
        }
    }
    private void L2R_WordValues(string text, StringBuilder str)
    {
        char[] separators = { '\n' };
        string[] lines = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
        foreach (string line in lines)
        {
            string[] word_texts = line.Split(' ');
            foreach (string word_text in word_texts)
            {
                long value = m_client.CalculateValue(word_text);
                str.Append(Radix.Encode(value, m_values_sequence_radix).PadLeft((m_values_sequence_radix > 2) ? 0 : 16, '0'));
                str.Append(" ");
            }
            str.Remove(str.Length - 1, 1); // last " "
            str.AppendLine();
        }
    }
    private void L2R_VerseValues(string text, StringBuilder str)
    {
        char[] separators = { '\n' };
        string[] lines = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
        foreach (string line in lines)
        {
            long value = m_client.CalculateValue(line);
            str.AppendLine(Radix.Encode(value, m_values_sequence_radix).PadLeft((m_values_sequence_radix > 2) ? 0 : 32, '0'));
        }
