    private bool m_values_sequence_right_to_left = false;
    private void ValuesSequenceDirectionLabel_Click(object sender, EventArgs e)
    {
        m_values_sequence_right_to_left = !m_values_sequence_right_to_left;
        ValuesSequenceTextBox.RightToLeft = m_values_sequence_right_to_left ? RightToLeft.Yes : RightToLeft.No;
        ValuesSequenceDirectionLabel.Left = m_values_sequence_right_to_left ? 2 : ValuesSequenceTextBox.Width - ((m_dpi_x == 96.0F) ? 17 : 20);
        ValuesSequenceDirectionLabel.Anchor = m_values_sequence_right_to_left ? (AnchorStyles.Top | AnchorStyles.Left) : (AnchorStyles.Top | AnchorStyles.Right);

        if (m_values_sequence_right_to_left)
        {
            if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "arrow_left.png"))
            {
                ValuesSequenceDirectionLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "arrow_left.png");
            }
        }
        else
        {
            if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "arrow_right.png"))
            {
                ValuesSequenceDirectionLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "arrow_right.png");
            }
        }
        ValuesSequenceDirectionLabel.Refresh();

        ValuesSequenceScopeComboBox_SelectedIndexChanged(null, null);
    }
    private void DisplayValuesSequence()
    {
        ValuesSequenceScopeComboBox_SelectedIndexChanged(null, null);
    }
    private void ValuesSequenceInspectLabel_Click(object sender, EventArgs e)
    {
        string filename = null;
        StringBuilder str = new StringBuilder();

        if (ValuesSequenceScopeComboBox.SelectedItem.ToString() == ValuesSequenceScope.TextValues.ToString())
        {
            filename = m_client.NumerologySystem.TextMode + "_" + ValuesSequenceScopeComboBox.SelectedItem.ToString() + "_" + DateTime.Now.ToString("yyyyMMdd_hhmmss") + ".txt";
            if (m_client != null)
            {
                if (m_client.NumerologySystem != null)
                {
                    if (m_values_sequence_labels != null)
                    {
                        for (int n = 0; n < m_values_sequence_labels.Length; n++)
                        {
                            int index = GetValuesSequenceLabelIndex(m_values_sequence_labels[n]);
                            if ((index >= 0) && (index < m_values_sequence_numerology_system_names.Count))
                            {
                                if (m_values_sequence_labels[n] != null)
                                {
                                    int pad_length = (m_client.NumerologySystem.TextMode == "Original") ? 32 : 40;
                                    string str1 = (m_client.NumerologySystem.TextMode + "_" + m_values_sequence_numerology_system_names[index]).PadRight(pad_length);
                                    pad_length = (m_client.NumerologySystem.TextMode == "Original") ? 8 : 12;
                                    string str2 = m_values_sequence_labels[n].Text.PadRight(pad_length);
                                    long value = 0L;
                                    if (long.TryParse(str2, out value))
                                    {
                                        string str3 = Numbers.GetNumberTypeAsString(value);
                                        string str4 = Numbers.FactorizeToString(value);
                                        str.AppendLine(str1 + "\t" + str2 + "\t" + str3 + "\t" + str4);
                                    }
                                }
                            }
                        }
                    }

                    int max = m_original_system_count + 1; // +1 for SimplifiedDots
                    if (m_client.NumerologySystem.TextMode != "SimplifiedDots")
                    {
                        int last_pad_length = (m_client.NumerologySystem.TextMode == "Original") ? 32 : 40;
                        string last_str1 = "SimplifiedDots_Letters_Dots".PadRight(last_pad_length);
                        last_pad_length = (m_client.NumerologySystem.TextMode == "Original") ? 8 : 12;
                        string last_str2 = m_numerology_value_labels[max - 1].Text.PadRight(last_pad_length);
                        long last_value = 0L;
                        if (long.TryParse(last_str2, out last_value))
                        {
                            string last_str3 = Numbers.GetNumberTypeAsString(last_value);
                            string last_str4 = Numbers.FactorizeToString(last_value);
                            str.AppendLine(last_str1 + "\t" + last_str2 + "\t" + last_str3 + "\t" + last_str4);
                        }
                    }

                    str.AppendLine();
                    str.AppendLine(m_current_text);
                }
            }
        }
        else
        {
            filename = (m_values_sequence_right_to_left ? "R2L" : "L2R") + "_" + "Base" + m_values_sequence_radix + " " + ValuesSequenceScopeComboBox.SelectedItem.ToString() + ".txt";
            str.AppendLine(ValuesSequenceTextBox.Text);
        }

        if (Directory.Exists(Globals.STATISTICS_FOLDER))
        {
            string path = Globals.STATISTICS_FOLDER + Path.DirectorySeparatorChar + filename;
            FileHelper.SaveText(path, str.ToString());
            FileHelper.DisplayFile(path);
        }
    }
    private void ValuesSequenceTextBox_Resize(object sender, EventArgs e)
    {
        ArrangeValuesSequenceLabels();
    }

    private Panel ValuesSequencePanel = null;
    private Label[] m_values_sequence_labels = null;
    private int WIDTH = 0;
    private int HEIGHT = 0;
    private int ROWS;
    private int COLS;
    private void CreateValuesSequenceLabels()
    {
        if (ValuesSequencePanel == null)
        {
            ValuesSequencePanel = new Panel();
            ValuesSequencePanel.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Right | AnchorStyles.Bottom;
            ValuesSequencePanel.BackColor = Color.White;
            ValuesSequencePanel.Location = ValuesSequenceTextBox.Location;
            ValuesSequencePanel.Dock = DockStyle.Fill;
            ValuesSequencePanel.AutoScroll = true;

            ValuesSequenceTextBox.Controls.Add(ValuesSequencePanel);
        }

        if (ValuesSequencePanel != null)
        {
            try
            {
                ValuesSequencePanel.SuspendLayout();

                if (m_client != null)
                {
                    if (m_client.LoadedNumerologySystems != null)
                    {
                        int count = 0;
                        foreach (NumerologySystem ns in m_client.LoadedNumerologySystems.Values)
                        {
                            if (TextModeComboBox.SelectedItem != null)
                            {
                                if (ns.TextMode == TextModeComboBox.SelectedItem.ToString())
                                {
                                    count++;
                                }
                            }
                        }
                        m_values_sequence_labels = new Label[count];

                        WIDTH = (Globals.EDITION == Edition.Standard) ? ((m_dpi_x == 96.0F) ? 92 : 104) : (m_dpi_x == 96.0F) ? 64 : 92;
                        HEIGHT = 18;
                        COLS = (ValuesSequenceTextBox.Width - SystemInformation.VerticalScrollBarWidth) / WIDTH;
                        ROWS = (count / COLS) + ((count % COLS == 0) ? 0 : 1);

                        ValuesSequencePanel.Controls.Clear();
                        for (int n = 0; n < m_values_sequence_labels.Length; n++)
                        {
                            Label label = new Label();
                            if (label != null)
                            {
                                int i = n / COLS;
                                int j = n % COLS;
                                label.Width = WIDTH;
                                label.Height = HEIGHT;
                                label.Top = i * HEIGHT;
                                label.Left = j * WIDTH;
                                label.Padding = new Padding(1, 0, 1, 0);
                                label.BorderStyle = BorderStyle.None;
                                label.Font = new Font("Microsoft Sans Serif", 8.25F);
                                label.BackColor = Color.White;
                                label.TextAlign = ContentAlignment.MiddleCenter;
                                label.Cursor = Cursors.Hand;
                                label.Click += ValuesSequenceLabel_Click;

                                m_values_sequence_labels[n] = label;
                                ValuesSequencePanel.Controls.Add(label);
                            }
                        }
                    }
                }
            }
            finally
            {
                ValuesSequencePanel.ResumeLayout();
            }
        }
    }
    private List<string> m_values_sequence_numerology_system_names = null;
    private void ArrangeValuesSequenceLabels()
    {
        if (m_values_sequence_labels != null)
        {
            int count = m_values_sequence_labels.Length;
            if (WIDTH > 0)
            {
                int cols = (ValuesSequenceTextBox.Width - SystemInformation.VerticalScrollBarWidth) / WIDTH;
                int rows = (count / COLS) + ((count % COLS == 0) ? 0 : 1);

                if ((COLS != cols) || (ROWS != rows))
                {
                    COLS = cols;
                    ROWS = rows;

                    for (int n = 0; n < m_values_sequence_labels.Length; n++)
                    {
                        int i = n / COLS;
                        int j = n % COLS;
                        m_values_sequence_labels[n].Width = WIDTH;
                        m_values_sequence_labels[n].Height = HEIGHT;
                        m_values_sequence_labels[n].Top = i * HEIGHT;
                        m_values_sequence_labels[n].Left = j * WIDTH;
                    }
                }
            }
        }
    }
    private void DisplayValuesSequence(string text)
    {
        ////if (TabControl.SelectedTab == ValuesSequenceTabPage)
        {
            if (m_client != null)
            {
                if (m_client.LoadedNumerologySystems != null)
                {
                    m_values_sequence_numerology_system_names = new List<string>();
                    foreach (NumerologySystem ns in m_client.LoadedNumerologySystems.Values)
                    {
                        if (ns.TextMode == m_client.NumerologySystem.TextMode)
                        {
                            m_values_sequence_numerology_system_names.Add(ns.LetterOrder + "_" + ns.LetterValue);
                        }
                    }

                    ClearValuesSequenceLabels();
                    if (m_values_sequence_numerology_system_names != null)
                    {
                        if (COLS > 0)
                        {
                            List<string> names = new List<string>();
                            for (int n = 0; n < m_values_sequence_numerology_system_names.Count; n++)
                            {
                                names.Add(m_client.NumerologySystem.TextMode + "_" + m_values_sequence_numerology_system_names[n]);
                                long value = m_client.LoadedNumerologySystems.ContainsKey(names[n]) ? m_client.LoadedNumerologySystems[names[n]].CalculateValue(text) : 0L;
                                if ((n >= 0) && (n < m_values_sequence_labels.Length))
                                {
                                    m_values_sequence_labels[n].Text = value.ToString();
                                    m_values_sequence_labels[n].ForeColor = Numbers.GetNumberTypeColor(value);
                                    m_values_sequence_labels[n].BackColor = (Numbers.Compare((int)value, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : Color.White;
                                    if (value.IsInterestingX(INTERESTINGX_COUNT))
                                        m_values_sequence_labels[n].BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                                    if (value.IsInteresting())
                                        m_values_sequence_labels[n].BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                                    if (value.IsCarmichaelX())
                                        m_values_sequence_labels[n].BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                                    if (value.IsCarmichael())
                                        m_values_sequence_labels[n].BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                                    ToolTip.SetToolTip(this.m_values_sequence_labels[n], m_values_sequence_numerology_system_names[n] + "\r\n" + value.ToString() + " = " + Numbers.FactorizeToString(value)
                                        + "\r\n" + value.FindInterestingSums(INTERESTINGX_COUNT));

                                    // display default_numerology_system in BOLD
                                    if (m_values_sequence_numerology_system_names[n] == NumerologySystem.DEFAULT_SUB_NAME)
                                    {
                                        m_values_sequence_labels[n].Font = new Font("Microsoft Sans Serif", 8.25F, FontStyle.Bold);
                                    }
                                    else
                                    {
                                        m_values_sequence_labels[n].Font = new Font("Microsoft Sans Serif", 8.25F);
                                    }

                                    m_values_sequence_labels[n].Refresh();
                                }
                            }
                        }
                    }

                    int index = NumerologySystemComboBox.SelectedIndex;
                    if (index != -1)
                    {
                        SelectValuesSequenceLabel(index);
                    }
                }
            }
        }
    }
    private void ClearValuesSequenceLabels()
    {
        if (m_values_sequence_labels != null)
        {
            for (int n = 0; n < m_values_sequence_labels.Length; n++)
            {
                if (m_values_sequence_labels[n] != null)
                {
                    m_values_sequence_labels[n].Text = "";
                    m_values_sequence_labels[n].Font = new Font("Microsoft Sans Serif", 8.25F);
                    m_values_sequence_labels[n].BackColor = Color.White;
                    m_values_sequence_labels[n].BorderStyle = BorderStyle.None;
                }
            }
        }
    }
    private void SelectValuesSequenceLabel(int index)
    {
        if (m_values_sequence_labels != null)
        {
            for (int n = 0; n < m_values_sequence_labels.Length; n++)
            {
                if (m_values_sequence_labels[n] != null)
                {
                    m_values_sequence_labels[n].BorderStyle = BorderStyle.None;
                }
            }

            if ((index >= 0) && (index < m_values_sequence_labels.Length))
            {
                Label label = m_values_sequence_labels[index];
                if (label != null)
                {
                    label.BorderStyle = BorderStyle.FixedSingle;
                    label.Refresh();
                }
            }
        }
    }
    private int GetValuesSequenceLabelIndex(Label label)
    {
        for (int n = 0; n < m_values_sequence_labels.Length; n++)
        {
            if (m_values_sequence_labels[n] == label)
            {
                return n;
            }
        }
        return -1;
    }
    private void ValuesSequenceLabel_Click(object sender, EventArgs e)
    {
        try
        {
            if (sender is Label)
            {
                Label label = sender as Label;
                if (label != null)
                {
                    int n = GetValuesSequenceLabelIndex(label);
                    if ((n >= 0) && (n < m_values_sequence_labels.Length))
                    {
                        if ((n >= 0) && (n < m_values_sequence_numerology_system_names.Count))
                        {
                            if (NumerologySystemComboBox.SelectedItem.ToString() != m_values_sequence_numerology_system_names[n])
                            {
                                NumerologySystemComboBox.SelectedItem = m_values_sequence_numerology_system_names[n];
                            }
                            else
                            {
                                NumerologySystemComboBox_SelectedIndexChanged(null, null);
                            }
                        }
                        else
                        {
                            NumerologySystemComboBox_SelectedIndexChanged(null, null);
                        }
                    }
                }
            }
        }
        catch
        {
            NumerologySystemComboBox_SelectedIndexChanged(null, null);
        }
    }

    private bool m_mouse_down = false;
    private bool m_usertext_mode_values_sequence = false;
    private void CalculateValuesSequenceUserTextValue()
    {
        int char_index = ValuesSequenceUserTextBox.GetFirstCharIndexOfCurrentLine();
        if (char_index >= 0)
        {
            m_current_text = ValuesSequenceUserTextBox.Text;
            if (ValuesSequenceUserTextBox.SelectionLength > 0)
            {
                // selected text
                m_current_text = ValuesSequenceUserTextBox.SelectedText;
            }
            else
            {
                // get current line text
                if (char_index >= 0)
                {
                    string text = ValuesSequenceUserTextBox.Text;
                    if (!String.IsNullOrEmpty(text))
                    {
                        int text_end = text.Length;
                        int index2 = text.IndexOf('\n', char_index);
                        if (index2 > -1)
                            text_end = index2 - 1; // skip '\r'
                        m_current_text = ValuesSequenceUserTextBox.Text.Substring(char_index, text_end - char_index);
                    }
                }
            }

            m_current_text = m_current_text.Replace("\r", "");
            m_current_text = m_current_text.Replace("\t", "");
            m_current_text = m_current_text.Replace("_", "");
            m_current_text = m_current_text.Replace(Constants.ORNATE_RIGHT_PARENTHESIS, "");
            m_current_text = m_current_text.Replace(Constants.ORNATE_LEFT_PARENTHESIS, "");
            foreach (char character in Constants.INDIAN_DIGITS)
            {
                m_current_text = m_current_text.Replace(character.ToString(), "");
            }
            foreach (char character in Constants.ARABIC_DIGITS)
            {
                m_current_text = m_current_text.Replace(character.ToString(), "");
            }
            foreach (char character in Constants.SYMBOLS)
            {
                m_current_text = m_current_text.Replace(character.ToString(), "");
            }
            foreach (char character in Constants.STOPMARKS)
            {
                m_current_text = m_current_text.Replace(character.ToString(), "");
            }
            foreach (char character in Constants.QURANMARKS)
            {
                m_current_text = m_current_text.Replace(character.ToString(), "");
            }
            m_current_text = m_current_text.Replace("\n ", "\n"); // quran marks
            m_current_text = m_current_text.Replace(" \n", "\n"); // sijood marks
            while (m_current_text.Contains("  "))
            {
                m_current_text = m_current_text.Replace("  ", " ");
            }

            if (m_client.NumerologySystem.LetterOrder != "English")
            {
                foreach (char character in Constants.ENGLISH_LETTERS)
                {
                    m_current_text = m_current_text.Replace(character.ToString(), "");
                }
            }

            m_current_text = m_current_text.Trim();
            DisplayValuesSequence(m_current_text);

            // calculate Letters value
            CalculateValueAndDisplayFactors(m_current_text);

            // calculate and display verse_number_sum, word_number_sum, letter_number_sum
            CalculateAndDisplayCounts(m_current_text);

            BuildLetterFrequencies();
            DisplayLetterFrequencies();

            if (ValuesSequenceUserTextBox.SelectionLength > 0)
            {
                DisplayWordFrequencies();
                this.AcceptButton = null;  // prevent stealing focus by this.AcceptButton = FindByTextButton;
            }
            else
            {
                WordFrequencyListBoxLabel.Visible = false;
                WordFrequencyListBox.Visible = false;
                WordFrequencyWithDiacriticsCheckBox.Visible = false;
            }
        }
    }
