    private void WordFrequencyListBox_KeyDown(object sender, KeyEventArgs e)
    {
        if (e.KeyCode == Keys.Enter)
        {
            if (WordFrequencyListBox.SelectedIndices.Count > 1)
            {
                FindSelectedWordsMenuItem_Click(null, null);
            }
            else
            {
                WordFrequencyListBox_DoubleClick(sender, e);
            }
        }
        else if (e.KeyCode == Keys.Space)
        {
            FindByTextTextBox.Text += " ";
            FindByTextTextBox.Focus();
        }
        else if ((e.KeyCode == Keys.Left) || (e.KeyCode == Keys.Right))
        {
            FindByTextTextBox.Focus();
        }
        FindByTextTextBox.SelectionStart = FindByTextTextBox.Text.Length;
    }
    private void WordFrequencyListBox_MouseDown(object sender, MouseEventArgs e)
    {
        if (e.Button == MouseButtons.Right)
        {
            // set cursor at mouse RIGHT-click location so we know which word to Find
            if (WordFrequencyListBox.SelectedIndices.Count == 1)
            {
                WordFrequencyListBox.SelectedIndex = -1;
            }
            WordFrequencyListBox.SelectedIndex = WordFrequencyListBox.IndexFromPoint(e.X, e.Y);
        }
    }
    private void WordFrequencyListBox_MouseMove(object sender, MouseEventArgs e)
    {
        if (ModifierKeys == Keys.Control)
        {
            if (m_client != null)
            {
                int index = WordFrequencyListBox.IndexFromPoint(e.Location);
                if (index != m_previous_index)
                {
                    m_previous_index = index;
                    if ((index >= 0) && (index < WordFrequencyListBox.Items.Count))
                    {
                        char[] separators = { ' ' };
                        string[] parts = WordFrequencyListBox.Items[index].ToString().Split(separators, StringSplitOptions.RemoveEmptyEntries);
                        if (parts.Length > 1)
                        {
                            DisplayWordVerses(parts[1]);
                        }
                    }
                }
            }
        }
        else
        {
            ToolTip.SetToolTip(this.WordFrequencyListBox, null);
        }
    }
