    private void WordFrequencyListBox_SelectedIndexChanged(object sender, EventArgs e)
    {
        if (m_word_frequency_dictionary != null)
        {
            int count = 0;
            int total = 0;
            if (WordFrequencyListBox.SelectedIndices.Count > 1)
            {
                // update total(unique) counts
                foreach (object item in WordFrequencyListBox.SelectedItems)
                {
                    string[] parts = item.ToString().Split();
                    if (parts.Length > 0)
                    {
                        total += int.Parse(parts[0]);
                        count++;
                    }
                }
            }
            else
            {
                // restore total(unique) counts
                foreach (string key in m_word_frequency_dictionary.Keys)
                {
                    total += m_word_frequency_dictionary[key];
                    count++;
                }
            }

            WordFrequencyListBoxLabel.Text = total.ToString() + " (" + count.ToString() + ")";
            WordFrequencyListBoxLabel.ForeColor = Numbers.GetNumberTypeColor(total);
            WordFrequencyListBoxLabel.Refresh();
        }
    }
    private void WordFrequencyListBoxLabel_Click(object sender, EventArgs e)
    {
        if (ModifierKeys == Keys.Control)
        {
            FactorizeNumber(sender as Label);
        }
        else
        {
            m_compare_by_word_frequency = !m_compare_by_word_frequency;
            ToolTip.SetToolTip(this.WordFrequencyListBoxLabel, (m_compare_by_word_frequency ? "sort alphabetically" : "sort by frequency"));

            if (m_auto_complete_mode)
            {
                PopulateWordFrequencyListBox();
            }
            else
            {
                PopulateWordFrequencyListBoxWithHighlightedWords();
            }
        }
    }
    private void AddNextWordToFindText()
    {
        if (WordFrequencyListBox.SelectedItem != null)
        {
            string word_to_add = WordFrequencyListBox.SelectedItem.ToString();
            int pos = word_to_add.LastIndexOf(' ');
            if (pos > -1)
            {
                word_to_add = word_to_add.Substring(pos + 1);
            }

            string text = FindByTextTextBox.Text;
            int index = text.LastIndexOf(' ');
            if (index != -1)
            {
                if (text.Length > index + 1)
                {
                    if ((text[index + 1] == '+') || (text[index + 1] == '-'))
                    {
                        index++;
                    }
                }

                text = text.Substring(0, index + 1);
                text += word_to_add;
                FindByTextTextBox.Text = text + " ";
            }
            else
            {
                FindByTextTextBox.Text = word_to_add + " ";
            }
            FindByTextTextBox.Refresh();
            FindByTextTextBox.SelectionStart = FindByTextTextBox.Text.Length;
        }
    }
    private void PopulateWordFrequencyListBox()
    {
        switch (m_text_search_type)
        {
            case TextSearchType.Exact:
                {
                    PopulateWordFrequencyListBoxWithCurrentOrNextWords();
                }
                break;
            case TextSearchType.Proximity:
                {
                    PopulateWordFrequencyListBoxWithCurrentWords();
                }
                break;
            case TextSearchType.Root:
                {
                    PopulateWordFrequencyListBoxWithRoots();
                }
                break;
        }

        WordFrequencyListBoxLabel.Visible = true;
        WordFrequencyListBox.Visible = true;
        FindByTextWithDiacriticsCheckBox.Visible = true;
    }
    private void PopulateWordFrequencyListBoxWithCurrentOrNextWords()
    {
        try
        {
            for (int i = 0; i < 3; i++)
                WordFrequencyListBox.SelectedIndexChanged -= new System.EventHandler(WordFrequencyListBox_SelectedIndexChanged);

            if (m_client != null)
            {
                //SearchGroupBox.Text = " Search by Exact words      ";
                //SearchGroupBox.Refresh();
                //WordFrequencyListBoxLabel.Text = "000 (00)";
                //WordFrequencyListBoxLabel.ForeColor = Numbers.GetNumberTypeColor(0);
                //WordFrequencyListBoxLabel.Refresh();

                WordFrequencyListBox.BeginUpdate();
                WordFrequencyListBox.Items.Clear();

                m_auto_complete_mode = true;
                WordFrequencyWithDiacriticsCheckBox.Visible = false;

                string text = FindByTextTextBox.Text;
                if (!String.IsNullOrEmpty(text))
                {
                    if (text.EndsWith(" "))
                    {
                        m_word_frequency_dictionary = m_client.GetNextWords(text, m_text_location_in_chapter, m_text_location_in_verse, m_text_location_in_word, m_text_wordness, m_case_sensitive, m_with_diacritics);
                    }
                    else
                    {
                        m_word_frequency_dictionary = m_client.GetCurrentWords(text, m_text_location_in_chapter, m_text_location_in_verse, m_text_location_in_word, m_text_wordness, m_case_sensitive, m_with_diacritics);
                    }

                    if (m_word_frequency_dictionary != null)
                    {
                        // sort dictionary by value or key
                        List<KeyValuePair<string, int>> list = new List<KeyValuePair<string, int>>(m_word_frequency_dictionary);
                        if (list != null)
                        {
                            if (m_compare_by_word_frequency)
                            {
                                list.Sort(
                                    delegate (KeyValuePair<string, int> firstPair, KeyValuePair<string, int> nextPair)
                                    {
                                        return nextPair.Value.CompareTo(firstPair.Value);
                                    }
                                );
                            }
                            else
                            {
                                list.Sort(
                                    delegate (KeyValuePair<string, int> firstPair, KeyValuePair<string, int> nextPair)
                                    {
                                        return firstPair.Key.CompareTo(nextPair.Key);
                                    }
                                );
                            }

                            int count = 0;
                            int total = 0;
                            foreach (KeyValuePair<string, int> pair in list)
                            {
                                //string value_str = found_words[key].ToString().PadRight(3, ' ');
                                //string key_str = key.PadLeft(10, ' ');
                                //string entry = String.Format("{0} {1}", value_str, key_str);
                                string entry = String.Format("{0,-3} {1,10}", pair.Value, pair.Key);
                                WordFrequencyListBox.Items.Add(entry);
                                total += pair.Value;
                                count++;
                            }

                            if (WordFrequencyListBox.Items.Count > 0)
                            {
                                WordFrequencyListBox.SelectedIndex = 0;
                            }
                            else // no match [either current text_mode doesn't have a match or it was last word in verse]
                            {
                                // m_word_frequency_list_double_click == false if input was via keyboard
                                // m_word_frequency_list_double_click == true  if input was via double click
                                // if no more word when double click, then it means it was the last word in the verse
                                // else the user has entered non-matching text

                                // if last word in verse, remove the extra space after it
                                if ((m_word_double_click) && (WordFrequencyListBox.Items.Count == 0) && (FindByTextTextBox.Text.EndsWith(" ")))
                                {
                                    for (int i = 0; i < 3; i++)
                                        FindByTextTextBox.TextChanged -= new System.EventHandler(FindByTextTextBox_TextChanged);
                                    try
                                    {
                                        FindByTextTextBox.Text = FindByTextTextBox.Text.Remove(FindByTextTextBox.Text.Length - 1);
                                    }
                                    catch (Exception ex)
                                    {
                                        MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
                                    }
                                    finally
                                    {
                                        FindByTextTextBox.TextChanged += new System.EventHandler(FindByTextTextBox_TextChanged);
                                    }
                                }
                            }

                            WordFrequencyListBoxLabel.Text = total.ToString() + " (" + count.ToString() + ")";
                            WordFrequencyListBoxLabel.ForeColor = Numbers.GetNumberTypeColor(total);
                            WordFrequencyListBoxLabel.Refresh();
                        }
                    }
                }
                else
                {
                    WordFrequencyListBoxLabel.Text = "0 (0)";
                    WordFrequencyListBoxLabel.ForeColor = Numbers.GetNumberTypeColor(0L);
                    WordFrequencyListBoxLabel.Refresh();
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            WordFrequencyListBox.EndUpdate();
            WordFrequencyListBox.SelectedIndexChanged += new System.EventHandler(WordFrequencyListBox_SelectedIndexChanged);
        }
    }
