    private void PopulateWordFrequencyListBoxWithRoots()
    {
        try
        {
            for (int i = 0; i < 3; i++)
                WordFrequencyListBox.SelectedIndexChanged -= new System.EventHandler(WordFrequencyListBox_SelectedIndexChanged);

            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    //SearchGroupBox.Text = " Search by Roots            ";
                    //SearchGroupBox.Refresh();
                    //WordFrequencyListBoxLabel.Text = "000 (00)";
                    //WordFrequencyListBoxLabel.ForeColor = Numbers.GetNumberTypeColor(0);
                    //WordFrequencyListBoxLabel.Refresh();

                    WordFrequencyListBox.BeginUpdate();
                    WordFrequencyListBox.Items.Clear();

                    m_auto_complete_mode = true;
                    WordFrequencyWithDiacriticsCheckBox.Visible = false;

                    string text = FindByTextTextBox.Text;

                    // to support multi root search take the last word a user is currently writing
                    string[] text_parts = text.Split();
                    if (text_parts.Length > 0)
                    {
                        text = text_parts[text_parts.Length - 1];
                    }

                    m_word_frequency_dictionary = new Dictionary<string, int>();
                    if (m_word_frequency_dictionary != null)
                    {
                        switch (m_client.SearchScope)
                        {
                            case SearchScope.Book:
                                {
                                    m_word_frequency_dictionary = m_client.Book.GetRoots(m_client.Book.Verses, text, m_text_location_in_word);
                                }
                                break;
                            case SearchScope.Selection:
                                {
                                    m_word_frequency_dictionary = m_client.Book.GetRoots(m_client.Selection.Verses, text, m_text_location_in_word);
                                }
                                break;
                            case SearchScope.Result:
                                {
                                    m_word_frequency_dictionary = m_client.Book.GetRoots(m_client.FoundVerses, text, m_text_location_in_word);
                                }
                                break;
                        }

                        if (m_word_frequency_dictionary != null)
                        {
                            // sort dictionary by value or key
                            List<KeyValuePair<string, int>> list = new List<KeyValuePair<string, int>>(m_word_frequency_dictionary);
                            if (m_compare_by_word_frequency)
                            {
                                list.Sort(
                                    delegate (KeyValuePair<string, int> firstPair, KeyValuePair<string, int> nextPair)
                                    {
                                        return nextPair.Value.CompareTo(firstPair.Value);
                                    }
                                );
                            }
                            else
                            {
                                list.Sort(
                                    delegate (KeyValuePair<string, int> firstPair, KeyValuePair<string, int> nextPair)
                                    {
                                        return firstPair.Key.CompareTo(nextPair.Key);
                                    }
                                );
                            }

                            int count = 0;
                            int total = 0;
                            foreach (KeyValuePair<string, int> pair in list)
                            {
                                //string value_str = found_words[key].ToString().PadRight(3, ' ');
                                //string key_str = key.PadLeft(10, ' ');
                                //string entry = String.Format("{0} {1}", value_str, key_str);
                                string entry = String.Format("{0,-3} {1,10}", pair.Value, pair.Key);
                                WordFrequencyListBox.Items.Add(entry);
                                total += pair.Value;
                                count++;
                            }

                            if (WordFrequencyListBox.Items.Count > 0)
                            {
                                WordFrequencyListBox.SelectedIndex = 0;
                            }
                            else
                            {
                                // if not a valid root, put word as is so we can find same rooted words
                                WordFrequencyListBox.Items.Add(text);
                            }
                            WordFrequencyListBoxLabel.Text = total.ToString() + " (" + count.ToString() + ")";
                            WordFrequencyListBoxLabel.ForeColor = Numbers.GetNumberTypeColor(total);
                            WordFrequencyListBoxLabel.Refresh();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            WordFrequencyListBox.EndUpdate();
            WordFrequencyListBox.SelectedIndexChanged += new System.EventHandler(WordFrequencyListBox_SelectedIndexChanged);
        }
    }
    private void PopulateWordFrequencyListBoxWithHighlightedWords()
    {
        try
        {
            for (int i = 0; i < 3; i++)
                WordFrequencyListBox.SelectedIndexChanged -= new System.EventHandler(WordFrequencyListBox_SelectedIndexChanged);

            if (m_client != null)
            {
                if (m_client.NumerologySystem != null)
                {
                    WordFrequencyListBox.BeginUpdate();
                    WordFrequencyListBox.Items.Clear();

                    m_auto_complete_mode = false;
                    WordFrequencyWithDiacriticsCheckBox.Visible = (m_client.NumerologySystem.TextMode == "Original") || m_usertext_mode;

                    string text = m_current_text;
                    if (!String.IsNullOrEmpty(text))
                    {
                        text = text.Replace("\n", " ");
                        text = text.Replace("\r", "");
                        text = text.Replace("\t", "");
                        text = text.Replace("_", "");
                        text = text.Replace(Constants.ORNATE_RIGHT_PARENTHESIS, "");
                        text = text.Replace(Constants.ORNATE_LEFT_PARENTHESIS, "");
                        foreach (char character in Constants.INDIAN_DIGITS)
                        {
                            text = text.Replace(character.ToString(), "");
                        }
                        foreach (char character in Constants.ARABIC_DIGITS)
                        {
                            text = text.Replace(character.ToString(), "");
                        }
                        foreach (char character in Constants.SYMBOLS)
                        {
                            text = text.Replace(character.ToString(), "");
                        }
                        foreach (char character in Constants.STOPMARKS)
                        {
                            text = text.Replace(character.ToString(), "");
                        }
                        foreach (char character in Constants.QURANMARKS)
                        {
                            text = text.Replace(character.ToString(), "");
                        }
                        if (!m_word_frequency_with_diacritics)
                        {
                            text = text.Simplify(m_client.NumerologySystem.TextMode);
                        }
                        while (text.Contains("  "))
                        {
                            text = text.Replace("  ", " ");
                        }
                        text = text.Trim();

                        string[] words = text.Split();
                        m_word_frequency_dictionary = new Dictionary<string, int>();
                        if (m_word_frequency_dictionary != null)
                        {
                            foreach (string word in words)
                            {
                                if (m_word_frequency_dictionary.ContainsKey(word))
                                {
                                    m_word_frequency_dictionary[word]++;
                                }
                                else
                                {
                                    m_word_frequency_dictionary.Add(word, 1);
                                }
                            }

                            // sort dictionary by value or key
                            List<KeyValuePair<string, int>> list = new List<KeyValuePair<string, int>>(m_word_frequency_dictionary);
                            if (m_compare_by_word_frequency)
                            {
                                list.Sort(
                                    delegate (KeyValuePair<string, int> pair, KeyValuePair<string, int> next)
                                    {
                                        return next.Value.CompareTo(pair.Value);
                                    }
                                );
                            }
                            else
                            {
                                list.Sort(
                                    delegate (KeyValuePair<string, int> pair, KeyValuePair<string, int> next)
                                    {
                                        return pair.Key.CompareTo(next.Key);
                                    }
                                );
                            }

                            int count = 0;
                            int total = 0;
                            foreach (KeyValuePair<string, int> pair in list)
                            {
                                string entry = String.Format("{0,-3} {1,10}", pair.Value, pair.Key);
                                WordFrequencyListBox.Items.Add(entry);
                                total += pair.Value;
                                count++;
                            }

                            if (WordFrequencyListBox.Items.Count > 0)
                            {
                                WordFrequencyListBox.SelectedIndex = 0;
                            }
                            else
                            {
                                // if not a valid word, keep word as is
                            }

                            WordFrequencyListBoxLabel.Text = total.ToString() + " (" + count.ToString() + ")";
                            WordFrequencyListBoxLabel.ForeColor = Numbers.GetNumberTypeColor(total);
                            WordFrequencyListBoxLabel.Refresh();
                        }
                    }
                    else
                    {
                        WordFrequencyListBoxLabel.Text = "0 (0)";
                        WordFrequencyListBoxLabel.ForeColor = Numbers.GetNumberTypeColor(0L);
                        WordFrequencyListBoxLabel.Refresh();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            WordFrequencyListBox.EndUpdate();
            WordFrequencyListBox.SelectedIndexChanged += new System.EventHandler(WordFrequencyListBox_SelectedIndexChanged);
        }
    }
    private void DisplayWordFrequencies()
    {
        PopulateWordFrequencyListBoxWithHighlightedWords();
        UpdateFindByTextControls();

        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;
        ToolTip.SetToolTip(this.InspectChaptersLabel, L[l]["Inspect word frequencies"]);

        WordFrequencyListBoxLabel.Visible = true;
        WordFrequencyListBox.Visible = true;
        FindByTextWithDiacriticsCheckBox.Visible = true;
    }
    private void DisplayWordVerses(string item_text)
    {
        if (Globals.EDITION != Edition.Standard)
        {
            if (!String.IsNullOrEmpty(item_text))
            {
                if (m_client != null)
                {
                    List<Verse> backup_found_verses = null;
                    List<Phrase> backup_found_phrases = null;
                    if (m_client.FoundVerses != null)
                    {
                        backup_found_verses = new List<Verse>(m_client.FoundVerses);
                    }
                    if (m_client.FoundPhrases != null)
                    {
                        backup_found_phrases = new List<Phrase>(m_client.FoundPhrases);
                    }

                    // get startup text from FindTextBox
                    string[] startup_words = FindByTextTextBox.Text.Split();
                    int count = startup_words.Length;
                    // ignore final incomplete word
                    if (!FindByTextTextBox.Text.EndsWith(" "))
                    {
                        count--;
                    }
                    string startup_text = "";
                    for (int i = 0; i < count; i++)
                    {
                        startup_text += startup_words[i] + " ";
                    }
                    if (startup_text.Length > 0)
                    {
                        startup_text = startup_text.Remove(startup_text.Length - 1, 1);
                    }

                    List<string> word_texts = new List<string>();
                    char[] separators = { ' ' };
                    string[] parts = item_text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
                    if (parts.Length == 1)  // root
                    {
                        word_texts.Add(parts[0]);
                    }
                    else if (parts.Length == 2) // exact or proximity
                    {
                        word_texts.Add(parts[1]);
                    }

                    // setup search parameters
                    string text = "";
                    //string translation = Client.DEFAULT_TRANSLATION;

                    // update m_text_location_in_verse and m_text_location_in_word
                    //UpdateFindByTextOptions();

                    List<Verse> total_verses = new List<Verse>();
                    if (word_texts.Count > 0)
                    {
                        foreach (string word_text in word_texts)
                        {
                            if (startup_text.Length > 0)
                            {
                                text = startup_text + " " + word_text;
                            }
                            else
                            {
                                text = word_text;
                            }

                            if (!String.IsNullOrEmpty(text))
                            {
                                switch (m_text_search_type)
                                {
                                    case TextSearchType.Exact:
                                        {
                                            m_client.FindPhrases(TextSearchBlockSize.Verse, text, m_language_type, null, m_text_location_in_chapter, m_text_location_in_verse, m_text_location_in_word, TextWordness.WholeWord, m_case_sensitive, m_with_diacritics, m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder);
                                        }
                                        break;
                                    case TextSearchType.Proximity:
                                        {
                                            m_client.FindWords(TextSearchBlockSize.Verse, text, m_language_type, null, m_text_word_grouping, TextWordness.WholeWord, m_case_sensitive, m_with_diacritics);
                                        }
                                        break;
                                    case TextSearchType.Root:
                                        {
                                            m_client.FindWords(TextSearchBlockSize.Verse, text, m_text_word_grouping, m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder);
                                        }
                                        break;
                                }

                                total_verses = total_verses.Union(m_client.FoundVerses);
                            }
                        }

                        int i = 0;
                        StringBuilder str = new StringBuilder();
                        foreach (Verse verse in total_verses)
                        {
                            i++;
                            if (i > 114)
                                break;
                            str.AppendLine(verse.Text);
                        }
                        ToolTip.SetToolTip(this.WordFrequencyListBox, str.ToString());
                    }

                    if (backup_found_verses != null)
                    {
                        m_client.FoundVerses = backup_found_verses;
                    }
                    if (backup_found_phrases != null)
                    {
                        m_client.FoundPhrases = backup_found_phrases;
                    }
                }
            }
        }
    }
    private bool m_word_frequency_with_diacritics = false;
    private void WordFrequencyWithDiacriticsCheckBox_CheckedChanged(object sender, EventArgs e)
    {
        m_word_frequency_with_diacritics = WordFrequencyWithDiacriticsCheckBox.Checked;
        DisplayWordFrequencies();
    }
    private void FindSelectedWordsMenuItem_Click(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                ClearFoundMatches();

                // get startup text from FindTextBox
                string[] startup_words = FindByTextTextBox.Text.Split();
                int count = startup_words.Length;
                // ignore final incomplete word
                if (!FindByTextTextBox.Text.EndsWith(" "))
                {
                    count--;
                }

                string startup_text = "";
                if (m_auto_complete_mode)
                {
                    for (int i = 0; i < count; i++)
                    {
                        startup_text += startup_words[i] + " ";
                    }
                    if (startup_text.Length > 0)
                    {
                        startup_text = startup_text.Remove(startup_text.Length - 1, 1);
                    }
                }

                // get selected word texts
                List<string> word_texts = new List<string>();
                if (WordFrequencyListBox.SelectedIndices.Count > 0)
                {
                    char[] separators = { ' ' };
                    foreach (object item in WordFrequencyListBox.SelectedItems)
                    {
                        string[] parts = item.ToString().Split(separators, StringSplitOptions.RemoveEmptyEntries);
                        if (parts.Length == 1)  // root
                        {
                            word_texts.Add(parts[0]);
                        }
                        else if (parts.Length == 2) // exact or proximity
                        {
                            word_texts.Add(parts[1]);
                        }
                    }
                }

                // setup search parameters
                string text = "";
                //string translation = Client.DEFAULT_TRANSLATION;

                // update m_text_location_in_verse and m_text_location_in_word
                //UpdateFindByTextOptions();

                if (word_texts.Count > 0)
                {
                    foreach (string word_text in word_texts)
                    {
                        if (startup_text.Length > 0)
                        {
                            text += startup_text + " " + word_text + "|"; // "|" for Regex
                        }
                        else
                        {
                            text += word_text + "|"; // "|" for Regex
                        }
                    }
                    if (text.Length > 0)
                    {
                        text = text.Remove(text.Length - 1, 1);
                    }

                    if (!String.IsNullOrEmpty(text))
                    {
                        switch (m_text_search_type)
                        {
                            case TextSearchType.Exact:
                                {
                                    text = "(" + text + ")";  // "(" and ")" for Regex
                                    if (FindByTextTextBox.Text.EndsWith(" "))
                                    {
                                        m_client.FindPhrases(TextSearchBlockSize.Verse, text, m_language_type, null, m_text_location_in_chapter, m_text_location_in_verse, m_text_location_in_word, TextWordness.Any, m_case_sensitive, m_with_diacritics, m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder);
                                    }
                                    else
                                    {
                                        m_client.FindPhrases(TextSearchBlockSize.Verse, text, m_language_type, null, m_text_location_in_chapter, m_text_location_in_verse, m_text_location_in_word, TextWordness.WholeWord, m_case_sensitive, m_with_diacritics, m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder);
                                    }
                                }
                                break;
                            case TextSearchType.Proximity:
                                {
                                    //m_client.FindWords(TextSearchBlockSize.Verse, text, m_language_type, null, m_text_word_grouping, TextWordness.Any, m_case_sensitive, m_with_diacritics);
                                    m_client.FindWords(TextSearchBlockSize.Verse, text, m_language_type, null, TextWordGrouping.Or, TextWordness.WholeWord, false, false);
                                }
                                break;
                            case TextSearchType.Root:
                                {
                                    //m_client.FindWords(TextSearchBlockSize.Verse, text, m_text_word_grouping, m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder);
                                    m_client.FindWords(TextSearchBlockSize.Verse, text, TextWordGrouping.Or, m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder);
                                }
                                break;
                        }
                    }
                }

                // display results
                if ((m_client.FoundWords != null) && (m_client.FoundWords.Count > 0))
                {
                    int word_count = GetValidWordCount(m_client.FoundWords);
                    if (m_client.FoundVerses != null)
                    {
                        int verse_count = m_client.FoundVerses.Count;
                        m_header_label_info = word_count + " " + L[l]["matches"] + " " + L[l]["in"] + " " + verse_count + ((verse_count == 1) ? " " + L[l]["verse"] : " " + L[l]["verses"]) + " " + L[l]["with"] + " " + text + " C_" + m_text_location_in_chapter.ToString() + " V_" + m_text_location_in_verse.ToString() + " W_" + m_text_location_in_word.ToString() + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                        DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, true);

                        WordFrequencyListBoxLabel.Visible = false;
                        WordFrequencyListBox.Visible = false;
                        WordFrequencyWithDiacriticsCheckBox.Visible = false;
                    }
                }
                else if ((m_client.FoundPhrases != null) && (m_client.FoundPhrases.Count > 0))
                {
                    int phrase_count = GetValidPhraseCount(m_client.FoundPhrases);
                    if (m_client.FoundVerses != null)
                    {
                        int verse_count = m_client.FoundVerses.Count;
                        m_header_label_info = phrase_count + " " + L[l]["matches"] + " " + L[l]["in"] + " " + verse_count + ((verse_count == 1) ? " " + L[l]["verse"] : " " + L[l]["verses"]) + " " + L[l]["with"] + " " + text + " C_" + m_text_location_in_chapter.ToString() + " V_" + m_text_location_in_verse.ToString() + " W_" + m_text_location_in_word.ToString() + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                        DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, true);

                        WordFrequencyListBoxLabel.Visible = false;
                        WordFrequencyListBox.Visible = false;
                        WordFrequencyWithDiacriticsCheckBox.Visible = false;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void InspectWordFrequencies()
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            string text = FindByTextTextBox.Text;

            if (Directory.Exists(Globals.STATISTICS_FOLDER))
            {
                string path = Globals.STATISTICS_FOLDER + Path.DirectorySeparatorChar + ((m_text_search_type == TextSearchType.Root) ? "root_" : "") + text + ".txt";
                using (StreamWriter writer = new StreamWriter(path, false, Encoding.Unicode))
                {
                    StringBuilder str = new StringBuilder();
                    str.AppendLine("#" + "\t" + ((m_text_search_type == TextSearchType.Root) ? "Root" : "Word") + "\t" + "Frequency");

                    int count = 0;
                    int total = 0;
                    char[] separators = { ' ' };
                    if (WordFrequencyListBox.SelectedIndices.Count > 1)
                    {
                        foreach (object item in WordFrequencyListBox.SelectedItems)
                        {
                            string[] parts = item.ToString().Split(separators, StringSplitOptions.RemoveEmptyEntries);
                            if (parts.Length == 2)
                            {
                                count++;
                                total += int.Parse(parts[0]);
                                str.AppendLine(count + "\t" + parts[1] + "\t" + parts[0]);
                            }
                        }
                    }
                    else
                    {
                        foreach (object item in WordFrequencyListBox.Items)
                        {
                            string[] parts = item.ToString().Split(separators, StringSplitOptions.RemoveEmptyEntries);
                            if (parts.Length == 2)
                            {
                                count++;
                                total += int.Parse(parts[0]);
                                str.AppendLine(count + "\t" + parts[1] + "\t" + parts[0]);
                            }
                        }
                    }

                    str.AppendLine(((count * (count + 1)) / 2).ToString() + "\t" + count.ToString() + "\t" + total.ToString());

                    writer.Write(str.ToString());
                }

                // show file content after save
                FileHelper.DisplayFile(path);
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
