    private void FindByTextTextBox_TextChanged(object sender, EventArgs e)
    {
        this.AcceptButton = FindByTextButton;

        UpdateFindByTextControls();

        PopulateWordFrequencyListBox();

        UpdateLanguageType(FindByTextTextBox.Text);

        UpdateSearchScopeLabels();

        if (PictureBox.Visible)
        {
            if (m_current_drawing_type == DrawingType.SearchTerms)
            {
                RedrawImage();
            }
        }
        else // incremental search
        {
            string text = FindByTextTextBox.Text;
            if ((text.Length >= 3) || (m_active_textbox.Text.Length <= 33667)) // Chapter 2
            {
                HighlightText(text, Color.Red);
            }
        }
    }
    private void HighlightText(string text, Color color)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (m_client.NumerologySystem != null)
                {
                    m_active_textbox.BeginUpdate();

                    m_active_textbox.ClearColor();
                    m_active_textbox.SelectionLength = 0;

                    if (!String.IsNullOrEmpty(text))
                    {
                        int start = m_active_textbox.SelectionStart;
                        int start_index = 0;
                        int index = -1;

                        int chapter_number_sum = 0;
                        int verse_number_sum = 0;
                        int word_number_sum = 0;
                        int letter_number_sum = 0;
                        int chapter_count = 0;
                        int verse_count = 0;
                        int word_count = 0;
                        int letter_count = 0;
                        long value = 0L;

                        char[] separators = { ' ' };
                        string[] terms = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
                        foreach (string term in terms)
                        //foreach (string term in m_word_frequency_dictionary.Keys)
                        {
                            long term_value = m_client.CalculateValue(term);
                            while ((index = m_active_textbox.Text.IndexOf(term, start_index)) != -1)
                            {
                                value += term_value;

                                word_count++;
                                letter_count += term.Simplify(m_client.NumerologySystem.TextMode).Length;

                                m_active_textbox.Select(index, term.Length);
                                m_active_textbox.SelectionColor = color;

                                start_index = index + term.Length;
                            }
                            start_index = 0;
                        }
                        m_active_textbox.AlignToStart();

                        DisplayCounts(chapter_count, verse_count, word_count, letter_count, chapter_number_sum, verse_number_sum, word_number_sum, letter_number_sum);
                        FactorizeValue(value, "Value");
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            m_active_textbox.EndUpdate();
            this.Cursor = Cursors.Default;
        }
    }
    private void UpdateSearchScopeLabels()
    {
        SearchScopeBookLabel.BackColor = Color.DarkGray;
        SearchScopeBookLabel.BorderStyle = BorderStyle.None;
        SearchScopeSelectionLabel.BackColor = Color.DarkGray;
        SearchScopeSelectionLabel.BorderStyle = BorderStyle.None;
        SearchScopeResultLabel.BackColor = Color.DarkGray;
        SearchScopeResultLabel.BorderStyle = BorderStyle.None;

        switch (m_client.SearchScope)
        {
            case SearchScope.Book:
                {
                    SearchScopeBookLabel.BackColor = Color.SteelBlue;
                    SearchScopeBookLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case SearchScope.Selection:
                {
                    SearchScopeSelectionLabel.BackColor = Color.SteelBlue;
                    SearchScopeSelectionLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case SearchScope.Result:
                {
                    SearchScopeResultLabel.BackColor = Color.SteelBlue;
                    SearchScopeResultLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            default:
                break;
        }
    }
    private void FindByTextTextBox_KeyPress(object sender, KeyPressEventArgs e)
    {
        FixMicrosoft(sender, e);

        if (e.KeyChar == ' ')
        {
            // prevent double spaces
            if (FindByTextTextBox.SelectionStart > 0)
            {
                if (FindByTextTextBox.Text[FindByTextTextBox.SelectionStart - 1] == ' ')
                {
                    e.Handled = true;
                }
            }
        }
    }
    private void FindByTextTextBox_KeyDown(object sender, KeyEventArgs e)
    {
        if (ModifierKeys == Keys.Control)
        {
            if (e.KeyCode == Keys.A)
            {
                if (sender is TextBoxBase)
                {
                    (sender as TextBoxBase).SelectAll();
                }
            }
        }
        else if ((e.KeyCode == Keys.Up) || (e.KeyCode == Keys.Down))
        {
            WordFrequencyListBox.Focus();
        }
    }
    private void FindByTextButton_Click(object sender, EventArgs e)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            switch (m_text_search_type)
            {
                case TextSearchType.Exact:
                    {
                        if (WordFrequencyListBox.SelectedIndices.Count > 1)
                        {
                            FindSelectedWordsMenuItem_Click(null, null);
                        }
                        else
                        {
                            FindByExact();
                        }
                    }
                    break;
                case TextSearchType.Proximity:
                    {
                        FindByProximity();
                    }
                    break;
                case TextSearchType.Root:
                    {
                        if (WordFrequencyListBox.SelectedIndices.Count > 1)
                        {
                            FindSelectedWordsMenuItem_Click(null, null);
                        }
                        else
                        {
                            FindByRoot();
                        }
                    }
                    break;
                default:
                    {
                        FindByExact();
                    }
                    break;
            }

            SearchGroupBox_Leave(null, null);
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void FindByExact()
    {
        if (m_client != null)
        {
            string text = FindByTextTextBox.Text;
            if (text.Length > 0)
            {
                string translation = Client.DEFAULT_TRANSLATION;
                if ((m_show_all_translations) || (!text.IsArabic()))
                {
                    translation = null; // all translations
                }
                else
                {
                    if (TranslatorComboBox.SelectedItem != null)
                    {
                        translation = m_client.GetTranslationKey(TranslatorComboBox.SelectedItem.ToString());
                    }
                }

                //UpdateFindByTextOptions();

                FindByExact(text, m_language_type, translation, m_text_wordness, m_case_sensitive, m_with_diacritics);
            }
            else // find consecutive words
            {
                FindRepeatedWords();
            }
        }
    }
    private void FindByExact(string text, LanguageType language_type, string translation, TextWordness text_wordness, bool case_sensitive, bool with_diacritics)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        m_search_type = SearchType.Text;

        if (m_client != null)
        {
            ClearFoundMatches();

            if (!String.IsNullOrEmpty(text))
            {
                m_client.FindPhrases(m_text_search_block_size, text, language_type, translation, m_text_location_in_chapter, m_text_location_in_verse, m_text_location_in_word, text_wordness, case_sensitive, with_diacritics, m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder);
                if (m_client.FoundPhrases != null)
                {
                    string multiplicity_text = "";
                    if (m_multiplicity_number_type == NumberType.Natural)
                    {
                        if (m_multiplicity_comparison_operator == ComparisonOperator.DivisibleBy)
                        {
                            multiplicity_text = FindByTextMultiplicityComparisonOperatorLabel.Text + m_multiplicity + "r" + m_multiplicity_remainder;
                        }
                        else
                        {
                            if (m_multiplicity_comparison_operator == ComparisonOperator.Equal)
                            {
                                multiplicity_text = "" + m_multiplicity;
                            }
                            else
                            {
                                multiplicity_text = FindByTextMultiplicityComparisonOperatorLabel.Text + "" + m_multiplicity;
                            }
                        }
                    }
                    else if (m_multiplicity_number_type != NumberType.None)
                    {
                        multiplicity_text = m_multiplicity_number_type.ToString();
                    }
                    else
                    {
                        // do nothing
                    }

                    if (m_client.FoundVerses != null)
                    {
                        int phrase_count = GetValidPhraseCount(m_client.FoundPhrases);
                        string block_name = ((m_multiplicity_comparison_operator == ComparisonOperator.Equal) && (m_text_search_block_size != TextSearchBlockSize.Verse)) ? m_text_search_block_size.ToString() : "verse";
                        if (m_multiplicity == 0)
                        {
                            m_header_label_info = m_client.FoundVerses.Count + " " + L[l][block_name] + ((m_client.FoundVerses.Count == 1) ? "" : "s") + " " + L[l]["without"] + " " + text + " C_" + m_text_location_in_chapter.ToString() + " V_" + m_text_location_in_verse.ToString() + " W_" + m_text_location_in_word.ToString() + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                        }
                        else
                        {
                            int block_count = 0;
                            if (m_text_search_block_size == TextSearchBlockSize.Verse)
                            {
                                block_count = m_client.FoundVerses.Count;
                            }
                            else
                            {
                                if ((m_multiplicity != -1) && (m_multiplicity_comparison_operator == ComparisonOperator.Equal))
                                {
                                    block_count = phrase_count / Math.Abs(m_multiplicity);
                                }
                                else
                                {
                                    block_count = -1; // unknown
                                }
                            }
                            m_header_label_info = phrase_count + " " + L[l]["matches"] + " " + L[l]["in"] + " " + block_count + " " + L[l][block_name] + ((block_count == 1) ? "" : "s") + " " + L[l]["with"] + " " + multiplicity_text + " " + text + " C_" + m_text_location_in_chapter.ToString() + " V_" + m_text_location_in_verse.ToString() + " W_" + m_text_location_in_word.ToString() + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                        }
                        DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, true);
                    }
                    else
                    {
                        DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                    }
                }
                else
                {
                    DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                }
            }

            WordFrequencyListBoxLabel.Visible = false;
            WordFrequencyListBox.Visible = false;
            WordFrequencyWithDiacriticsCheckBox.Visible = false;
        }
    }
    private void FindByProximity()
    {
        if (m_client != null)
        {
            string text = FindByTextTextBox.Text;
            if (text.Length > 0)
            {
                string translation = Client.DEFAULT_TRANSLATION;
                if ((m_show_all_translations) || (!text.IsArabic()))
                {
                    translation = null; // all translations
                }
                else
                {
                    if (TranslatorComboBox.SelectedItem != null)
                    {
                        translation = m_client.GetTranslationKey(TranslatorComboBox.SelectedItem.ToString());
                    }
                }

                if (FindByTextAnyWordRadioButton.Checked)
                {
                    m_text_word_grouping = TextWordGrouping.Or;
                }
                else if (FindByTextAllWordsRadioButton.Checked)
                {
                    m_text_word_grouping = TextWordGrouping.And;
                }

                FindByProximity(text, m_language_type, translation, m_text_word_grouping, m_text_wordness, m_case_sensitive, m_with_diacritics);
            }
        }
        else // find consecutive words
        {
            FindRepeatedWords();
        }
    }
    private void FindByProximity(string text, LanguageType language_type, string translation, TextWordGrouping text_word_grouping, TextWordness text_wordness, bool case_sensitive, bool with_diacritics)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        m_search_type = SearchType.Text;

        if (m_client != null)
        {
            ClearFoundMatches();

            if (!String.IsNullOrEmpty(text))
            {
                m_client.FindWords(m_text_search_block_size, text, language_type, translation, text_word_grouping, text_wordness, case_sensitive, with_diacritics);
                if (m_client.FoundWords != null)
                {
                    if (m_client.FoundVerses != null)
                    {
                        int word_count = GetValidWordCount(m_client.FoundWords);
                        string block_name = "verse";
                        if (m_multiplicity == 0)
                        {
                            m_header_label_info = m_client.FoundVerses.Count + " " + ((m_client.FoundVerses.Count == 1) ? L[l][block_name] : (L[l][block_name + "s"])) + " " + L[l]["without"] + " " + text.Replace(" ", (m_text_word_grouping == TextWordGrouping.Or) ? "|" : "&&") + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                        }
                        else
                        {
                            int block_count = 0;
                            if (m_text_search_block_size == TextSearchBlockSize.Verse)
                            {
                                block_count = m_client.FoundVerses.Count;
                            }
                            else
                            {
                                if ((m_multiplicity != -1) && (m_multiplicity_comparison_operator == ComparisonOperator.Equal))
                                {
                                    block_count = word_count / Math.Abs(m_multiplicity);
                                }
                                else
                                {
                                    block_count = -1; // unknown
                                }
                            }
                            m_header_label_info = word_count + " " + L[l]["matches"] + " " + L[l]["in"] + " " + block_count + " " + L[l][block_name] + ((block_count == 1) ? "" : "s") + " " + L[l]["with"] + " " + text.Replace(" ", (m_text_word_grouping == TextWordGrouping.Or) ? "|" : "&&") + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                        }
                        DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, true);
                    }
                    else
                    {
                        DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, false);
                    }
                }
                else
                {
                    DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, false);
                }
            }
            else
            {
                DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, false);
            }

            WordFrequencyListBoxLabel.Visible = false;
            WordFrequencyListBox.Visible = false;
            WordFrequencyWithDiacriticsCheckBox.Visible = false;
        }
    }
    private void FindByRoot()
    {
        if (m_emlaaei_text)
            return;

        string text = FindByTextTextBox.Text;
        if (text.Length > 0)
        {
            FindByRoot(text);
        }
        else // find consecutive roots
        {
            FindRepeatedRoots();
        }
    }
    private void FindByRoot(Word word)
    {
        if (word != null)
        {
            string root = word.Root;
            if (!String.IsNullOrEmpty(root))
            {
                this.Cursor = Cursors.WaitCursor;
                try
                {
                    if (m_client != null)
                    {
                        FindByRoot(root);
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
                }
                finally
                {
                    this.Cursor = Cursors.Default;
                }
            }
        }
    }
    private void FindByRoot(string roots)
