                    string block_name = ((m_multiplicity_comparison_operator == ComparisonOperator.Equal) && (m_text_search_block_size != TextSearchBlockSize.Verse)) ? m_text_search_block_size.ToString() : "verse";
                    if (m_multiplicity == 0)
                    {
                        m_header_label_info = m_client.FoundVerses.Count + " " + ((m_client.FoundVerses.Count == 1) ? L[l][block_name] : (L[l][block_name + "s"])) + " " + L[l]["without"] + " " + multiplicity_text + " root " + roots.Replace(" ", (m_text_word_grouping == TextWordGrouping.Or) ? "|" : "&&") + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                    }
                    else
                    {
                        int block_count = 0;
                        if (m_text_search_block_size == TextSearchBlockSize.Verse)
                        {
                            block_count = m_client.FoundVerses.Count;
                        }
                        else
                        {
                            if ((m_multiplicity != -1) && (m_multiplicity_comparison_operator == ComparisonOperator.Equal))
                            {
                                block_count = word_count / Math.Abs(m_multiplicity);
                            }
                            else
                            {
                                block_count = -1; // unknown
                            }
                        }
                        m_header_label_info = word_count + " " + L[l]["matches"] + " " + L[l]["in"] + " " + block_count + " " + L[l][block_name] + ((block_count == 1) ? "" : "s") + " " + L[l]["with"] + " " + multiplicity_text + " " + L[l]["root"] + " " + roots.Replace(" ", (m_text_word_grouping == TextWordGrouping.Or) ? "|" : "&&") + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                    }
                    DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, true);
                }
                else
                {
                    DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, false);
                }
            }
            else
            {
                DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, false);
            }

            WordFrequencyListBoxLabel.Visible = false;
            WordFrequencyListBox.Visible = false;
            WordFrequencyWithDiacriticsCheckBox.Visible = false;
        }
