    private void FindRepeatedWords()
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        m_search_type = SearchType.Repetition;

        if (m_client != null)
        {
            ClearFoundMatches();

            if (m_multiplicity > 0)
            {
                m_client.FindConsecutivelyRepeatedWords(m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder, m_with_diacritics);
                if (m_client.FoundWords != null)
                {
                    if (m_client.FoundVerses != null)
                    {
                        int verse_count = m_client.FoundVerses.Count;
                        int word_count = m_client.FoundWords.Count / m_multiplicity;
                        m_header_label_info = word_count + " " + L[l]["repeated words"] + " " + L[l]["in"] + " " + verse_count + " " + ((verse_count == 1) ? L[l]["verse"] : (L[l]["verses"]) + (m_with_diacritics ? (" " + L[l]["with diacritics"]) : ""));

                        DisplayFoundWords(FINDBYREPETITION_MATCH_COLOR, true);

                        WordFrequencyListBoxLabel.Visible = false;
                        WordFrequencyListBox.Visible = false;
                        WordFrequencyWithDiacriticsCheckBox.Visible = false;
                    }
                }
            }
        }
    }
    private void FindRepeatedRoots()
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        m_search_type = SearchType.Repetition;

        if (m_client != null)
        {
            ClearFoundMatches();

            if (m_multiplicity > 0)
            {
                m_client.FindConsecutivelyRepeatedRoots(m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder);
                if (m_client.FoundWords != null)
                {
                    if (m_client.FoundVerses != null)
                    {
                        int verse_count = m_client.FoundVerses.Count;
                        int word_count = m_client.FoundWords.Count / m_multiplicity;
                        m_header_label_info = word_count + " " + L[l]["repeated roots"] + " " + L[l]["in"] + " " + verse_count + " " + ((verse_count == 1) ? L[l]["verse"] : (L[l]["verses"]) + (m_with_diacritics ? (" " + L[l]["with diacritics"]) : ""));

                        DisplayFoundWords(FINDBYREPETITION_MATCH_COLOR, true);

                        WordFrequencyListBoxLabel.Visible = false;
                        WordFrequencyListBox.Visible = false;
                        WordFrequencyWithDiacriticsCheckBox.Visible = false;
                    }
                }
            }
        }
    }
    private void QuranHealingLabel_Click(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        this.Cursor = Cursors.WaitCursor;
        try
        {
            ClearFoundMatches();

            if (FindByTextTextBox.Text.Length > 0)
            {
                // get startup text from FindTextBox
                string[] startup_words = FindByTextTextBox.Text.Split();
                int count = startup_words.Length;

                string text = "";
                if (m_auto_complete_mode)
                {
                    for (int i = 0; i < count; i++)
                    {
                        text += startup_words[i] + " ";
                    }
                    text = text.Trim();
                }

                // update m_text_location_in_verse and m_text_location_in_word
                //UpdateFindByTextOptions();

                text = text.Trim();
                if (!String.IsNullOrEmpty(text))
                {
                    string translation = Client.DEFAULT_TRANSLATION;
                    if ((m_show_all_translations) || (!text.IsArabic()))
                    {
                        translation = null; // all translations
                    }
                    else
                    {
                        if (TranslatorComboBox.SelectedItem != null)
                        {
                            translation = m_client.GetTranslationKey(TranslatorComboBox.SelectedItem.ToString());
                        }
                    }

                    switch (m_text_search_type)
                    {
                        case TextSearchType.Exact:
                            {
                                m_client.FindPhrases(m_text_search_block_size, text, m_language_type, translation, m_text_location_in_chapter, m_text_location_in_verse, m_text_location_in_word, m_text_wordness, m_case_sensitive, m_with_diacritics, m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder);
                            }
                            break;
                        case TextSearchType.Proximity:
                            {
                                m_client.FindWords(m_text_search_block_size, text, m_language_type, translation, m_text_word_grouping, m_text_wordness, m_case_sensitive, m_with_diacritics);
                            }
                            break;
                        case TextSearchType.Root:
                            {
                                m_client.FindWords(TextSearchBlockSize.Verse, text, m_text_word_grouping, m_multiplicity, m_multiplicity_number_type, m_multiplicity_comparison_operator, m_multiplicity_remainder);
                            }
                            break;
                        default:
                            break;
                    }
                }

                List<Verse> result = new List<Verse>();
                if (m_client.FoundVerses != null)
                {
                    foreach (Verse verse in m_client.FoundVerses)
                    {
                        long value = m_client.CalculateValue(verse);

                        Verse verse_by_verse_number = m_client.Book.GetVerseByNumber((int)value);
                        if (verse_by_verse_number != null)
                        {
                            result.Add(verse_by_verse_number);
                        }

                        if (ModifierKeys == Keys.Control)
                        {
                            Word word = m_client.Book.GetWordByNumber((int)value);
                            if (word != null)
                            {
                                Verse verse_by_word_number = word.Verse;
                                if (verse_by_word_number != null)
                                {
                                    result.Add(verse_by_word_number);
                                }
                            }
                        }

                        if (ModifierKeys == Keys.Shift)
                        {
                            Letter letter = m_client.Book.GetLetterByNumber((int)value);
                            if (letter != null)
                            {
                                if (letter.Word != null)
                                {
                                    Verse verse_by_letter_number = letter.Word.Verse;
                                    if (verse_by_letter_number != null)
                                    {
                                        result.Add(verse_by_letter_number);
                                    }
                                }
                            }
                        }
                    }
                }

                // overwrite
                m_client.FoundVerses = result;
                m_client.FoundWords = null;

                // display results
                if (m_client.FoundVerses != null)
                {
                    int verse_count = m_client.FoundVerses.Count;
                    m_header_label_info = verse_count + ((verse_count == 1) ? " " + L[l]["verse"] : " " + L[l]["verses"]) + " " + L[l]["with"] + " " + text + " C_" + m_text_location_in_chapter.ToString() + " V_" + m_text_location_in_verse.ToString() + " W_" + m_text_location_in_word.ToString() + " " + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                    DisplayFoundVerses(FINDBYVALUE_MATCH_COLOR, false);

                    WordFrequencyListBoxLabel.Visible = false;
                    WordFrequencyListBox.Visible = false;
                    WordFrequencyWithDiacriticsCheckBox.Visible = false;
                }

                SearchGroupBox_Leave(null, null);
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }

    private void FindByTextKeyboardLabel_Click(object sender, EventArgs e)
    {
        Control control = (sender as Control);
        if (control != null)
        {
            control.BackColor = Color.LightSteelBlue;
            control.Refresh();

            // prevent double spaces
            if (control == FindByTextSpaceLabel)
            {
                if (FindByTextTextBox.SelectionStart > 0)
                {
                    if (FindByTextTextBox.Text[FindByTextTextBox.SelectionStart - 1] == ' ')
                    {
                        return;
                    }
                }
            }

            string letter = control.Text[0].ToString();
            int pos = FindByTextTextBox.SelectionStart;
            int len = FindByTextTextBox.SelectionLength;
            if (pos > -1)
            {
                if (len > 0)
                {
                    FindByTextTextBox.Text = FindByTextTextBox.Text.Remove(pos, len);
                }
                else
                {
                    // do nothing
                }
                FindByTextTextBox.Text = FindByTextTextBox.Text.Insert(pos, letter);
                FindByTextTextBox.SelectionStart = pos + 1;
                FindByTextTextBox.Refresh();
            }

            Thread.Sleep(100);
            control.BackColor = Color.LightGray;
            control.Refresh();

            FindByTextKeyboardLabel_MouseEnter(sender, e);
            FindByTextControls_Enter(null, null);

            FindByTextTextBox.Focus();
        }
    }
    private void FindByTextBackspaceLabel_Click(object sender, EventArgs e)
    {
        Control control = (sender as Control);
        if (control != null)
        {
            control.BackColor = Color.LightSteelBlue;
            control.Refresh();

            int pos = FindByTextTextBox.SelectionStart;
            int len = FindByTextTextBox.SelectionLength;
            if ((len == 0) && (pos > 0))        // delete character prior to cursor
            {
                FindByTextTextBox.Text = FindByTextTextBox.Text.Remove(pos - 1, 1);
                FindByTextTextBox.SelectionStart = pos - 1;
            }
            else if ((len > 0) && (pos >= 0))   // delete current highlighted characters
            {
                FindByTextTextBox.Text = FindByTextTextBox.Text.Remove(pos, len);
                FindByTextTextBox.SelectionStart = pos;
            }
            else                  // nothing to delete
            {
            }
            FindByTextTextBox.Refresh();

            Thread.Sleep(100);
            control.BackColor = Color.LightGray;
            control.Refresh();

            FindByTextKeyboardLabel_MouseEnter(sender, e);
            FindByTextControls_Enter(null, null);

            FindByTextTextBox.Focus();
        }
    }
    private void FindByTextKeyboardLabel_MouseEnter(object sender, EventArgs e)
    {
        Control control = (sender as Control);
        if (control != null)
        {
            if (control == FindByTextBackspaceLabel)
            {
                control.BackColor = Color.DarkGray;
            }
            else
            {
                control.BackColor = Color.White;
            }
            control.Refresh();
        }
    }
    private void FindByTextKeyboardLabel_MouseLeave(object sender, EventArgs e)
    {
        Control control = (sender as Control);
        if (control != null)
        {
            control.BackColor = Color.LightGray;
            control.Refresh();
        }
    }
    private void FindByTextKeyboardModifierLabel_MouseLeave(object sender, EventArgs e)
    {
        Control control = (sender as Control);
        if (control != null)
        {
            if ((control == FindByTextSpaceLabel) || (control == FindByTextBackspaceLabel))
            {
                control.BackColor = Color.Silver;
            }
            else
            {
                control.BackColor = Color.LightGray;
            }
            control.Refresh();
        }
    }
