        FindByTextMinusLabel.Visible = ((m_text_search_type == TextSearchType.Proximity) || (m_text_search_type == TextSearchType.Root));
        FindByTextAllWordsRadioButton.Enabled = ((m_text_search_type == TextSearchType.Proximity) || (m_text_search_type == TextSearchType.Root));
        FindByTextAnyWordRadioButton.Enabled = ((m_text_search_type == TextSearchType.Proximity) || (m_text_search_type == TextSearchType.Root)) && (!FindByTextTextBox.Text.Contains("-")) && (!FindByTextTextBox.Text.Contains("+"));

        FindByTextWordnessCheckBox.Enabled = ((m_text_search_type == TextSearchType.Exact) || (m_text_search_type == TextSearchType.Proximity));

        FindByTextMultiplicityCheckBox.Enabled = ((m_text_search_type == TextSearchType.Exact) || (m_text_search_type == TextSearchType.Root));
        FindByTextMultiplicityComparisonOperatorLabel.Enabled = (FindByTextMultiplicityCheckBox.Enabled) && (FindByTextMultiplicityCheckBox.Checked) && (FindByTextMultiplicityNumberTypeLabel.Text == "");
        FindByTextMultiplicityNumericUpDown.Enabled = (FindByTextMultiplicityCheckBox.Enabled) && (FindByTextMultiplicityCheckBox.Checked) && (FindByTextMultiplicityNumberTypeLabel.Text == "");
        FindByTextMultiplicityNumberTypeLabel.Enabled = (FindByTextMultiplicityCheckBox.Enabled) && (FindByTextMultiplicityCheckBox.Checked);

        QuranHealingLabel.Enabled = (FindByTextTextBox.Text.Length > 0);
        FindByTextCaseSensitiveCheckBox.Enabled = (m_language_type == LanguageType.LeftToRight);
    }
