    private void FindByGrammarLabel_Click(object sender, EventArgs e)
    {
        this.AcceptButton = FindByGrammarButton;

        FindByGrammarButton.Dock = DockStyle.Top;
        FindByTextButton.Dock = DockStyle.None;
        FindByNumbersButton.Dock = DockStyle.None;
        FindBySimilarityButton.Dock = DockStyle.None;
        FindByFrequencyButton.Dock = DockStyle.Top;

        FindByGrammarButton.Visible = !FindByGrammarButton.Visible;
        FindByGrammarCloseLabel.Visible = !FindByGrammarCloseLabel.Visible;
        FindByGrammarListBox.Visible = !FindByGrammarListBox.Visible;
        if (FindByGrammarButton.Visible)
        {
            FindByTextWithDiacriticsCheckBox.SendToBack();
            DrawSearchTermsLabel.SendToBack();
            FindByGrammarCloseLabel.BringToFront();
        }
        else
        {
            FindByTextWithDiacriticsCheckBox.BringToFront();
            DrawSearchTermsLabel.BringToFront();
            FindByGrammarCloseLabel.SendToBack();
        }
    }
    private void PopulateFindByGrammarListBox()
    {
        if (!L.ContainsKey("Arabic"))
            LoadLanguage("Arabic");
        if (!L.ContainsKey("English"))
            LoadLanguage("English");

        try
        {
            for (int i = 0; i < 3; i++)
                FindByGrammarListBox.SelectedIndexChanged -= new System.EventHandler(FindByGrammarListBox_SelectedIndexChanged);
            FindByGrammarListBox.BeginUpdate();

            m_grammar_keys = new List<string>(WordPartGrammar.Keys);
            m_grammar_keys.Remove("DET");
            m_grammar_keys.Remove("DEF");
            m_grammar_keys.Remove("IND");
            m_grammar_keys.Remove("ACT");
            m_grammar_keys.Remove("CAUS");
            m_grammar_keys.Remove("CIRC");
            m_grammar_keys.Remove("COM");
            m_grammar_keys.Remove("EQ");
            m_grammar_keys.Remove("EMPH");
            m_grammar_keys.Remove("REM");
            m_grammar_keys.Remove("RSLT");
            m_grammar_keys.Remove("VOC");
            m_grammar_keys.Remove("PART");
            //m_grammar_keys.Sort();

            FindByGrammarListBox.Items.Clear();
            foreach (string key in m_grammar_keys)
            {
                FindByGrammarListBox.Items.Add(L[l]["Grammar_" + key] + "   " + ((l == "Arabic") ? (L["English"]["Grammar_" + key]) : (L["Arabic"]["Grammar_" + key])));
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            FindByGrammarListBox.EndUpdate();
            FindByGrammarListBox.SelectedIndexChanged += new System.EventHandler(FindByGrammarListBox_SelectedIndexChanged);
        }
    }
    private void FindByGrammarListBox_SelectedIndexChanged(object sender, EventArgs e)
    {
        m_search_type = SearchType.Grammar;
    }
    private void FindByGrammarButton_Click(object sender, EventArgs e)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            List<int> indexes = new List<int>();
            foreach (int index in FindByGrammarListBox.SelectedIndices)
            {
                indexes.Add(index);
            }

            if (indexes.Count > 0)
            {
                FindByGrammar(indexes);
            }

            FindByTextWithDiacriticsCheckBox.SendToBack();
            DrawSearchTermsLabel.SendToBack();
            FindByGrammarCloseLabel.BringToFront();
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void FindByGrammar(List<int> indexes)
    {
        m_search_type = SearchType.Grammar;

        try
        {
            if (m_client != null)
            {
                ClearFoundMatches();
                m_client.FoundWords = new List<Word>();

                List<string> keys = new List<string>();
                foreach (int index in indexes)
                {
                    if ((index >= 0) && (index < m_grammar_keys.Count))
                    {
                        string key = m_grammar_keys[index];
                        keys.Add(key);
                    }
                }

                foreach (string key in keys)
                {
                    List<Verse> verses = GetSearchScopeVerses();
                    if (verses != null)
                    {
                        List<Word> words = new List<Word>();
                        foreach (Verse verse in verses)
                        {
                            foreach (Word word in verse.Words)
                            {
                                foreach (WordPartGrammar grammar in word.Grammar)
                                {
                                    if (grammar.Contains(key))
                                    {
                                        words.Add(word);
                                    }
                                }
                            }
                        }

                        if (words != null)
                        {
                            if (words.Count > 0)
                            {
                                m_client.FoundWords.AddRange(words);
                            }
                        }
                    }
                }

                if (m_client.FoundWords != null)
                {
                    m_client.FoundVerses = m_client.Book.GetVerses(m_client.FoundWords);
                    if (m_client.FoundVerses != null)
                    {
                        int verse_count = m_client.FoundVerses.Count;
                        int word_count = m_client.FoundWords.Count;
                        string grammar_keys = null;
                        foreach (string key in keys)
                        {
                            grammar_keys += L[l]["Grammar_" + key] + " ";
                        }
                        m_header_label_info = word_count + " " + L[l]["words"] + " " + L[l]["in"] + " " + verse_count + " " + L[l]["verses"] + " " + L[l]["with"] + " " + grammar_keys;
                        UpdateHeaderLabel();

                        DisplayFoundWords(FINDBYGRAMMAR_MATCH_COLOR, true);
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
        }
    }
    private string GetGrammarInformation(Word word)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return null;

        if (m_emlaaei_text)
            return null;

        if (word != null)
        {
            string grammar_info = "";

            //if (word.Lemma != null)
            //{
            //    grammar_info += "Lemma\t" + word.Lemma.ToArabic() + "\t";
            //}
            //if (word.Root != null)
            //{
            //    grammar_info += "Root\t" + word.Root.ToArabic() + "\t";
            //}
            //if (word._SpecialGroup != null)
            //{
            //    grammar_info += "Special Group\t" + word._SpecialGroup.ToArabic() + "\t";
            //}
            //if (grammar_info.Length > 0)
            //{
            //    grammar_info += "\r\n";
            //}

            if (!String.IsNullOrEmpty(word.GrammarText))
            {
                string word_grammar_text = word.GrammarText.Replace("\r", "");

                StringBuilder str = new StringBuilder();
                char[] separators = { '\n' };
                string[] lines = word_grammar_text.Split(separators);
                foreach (string line in lines)
                {
                    char[] part_separators = { '\t' };
                    string[] parts = line.Split(part_separators);
                    foreach (string part in parts)
                    {
                        string modified_part = part;
                        if (L[l].ContainsKey("Grammar_" + part))
                        {
                            modified_part = L[l]["Grammar_" + part];
                        }
                        str.Append(modified_part + "\t");
                    }
                    str.Remove(str.Length - 1, 1); // remove last "\t"
                    str.AppendLine();
                }
                if (str.Length > 2)
                {
                    str.Remove(str.Length - 2, 2); // "\r\n"
                }

                grammar_info += str.ToString();
            }

            return grammar_info;
        }

        return null;
    }
    private void DisplayGrammarInformation(Word word)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (m_emlaaei_text)
            return;

        if (
             (m_text_display_mode == TextDisplayMode.Both) ||
             (m_text_display_mode == TextDisplayMode.TranslationOnly)
           )
        {
            if (
                (TabControl.SelectedTab == TranslationTabPage) ||
                (TabControl.SelectedTab == GrammarTabPage) ||
                (TabControl.SelectedTab == RelatedWordsTabPage)
               )
            {
                if (word != null)
                {
                    GrammarTextBox.Text = GetGrammarInformation(word) + "\r\n\r\n" + BuildVerbForms(word);
                }
                else
                {
                    GrammarTextBox.Text = L[l]["Click a word to display its grammar information."];
                }
                GrammarTextBox.Refresh();
            }
        }
    }
