    private void FindByEquation(string text)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    if (!String.IsNullOrEmpty(text))
                    {
                        string result_type = "V:";
                        if (text.Contains(":"))
                        {
                            result_type = text.Substring(0, 2);
                            text = text.Substring(2);
                        }

                        if (text.Contains("=")) // = natural number or math_expression|p|ap|xp|c|ac|xc|o|e|val
                        {
                            Calculator calculator = new Calculator();

                            SelectionScope selection_scope = SelectionScope.Verse;
                            List<int> indexes = new List<int>();

                            string expression = text.Trim();
                            char[] separators = { '=' };
                            string[] parts = expression.Split(separators, StringSplitOptions.RemoveEmptyEntries);
                            if (parts.Length == 2)
                            {
                                // allowed expression variables 
                                int C = 0;      // chapter number
                                int V = 0;      // verse number
                                int W = 0;      // word number
                                int L = 0;      // letter number
                                int Vc = 0;     // verse number in chapter
                                int Wc = 0;     // word number in chapter
                                int Lc = 0;     // letter number in chapter
                                int Wv = 0;     // word number in verse
                                int Lv = 0;     // letter number in verse
                                int Lw = 0;     // letter number in word
                                int Cs = 0;     // number of chapters
                                int Vs = 0;     // number of verses
                                int Ws = 0;     // number of words
                                int Ls = 0;     // number of letters
                                int Us = 0;     // number of unique letters
                                long Value = 0L;

                                switch (result_type)
                                {
                                    case "L:":
                                        {
                                            selection_scope = SelectionScope.Letter;
                                            #region Find Letters
                                            foreach (Letter letter in m_client.Book.Letters)
                                            {
                                                Value = m_client.CalculateValue(letter);
                                                Cs = 1;
                                                Vs = 1;
                                                Ws = 1;
                                                Ls = 1;
                                                Us = 1;
                                                Vc = letter.Word.Verse.NumberInChapter;
                                                Wc = letter.Word.NumberInChapter;
                                                Lc = letter.NumberInChapter;
                                                Wv = letter.Word.NumberInVerse;
                                                Lv = letter.NumberInVerse;
                                                Lw = letter.NumberInWord;
                                                C = letter.Word.Verse.Chapter.SortedNumber;
                                                V = letter.Word.Verse.Number;
                                                W = letter.Word.Number;
                                                L = letter.Number;

                                                string xxx = parts[0];
                                                // Don't change replace order.
                                                xxx = xxx.Replace("val", Value.ToString());
                                                xxx = xxx.Replace("Cs", Cs.ToString());
                                                xxx = xxx.Replace("Vs", Vs.ToString());
                                                xxx = xxx.Replace("Ws", Ws.ToString());
                                                xxx = xxx.Replace("Ls", Ls.ToString());
                                                xxx = xxx.Replace("Us", Us.ToString());
                                                xxx = xxx.Replace("Vc", Vc.ToString());
                                                xxx = xxx.Replace("Wc", Wc.ToString());
                                                xxx = xxx.Replace("Lc", Lc.ToString());
                                                xxx = xxx.Replace("Wv", Wv.ToString());
                                                xxx = xxx.Replace("Lv", Lv.ToString());
                                                xxx = xxx.Replace("Lw", Lw.ToString());
                                                xxx = xxx.Replace("C", C.ToString());
                                                xxx = xxx.Replace("V", V.ToString());
                                                xxx = xxx.Replace("W", W.ToString());
                                                xxx = xxx.Replace("L", L.ToString());
                                                double xxx_value = calculator.Calculate(xxx);

                                                string yyy = parts[1];
                                                // Don't change replace order.
                                                yyy = yyy.Replace("val", Value.ToString());
                                                yyy = yyy.Replace("Cs", Cs.ToString());
                                                yyy = yyy.Replace("Vs", Vs.ToString());
                                                yyy = yyy.Replace("Ws", Ws.ToString());
                                                yyy = yyy.Replace("Ls", Ls.ToString());
                                                yyy = yyy.Replace("Us", Us.ToString());
                                                yyy = yyy.Replace("Vc", Vc.ToString());
                                                yyy = yyy.Replace("Wc", Wc.ToString());
                                                yyy = yyy.Replace("Lc", Lc.ToString());
                                                yyy = yyy.Replace("Wv", Wv.ToString());
                                                yyy = yyy.Replace("Lv", Lv.ToString());
                                                yyy = yyy.Replace("Lw", Lw.ToString());
                                                yyy = yyy.Replace("C", C.ToString());
                                                yyy = yyy.Replace("V", V.ToString());
                                                yyy = yyy.Replace("W", W.ToString());
                                                yyy = yyy.Replace("L", L.ToString());

                                                switch (yyy.Trim())
                                                {
                                                    case "p":
                                                        {
                                                            if (Numbers.IsPrime((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(letter.Number - 1))
                                                                {
                                                                    indexes.Add(letter.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "ap":
                                                        {
                                                            if (Numbers.IsAdditivePrime((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(letter.Number - 1))
                                                                {
                                                                    indexes.Add(letter.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "xp":
                                                        {
                                                            if (Numbers.IsNonAdditivePrime((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(letter.Number - 1))
                                                                {
                                                                    indexes.Add(letter.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "c":
                                                        {
                                                            if (Numbers.IsComposite((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(letter.Number - 1))
                                                                {
                                                                    indexes.Add(letter.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "ac":
                                                        {
                                                            if (Numbers.IsAdditiveComposite((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(letter.Number - 1))
                                                                {
                                                                    indexes.Add(letter.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "xc":
                                                        {
                                                            if (Numbers.IsNonAdditiveComposite((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(letter.Number - 1))
                                                                {
                                                                    indexes.Add(letter.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "o":
                                                        {
                                                            if (Numbers.IsOdd((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(letter.Number - 1))
                                                                {
                                                                    indexes.Add(letter.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "e":
                                                        {
                                                            if (Numbers.IsEven((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(letter.Number - 1))
                                                                {
                                                                    indexes.Add(letter.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    default:
                                                        {
                                                            double yyy_value = calculator.Calculate(yyy);
                                                            if (Math.Abs(xxx_value - yyy_value) < Numbers.ERROR_MARGIN)
                                                            {
                                                                if (!indexes.Contains(letter.Number - 1))
                                                                {
                                                                    indexes.Add(letter.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                } // switch
                                            } // for
                                            #endregion
                                        }
                                        break;
                                    case "W:":
                                        {
                                            selection_scope = SelectionScope.Word;
                                            #region Find Words
                                            foreach (Word word in m_client.Book.Words)
                                            {
                                                Value = m_client.CalculateValue(word);
                                                Cs = 1;
                                                Vs = 1;
                                                Ws = 1;
                                                Ls = word.Letters.Count;
                                                Us = word.UniqueLetters.Count;
                                                Vc = word.Verse.NumberInChapter;
                                                Wc = word.NumberInChapter;
                                                Lc = 0;
                                                Wv = word.NumberInVerse;
                                                Lv = 0;
                                                Lw = 0;
                                                C = word.Verse.Chapter.SortedNumber;
                                                V = word.Verse.Number;
                                                W = word.Number;
                                                L = 0;

                                                string xxx = parts[0];
                                                // Don't change replace order.
                                                xxx = xxx.Replace("val", Value.ToString());
                                                xxx = xxx.Replace("Cs", Cs.ToString());
                                                xxx = xxx.Replace("Vs", Vs.ToString());
                                                xxx = xxx.Replace("Ws", Ws.ToString());
                                                xxx = xxx.Replace("Ls", Ls.ToString());
                                                xxx = xxx.Replace("Us", Us.ToString());
                                                xxx = xxx.Replace("Vc", Vc.ToString());
                                                xxx = xxx.Replace("Wc", Wc.ToString());
                                                xxx = xxx.Replace("Lc", Lc.ToString());
                                                xxx = xxx.Replace("Wv", Wv.ToString());
                                                xxx = xxx.Replace("Lv", Lv.ToString());
                                                xxx = xxx.Replace("Lw", Lw.ToString());
                                                xxx = xxx.Replace("C", C.ToString());
                                                xxx = xxx.Replace("V", V.ToString());
                                                xxx = xxx.Replace("W", W.ToString());
                                                xxx = xxx.Replace("L", L.ToString());
                                                double xxx_value = calculator.Calculate(xxx);

                                                string yyy = parts[1];
                                                // Don't change replace order.
                                                yyy = yyy.Replace("val", Value.ToString());
                                                yyy = yyy.Replace("Cs", Cs.ToString());
                                                yyy = yyy.Replace("Vs", Vs.ToString());
                                                yyy = yyy.Replace("Ws", Ws.ToString());
                                                yyy = yyy.Replace("Ls", Ls.ToString());
                                                yyy = yyy.Replace("Us", Us.ToString());
                                                yyy = yyy.Replace("Vc", Vc.ToString());
                                                yyy = yyy.Replace("Wc", Wc.ToString());
                                                yyy = yyy.Replace("Lc", Lc.ToString());
                                                yyy = yyy.Replace("Wv", Wv.ToString());
                                                yyy = yyy.Replace("Lv", Lv.ToString());
                                                yyy = yyy.Replace("Lw", Lw.ToString());
                                                yyy = yyy.Replace("C", C.ToString());
                                                yyy = yyy.Replace("V", V.ToString());
                                                yyy = yyy.Replace("W", W.ToString());
                                                yyy = yyy.Replace("L", L.ToString());

                                                switch (yyy.Trim())
                                                {
                                                    case "p":
                                                        {
                                                            if (Numbers.IsPrime((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(word.Number - 1))
                                                                {
                                                                    indexes.Add(word.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "ap":
                                                        {
                                                            if (Numbers.IsAdditivePrime((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(word.Number - 1))
                                                                {
                                                                    indexes.Add(word.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "xp":
                                                        {
                                                            if (Numbers.IsNonAdditivePrime((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(word.Number - 1))
                                                                {
                                                                    indexes.Add(word.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "c":
                                                        {
                                                            if (Numbers.IsComposite((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(word.Number - 1))
                                                                {
                                                                    indexes.Add(word.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "ac":
                                                        {
                                                            if (Numbers.IsAdditiveComposite((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(word.Number - 1))
                                                                {
                                                                    indexes.Add(word.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "xc":
                                                        {
                                                            if (Numbers.IsNonAdditiveComposite((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(word.Number - 1))
                                                                {
                                                                    indexes.Add(word.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "o":
                                                        {
                                                            if (Numbers.IsOdd((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(word.Number - 1))
                                                                {
                                                                    indexes.Add(word.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "e":
                                                        {
                                                            if (Numbers.IsEven((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(word.Number - 1))
                                                                {
                                                                    indexes.Add(word.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    default:
                                                        {
                                                            double yyy_value = calculator.Calculate(yyy);
                                                            if (Math.Abs(xxx_value - yyy_value) < Numbers.ERROR_MARGIN)
                                                            {
                                                                if (!indexes.Contains(word.Number - 1))
