                                                            if (Numbers.IsNonAdditivePrime((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(bowing.Number - 1))
                                                                {
                                                                    indexes.Add(bowing.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "c":
                                                        {
                                                            if (Numbers.IsComposite((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(bowing.Number - 1))
                                                                {
                                                                    indexes.Add(bowing.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "ac":
                                                        {
                                                            if (Numbers.IsAdditiveComposite((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(bowing.Number - 1))
                                                                {
                                                                    indexes.Add(bowing.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "xc":
                                                        {
                                                            if (Numbers.IsNonAdditiveComposite((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(bowing.Number - 1))
                                                                {
                                                                    indexes.Add(bowing.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "o":
                                                        {
                                                            if (Numbers.IsOdd((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(bowing.Number - 1))
                                                                {
                                                                    indexes.Add(bowing.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    case "e":
                                                        {
                                                            if (Numbers.IsEven((long)xxx_value))
                                                            {
                                                                if (!indexes.Contains(bowing.Number - 1))
                                                                {
                                                                    indexes.Add(bowing.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                    default:
                                                        {
                                                            double yyy_value = calculator.Calculate(yyy);
                                                            if (Math.Abs(xxx_value - yyy_value) < Numbers.ERROR_MARGIN)
                                                            {
                                                                if (!indexes.Contains(bowing.Number - 1))
                                                                {
                                                                    indexes.Add(bowing.Number - 1);
                                                                }
                                                            }
                                                        }
                                                        break;
                                                } // switch
                                            } // for
                                            #endregion
                                        }
                                        break;
                                    default:
                                        break;
                                } // switch
                            }

                            if (indexes.Count > 0)
                            {
                                if (ModifierKeys == Keys.Control)
                                {
                                    m_client.FoundVerses = new List<Verse>();
                                    foreach (int index in indexes)
                                    {
                                        if ((index >= 0) && (index < m_client.Book.Verses.Count))
                                        {
                                            m_client.FoundVerses.Add(m_client.Book.Verses[index]);
                                        }
                                    }
                                    DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, true); // no phrases are found so no color is needed
                                }
                                else
                                {
                                    m_client.Selection = new Selection(m_client.Book, selection_scope, indexes);
                                    DisplaySelection(true);
                                }
                            }
                        }
                    }
                }
            }
        }
        catch
        {
            // silence exception
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
