    private void FindByNumbersControls_Enter(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        this.AcceptButton = FindByNumbersButton;

        FindByTextButton.Enabled = false;
        FindByNumbersButton.Enabled = true;
        FindBySimilarityButton.Enabled = false;
        FindByFrequencyButton.Enabled = false;
        FindByGrammarButton.Dock = DockStyle.None;
        FindByTextButton.Dock = DockStyle.None;
        FindByNumbersButton.Dock = DockStyle.Top;
        FindBySimilarityButton.Dock = DockStyle.None;
        FindByFrequencyButton.Dock = DockStyle.None;
        FindByNumbersSetsCheckBox.BringToFront();

        ToolTip.SetToolTip(this.InspectChaptersLabel, L[l]["Inspect chapters"]);
        WordFrequencyListBoxLabel.Visible = false;
        WordFrequencyListBox.Visible = false;
        WordFrequencyWithDiacriticsCheckBox.Visible = false;

        ResetFindByTextSearchBlockSizeLabels();
        ResetFindByTextSearchTypeLabels();
        ResetFindBySimilarityResultTypeLabels();
        ResetFindByNumbersResultTypeLabels();
        ResetFindByFrequencyResultTypeLabels();

        UpdateFindByNumbersResultType();

        switch (m_numbers_result_type)
        {
            case NumbersResultType.Letters:
            case NumbersResultType.LetterRanges:
            case NumbersResultType.LetterSets:
                {
                    FindByNumbersResultTypeLettersLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypeLettersLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case NumbersResultType.Words:
            case NumbersResultType.WordRanges:
            case NumbersResultType.WordSets:
                {
                    FindByNumbersResultTypeWordsLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypeWordsLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case NumbersResultType.Sentences:
                {
                    FindByNumbersResultTypeSentencesLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypeSentencesLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case NumbersResultType.Verses:
            case NumbersResultType.VerseRanges:
            case NumbersResultType.VerseSets:
                {
                    FindByNumbersResultTypeVersesLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypeVersesLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case NumbersResultType.Chapters:
            case NumbersResultType.ChapterRanges:
            case NumbersResultType.ChapterSets:
                {
                    FindByNumbersResultTypeChaptersLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypeChaptersLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;

            case NumbersResultType.Pages:
            case NumbersResultType.PageRanges:
            case NumbersResultType.PageSets:
                {
                    FindByNumbersResultTypePagesLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypePagesLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case NumbersResultType.Stations:
            case NumbersResultType.StationRanges:
            case NumbersResultType.StationSets:
                {
                    FindByNumbersResultTypeStationsLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypeStationsLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case NumbersResultType.Parts:
            case NumbersResultType.PartRanges:
            case NumbersResultType.PartSets:
                {
                    FindByNumbersResultTypePartsLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypePartsLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case NumbersResultType.Groups:
            case NumbersResultType.GroupRanges:
            case NumbersResultType.GroupSets:
                {
                    FindByNumbersResultTypeGroupsLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypeGroupsLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case NumbersResultType.Halfs:
            case NumbersResultType.HalfRanges:
            case NumbersResultType.HalfSets:
                {
                    FindByNumbersResultTypeHalfsLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypeHalfsLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case NumbersResultType.Quarters:
            case NumbersResultType.QuarterRanges:
            case NumbersResultType.QuarterSets:
                {
                    FindByNumbersResultTypeQuartersLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypeQuartersLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;
            case NumbersResultType.Bowings:
            case NumbersResultType.BowingRanges:
            case NumbersResultType.BowingSets:
                {
                    FindByNumbersResultTypeBowingsLabel.BackColor = Color.SteelBlue;
                    FindByNumbersResultTypeBowingsLabel.BorderStyle = BorderStyle.Fixed3D;
                }
                break;

            default:
                break;
        }
    }
    private void FindByNumbersNumericUpDown_Leave(object sender, EventArgs e)
    {
        NumericUpDown control = sender as NumericUpDown;
        if (control != null)
        {
            if (String.IsNullOrEmpty(control.Text))
            {
                control.Value = 0;
                control.Refresh();
            }
        }

        UpdateNumberTypeLabelTags();
    }
    private void FindByNumbersNumericUpDown_ValueChanged(object sender, EventArgs e)
    {
        UpdateFindByNumbersResultType();

        UpdateNumberTypeLabelTags();

        // Range/Set operations take too long so don't auto-fine and wait for Enter key
        if ((sender as NumericUpDown).Value != 0)
        {
            if
              (
                // finding letters and range/set operations are too slow so don't autorun
                (
                    (m_numbers_result_type != NumbersResultType.Letters) &&
                    (m_numbers_result_type != NumbersResultType.LetterRanges) &&
                    (m_numbers_result_type != NumbersResultType.LetterSets) &&
                    (m_numbers_result_type != NumbersResultType.Words) &&
                    (m_numbers_result_type != NumbersResultType.WordRanges) &&
                    (m_numbers_result_type != NumbersResultType.WordSets) &&
                    (m_numbers_result_type != NumbersResultType.VerseRanges) &&
                    (m_numbers_result_type != NumbersResultType.VerseSets) &&
                    (m_numbers_result_type != NumbersResultType.ChapterRanges) &&
                    (m_numbers_result_type != NumbersResultType.ChapterSets) &&
                    (m_numbers_result_type != NumbersResultType.PageRanges) &&
                    (m_numbers_result_type != NumbersResultType.PageSets) &&
                    (m_numbers_result_type != NumbersResultType.StationRanges) &&
                    (m_numbers_result_type != NumbersResultType.StationSets) &&
                    (m_numbers_result_type != NumbersResultType.PartRanges) &&
                    (m_numbers_result_type != NumbersResultType.PartSets) &&
                    (m_numbers_result_type != NumbersResultType.GroupRanges) &&
                    (m_numbers_result_type != NumbersResultType.GroupSets) &&
                    (m_numbers_result_type != NumbersResultType.HalfRanges) &&
                    (m_numbers_result_type != NumbersResultType.HalfSets) &&
                    (m_numbers_result_type != NumbersResultType.QuarterRanges) &&
                    (m_numbers_result_type != NumbersResultType.QuarterSets) &&
                    (m_numbers_result_type != NumbersResultType.BowingRanges) &&
                    (m_numbers_result_type != NumbersResultType.BowingSets)
                )
                && // allow autorun for most frequently used operations only
                (
                    (sender == FindByNumbersNumberNumericUpDown) ||
                    (sender == FindByNumbersPartitionsNumericUpDown) ||
                    (sender == FindByNumbersVersesNumericUpDown) ||
                    (sender == FindByNumbersWordsNumericUpDown) ||
                    (sender == FindByNumbersLettersNumericUpDown) ||
                    (sender == FindByNumbersUniqueLettersNumericUpDown) ||
                    (sender == FindByNumbersValueNumericUpDown) ||
                    (sender == FindByNumbersFrequencyNumericUpDown) ||
                    (sender == FindByNumbersOccurrenceNumericUpDown)
                )
              )
            {
                this.Cursor = Cursors.WaitCursor;
                try
                {
                    //FindByNumbers();
                }
                catch (Exception ex)
                {
                    MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
                }
                finally
                {
                    this.Cursor = Cursors.Default;
                }
            }
        }
    }
    private void FindByNumbersNumericUpDown_TextChanged(object sender, EventArgs e)
    {
        if (m_client == null)
            return; // delay Numbers' constructor until after splash screen

        if (sender is NumericUpDown)
        {
            (sender as NumericUpDown).ForeColor = Numbers.GetNumberTypeColor(((long)(sender as NumericUpDown).Value));
            (sender as NumericUpDown).Refresh();
        }
    }
    private void UpdateNumberTypeLabelTags()
    {
        FindByNumbersNumberNumberTypeLabel.Tag = (int)FindByNumbersNumberNumericUpDown.Value;
        FindByNumbersPartitionsNumberTypeLabel.Tag = (int)FindByNumbersPartitionsNumericUpDown.Value;
        FindByNumbersVersesNumberTypeLabel.Tag = (int)FindByNumbersVersesNumericUpDown.Value;
        FindByNumbersWordsNumberTypeLabel.Tag = (int)FindByNumbersWordsNumericUpDown.Value;
        FindByNumbersLettersNumberTypeLabel.Tag = (int)FindByNumbersLettersNumericUpDown.Value;
        FindByNumbersUniqueLettersNumberTypeLabel.Tag = (int)FindByNumbersUniqueLettersNumericUpDown.Value;
        FindByNumbersValueNumberTypeLabel.Tag = (int)FindByNumbersValueNumericUpDown.Value;

        int number;
        if (int.TryParse(FindByNumbersNumberNumberTypeLabel.Text, out number))
        {
            if (number >= (int)FindByNumbersNumberNumericUpDown.Value)
            {
                number = (int)FindByNumbersNumberNumericUpDown.Value - 1;
                if (number < 0)
                    number = 0;
                FindByNumbersNumberNumberTypeLabel.Text = number.ToString();
            }
        }

        if (int.TryParse(FindByNumbersPartitionsNumberTypeLabel.Text, out number))
        {
            if (number >= (int)FindByNumbersPartitionsNumericUpDown.Value)
            {
                number = (int)FindByNumbersPartitionsNumericUpDown.Value - 1;
                if (number < 0)
                    number = 0;
                FindByNumbersPartitionsNumberTypeLabel.Text = number.ToString();
            }
        }

        if (int.TryParse(FindByNumbersVersesNumberTypeLabel.Text, out number))
        {
            if (number >= (int)FindByNumbersVersesNumericUpDown.Value)
            {
                number = (int)FindByNumbersVersesNumericUpDown.Value - 1;
                if (number < 0)
                    number = 0;
                FindByNumbersVersesNumberTypeLabel.Text = number.ToString();
            }
        }

        if (int.TryParse(FindByNumbersWordsNumberTypeLabel.Text, out number))
        {
            if (number >= (int)FindByNumbersWordsNumericUpDown.Value)
            {
                number = (int)FindByNumbersWordsNumericUpDown.Value - 1;
                if (number < 0)
                    number = 0;
                FindByNumbersWordsNumberTypeLabel.Text = number.ToString();
            }
        }

        if (int.TryParse(FindByNumbersLettersNumberTypeLabel.Text, out number))
        {
            if (number >= (int)FindByNumbersLettersNumericUpDown.Value)
            {
                number = (int)FindByNumbersLettersNumericUpDown.Value - 1;
                if (number < 0)
                    number = 0;
                FindByNumbersLettersNumberTypeLabel.Text = number.ToString();
            }
        }

        if (int.TryParse(FindByNumbersUniqueLettersNumberTypeLabel.Text, out number))
        {
            if (number >= (int)FindByNumbersUniqueLettersNumericUpDown.Value)
            {
                number = (int)FindByNumbersUniqueLettersNumericUpDown.Value - 1;
                if (number < 0)
                    number = 0;
                FindByNumbersUniqueLettersNumberTypeLabel.Text = number.ToString();
            }
        }

        if (int.TryParse(FindByNumbersValueNumberTypeLabel.Text, out number))
        {
            if (number >= (int)FindByNumbersValueNumericUpDown.Value)
            {
                number = (int)FindByNumbersValueNumericUpDown.Value - 1;
                if (number < 0)
                    number = 0;
                FindByNumbersValueNumericUpDown.Text = number.ToString();
            }
        }
    }
    private void FindByNumbersButton_Click(object sender, EventArgs e)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            FindByNumbers();
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
