    private void FindByFrequencyLettersType(FrequencyMatchingType frequency_matching_type)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        m_search_type = SearchType.Frequency;

        if (m_client != null)
        {
            ClearFoundMatches();

            string phrase = "";
            if (FindByFrequencyPhraseTextBox.Text.Length > 0)
            {
                if (FindByFrequencyPhraseTextBox.SelectionLength > 0)
                {
                    phrase = FindByFrequencyPhraseTextBox.SelectedText;
                }
                else
                {
                    phrase = FindByFrequencyPhraseTextBox.Text;
                }
            }

            if (!String.IsNullOrEmpty(phrase))
            {
                phrase = phrase.Replace("\r", "");
                phrase = phrase.Replace("\n", " ");
                phrase = phrase.Replace("\t", "");

                switch (m_frequency_result_type)
                {
                    case FrequencyResultType.Words:
                        {
                            int match_count = m_client.FindWords(phrase, frequency_matching_type, m_frequency_search_type, m_include_diacritics);
                            if (m_client.FoundWords != null)
                            {
                                m_header_label_info = match_count + ((match_count == 1) ? " " + L[l]["word"] : " " + L[l]["words"]) + " " + L[l]["with"] + " " + frequency_matching_type + " " + phrase + " " + ((m_frequency_search_type == FrequencySearchType.DuplicateLetters) ? L[l]["with"] + " " + L[l]["same"] + " " + L[l]["frequency"] + " " : "") + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                                DisplayFoundWords(FINDBYTEXT_MATCH_COLOR, false);
                            }
                        }
                        break;
                    case FrequencyResultType.Sentences:
                        {
                            int match_count = m_client.FindSentences(phrase, frequency_matching_type, m_frequency_search_type, m_include_diacritics);
                            if (m_client.FoundSentences != null)
                            {
                                m_header_label_info = match_count + ((match_count == 1) ? " " + L[l]["sentence"] : " " + L[l]["sentences"]) + " " + L[l]["with"] + " " + frequency_matching_type + " " + phrase + " " + ((m_frequency_search_type == FrequencySearchType.DuplicateLetters) ? L[l]["with"] + " " + L[l]["same"] + " " + L[l]["frequency"] + " " : "") + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                                DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, true);
                            }
                        }
                        break;
                    case FrequencyResultType.Verses:
                        {
                            int match_count = m_client.FindVerses(phrase, frequency_matching_type, m_frequency_search_type, m_include_diacritics);
                            if (m_client.FoundVerses != null)
                            {
                                m_header_label_info = match_count + ((match_count == 1) ? " " + L[l]["verse"] : " " + L[l]["verses"]) + " " + L[l]["with"] + " " + frequency_matching_type + " " + phrase + " " + ((m_frequency_search_type == FrequencySearchType.DuplicateLetters) ? L[l]["with"] + " " + L[l]["same"] + " " + L[l]["frequency"] + " " : "") + L[l]["in"] + " " + L[l][m_client.SearchScope.ToString()];
                                DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, true);
                            }
                        }
                        break;
                    case FrequencyResultType.Chapters:
                        {
                            int match_count = m_client.FindChapters(phrase, frequency_matching_type, m_frequency_search_type, m_include_diacritics);
                            if (m_client.FoundChapters != null)
                            {
