    private struct FoundMatch
    {
        public int Start;
        public int Length;
    }
    private List<FoundMatch> m_found_matches = null;
    private void BuildFoundMatches()
    {
        if (m_client != null)
        {
            m_found_matches = new List<FoundMatch>();

            if (m_client.FoundWords != null)
            {
                foreach (Word word in m_client.FoundWords)
                {
                    if (word != null)
                    {
                        if (word.Verse != null)
                        {
                            if (word.Verse.Chapter != null)
                            {
                                if (m_matches_per_chapter[word.Verse.Chapter.SortedNumber - 1] > 0)
                                {
                                    int start = GetPositionInRichTextBox(word);
                                    if ((start >= 0) && (start < SearchResultTextBox.Text.Length))
                                    {
                                        if (word.Text != null)
                                        {
                                            int length = word.Text.Length;

                                            FoundMatch find_match = new FoundMatch();
                                            find_match.Start = start;
                                            find_match.Length = length;
                                            m_found_matches.Add(find_match);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            else if (m_client.FoundPhrases != null)
            {
                foreach (Phrase phrase in m_client.FoundPhrases)
                {
                    if (phrase != null)
                    {
                        if (phrase.Verse != null)
                        {
                            if (m_matches_per_chapter[phrase.Verse.Chapter.SortedNumber - 1] > 0)
                            {
                                int start = GetPositionInRichTextBox(phrase);
                                if ((start >= 0) && (start < SearchResultTextBox.Text.Length))
                                {
                                    if (!String.IsNullOrEmpty(phrase.Text))
                                    {
                                        int length = phrase.Text.Length;

                                        FoundMatch find_match = new FoundMatch();
                                        find_match.Start = start;
                                        find_match.Length = length;
                                        m_found_matches.Add(find_match);
                                    }
                                }
                            }
                        }
                    }
                }
            }

            if (m_found_matches != null)
            {
                this.FoundMatchesNumericUpDown.TextChanged -= new System.EventHandler(this.FoundMatchesNumericUpDown_TextChanged);
                FoundMatchesNumericUpDown.Minimum = 0;
                FoundMatchesNumericUpDown.Maximum = m_found_matches.Count;
                FoundMatchesNumericUpDown.Value = 0;
                FoundMatchesNumericUpDown.ForeColor = Numbers.GetNumberTypeColor(((long)FoundMatchesNumericUpDown.Value));
                FoundMatchesNumericUpDown.Focus();
                FoundMatchesNumericUpDown.Refresh();
                this.FoundMatchesNumericUpDown.TextChanged += new System.EventHandler(this.FoundMatchesNumericUpDown_TextChanged);

                FoundMatchesTotalLabel.Text = m_found_matches.Count.ToString();

                FoundMatchesNumericUpDown.Visible = (m_found_matches.Count > 0);
                FoundMatchesTotalLabel.Visible = (m_found_matches.Count > 0);
            }
            else
            {
                FoundMatchesNumericUpDown.Visible = false;
                FoundMatchesTotalLabel.Visible = false;
            }
        }
    }
    // F3/Shift+F3 Goto next/previous matches
    private void SelectPreviousFoundMatch()
    {
        if (m_client != null)
        {
            if (m_found_verses_displayed)
            {
                if (m_found_matches != null)
                {
                    if (m_found_matches.Count > 0)
                    {
                        int selection_start = SearchResultTextBox.SelectionStart;
                        int selection_length = SearchResultTextBox.SelectionLength;

                        bool found = false;
                        int index = int.MaxValue;
                        for (int i = m_found_matches.Count - 1; i >= 0; i--)
                        {
                            int start = m_found_matches[i].Start;
                            int length = m_found_matches[i].Length;

                            // match is selected, go to next match
                            if ((selection_start == start) && (selection_length == length))
                            {
                                index = i - 1;
                                found = (index > -1); // allow round robin
                                break;
                            }
                            // cursor is after or at match, select match
                            else if (selection_start > start)
                            {
                                index = i;
                                found = true;
                                break;
                            }
                        }
                        if (!found)
                        {
                            index = m_found_matches.Count - 1;  // round robin
                        }

                        int number = index + 1;
                        SelectFoundMatch(number);
                    }
                }
            }
        }
    }
    private void SelectNextFoundMatch()
    {
        if (m_client != null)
        {
            if (m_found_verses_displayed)
            {
                if (m_found_matches != null)
                {
                    if (m_found_matches.Count > 0)
                    {
                        int selection_start = SearchResultTextBox.SelectionStart;
                        int selection_length = SearchResultTextBox.SelectionLength;

                        bool found = false;
                        int index = int.MinValue;
                        for (int i = 0; i < m_found_matches.Count; i++)
                        {
                            int start = m_found_matches[i].Start;
                            int length = m_found_matches[i].Length;

                            // match is selected, go to next match
                            if ((selection_start == start) && (selection_length == length))
                            {
                                index = i + 1;
                                found = (index < m_found_matches.Count); // allow round robin
                                break;
                            }
                            // cursor is before or at match, select match
                            else if (selection_start <= (start + length))
                            {
                                index = i;
                                found = true;
                                break;
                            }
                        }
                        if (!found)
                        {
                            index = 0; // round robin
                        }

                        int number = index + 1;
                        SelectFoundMatch(number);
                    }
                }
            }
        }
    }
    private void SelectFoundMatch(int number)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (m_client != null)
        {
            if (m_found_verses_displayed)
            {
                if (m_found_matches != null)
                {
                    if (m_found_matches.Count > 0)
                    {
                        Color color = Color.Black;
                        switch (m_search_type)
                        {
                            case SearchType.Grammar:
                                {
                                    color = FINDBYGRAMMAR_MATCH_COLOR;
                                    break;
                                }
                            case SearchType.Repetition:
                                {
                                    color = FINDBYREPETITION_MATCH_COLOR;
                                    break;
                                }
                            case SearchType.Text:
                                {
                                    color = FINDBYTEXT_MATCH_COLOR;
                                    break;
                                }
                            case SearchType.Numbers:
                                {
                                    color = FINDBYTEXT_MATCH_COLOR;
                                    break;
                                }
                            case SearchType.Similarity:
                                {
                                    color = FINDBYTEXT_MATCH_COLOR;
                                    break;
                                }
                            case SearchType.Frequency:
                                {
                                    color = FINDBYTEXT_MATCH_COLOR;
                                    break;
                                }
                            default:
                                {
                                    color = Color.Black;
                                    break;
                                }
                        }

                        // select found match
                        int index = number - 1;
                        if ((index >= 0) && (index < m_found_matches.Count))
                        {
                            int start = m_found_matches[index].Start;
                            int length = m_found_matches[index].Length;
                            if ((start >= 0) && ((start + length) <= SearchResultTextBox.Text.Length))
                            {
                                SearchResultTextBox.Focus();
                                SearchResultTextBox.Select(start, length);
                                SearchResultTextBox.SelectionColor = color;
                                SearchResultTextBox.SelectionStart = start;

                                //if (m_header_display_mode == HeaderDisplayMode.Info)
                                //{
                                //    Verse verse = GetCurrentVerse();
                                //    if (verse != null)
                                //    {
                                //        if (verse.Chapter != null)
                                //        {
                                //            m_header_label_info = L[l]["Verse"] + " " + (CurrentVerseIndex + 1) + SPACE_GAP + GetVerseSummary(verse);
                                //            UpdateHeaderLabel();
                                //        }
                                //    }
                                //}
                                //else
                                //{
                                //    UpdateHeaderLabel();
                                //    m_header_label_info = HeaderLabel.Text;
                                //}
                            }
                        }

                        if ((number > 0) && (number <= m_found_matches.Count))
                        {
                            this.FoundMatchesNumericUpDown.TextChanged -= new System.EventHandler(this.FoundMatchesNumericUpDown_TextChanged);
                            FoundMatchesNumericUpDown.Minimum = 0;
                            FoundMatchesNumericUpDown.Maximum = m_found_matches.Count;
                            FoundMatchesNumericUpDown.Value = number;
                            FoundMatchesNumericUpDown.ForeColor = Numbers.GetNumberTypeColor(((long)FoundMatchesNumericUpDown.Value));
                            FoundMatchesNumericUpDown.Focus();
                            FoundMatchesNumericUpDown.Refresh();
                            this.FoundMatchesNumericUpDown.TextChanged += new System.EventHandler(this.FoundMatchesNumericUpDown_TextChanged);

                            FoundMatchesNumericUpDown.Visible = (m_found_matches.Count > 0);
                            FoundMatchesTotalLabel.Visible = (m_found_matches.Count > 0);
                        }
                    }
                    else
                    {
                        FoundMatchesNumericUpDown.Visible = false;
                        FoundMatchesTotalLabel.Visible = false;
                    }
                }
                else
                {
                    FoundMatchesNumericUpDown.Visible = false;
                    FoundMatchesTotalLabel.Visible = false;
                }
            }
            else
            {
                FoundMatchesNumericUpDown.Visible = false;
                FoundMatchesTotalLabel.Visible = false;
            }
        }
    }
    private void FoundMatchesNumericUpDown_TextChanged(object sender, EventArgs e)
    {
        int number = (int)(FoundMatchesNumericUpDown.Value);
        if (m_found_matches != null)
        {
            if (m_found_matches.Count > 0)
            {
                SelectFoundMatch(number);
            }
        }
    }

    private enum HeaderDisplayMode { Info, Letter, Word, Verse, Chapter, SameLetter, SameWord, SameVerse };
    private HeaderDisplayMode m_header_display_mode = HeaderDisplayMode.Info;
    private void HeaderLabel_DoubleClick(object sender, EventArgs e)
    {
        if (ModifierKeys == Keys.Shift)
        {
            switch (m_header_display_mode)
            {
                case HeaderDisplayMode.Info:
                    m_header_display_mode = (Globals.EDITION == Edition.Standard) ? HeaderDisplayMode.Chapter : HeaderDisplayMode.SameVerse;
                    break;
                case HeaderDisplayMode.Letter:
                    m_header_display_mode = HeaderDisplayMode.Info;
                    break;
                case HeaderDisplayMode.Word:
                    m_header_display_mode = HeaderDisplayMode.Letter;
                    break;
                case HeaderDisplayMode.Verse:
                    m_header_display_mode = HeaderDisplayMode.Word;
                    break;
                case HeaderDisplayMode.Chapter:
                    m_header_display_mode = HeaderDisplayMode.Verse;
                    break;
                case HeaderDisplayMode.SameLetter:
                    m_header_display_mode = HeaderDisplayMode.Chapter;
                    break;
                case HeaderDisplayMode.SameWord:
                    m_header_display_mode = HeaderDisplayMode.SameLetter;
                    break;
                case HeaderDisplayMode.SameVerse:
                    m_header_display_mode = HeaderDisplayMode.SameWord;
                    break;
            }
        }
        else
        {
            switch (m_header_display_mode)
            {
                case HeaderDisplayMode.Info:
                    m_header_display_mode = HeaderDisplayMode.Letter;
                    break;
                case HeaderDisplayMode.Letter:
                    m_header_display_mode = HeaderDisplayMode.Word;
                    break;
                case HeaderDisplayMode.Word:
                    m_header_display_mode = HeaderDisplayMode.Verse;
                    break;
                case HeaderDisplayMode.Verse:
                    m_header_display_mode = HeaderDisplayMode.Chapter;
                    break;
                case HeaderDisplayMode.Chapter:
                    m_header_display_mode = (Globals.EDITION == Edition.Standard) ? HeaderDisplayMode.Info : HeaderDisplayMode.SameLetter;
                    break;
                case HeaderDisplayMode.SameLetter:
                    m_header_display_mode = HeaderDisplayMode.SameWord;
                    break;
                case HeaderDisplayMode.SameWord:
                    m_header_display_mode = HeaderDisplayMode.SameVerse;
                    break;
                case HeaderDisplayMode.SameVerse:
                    m_header_display_mode = HeaderDisplayMode.Info;
                    break;
            }
        }

        UpdateHeaderLabel();
    }
    private string m_header_label_info = null;
    private void UpdateHeaderLabel()
    {
        if (m_client != null)
        {
            HeaderLabel.Text = "";
            switch (m_header_display_mode)
            {
                case HeaderDisplayMode.Info:
                    {
                        if (m_found_verses_displayed)
                        {
                            if (!String.IsNullOrEmpty((m_header_label_info)))
                            {
                                HeaderLabel.Text = m_header_label_info;

                                string[] parts = m_header_label_info.Split();
                                if (parts.Length > 0)
                                {
                                    int number = 0;
                                    if (int.TryParse(parts[0], out number))
                                    {
                                        HeaderLabel.ForeColor = Numbers.GetNumberTypeColor(number);
                                    }
                                }

                                HeaderLabel.Refresh();
                            }
                        }
                        else
                        {
                            Verse verse = GetCurrentVerse();
                            if (verse != null)
                            {
                                if (verse.Chapter != null)
                                {
                                    HeaderLabel.Text = GetVerseSummary(verse);
                                    HeaderLabel.ForeColor = Numbers.GetNumberTypeColor(verse.NumberInChapter);
                                    HeaderLabel.Refresh();
                                }
                            }
                        }
                    }
                    break;
                case HeaderDisplayMode.Letter:
                    {
                        if (m_clicked_letter != null)
                        {
                            int to_book_start = m_clicked_letter.Number - 1;
                            int to_chapter_start = m_clicked_letter.NumberInChapter - 1;
                            int to_verse_start = m_clicked_letter.NumberInVerse - 1;
                            int to_word_start = m_clicked_letter.NumberInWord - 1;

