                            int to_chapter_end = m_clicked_letter.Word.Verse.Chapter.Letters.Count - m_clicked_letter.NumberInChapter;
                            int to_verse_end = m_clicked_letter.Word.Verse.Letters.Count - m_clicked_letter.NumberInVerse;
                            int to_word_end = m_clicked_letter.Word.Letters.Count - m_clicked_letter.NumberInWord;

                            //int to_book_diff = (int)Math.Abs(to_book_end - to_book_start);
                            //int to_chapter_diff = (int)Math.Abs(to_chapter_end - to_chapter_start);
                            //int to_verse_diff = (int)Math.Abs(to_verse_end - to_verse_start);
                            //int to_word_diff = (int)Math.Abs(to_word_end - to_word_start);
                            HeaderLabel.Text =
                                //"∆ " +
                                //to_book_diff.ToString() + "-" +
                                //to_chapter_diff.ToString() + "-" +
                                //to_verse_diff.ToString() + "-" +
                                //to_word_diff.ToString() +
                                //"                    " +
