                    break;
                case HeaderDisplayMode.Word:
                    {
                        if (m_clicked_word != null)
                        {
                            int to_book_start = m_clicked_word.Number - 1;
                            int to_chapter_start = m_clicked_word.NumberInChapter - 1;
                            int to_verse_start = m_clicked_word.NumberInVerse - 1;

