    private string GetVerseSummary(Verse verse)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return null;

        if (verse == null)
            return null;

        //string text = L[l]["Chapter"] + " " + verse.Chapter.SortedNumber + " " + L[l][verse.Chapter.TransliteratedName] + "     "
        string text = L[l][verse.Chapter.TransliteratedName]
             + "     "
             + L[l]["Verse"] + " " + verse.NumberInChapter //+ "/" + verse.Chapter.Verses.Count + "   "
             + "     "
             + L[l]["Page"] + " " + ((verse.Page != null) ? verse.Page.Number : -1)
        ;

        return text;
    }

    private RichTextBoxEx m_active_textbox = null;
    private bool m_found_verses_displayed = false;
    private void SwitchToMainTextBox()
    {
        CloseScript();

        HelpMessageLabel.SendToBack();
        BookmarkTextBox.Enabled = true;

        FoundMatchesNumericUpDown.Visible = false;
        FoundMatchesTotalLabel.Visible = false;

        if (m_active_textbox != null)
        {
            if (m_found_verses_displayed)
            {
                m_found_verses_displayed = false;
                PopulateChaptersListBox();
            }

            SearchResultTextBox.Visible = false;
            MainTextBox.Visible = true;
            Verse.IncludeNumber = m_word_wrap_main_textbox;
            m_active_textbox = MainTextBox;

            CalculateCurrentValue();
            CalculateCurrentText();

            BuildLetterFrequencies();
            DisplayLetterFrequencies();

            DisplayCurrentPositions();

            UpdateWordWrapLabel(m_active_textbox.WordWrap);

            DisplayChapterRevelationInfo();

            UserRatioPresetLabel.Visible = (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioNumericUpDown.Visible = (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioScopeLabel.Visible = (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioDelimiterLabel.Visible = true;
            UserRatioTypeLabel.Visible = (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioLengthLabel.Visible = (m_user_ratio_delimiter != UserRatioDelimiter.None);

            ToolTip.SetToolTip(this.InspectResultsLabel, L[l]["Inspect verses"]);

            this.Text = Application.ProductName + " | " + GetSelectionSummary();
        }
    }
    private void SwitchToSearchResultTextBox()
    {
        CloseScript();

        HelpMessageLabel.BringToFront();
        BookmarkTextBox.Enabled = false;

        if (m_found_matches != null)
        {
            FoundMatchesNumericUpDown.Visible = (m_found_matches.Count > 0);
            FoundMatchesTotalLabel.Visible = (m_found_matches.Count > 0);
        }

        if (m_active_textbox != null)
        {
            // allow subsequent Finds to update chapter list, and browse history
            m_current_drawing_type = DrawingType.None; // so not to SwitchToPictureBox

            m_found_verses_displayed = true;
            PopulateChaptersListBox();

            // in all cases
            MainTextBox.Visible = false;
            SearchResultTextBox.Visible = true;
            Verse.IncludeNumber = false;
            m_active_textbox = SearchResultTextBox;

            CalculateCurrentValue();
            CalculateCurrentText();

            BuildLetterFrequencies();
            DisplayLetterFrequencies();

            DisplayCurrentPositions();

            UpdateWordWrapLabel(m_active_textbox.WordWrap);

            UserRatioPresetLabel.Visible = (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioNumericUpDown.Visible = (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioScopeLabel.Visible = (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioDelimiterLabel.Visible = true;
            UserRatioTypeLabel.Visible = (m_user_ratio_delimiter != UserRatioDelimiter.None);
            UserRatioLengthLabel.Visible = (m_user_ratio_delimiter != UserRatioDelimiter.None);

            ToolTip.SetToolTip(this.InspectResultsLabel, L[l]["Inspect results"]);

            this.Text = Application.ProductName + " | " + GetSelectionSummary();
        }
    }
    private void SwitchToPictureBox()
    {
        CloseScript();

        HelpMessageLabel.BringToFront();
        BookmarkTextBox.Enabled = false;

        FoundMatchesNumericUpDown.Visible = false;
        FoundMatchesTotalLabel.Visible = false;

        UserRatioPresetLabel.Visible = false;
        UserRatioNumericUpDown.Visible = false;
        UserRatioScopeLabel.Visible = false;
        UserRatioDelimiterLabel.Visible = false;
        UserRatioTypeLabel.Visible = false;
        UserRatioLengthLabel.Visible = false;

        ShowPictureBox();
    }

    private int[] m_matches_per_chapter = null;
    private void DisplayFoundLetters(Color color, bool add_to_history)
    {
        if (m_client != null)
        {
            if (m_client.FoundVerses != null)
            {
                DisplayFoundVerses(color, add_to_history);
            }

            // word statistics
            if (m_client.FoundWords != null)
            {
                if (m_client.FoundWords.Count > 0)
                {
                    CalculateFoundWordsStatistics();
                }
            }

            // letter statistics
            if (m_client.FoundLetters != null)
            {
                if (m_client.FoundLetters.Count > 0)
                {
                    CalculateFoundLettersStatistics();
                }
            }
        }
    }
    private void DisplayFoundLetterRanges(Color color, bool add_to_history)
    {
        DisplayFoundLetterRangesTextFile();

        if (m_client != null)
        {
            if (m_client.FoundLetterRanges != null)
            {
                if (m_client.FoundLetterRanges.Count > 0)
                {
                    m_client.FoundLetters = new List<Letter>();
                    foreach (List<Letter> range in m_client.FoundLetterRanges)
                    {
                        m_client.FoundLetters.AddRange(range);
                    }
                }
            }
        }
        DisplayFoundLetters(color, add_to_history);
    }
    private void DisplayFoundLetterSets(Color color, bool add_to_history)
    {
        DisplayFoundLetterSetsTextFile();

        if (Globals.EDITION == Edition.BigNumbers)
        {
            if (m_client != null)
            {
                if (m_client.FoundLetterSets != null)
                {
                    if (m_client.FoundLetterSets.Count > 0)
                    {
                        m_client.FoundLetters = new List<Letter>();
                        foreach (List<Letter> set in m_client.FoundLetterSets)
                        {
                            m_client.FoundLetters.AddRange(set);
                        }
                    }
                }
            }
            DisplayFoundLetters(color, add_to_history);
        }
    }

    private void DisplayFoundWords(Color color, bool add_to_history)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (m_client.FoundWords != null)
                {
                    if (m_client.FoundWords.Count > 0)
                    {
                        StringBuilder word_texts = new StringBuilder();
                        if (m_client.Book != null)
                        {
                            if (m_client.FoundWords != null)
                            {
                                m_matches_per_chapter = new int[m_client.Book.Chapters.Count];
                                foreach (Word word in m_client.FoundWords)
                                {
                                    if (word != null)
                                    {
                                        word_texts.AppendLine(word.Text);

                                        if (word.Verse != null)
                                        {
                                            if (word.Verse.Chapter != null)
                                            {
                                                m_matches_per_chapter[word.Verse.Chapter.SortedNumber - 1]++;
                                            }
                                        }
                                    }
                                }
                            }
                            else
                            {
                                foreach (Verse verse in m_client.FoundVerses)
                                {
                                    if (verse != null)
                                    {
                                        if (verse.Chapter != null)
                                        {
                                            m_matches_per_chapter[verse.Chapter.SortedNumber - 1]++;
                                        }
                                    }
                                }
                            }
                        }

                        SwitchToSearchResultTextBox();

                        for (int i = 0; i < 3; i++)
                            SearchResultTextBox.TextChanged -= new System.EventHandler(MainTextBox_TextChanged);
                        for (int i = 0; i < 3; i++)
                            SearchResultTextBox.SelectionChanged -= new System.EventHandler(MainTextBox_SelectionChanged);
                        SearchResultTextBox.BeginUpdate();

                        StringBuilder str = new StringBuilder();
                        foreach (Verse verse in m_client.FoundVerses)
                        {
                            if (verse != null)
                            {
                                if (Globals.EDITION == Edition.Standard)
                                {
                                    str.Append(verse.ArabicAddress + "\t" + verse.Text + "\n");
                                }
                                else if (Globals.EDITION == Edition.Research)
                                {
                                    str.Append(verse.Chapter.Name + "\t" + verse.NumberInChapter.ToString() + "\t" + verse.Text + "\n");
                                }
                                else
                                {
                                    str.Append(verse.Chapter.Name + "\t" + verse.NumberInChapter.ToArabic() + "\t" + verse.Text + "\n");
                                }
                            }
                        }
                        if (str.Length > 1)
                        {
                            str.Remove(str.Length - 1, 1); // last space in " {###} "   OR  \n
                        }
                        m_current_text = str.ToString();

                        m_usertext_mode = false;
                        m_selection_mode = false;

                        if (m_client.FoundVerses.Count > 0)
                        {
                            if (m_client.FoundVerses[0] != null)
                            {
                                m_clicked_chapter = m_client.FoundVerses[0].Chapter;
                                m_clicked_verse = m_client.FoundVerses[0];
                                m_clicked_word = m_client.FoundVerses[0].Words[0];
                                m_clicked_letter = m_client.FoundVerses[0].Words[0].Letters[0];
                                m_header_display_mode = HeaderDisplayMode.Info;
                                UpdateHeaderLabel();
                            }
                        }

                        if (
                             (m_text_display_mode == TextDisplayMode.Both) ||
                             (m_text_display_mode == TextDisplayMode.QuranOnly)
                           )
                        {
                            SearchResultTextBox.Text = m_current_text;
                            SearchResultTextBox.Refresh();
                        }

                        WordFrequencyListBoxLabel.Visible = false;
                        WordFrequencyListBox.Visible = false;
                        WordFrequencyWithDiacriticsCheckBox.Visible = false;

                        GenerateSentencesLabel.Visible = false;
                        GenerateSentencesDuplicateLettersCheckBox.Visible = false;

                        if (m_client.FoundWords != null)
                        {
                            if (word_texts.Length > 0)
                            {
                                m_current_text = word_texts.ToString(); // must be assigned here
                                CalculateCurrentValue(m_client.FoundWords);
                                m_current_text = word_texts.ToString(); // must be restored again
                            }
                            else
                            {
                                CalculateCurrentValue(m_client.FoundWords);
                            }

                            // word statistics
                            if (m_client.FoundWords.Count > 0)
                            {
                                CalculateFoundWordsStatistics();
                            }

                            // letter statistics
                            if (m_client.FoundLetters != null)
                            {
                                if (m_client.FoundLetters.Count > 0)
                                {
                                    CalculateFoundLettersStatistics();
                                }
                            }
                        }

                        BuildLetterFrequencies();
                        DisplayLetterFrequencies();

                        if (m_client.FoundWords != null)
                        {
                            if (m_client.FoundWords.Count > 0)
                            {
                                ColorizeFoundWords(color);
                                BuildFoundMatches();
                                HighlightFoundVerses();
                            }
                        }

                        RealignFoundMatchesToStart();
                        DisplayCurrentPositions();
                        RealignFoundMatchesToStart();

                        DisplayTranslations(m_client.FoundVerses);
                        DisplaySymmetry();
                        DisplayPiephiDigits();
                        DisplayCVWLSequence();
                        DisplayValuesSequence();
                        DisplayDNASequence();

                        if (add_to_history)
                        {
                            AddSearchHistoryItem();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            HidePictureBox();
            SearchResultTextBox.EndUpdate();
            SearchResultTextBox.SelectionChanged += new System.EventHandler(MainTextBox_SelectionChanged);
            SearchResultTextBox.TextChanged += new System.EventHandler(MainTextBox_TextChanged);
            this.Cursor = Cursors.Default;
        }
