    private void DisplayFoundLetterRangesTextFile()
    {
        if (Globals.EDITION == Edition.Standard)
            return;

        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (m_client.FoundLetterRanges != null)
                {
                    if (m_client.FoundLetterRanges.Count > 0)
                    {
                        StringBuilder str = new StringBuilder();
                        int count = 0;
                        foreach (List<Letter> range in m_client.FoundLetterRanges)
                        {
                            str.Append(++count + "\t");
                            if (range.Count >= 2)
                            {
                                str.Append(range[0].Number + "-" + range[range.Count - 1].Number);
                            }
                            else if (range.Count == 1)
                            {
                                str.Append(range[0].Number);
                            }
                            else // empty range
                            {
                                // do nothing
                            }
                            str.AppendLine();
                        }

                        string filename = "Found" + ((m_search_type == SearchType.Numbers) ? m_numbers_result_type.ToString() : "LetterRanges") + ".txt";
                        if (Directory.Exists(Globals.STATISTICS_FOLDER))
                        {
                            string path = Globals.STATISTICS_FOLDER + Path.DirectorySeparatorChar + filename;
                            FileHelper.SaveText(path, str.ToString());
                            FileHelper.DisplayFile(path);
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            if (PictureBox.Visible)
            {
                PictureBox.Visible = false;
            }
            this.Cursor = Cursors.Default;
        }
    }
