    private void CalculateFoundPhrasesStatistics()
    {
        if (m_client != null)
        {
            if (m_client.NumerologySystem != null)
            {
                if (m_client.FoundPhrases != null)
                {
                    int word_number_sum = 0;
                    int letter_number_sum = 0;
                    int word_count = 0;
                    int letter_count = 0;
                    Word previous_word = null;
                    Word this_word = null;
                    StringBuilder phrase_str = new StringBuilder();
                    foreach (Phrase phrase in m_client.FoundPhrases)
                    {
                        if (phrase != null)
                        {
                            if (!String.IsNullOrEmpty(phrase.Text))
                            {
                                if (phrase.Verse != null)
                                {
                                    List<Word> words = phrase.Verse.Words;
                                    if (words != null)
                                    {
                                        if (words.Count > 0)
                                        {
                                            foreach (Word word in words)
                                            {
                                                if ((phrase.Position >= word.Position) && (phrase.Position <= (word.Position + word.Text.Length)))
                                                {
                                                    this_word = word;
                                                    break;
                                                }
                                            }

                                            int phrase_word_count = phrase.Text.Split(' ').Length;
                                            if (phrase_word_count == 1)
                                            {
                                                if (this_word != previous_word)
                                                {
                                                    word_count++;
                                                }
                                            }
                                            else // cross-word phrases are not processed YET
                                            {
                                                word_count += phrase_word_count;
                                            }

                                            previous_word = this_word;
                                        }
                                    }
                                }

                                string phrase_no_spaces = phrase.Text.Replace(" ", "");
                                if (!m_with_diacritics)
                                {
                                    phrase_no_spaces = phrase_no_spaces.Simplify(m_client.NumerologySystem.TextMode);
                                }
                                letter_count += phrase_no_spaces.Length;

                                phrase_str.AppendLine(phrase.Text);
                            }
                        }
                    }

                    WordsTextBox.Text = Radix.Encode(word_count, m_radix);
                    WordsTextBox.ForeColor = Numbers.GetNumberTypeColor(WordsTextBox.Text, m_radix);
                    WordsTextBox.BackColor = (Numbers.Compare(word_count, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.ControlLight;
                    if (Globals.EDITION != Edition.Standard)
                        if (word_count.IsInterestingX(INTERESTINGX_COUNT))
                            WordsTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                    if (word_count.IsInteresting())
                        WordsTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (word_count.IsCarmichaelX())
                        WordsTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (word_count.IsCarmichael())
                        WordsTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    ToolTip.SetToolTip(this.WordsTextBox, word_count.FindInterestingSums(INTERESTINGX_COUNT));
                    WordsTextBox.Refresh();
                    DecimalWordsTextBox.Text = word_count.ToString();
                    DecimalWordsTextBox.ForeColor = Numbers.GetNumberTypeColor(word_count);
                    DecimalWordsTextBox.Visible = (m_radix != Numbers.DEFAULT_RADIX);
                    DecimalWordsTextBox.Refresh();

                    LettersTextBox.Text = Radix.Encode(letter_count, m_radix);
                    LettersTextBox.ForeColor = Numbers.GetNumberTypeColor(LettersTextBox.Text, m_radix);
                    LettersTextBox.BackColor = (Numbers.Compare(letter_count, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.ControlLight;
                    if (Globals.EDITION != Edition.Standard)
                        if (letter_count.IsInterestingX(INTERESTINGX_COUNT))
                            LettersTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                    if (letter_count.IsInteresting())
                        LettersTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (letter_count.IsCarmichaelX())
                        LettersTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (letter_count.IsCarmichael())
                        LettersTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    LettersTextBox.Refresh();
                    DecimalLettersTextBox.Text = letter_count.ToString();
                    DecimalLettersTextBox.ForeColor = Numbers.GetNumberTypeColor(letter_count);
                    DecimalLettersTextBox.Visible = (m_radix != Numbers.DEFAULT_RADIX);
                    DecimalLettersTextBox.Refresh();

                    if (m_client.CalculationMode == CalculationMode.SumOfLetterValues)
                    {
                        long value = 0L;
                        foreach (Phrase phrase in m_client.FoundPhrases)
                        {
                            if (phrase != null)
                            {
                                if (!String.IsNullOrEmpty(phrase.Text))
                                {
                                    value += m_client.CalculateValue(phrase.Text);
                                }
                            }
                        }
                        FactorizeValue(value, "Value");
                    }
                    else
                    {
                        CalculateValueAndDisplayFactors(phrase_str.ToString());
                    }

                    WordNumberSumTextBox.Text = SUM_SYMBOL + word_number_sum.ToString();
                    WordNumberSumTextBox.ForeColor = Numbers.GetNumberTypeColor(word_number_sum);
                    WordNumberSumTextBox.BackColor = (Numbers.Compare(word_number_sum, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.ControlLight;
                    if (Globals.EDITION != Edition.Standard)
                        if (word_number_sum.IsInterestingX(INTERESTINGX_COUNT))
                            WordNumberSumTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                    if (word_number_sum.IsInteresting())
                        WordNumberSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (word_number_sum.IsCarmichaelX())
                        WordNumberSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (word_number_sum.IsCarmichael())
                        WordNumberSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    ToolTip.SetToolTip(this.WordNumberSumTextBox, word_number_sum.FindInterestingSums(INTERESTINGX_COUNT));
                    LetterNumberSumTextBox.Text = SUM_SYMBOL + letter_number_sum.ToString();
                    WordNumberSumTextBox.Refresh();

                    LetterNumberSumTextBox.Text = SUM_SYMBOL + letter_number_sum.ToString();
                    LetterNumberSumTextBox.ForeColor = Numbers.GetNumberTypeColor(letter_number_sum);
                    LetterNumberSumTextBox.BackColor = (Numbers.Compare(letter_number_sum, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.ControlLight;
                    if (Globals.EDITION != Edition.Standard)
                        if (word_number_sum.IsInterestingX(INTERESTINGX_COUNT))
                            WordNumberSumTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                    if (word_number_sum.IsInteresting())
                        WordNumberSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (word_number_sum.IsCarmichaelX())
                        WordNumberSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (word_number_sum.IsCarmichael())
                        WordNumberSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    ToolTip.SetToolTip(this.WordNumberSumTextBox, word_number_sum.FindInterestingSums(INTERESTINGX_COUNT));
                    LetterNumberSumTextBox.Refresh();
                }
            }
        }
    }

    private Dictionary<Verse, Color> m_found_verses_backcolors = new Dictionary<Verse, Color>();
    private void CalculateFoundVersesBackColors()
    {
        if (m_found_verses_backcolors != null)
        {
            m_found_verses_backcolors.Clear();
        }

        if (m_client != null)
        {
            if (m_client.FoundVerses != null)
            {
                Dictionary<Verse, int> matches_per_verse_dictionary = new Dictionary<Verse, int>();
                if (m_client.FoundLetters != null)
                {
                    if (m_client.FoundLetters.Count >= m_client.FoundVerses.Count)
                    {
                        foreach (Letter letter in m_client.FoundLetters)
                        {
                            if (letter != null)
                            {
                                if (matches_per_verse_dictionary.ContainsKey(letter.Word.Verse))
                                {
                                    matches_per_verse_dictionary[letter.Word.Verse]++;
                                }
                                else
                                {
                                    matches_per_verse_dictionary.Add(letter.Word.Verse, 1);
                                }
                            }
                        }
                    }
                }
                else if (m_client.FoundWords != null)
                {
                    if (m_client.FoundWords.Count >= m_client.FoundVerses.Count)
                    {
                        foreach (Word word in m_client.FoundWords)
                        {
                            if (word != null)
                            {
                                if (matches_per_verse_dictionary.ContainsKey(word.Verse))
                                {
                                    matches_per_verse_dictionary[word.Verse]++;
                                }
                                else
                                {
                                    matches_per_verse_dictionary.Add(word.Verse, 1);
                                }
                            }
                        }
                    }
                }
                else if (m_client.FoundPhrases != null)
                {
                    if (m_client.FoundPhrases.Count >= m_client.FoundVerses.Count)
                    {
                        foreach (Phrase phrase in m_client.FoundPhrases)
                        {
                            if (phrase != null)
                            {
                                if (matches_per_verse_dictionary.ContainsKey(phrase.Verse))
                                {
                                    matches_per_verse_dictionary[phrase.Verse]++;
                                }
                                else
                                {
                                    matches_per_verse_dictionary.Add(phrase.Verse, 1);
                                }
                            }
                        }
                    }
                }
                foreach (Verse verse in m_client.FoundVerses)
                {
                    if (matches_per_verse_dictionary.ContainsKey(verse))
                    {
                        int match_count = matches_per_verse_dictionary[verse];
                        if (match_count > 1)
                        {
                            int red = 255;
                            int green = 255;
                            int blue = 255;
                            green -= ((match_count - 1) * 8);
                            if (green < 0)
                            {
                                red += green;
                                green = 0;
                            }
                            if (red < 0)
                            {
                                blue += red;
                                red = 0;
                            }
                            if (blue < 0)
                            {
                                blue = 0;
                            }

                            if (m_found_verses_backcolors != null)
                            {
                                if (m_found_verses_backcolors.ContainsKey(verse))
                                {
                                    m_found_verses_backcolors[verse] = Color.FromArgb(red, green, blue);
                                }
                                else
                                {
                                    m_found_verses_backcolors.Add(verse, Color.FromArgb(red, green, blue));
                                }
                            }
                        }
                        else
                        {
                            if (m_found_verses_backcolors != null)
                            {
                                if (m_found_verses_backcolors.ContainsKey(verse))
                                {
                                    m_found_verses_backcolors[verse] = SearchResultTextBox.BackColor;
                                }
                                else
                                {
                                    m_found_verses_backcolors.Add(verse, SearchResultTextBox.BackColor);
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private void HighlightFoundVerses()
    {
        try
        {
            CalculateFoundVersesBackColors();

            // SearchByText|WORDS|Or: بررة منسك SearchResultTextBox not responding to mouse if BeginUpdate used!!! 
            for (int i = 0; i < 3; i++)
                SearchResultTextBox.TextChanged -= new System.EventHandler(MainTextBox_TextChanged);
            for (int i = 0; i < 3; i++)
                SearchResultTextBox.SelectionChanged -= new System.EventHandler(MainTextBox_SelectionChanged);
            //SearchResultTextBox.BeginUpdate();
            SearchResultTextBox.ClearHighlight();

            if (m_client != null)
            {
                if (m_client.FoundVerses != null)
                {
                    foreach (Verse verse in m_client.FoundVerses)
                    {
                        if (m_found_verses_backcolors.ContainsKey(verse))
                        {
                            int start = GetVerseDisplayStart(verse);
                            int length = GetVerseDisplayLength(verse);
                            /////?????
                            SearchResultTextBox.Highlight(start, length, m_found_verses_backcolors[verse]);
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            SearchResultTextBox.SelectionChanged += new System.EventHandler(MainTextBox_SelectionChanged);
            SearchResultTextBox.TextChanged += new System.EventHandler(MainTextBox_TextChanged);
        }
    }
    private void ColorizeFoundLetters(Color color)
    {
        if (m_client != null)
        {
            if (m_client.NumerologySystem.TextMode != "Original")
            {
                if (m_client.FoundLetters != null)
                {
                    foreach (Letter letter in m_client.FoundLetters)
                    {
                        if (letter != null)
                        {
                            if (letter.Word.Verse != null)
                            {
                                int start = GetPositionInRichTextBox(letter);
                                if ((start >= 0) && (start < SearchResultTextBox.Text.Length))
                                {
                                    if (letter.Text != null)
                                    {
                                        int extra = 0;
                                        foreach (char c in letter.Text)
                                        {
                                            if ((Constants.STOPMARKS.Contains(c)) || (Constants.QURANMARKS.Contains(c)))
                                            {
                                                extra += 2;
                                            }
                                        }
                                        int length = letter.Text.Length + extra;
                                        SearchResultTextBox.Select(start, length);
                                        SearchResultTextBox.SelectionColor = color;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
