    private void InspectResultsLabel_Click(object sender, EventArgs e)
    {
        if (m_client != null)
        {
            if (m_client.Book != null)
            {
                if (m_client.NumerologySystem != null)
                {
                    string result = null;
                    string filename = null;
                    if (m_found_verses_displayed)
                    {
                        if (m_search_type == SearchType.Grammar)
                        {
                            if (m_client.FoundWords != null)
                            {
                                result = DisplayInformation(m_client.FoundWords) + "\r\n\r\n" + DisplayInformation(m_client.FoundVerses);
                            }
                        }
                        else if (m_search_type == SearchType.Repetition)
                        {
                            if (m_client.FoundWords != null)
                            {
                                result = DisplayInformation(m_client.FoundWords) + "\r\n\r\n" + DisplayInformation(m_client.FoundVerses);
                            }
                        }
                        else if (m_search_type == SearchType.Text)
                        {
                            switch (m_text_search_block_size)
                            {
                                case TextSearchBlockSize.Verse:
                                    {
                                        result = ((m_client.FoundLetters != null) ? (DisplayInformation(m_client.FoundLetters) + "\r\n\r\n") : "") +
                                                 ((m_client.FoundWords != null) ? (DisplayInformation(m_client.FoundWords) + "\r\n\r\n") : "") +
                                                 DisplayInformation(m_client.FoundVerses);
                                    }
                                    break;
                                case TextSearchBlockSize.Chapter:
                                    {
                                        List<Chapter> chapters = m_client.Book.GetChapters(m_client.FoundVerses);
                                        if (chapters != null)
                                        {
                                            result = DisplayInformation(chapters);
                                        }
                                    }
                                    break;
                                case TextSearchBlockSize.Page:
                                    {
                                        List<Page> pages = m_client.Book.GetPages(m_client.FoundVerses);
                                        if (pages != null)
                                        {
                                            result = DisplayInformation(pages);
                                        }
                                    }
                                    break;
                                case TextSearchBlockSize.Station:
                                    {
                                        List<Station> stations = m_client.Book.GetStations(m_client.FoundVerses);
                                        if (stations != null)
                                        {
                                            result = DisplayInformation(stations);
                                        }
                                    }
                                    break;
                                case TextSearchBlockSize.Part:
                                    {
                                        List<Part> parts = m_client.Book.GetParts(m_client.FoundVerses);
                                        if (parts != null)
                                        {
                                            result = DisplayInformation(parts);
                                        }
                                    }
                                    break;
                                case TextSearchBlockSize.Group:
                                    {
                                        List<Group> group = m_client.Book.GetGroups(m_client.FoundVerses);
                                        if (group != null)
                                        {
                                            result = DisplayInformation(group);
                                        }
                                    }
                                    break;
                                case TextSearchBlockSize.Half:
                                    {
                                        List<Half> halfs = m_client.Book.GetHalfs(m_client.FoundVerses);
                                        if (halfs != null)
                                        {
                                            result = DisplayInformation(halfs);
                                        }
                                    }
                                    break;
                                case TextSearchBlockSize.Quarter:
                                    {
                                        List<Quarter> quarters = m_client.Book.GetQuarters(m_client.FoundVerses);
                                        if (quarters != null)
                                        {
                                            result = DisplayInformation(quarters);
                                        }
                                    }
                                    break;
                                case TextSearchBlockSize.Bowing:
                                    {
                                        List<Bowing> bowings = m_client.Book.GetBowings(m_client.FoundVerses);
                                        if (bowings != null)
                                        {
                                            result = DisplayInformation(bowings);
                                        }
                                    }
                                    break;
                            }
                        }
                        else if (m_search_type == SearchType.Numbers)
                        {
                            switch (m_numbers_result_type)
                            {
                                case NumbersResultType.Letters:
                                case NumbersResultType.LetterRanges:
                                case NumbersResultType.LetterSets:
                                    {
                                        result = DisplayInformation(m_client.FoundLetters) + "\r\n\r\n" + DisplayInformation(m_client.FoundVerses);
                                    }
                                    break;
                                case NumbersResultType.Words:
                                case NumbersResultType.WordRanges:
                                case NumbersResultType.WordSets:
                                    {
                                        result = DisplayInformation(m_client.FoundWords) + "\r\n\r\n" + DisplayInformation(m_client.FoundVerses);
                                    }
                                    break;
                                case NumbersResultType.Sentences:
                                    {
                                        result = DisplayInformation(m_client.FoundVerses); // Sentence and Phrase don't know about Words
                                    }
                                    break;
                                case NumbersResultType.Verses:
                                case NumbersResultType.VerseRanges:
                                case NumbersResultType.VerseSets:
                                    {
                                        result = DisplayInformation(m_client.FoundVerses);
                                    }
                                    break;
                                case NumbersResultType.Chapters:
                                case NumbersResultType.ChapterRanges:
                                case NumbersResultType.ChapterSets:
                                    {
                                        List<Chapter> chapters = m_client.Book.GetChapters(m_client.FoundVerses);
                                        if (chapters != null)
                                        {
                                            result = DisplayInformation(chapters);
                                        }
                                    }
                                    break;
                                case NumbersResultType.Pages:
                                case NumbersResultType.PageRanges:
                                case NumbersResultType.PageSets:
                                    {
                                        List<Page> pages = m_client.Book.GetPages(m_client.FoundVerses);
                                        if (pages != null)
                                        {
                                            result = DisplayInformation(pages);
                                        }
                                    }
                                    break;
                                case NumbersResultType.Stations:
                                case NumbersResultType.StationRanges:
                                case NumbersResultType.StationSets:
                                    {
                                        List<Station> stations = m_client.Book.GetStations(m_client.FoundVerses);
                                        if (stations != null)
                                        {
                                            result = DisplayInformation(stations);
                                        }
                                    }
                                    break;
                                case NumbersResultType.Parts:
                                case NumbersResultType.PartRanges:
                                case NumbersResultType.PartSets:
                                    {
                                        List<Part> parts = m_client.Book.GetParts(m_client.FoundVerses);
                                        if (parts != null)
                                        {
                                            result = DisplayInformation(parts);
                                        }
                                    }
                                    break;
                                case NumbersResultType.Groups:
                                case NumbersResultType.GroupRanges:
                                case NumbersResultType.GroupSets:
                                    {
                                        List<Group> group = m_client.Book.GetGroups(m_client.FoundVerses);
                                        if (group != null)
                                        {
                                            result = DisplayInformation(group);
                                        }
                                    }
                                    break;
                                case NumbersResultType.Halfs:
                                case NumbersResultType.HalfRanges:
                                case NumbersResultType.HalfSets:
                                    {
                                        List<Half> halfs = m_client.Book.GetHalfs(m_client.FoundVerses);
                                        if (halfs != null)
                                        {
                                            result = DisplayInformation(halfs);
                                        }
                                    }
                                    break;
                                case NumbersResultType.Quarters:
                                case NumbersResultType.QuarterRanges:
                                case NumbersResultType.QuarterSets:
                                    {
                                        List<Quarter> quarters = m_client.Book.GetQuarters(m_client.FoundVerses);
                                        if (quarters != null)
                                        {
                                            result = DisplayInformation(quarters);
                                        }
                                    }
                                    break;
                                case NumbersResultType.Bowings:
                                case NumbersResultType.BowingRanges:
                                case NumbersResultType.BowingSets:
                                    {
                                        List<Bowing> bowings = m_client.Book.GetBowings(m_client.FoundVerses);
                                        if (bowings != null)
                                        {
                                            result = DisplayInformation(bowings);
                                        }
                                    }
                                    break;
                            }
                        }
                        else if (m_search_type == SearchType.Similarity)
                        {
                            result = DisplayInformation(m_client.FoundVerses);
                        }
                        else if (m_search_type == SearchType.Frequency)
                        {
                            switch (m_frequency_result_type)
                            {
                                case FrequencyResultType.Words:
                                    {
                                        result = DisplayInformation(m_client.FoundWords) + "\r\n\r\n" + DisplayInformation(m_client.FoundVerses);
                                    }
                                    break;
                                case FrequencyResultType.Sentences:
                                    {
                                        result = DisplayInformation(m_client.FoundVerses); // Sentence and Phrase don't know about Words
                                    }
                                    break;
                                case FrequencyResultType.Verses:
                                    {
                                        result = DisplayInformation(m_client.FoundVerses);
                                    }
                                    break;
                                case FrequencyResultType.Chapters:
                                    {
                                        List<Chapter> chapters = m_client.Book.GetChapters(m_client.FoundVerses);
                                        if (chapters != null)
                                        {
                                            result = DisplayInformation(chapters);
                                        }
                                    }
                                    break;
                            }
                        }
                        else // default
                        {
                            result = DisplayInformation(m_client.FoundVerses);
                        }

                        if (!String.IsNullOrEmpty(m_header_label_info))
                        {
                            string text = m_header_label_info;
                            text = text.Replace(" ", "_");
                            text = text.Replace("*", "");
                            text = text.Replace("=", "_eq");
                            text = text.Replace("≠", "_neq");
                            text = text.Replace("≤", "_lt");
                            text = text.Replace("<=", "_leq");
                            text = text.Replace(">", "_gt");
                            text = text.Replace("≥", "_geq");
                            text = text.Replace("!÷", "_ndiv");
                            text = text.Replace("÷", "_div");
                            text = text.Replace("Σ", "_sum");
                            filename = m_client.NumerologySystem.Name + "_" + text + ".txt";
                        }
                        else
                        {
                            filename = m_client.NumerologySystem.Name + ".txt";
                        }
                    }
                    else // not found_verses_displayed
                    {
                        if (m_client.Selection != null)
                        {
                            List<Verse> verses = m_client.Selection.Verses;
                            if (verses != null)
                            {
                                result = DisplayInformation(verses);
                            }

                            StringBuilder str = new StringBuilder();
                            str.Append(m_client.Selection.Scope.ToString());
                            if (m_client.Selection.Scope == SelectionScope.Chapter)
                            {
                                foreach (Chapter chapter in m_client.Selection.Chapters)
                                {
                                    str.Append("." + chapter.SortedNumber);
                                }
                            }
                            else
                            {
                                foreach (int index in m_client.Selection.Indexes)
                                {
                                    str.Append("." + (index + 1).ToString());
                                }
                            }
                            if (str.Length > MAX_SCOPE_TEXT_LENGTH)
                            {
                                str.Remove(MAX_SCOPE_TEXT_LENGTH, str.Length - MAX_SCOPE_TEXT_LENGTH);
                                int pos = str.ToString().LastIndexOf('.');
                                if (pos > -1)
                                {
                                    str.Remove(pos, str.Length - pos);
                                }

                                if (str[str.Length - 1] == '.')
                                {
                                    str.Append("..");
                                }
                                else
                                {
                                    str.Append("...");
                                }
                            }

                            filename = m_client.NumerologySystem.Name + "_" + ((m_client.Selection.Scope == SelectionScope.Verse) ? "" : "VersesOf") + str.ToString() + ".txt";
                        }
                    }
                    if (Directory.Exists(Globals.STATISTICS_FOLDER))
                    {
                        string path = Globals.STATISTICS_FOLDER + Path.DirectorySeparatorChar + filename;
                        FileHelper.SaveText(path, result);
                        FileHelper.DisplayFile(path);
                    }
                }
            }
        }
    }
    private string DisplayInformation(List<Letter> letters)
    {
        if (letters == null)
            return null;

        StringBuilder str = new StringBuilder();
        if (letters.Count > 0)
        {
            str.Append
            (
                "#" + "\t" +
                "Number" + "\t" +
                "InChap" + "\t" +
                "InVerse" + "\t" +
                "Chapter" + "\t" +
                "Verse" + "\t" +
                "Word" + "\t" +
                "Letter" + "\t" +
                "Unique" + "\t" +
                "Value" + "\t" +
                "Text" + "\t" +
                "Word" + "\r\n"
            );

            int count_sum = 0;
            int letter_number_in_book_sum = 0;
            int letter_number_in_chapter_sum = 0;
            int letter_number_in_verse_sum = 0;
            int chapter_number_sum = 0;
            int verse_number_sum = 0;
            int word_number_sum = 0;
            int letter_number_sum = 0;
            long value_sum = 0L;

            int count = 0;
            foreach (Letter letter in letters)
            {
                count++;
                int letter_number_in_book = letter.Number;
                int letter_number_in_chapter = letter.NumberInChapter;
                int letter_number_in_verse = letter.NumberInVerse;
                int chapter_number = letter.Word.Verse.Chapter.SortedNumber;
                int verse_number = letter.Word.Verse.NumberInChapter;
                int word_number = letter.Word.NumberInVerse;
                int letter_number = letter.NumberInWord;
                long value = m_client.CalculateValue(letter);
                str.Append
                (
                    count.ToString() + "\t" +
                    letter_number_in_book.ToString() + "\t" +
                    letter_number_in_chapter.ToString() + "\t" +
                    letter_number_in_verse.ToString() + "\t" +
                    chapter_number.ToString() + "\t" +
                    verse_number.ToString() + "\t" +
                    word_number.ToString() + "\t" +
                    letter_number.ToString() + "\t" +
                    value.ToString() + "\t" +
                    letter.Text + "\t" +
                    letter.Word.ToString() + "\r\n"
                );
                count_sum += count;
                letter_number_in_book_sum += letter_number_in_book;
                letter_number_in_chapter_sum += letter_number_in_chapter;
                letter_number_in_verse_sum += letter_number_in_verse;
                chapter_number_sum += chapter_number;
                verse_number_sum += verse_number;
                word_number_sum += word_number;
                letter_number_sum += letter_number;
                value_sum += value;
            }

            str.Append
            (
                count_sum.ToString() + "\t" +
                letter_number_in_book_sum.ToString() + "\t" +
                letter_number_in_chapter_sum.ToString() + "\t" +
                letter_number_in_verse_sum.ToString() + "\t" +
                chapter_number_sum.ToString() + "\t" +
                verse_number_sum.ToString() + "\t" +
                word_number_sum.ToString() + "\t" +
                letter_number_sum.ToString() + "\t" +
                value_sum.ToString() + "\t" +
                "" + "\t" +
                "" + "\r\n"
            );
        }
        return str.ToString();
    }
