    private string DisplayInformation(List<Verse> verses)
    {
        if (m_client == null)
            return null;
        if (verses == null)
            return null;

        StringBuilder str = new StringBuilder();

        str.Append("#" + "\t" + "Number" + "\t" + "Chapter" + "\t" + "Verse" + "\t" + "Words" + "\t" + "Letters" + "\t" + "Unique" + "\t" + "Value" + "\t");

        NumerologySystem numerology_system = m_client.NumerologySystem;
        if (numerology_system != null)
        {
            foreach (char key in numerology_system.LetterValues.Keys)
            {
                str.Append(key.ToString() + "\t");
            }
            str.AppendLine("Text");

            int count = 0;
            int count_sum = 0;
            int verse_sum = 0;
            int chapter_sum = 0;
            int chapter_verse_sum = 0;
            int word_sum = 0;
            int letter_sum = 0;
            int unique_letter_sum = 0;
            long value = 0L;
            long value_sum = 0L;
            int[] letter_sums = new int[numerology_system.LetterValues.Count];
            foreach (Verse verse in verses)
            {
                count++;
                count_sum += count;
                verse_sum += verse.Number;
                chapter_sum += verse.Chapter.SortedNumber;
                chapter_verse_sum += verse.NumberInChapter;
                word_sum += verse.Words.Count;
                letter_sum += verse.Letters.Count;
                unique_letter_sum += verse.UniqueLetters.Count;
                value = m_client.CalculateValue(verse);
                value_sum += value;

                str.Append(count.ToString() + "\t");
                str.Append(verse.Number.ToString() + "\t");
                str.Append(verse.Chapter.SortedNumber.ToString() + "\t");
                str.Append(verse.NumberInChapter.ToString() + "\t");
                str.Append(verse.Words.Count.ToString() + "\t");
                str.Append(verse.Letters.Count.ToString() + "\t");
                str.Append(verse.UniqueLetters.Count.ToString() + "\t");
                str.Append(value.ToString() + "\t");

                int i = 0;
                foreach (char key in numerology_system.LetterValues.Keys)
                {
                    int letter_count = verse.GetLetterFrequency(key);
                    letter_sums[i] += letter_count;
                    i++;
                    str.Append(letter_count.ToString() + "\t");
                }

                str.AppendLine(verse.Text);
            }
            if (str.Length > 2)
            {
                str.Remove(str.Length - 2, 2);
            }

            str.AppendLine();
            str.Append(count_sum + "\t" + verse_sum + "\t" + chapter_sum + "\t" + chapter_verse_sum + "\t" + word_sum + "\t" + letter_sum + "\t" + unique_letter_sum + "\t" + value_sum + "\t");
            for (int i = 0; i < letter_sums.Length; i++)
            {
                str.Append(letter_sums[i].ToString() + "\t");
            }
            str.Remove(str.Length - 1, 1); // \t
            str.AppendLine();
        }

        // needed by Tariq
        str.AppendLine();
        str.AppendLine();
        str.AppendLine("------------------");
        str.AppendLine("Verses from Values");
        str.AppendLine("------------------");
        str.Append(DisplayValueVerses(verses));

        return str.ToString();
    }
    private string DisplayValueVerses(List<Verse> verses)
    {
        if (m_client == null)
            return null;
        if (verses == null)
            return null;

        StringBuilder str = new StringBuilder();

        str.Append("#" + "\t" + "Number" + "\t" + "Chapter" + "\t" + "Verse" + "\t" + "Words" + "\t" + "Letters" + "\t" + "Unique" + "\t" + "Value" + "\t");

        NumerologySystem numerology_system = m_client.NumerologySystem;
        if (numerology_system != null)
        {
            foreach (char key in numerology_system.LetterValues.Keys)
            {
                str.Append(key.ToString() + "\t");
            }
            str.AppendLine("Text");

            int count = 0;
            int count_sum = 0;
            int verse_sum = 0;
            int chapter_sum = 0;
            int chapter_verse_sum = 0;
            int word_sum = 0;
            int letter_sum = 0;
            int unique_letter_sum = 0;
            long value = 0L;
            long value_sum = 0L;
            int[] letter_sums = new int[numerology_system.LetterValues.Count];
            int[] verse_numbers = new int[verses.Count];
            foreach (Verse v in verses)
            {
                // get index from verse value
                int index = (int)m_client.CalculateValue(v) - 1;
                if (index < 0)
                    index -= index;
                if (index >= m_client.Book.Verses.Count)
                    index %= m_client.Book.Verses.Count;

                Verse verse = m_client.Book.Verses[index];
                if (verse != null)
                {
                    count++;
                    count_sum += count;
                    verse_sum += verse.Number;
                    chapter_sum += verse.Chapter.SortedNumber;
                    chapter_verse_sum += verse.NumberInChapter;
                    word_sum += verse.Words.Count;
                    letter_sum += verse.Letters.Count;
                    unique_letter_sum += verse.UniqueLetters.Count;
                    value = m_client.CalculateValue(verse);
                    value_sum += value;

                    str.Append(count.ToString() + "\t");
                    str.Append(verse.Number.ToString() + "\t");
                    verse_numbers[count - 1] = verse.Number;
                    str.Append(verse.Chapter.SortedNumber.ToString() + "\t");
                    str.Append(verse.NumberInChapter.ToString() + "\t");
                    str.Append(verse.Words.Count.ToString() + "\t");
                    str.Append(verse.Letters.Count.ToString() + "\t");
                    str.Append(verse.UniqueLetters.Count.ToString() + "\t");
                    str.Append(value.ToString() + "\t");

                    int i = 0;
                    foreach (char key in numerology_system.LetterValues.Keys)
                    {
                        int letter_count = verse.GetLetterFrequency(key);
                        letter_sums[i] += letter_count;
                        i++;
                        str.Append(letter_count.ToString() + "\t");
                    }

                    str.AppendLine(verse.Text);
                }
            }
            if (str.Length > 2)
            {
                str.Remove(str.Length - 2, 2);
            }

            str.AppendLine();
            str.Append(count_sum + "\t" + verse_sum + "\t" + chapter_sum + "\t" + chapter_verse_sum + "\t" + word_sum + "\t" + letter_sum + "\t" + unique_letter_sum + "\t" + value_sum + "\t");
            for (int i = 0; i < letter_sums.Length; i++)
            {
                str.Append(letter_sums[i].ToString() + "\t");
            }
            str.Remove(str.Length - 1, 1); // \t
            str.AppendLine();

            str.AppendLine();
            str.AppendLine("Paste these Values into the Book's [Verse] field for next \"Verses from Values\":");
            foreach (int n in verse_numbers)
            {
                str.Append(n.ToString() + ",");
            }
            str.Remove(str.Length - 1, 1); // ,
            str.AppendLine();
        }
        return str.ToString();
    }
