        NumerologySystem numerology_system = m_client.NumerologySystem;
        if (numerology_system != null)
        {
            if (numerology_system.LetterValues.Keys.Count > 0)
            {
                foreach (char key in numerology_system.LetterValues.Keys)
                {
                    str.Append(key.ToString() + "\t");
                }
                if (str.Length > 1)
                {
                    str.Remove(str.Length - 1, 1); // \t
                }
                str.AppendLine();
            }

            int count = 0;
            int count_sum = 0;
            int match_sum = 0;
            int chapter_sum = 0;
            int verse_sum = 0;
            int word_sum = 0;
            int letter_sum = 0;
            int unique_letter_sum = 0;
            long value = 0L;
            long value_sum = 0L;
            int[] letter_sums = new int[numerology_system.LetterValues.Count];
            foreach (Chapter chapter in chapters)
            {
                count++;
                count_sum += count;
                chapter_sum += chapter.SortedNumber;
                verse_sum += chapter.Verses.Count;
                word_sum += chapter.Words.Count;
                letter_sum += chapter.Letters.Count;
                unique_letter_sum += chapter.UniqueLetters.Count;
                value = m_client.CalculateValue(chapter);
                value_sum += value;

                str.Append(count + "\t");
                str.Append(chapter.Name + "\t");
                if (m_found_verses_displayed)
                {
                    int index = chapter.SortedNumber - 1;
                    if (m_matches_per_chapter != null)
                    {
                        if ((index >= 0) && (index < m_matches_per_chapter.Length))
                        {
                            int match_count = m_matches_per_chapter[index];
                            str.Append(match_count + "\t");
                            match_sum += match_count;
                        }
                    }
                }
                str.Append(chapter.SortedNumber.ToString() + "\t");
                str.Append(chapter.Verses.Count.ToString() + "\t");
                str.Append(chapter.Words.Count.ToString() + "\t");
                str.Append(chapter.Letters.Count.ToString() + "\t");
                str.Append(chapter.UniqueLetters.Count.ToString() + "\t");
                str.Append(value.ToString() + "\t");
                if (numerology_system.LetterValues.Keys.Count > 0)
                {
                    int i = 0;
                    foreach (char key in numerology_system.LetterValues.Keys)
                    {
                        int letter_count = chapter.GetLetterFrequency(key);
                        letter_sums[i] += letter_count;
                        i++;
                        str.Append(letter_count.ToString() + "\t");
                    }
                    if (str.Length > 1)
                    {
                        str.Remove(str.Length - 1, 1); // \t
                    }
                    str.AppendLine();
                }
            }
            if (str.Length > 2)
            {
                str.Remove(str.Length - 2, 2);
            }

            str.AppendLine();
            str.Append(count_sum + "\t" + "Sum" + (m_found_verses_displayed ? "\t" + match_sum : "") + "\t" + chapter_sum + "\t" + verse_sum + "\t" + word_sum + "\t" + letter_sum + "\t" + unique_letter_sum + "\t" + value_sum + "\t");
            for (int i = 0; i < letter_sums.Length; i++)
            {
                str.Append(letter_sums[i].ToString() + "\t");
            }
            str.Remove(str.Length - 1, 1); // \t
            str.AppendLine();
        }
        return str.ToString();
    }
