    private int GetPositionInRichTextBox(Letter letter)
    {
        if (letter == null)
            return 0;

        if (m_client != null)
        {
            if (m_client.FoundVerses != null)
            {
                int char_index = 0;
                foreach (Verse verse in m_client.FoundVerses)
                {
                    if (verse != null)
                    {
                        if (letter.Word.Verse.Number == verse.Number)
                        {
                            if (Globals.EDITION == Edition.Standard)
                            {
                                //                                         \t
                                return (char_index + verse.Address.Length - 1 + letter.Word.NumberInVerse + letter.NumberInVerse);
                            }
                            else
                            {
                                //                                              \t                                            \t
                                return (char_index + verse.Chapter.Name.Length + 1 + verse.NumberInChapter.ToString().Length - 1 + letter.Word.NumberInVerse + letter.NumberInVerse);
                            }
                        }
                        char_index += GetVerseDisplayLength(verse);
                    }
                }
            }
        }
        return -1;
    }
    private int GetPositionInRichTextBox(Word word)
    {
        if (word == null)
            return 0;

        if (m_client != null)
        {
            if (m_client.FoundVerses != null)
            {
                int char_index = 0;
                foreach (Verse verse in m_client.FoundVerses)
                {
                    if (verse != null)
                    {
                        if (word.Verse.Number == verse.Number)
                        {
                            if (Globals.EDITION == Edition.Standard)
                            {
                                //                                         \t
                                return (char_index + verse.Address.Length + 1 + word.Position);
                            }
                            else
                            {
                                //                                              \t                                            \t
                                return (char_index + verse.Chapter.Name.Length + 1 + verse.NumberInChapter.ToString().Length + 1 + word.Position);
                            }
                        }
                        char_index += GetVerseDisplayLength(verse);
                    }
                }
            }
        }
        return -1;
    }
    private int GetPositionInRichTextBox(Phrase phrase)
    {
        if (phrase == null)
            return 0;

        if (m_client != null)
        {
            if (m_client.FoundVerses != null)
            {
                int char_index = 0;
                foreach (Verse verse in m_client.FoundVerses)
                {
                    if (verse != null)
                    {
                        if (!String.IsNullOrEmpty(verse.Text))
                        {
                            if (phrase.Verse.Number == verse.Number)
                            {
                                if (!String.IsNullOrEmpty(phrase.Text))
                                {
                                    if (!Constants.QURANMARKS.Contains(phrase.Text[0]))
                                    {
                                        int position = 0;
                                        if (Globals.EDITION == Edition.Standard)
                                        {
                                            //                                            \t
                                            position = char_index + verse.Address.Length + 1 + phrase.Position;
                                        }
                                        else
                                        {
                                            //                                                 \t                                            \t
                                            position = char_index + verse.Chapter.Name.Length + 1 + verse.NumberInChapter.ToString().Length + 1 + phrase.Position;
                                        }

                                        if ((m_with_diacritics) && (Constants.QURANMARKS.Contains(verse.Text[0])))
                                        {
                                            position += 2;
                                        }
                                        return position;
                                    }
                                }
                            }
                            char_index += GetVerseDisplayLength(verse);
                        }
                    }
                }
            }
        }
        return -1;
    }
    private void RealignFoundMatchesToStart()
    {
        try
        {
            for (int i = 0; i < 3; i++)
                SearchResultTextBox.SelectionChanged -= MainTextBox_SelectionChanged;

            if (m_found_verses_displayed)
            {
                if (SearchResultTextBox.Text.Length > 0)
                {
                    CurrentVerseIndex = 0;

                    SearchResultTextBox.AlignToStart();
                    SearchResultTextBox.Refresh();
                }
            }

            //???UpdateZoomFactor();
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            SearchResultTextBox.SelectionChanged += MainTextBox_SelectionChanged;
        }
    }
