    private int m_usertext_readonly_cells = 8;
    private int m_usertext_readwrite_cells = 2;
    private bool[] m_usertext_occupied_cells = null;
    private Control m_usertext_load_control = null;
    private void SetupUserTextCells()
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (m_usertext_occupied_cells == null)
        {
            int size = m_usertext_readonly_cells + m_usertext_readwrite_cells;
            m_usertext_occupied_cells = new bool[size];
            for (int i = 0; i < size; i++)
            {
                m_usertext_occupied_cells[i] = (i < m_usertext_readonly_cells);
            }
        }

        if (m_usertext_occupied_cells != null)
        {
            for (int i = 0; i < m_usertext_occupied_cells.Length; i++)
            {
                string filename = "UserText" + (i + 1) + ".txt";
                if (Directory.Exists(Globals.USERTEXT_FOLDER))
                {
                    string path = Globals.USERTEXT_FOLDER + Path.DirectorySeparatorChar + filename;
                    List<string> lines = FileHelper.LoadLines(path);
                    string load_control_name = "UserText" + (i + 1) + "LoadLabel";
                    Control control = GetControl(load_control_name);
                    if (control != null)
                    {
                        ToolTip.SetToolTip(control, (lines.Count > 0) ? lines[0] : L[l]["Load"]);
                        control.ForeColor = (lines.Count > 0) ? Color.White : Color.Green;
                        control.BackColor = (lines.Count > 0) ? Color.Green : Color.White;
                        m_usertext_occupied_cells[i] = (lines.Count > 0);
                    }

                    string save_control_name = "UserText" + (i + 1) + "SaveLabel";
                    control = GetControl(save_control_name);
                    if (control != null)
                    {
                        if (i < m_usertext_readonly_cells)
                        {
                            ToolTip.SetToolTip(control, null);
                            control.BackColor = Color.DarkGray;
                            control.Cursor = Cursors.Default;
                        }
                        else
                        {
                            ToolTip.SetToolTip(control, L[l]["Save"]);
                            control.BackColor = Color.DarkGreen;
                            control.Cursor = Cursors.Hand;
                        }
                    }
                }
            }
        }
    }

    private bool m_usertext_mode = false;
    private int m_usertext_selection_length = 0;
    private void CalculateUserTextValue()
    {
        int char_index = UserTextTextBox.GetFirstCharIndexOfCurrentLine();
        if (char_index >= 0)
        {
            m_current_text = UserTextTextBox.Text;
            if (UserTextTextBox.SelectionLength > 0)
            {
                // selected text
                m_current_text = UserTextTextBox.SelectedText;
            }
            else
            {
                // get current line text
                if (char_index >= 0)
                {
                    string text = UserTextTextBox.Text;
                    if (!String.IsNullOrEmpty(text))
                    {
                        int text_end = text.Length;
                        int index2 = text.IndexOf('\n', char_index);
                        if (index2 > -1)
                            text_end = index2 - 1; // skip '\r'
                        m_current_text = UserTextTextBox.Text.Substring(char_index, text_end - char_index);
                    }
                }
            }

            m_current_text = m_current_text.Replace("\r", "");
            m_current_text = m_current_text.Replace("\t", "");
            m_current_text = m_current_text.Replace("_", "");
            m_current_text = m_current_text.Replace(Constants.ORNATE_RIGHT_PARENTHESIS, "");
            m_current_text = m_current_text.Replace(Constants.ORNATE_LEFT_PARENTHESIS, "");
            foreach (char character in Constants.INDIAN_DIGITS)
            {
                m_current_text = m_current_text.Replace(character.ToString(), "");
            }
            foreach (char character in Constants.ARABIC_DIGITS)
            {
                m_current_text = m_current_text.Replace(character.ToString(), "");
            }
            foreach (char character in Constants.SYMBOLS)
            {
                m_current_text = m_current_text.Replace(character.ToString(), "");
            }
            foreach (char character in Constants.STOPMARKS)
            {
                m_current_text = m_current_text.Replace(character.ToString(), "");
            }
            foreach (char character in Constants.QURANMARKS)
            {
                m_current_text = m_current_text.Replace(character.ToString(), "");
            }
            m_current_text = m_current_text.Replace("\n ", "\n"); // quran marks
            m_current_text = m_current_text.Replace(" \n", "\n"); // sijood marks
            while (m_current_text.Contains("  "))
            {
                m_current_text = m_current_text.Replace("  ", " ");
            }

            if (m_client.NumerologySystem.LetterOrder != "English")
            {
                foreach (char character in Constants.ENGLISH_LETTERS)
                {
                    m_current_text = m_current_text.Replace(character.ToString(), "");
                }
            }

            m_current_text = m_current_text.Trim();
            DisplayValuesSequence(m_current_text);

            // calculate Letters value
            CalculateValueAndDisplayFactors(m_current_text);

            // calculate and display verse_number_sum, word_number_sum, letter_number_sum
            CalculateAndDisplayCounts(m_current_text);

            BuildLetterFrequencies();
            DisplayLetterFrequencies();

            if (UserTextTextBox.SelectionLength > 0)
            {
                DisplayWordFrequencies();
                this.AcceptButton = null;  // prevent stealing focus by this.AcceptButton = FindByTextButton;
            }
            else
            {
                WordFrequencyListBoxLabel.Visible = false;
                WordFrequencyListBox.Visible = false;
                WordFrequencyWithDiacriticsCheckBox.Visible = false;
            }
        }
    }
