    private void UserTextValueButton_Click(object sender, EventArgs e)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (m_client.LoadedNumerologySystems != null)
                {
                    if (m_client.LoadedNumerologySystems.Count > 0)
                    {
                        StringBuilder str = new StringBuilder();
                        if (str != null)
                        {
                            if (UserTextTextBox.SelectionLength > 0)  // find numerology systems with value of selected text = given value
                            {
                                string selected_text = UserTextTextBox.SelectedText;
                                if (!String.IsNullOrEmpty(selected_text))
                                {
                                    selected_text = selected_text.Replace("\t", " ");
                                    selected_text = selected_text.Replace("\r", ""); // remove totally
                                                                                     //selected_text = selected_text.Replace("\n", " ");

                                    List<long> targets = new List<long>();
                                    long target = (long)UserTextValueNumericUpDown.Value;
                                    if (target > 0L)
                                    {
                                        targets.Add(target);
                                    }
                                    else
                                    {
                                        targets = new List<long>(Numbers.InterestingNumbers);
                                    }

                                    if ((targets != null) && (targets.Count > 0))
                                    {
                                        if (selected_text.Contains("="))
                                        {
                                            string[] parts = selected_text.Split('=');
                                            if (parts.Length >= 2)
                                            {
                                                string text1 = parts[0];
                                                string text2 = parts[1];
                                                text1 = text1.RemovePunctuations();
                                                text2 = text2.RemovePunctuations();

                                                int count = 0;
                                                if (long.TryParse(text2, out target))  // text1 = value1
                                                {
                                                    targets.Clear();
                                                    targets.Add(target);
                                                    if ((targets != null) && (targets.Count > 0))
                                                    {
                                                        foreach (NumerologySystem ns1 in m_client.LoadedNumerologySystems.Values)
                                                        {
                                                            if (ns1.Name.StartsWith("Original"))
                                                                continue;

                                                            long value1 = ns1.CalculateValue(text1);
                                                            if ((target > 0L) && (value1 == target))
                                                            {
                                                                count++;
                                                                str.AppendLine(ns1.Name + "\t" + text1 + "\t" + value1);
                                                            }
                                                        }
                                                    }
                                                }
                                                else   // text1 = text2
                                                {
                                                    foreach (NumerologySystem ns1 in m_client.LoadedNumerologySystems.Values)
                                                    {
                                                        if (ns1.Name.StartsWith("Original"))
                                                            continue;

                                                        bool ns1_written = false;
                                                        bool found = false;
                                                        long value1 = ns1.CalculateValue(text1);
                                                        if (targets.Contains(value1))
                                                        {
                                                            foreach (NumerologySystem ns2 in m_client.LoadedNumerologySystems.Values)
                                                            {
                                                                if (ns2.Name.StartsWith("Original"))
                                                                    continue;

                                                                long value2 = ns2.CalculateValue(text2);
                                                                if (value1 == value2)
                                                                {
                                                                    count++;

                                                                    if (!ns1_written)
                                                                    {
                                                                        str.AppendLine(ns1.Name + "\t" + text1 + "\t" + value1);
                                                                        ns1_written = true;
                                                                    }

                                                                    str.AppendLine(ns2.Name + "\t" + text2 + "\t" + value2);
                                                                    found = true;
                                                                }
                                                            }
                                                        }
                                                        if (found)
                                                        {
                                                            str.AppendLine();
                                                            found = false;
                                                        }
                                                    }
                                                }

                                                if (count > 0)
                                                {
                                                    string filename = text1 + " = " + text2 + "_" + Globals.INTERESTING_NUMBERS_FILENAME;
                                                    if (!String.IsNullOrEmpty(filename))
                                                    {
                                                        string path = Globals.RESEARCH_FOLDER + Path.DirectorySeparatorChar + filename;
                                                        FileHelper.SaveText(path, str.ToString());
                                                        FileHelper.DisplayFile(path); //??? this beeps. Why!!!
                                                    }
                                                }
                                            }
                                            else // selected text contains "=" but less than 2 parts
                                            {
                                                // do nothing
                                            }
                                        }
                                        else // selected text does not contain "="
                                        {
                                            int count = 0;
                                            foreach (long t in targets)
                                            {
                                                int inner_count = 0;
                                                foreach (NumerologySystem ns in m_client.LoadedNumerologySystems.Values)
                                                {
                                                    if (ns.Name.StartsWith("Original"))
                                                        continue;

                                                    long value = ns.CalculateValue(selected_text);
                                                    if (value == t)
                                                    {
                                                        count++;
                                                        inner_count++;
                                                        str.AppendLine(ns.Name + "\t" + selected_text + "\t" + value);
                                                    }
                                                }
                                                if (inner_count > 0)
                                                {
                                                    str.AppendLine();
                                                }
                                            }

                                            if (count > 0)
                                            {
                                                selected_text = selected_text.Replace("\n", " ");

                                                string filename = null;
                                                if (target == 0L)
                                                {
                                                    filename = selected_text + "_" + Globals.INTERESTING_NUMBERS_FILENAME;
                                                }
                                                else
                                                {
                                                    filename = selected_text + "_" + target.ToString() + ".txt";
                                                }

                                                if (!String.IsNullOrEmpty(filename))
                                                {
                                                    string path = Globals.RESEARCH_FOLDER + Path.DirectorySeparatorChar + filename;
                                                    if (path.Length > 64)
                                                    {
                                                        path = path.Substring(0, 64);
                                                    }
                                                    FileHelper.SaveText(path, str.ToString());
                                                    FileHelper.DisplayFile(path); //??? this beeps. Why!!!
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            //////////////////////// THE ORIGINAL METHOD /////////////////////////
                            else // find Quran words with given value in current numerology system
                            {
                                long target = (long)UserTextValueNumericUpDown.Value;

                                if (m_client.NumerologySystem != null)
                                {
                                    SortedDictionary<string, List<Word>> matches = new SortedDictionary<string, List<Word>>();
                                    if (matches != null)
                                    {
                                        List<Word> words = new List<Word>();
                                        if (words != null)
                                        {
                                            List<Verse> verses = GetSearchScopeVerses();
                                            if (verses != null)
                                            {
                                                foreach (Verse verse in verses)
                                                {
                                                    words.AddRange(verse.Words);
                                                }
                                            }
                                        }

                                        foreach (Word word in words)
                                        {
                                            long value = m_client.CalculateValue(word);
                                            if (value == target)
                                            {
                                                string simplified_word_text = word.Text.Simplify(m_client.NumerologySystem.TextMode);
                                                if (matches.ContainsKey(simplified_word_text))
                                                {
                                                    matches[simplified_word_text].Add(word);
                                                }
                                                else
                                                {
                                                    List<Word> list = new List<Word>();
                                                    list.Add(word);
                                                    matches.Add(simplified_word_text, list);
                                                }
                                            }
                                        }

                                        int count = 0;
                                        int word_count = 0;
                                        int letter_count = 0;
                                        foreach (string key in matches.Keys)
                                        {
                                            count++;
                                            word_count += matches[key].Count;
                                            letter_count += key.Length;

                                            StringBuilder addresses = new StringBuilder();
                                            foreach (Word word in matches[key])
                                            {
                                                addresses.Append(word.Address + ",");
                                            }
                                            if (addresses.Length > 0)
                                            {
                                                addresses.Remove(addresses.Length - 1, 1);
                                            }
                                            str.AppendLine(count + "\t" + key + "\t" + matches[key].Count + "\t" + addresses.ToString());
                                        }
                                        str.AppendLine();
                                        str.AppendLine(count + "\t" + letter_count + "\t" + word_count);

                                        ////UserTextTextBox.Text = str.ToString();
                                        ////UserTextTextBox.SelectionStart = UserTextTextBox.TextLength;
                                        ////UserTextTextBox.ScrollToCaret();
                                        if (count > 0)
                                        {
                                            string filename = "Words" + "_" + target + "_" + m_client.NumerologySystem.Name + ".txt";
                                            string path = Globals.RESEARCH_FOLDER + Path.DirectorySeparatorChar + filename;
                                            FileHelper.SaveText(path, str.ToString());
                                            FileHelper.DisplayFile(path); //??? this beeps. Why!!!
                                        }
                                    }
                                }
                            }
                            //////////////////////////////////////////////////////////////////////
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
