                        UserTextTextBox.Refresh();
                        UserTextTextBox.Focus();
                    }

                    m_usertext_load_control = load_control;
                    HighlightActiveControl();
                }
            }
        }
    }
    private void UserTextSaveLabel_Click(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        Control control = (sender as Label);
        if (control != null)
        {
            // prevent overwriting readonly cells
            if (control.Name.StartsWith("UserText"))
            {
                int pos = control.Name.IndexOf("LoadLabel");
                if (pos == -1)
                    pos = control.Name.IndexOf("SaveLabel");
                if (pos != -1)
                {
                    string s = control.Name.Substring("UserText".Length, control.Name.Length - "UserText".Length - "XxxxLabel".Length);
                    int number;
                    if (int.TryParse(s, out number))
                    {
                        if (number <= m_usertext_readonly_cells)  // if cell is readonly
                        {
                            return;
                        }
                    }
                }

                this.Cursor = Cursors.WaitCursor;
                try
                {
                    // show WaitCursor cursor
                    Thread.Sleep(114);

                    // sender could be either Load or Save controls
                    string control_name = control.Name;
                    if (control_name.Contains("Load"))
                    {
                        control_name = control_name.Replace("Load", "Save");
                    }

                    pos = control_name.IndexOf("Save");
                    if (pos > -1)
                    {
                        string filename = control_name.Remove(pos) + ".txt";
                        if (Directory.Exists(Globals.USERTEXT_FOLDER))
                        {
                            string path = Globals.USERTEXT_FOLDER + Path.DirectorySeparatorChar + filename;
                            string text = UserTextTextBox.Text;
                            if ((text == "\r\n") || (text == "\n") || (text == "\r"))
                            {
                                text = "";
                            }

                            FileHelper.SaveText(path, text);
                            UserTextTextBox.Focus();

                            // light up the Load label to show its file has text
                            string load_control_name = control_name.Replace("Save", "Load");
                            Control load_control = GetControl(load_control_name);
                            if (load_control != null)
                            {
                                string[] lines = text.Split('\n');
                                ToolTip.SetToolTip(load_control, (lines.Length > 0) ? lines[0] : L[l]["Load"]);
                                load_control.ForeColor = (text.Length > 0) ? Color.White : Color.Lime;
                                load_control.BackColor = (text.Length > 0) ? Color.Lime : Color.White;

                                m_usertext_load_control = load_control;
                                pos = load_control.Name.IndexOf("Load");
                                if (pos > -1)
                                {
                                    string control_number_text = load_control.Name.Substring("UserText".Length, pos - "UserText".Length);
                                    int control_number = -1;
                                    if (int.TryParse(control_number_text, out control_number))
                                    {
                                        m_usertext_occupied_cells[control_number - 1] = (text.Length > 0);
                                    }
                                }
                            }

                            HighlightActiveControl();
                        }
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
                }
                finally
                {
                    this.Cursor = Cursors.Default;
                }
            }
        }
    }
    private void HighlightActiveControl()
    {
        // highlight clicked control and dim others
        if (m_usertext_occupied_cells != null)
        {
            for (int i = 0; i < m_usertext_occupied_cells.Length; i++)
            {
                string load_control_name = "UserText" + (i + 1) + "LoadLabel";
                Control load_control = GetControl(load_control_name);
                if (load_control != null)
                {
                    if (load_control == m_usertext_load_control)
                    {
                        load_control.ForeColor = m_usertext_occupied_cells[i] ? Color.White : Color.Lime;
                        load_control.BackColor = m_usertext_occupied_cells[i] ? Color.Lime : Color.White;
                    }
                    else
                    {
                        load_control.ForeColor = m_usertext_occupied_cells[i] ? Color.White : Color.Green;
                        load_control.BackColor = m_usertext_occupied_cells[i] ? Color.Green : Color.White;
                    }
                }
            }
        }
    }
