    private void UserRatioNumericUpDown_ValueChanged(object sender, EventArgs e)
    {
        if (UserRatioNumericUpDown.Focused)
        {
            UserRatioPresetLabel.ForeColor = Color.Gray;
        }
        else
        {
            UserRatioPresetLabel.ForeColor = Color.DarkOrange;
        }
        m_user_ratio = (double)UserRatioNumericUpDown.Value;

        ColorizeUserRatios();
    }
    private void UserRatioNumericUpDown_KeyDown(object sender, KeyEventArgs e)
    {
        if (e.KeyCode == Keys.Enter)
        {
            UserRatioNumericUpDown_ValueChanged(null, null);
        }

        if ((e.KeyCode == Keys.Enter) || (e.KeyCode == Keys.Escape))
        {
            e.SuppressKeyPress = true; // stop annoying beep due to parent not having an AcceptButton
        }
    }
    private enum UserRatioPreset { Pi, E, Phi, Heart };
    private UserRatioPreset m_user_ratio_preset = UserRatioPreset.Phi;
    private void UserRatioPresetLabel_Click(object sender, EventArgs e)
    {
        UserRatioPresetLabel.Focus();

        if (UserRatioPresetLabel.ForeColor == Color.DarkOrange)
        {
            if (ModifierKeys == Keys.Shift)
            {
                switch (m_user_ratio_preset)
                {
                    case UserRatioPreset.Pi:
                        {
                            m_user_ratio_preset = UserRatioPreset.Heart;
                            UserRatioPresetLabel.Text = "1/♥";
                            UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.HEART);
                        }
                        break;
                    case UserRatioPreset.E:
                        {
                            m_user_ratio_preset = UserRatioPreset.Pi;
                            UserRatioPresetLabel.Text = "1/π";
                            UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.PI);
                        }
                        break;
                    case UserRatioPreset.Phi:
                        {
                            m_user_ratio_preset = UserRatioPreset.E;
                            UserRatioPresetLabel.Text = "1/e";
                            UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.E);
                        }
                        break;
                    case UserRatioPreset.Heart:
                        {
                            m_user_ratio_preset = UserRatioPreset.Phi;
                            UserRatioPresetLabel.Text = "1/φ";
                            UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.PHI);
                        }
                        break;
                }
            }
            else
            {
                switch (m_user_ratio_preset)
                {
                    case UserRatioPreset.Pi:
                        {
                            m_user_ratio_preset = UserRatioPreset.E;
                            UserRatioPresetLabel.Text = "1/e";
                            UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.E);
                        }
                        break;
                    case UserRatioPreset.E:
                        {
                            m_user_ratio_preset = UserRatioPreset.Phi;
                            UserRatioPresetLabel.Text = "1/φ";
                            UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.PHI);
                        }
                        break;
                    case UserRatioPreset.Phi:
                        {
                            m_user_ratio_preset = UserRatioPreset.Heart;
                            UserRatioPresetLabel.Text = "1/♥";
                            UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.HEART);
                        }
                        break;
                    case UserRatioPreset.Heart:
                        {
                            m_user_ratio_preset = UserRatioPreset.Pi;
                            UserRatioPresetLabel.Text = "1/π";
                            UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.PI);
                        }
                        break;
                }
            }
        }
        else // stay where you are
        {
            switch (m_user_ratio_preset)
            {
                case UserRatioPreset.Pi:
                    {
                        m_user_ratio_preset = UserRatioPreset.Pi;
                        UserRatioPresetLabel.Text = "1/π";
                        UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.PI);
                    }
                    break;
                case UserRatioPreset.E:
                    {
                        m_user_ratio_preset = UserRatioPreset.E;
                        UserRatioPresetLabel.Text = "1/e";
                        UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.E);
                    }
                    break;
                case UserRatioPreset.Phi:
                    {
                        m_user_ratio_preset = UserRatioPreset.Phi;
                        UserRatioPresetLabel.Text = "1/φ";
                        UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.PHI);
                    }
                    break;
                case UserRatioPreset.Heart:
                    {
                        m_user_ratio_preset = UserRatioPreset.Heart;
                        UserRatioPresetLabel.Text = "1/♥";
                        UserRatioNumericUpDown.Value = (decimal)(1.0D / Numbers.HEART);
                    }
                    break;
            }
        }
    }
    private void UpdateUserRatioPreset()
    {
        switch (m_user_ratio_preset)
        {
            case UserRatioPreset.Pi:
                {
                    m_user_ratio_preset = UserRatioPreset.Pi;
                    UserRatioPresetLabel.Text = "1/π";
                    if (UserRatioNumericUpDown.Value == (decimal)(1.0D / Numbers.PI))
                    {
                        UserRatioPresetLabel.ForeColor = Color.DarkOrange;
                    }
                    else
                    {
                        UserRatioPresetLabel.ForeColor = Color.Gray;
                    }
                }
                break;
            case UserRatioPreset.E:
                {
                    m_user_ratio_preset = UserRatioPreset.E;
                    UserRatioPresetLabel.Text = "1/e";
                    if (UserRatioNumericUpDown.Value == (decimal)(1.0D / Numbers.E))
                    {
                        UserRatioPresetLabel.ForeColor = Color.DarkOrange;
                    }
                    else
                    {
                        UserRatioPresetLabel.ForeColor = Color.Gray;
                    }
                }
                break;
            case UserRatioPreset.Phi:
                {
                    m_user_ratio_preset = UserRatioPreset.Phi;
                    UserRatioPresetLabel.Text = "1/φ";
                    if (UserRatioNumericUpDown.Value == (decimal)(1.0D / Numbers.PHI))
                    {
                        UserRatioPresetLabel.ForeColor = Color.DarkOrange;
                    }
                    else
                    {
                        UserRatioPresetLabel.ForeColor = Color.Gray;
                    }
                }
                break;
            case UserRatioPreset.Heart:
                {
                    m_user_ratio_preset = UserRatioPreset.Heart;
                    UserRatioPresetLabel.Text = "1/♥";
                    if (UserRatioNumericUpDown.Value == (decimal)(1.0D / Numbers.HEART))
                    {
                        UserRatioPresetLabel.ForeColor = Color.DarkOrange;
                    }
                    else
                    {
                        UserRatioPresetLabel.ForeColor = Color.Gray;
                    }
                }
                break;
        }
    }
