    private void UserRatioDelimiterLabel_Click(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (ModifierKeys == Keys.Shift)
            {
                switch (m_user_ratio_delimiter)
                {
                    case UserRatioDelimiter.None:
                        {
                            if (m_user_ratio_scope == UserRatioScope.Book)
                            {
                                m_user_ratio_delimiter = UserRatioDelimiter.Chapter;
