    private void ColorizeUserRatios()
    {
        // common to all user_ratio colorization methods
        if (m_user_ratio_delimiter == UserRatioDelimiter.None)
        {
            UncolorizeUserRatios();
            CalculateCurrentValue(); // must re-calculate to replace colorized stats
            return;
        }

        this.Cursor = Cursors.WaitCursor;
        try
        {
            for (int i = 0; i < 3; i++)
                m_active_textbox.TextChanged -= new System.EventHandler(MainTextBox_TextChanged);
            for (int i = 0; i < 3; i++)
                m_active_textbox.SelectionChanged -= new System.EventHandler(MainTextBox_SelectionChanged);
            m_active_textbox.BeginUpdate();

            // uncolorize all
            m_active_textbox.Colorize(MAINTEXTBOX_FORECOLOR);

            if (m_client != null)
            {
                if (m_client.NumerologySystem != null)
                {
                    switch (m_user_ratio_scope)
                    {
                        case UserRatioScope.Verse:
                            {
                                ColorizeVerseUserRatiosText();
                            }
                            break;
                        case UserRatioScope.Chapter:
                            {
                                ColorizeChapterUserRatiosText();
                            }
                            break;
                        case UserRatioScope.Page:
                            {
                                ColorizePageUserRatiosText();
                            }
                            break;
                        case UserRatioScope.Station:
                            {
                                ColorizeStationUserRatiosText();
                            }
                            break;
                        case UserRatioScope.Part:
                            {
                                ColorizePartUserRatiosText();
                            }
                            break;
                        case UserRatioScope.Group:
                            {
                                ColorizeGroupUserRatiosText();
                            }
                            break;
                        case UserRatioScope.Half:
                            {
                                ColorizeHalfUserRatiosText();
                            }
                            break;
                        case UserRatioScope.Quarter:
                            {
                                ColorizeQuarterUserRatiosText();
                            }
                            break;
                        case UserRatioScope.Bowing:
                            {
                                ColorizeBowingUserRatiosText();
                            }
                            break;
                        case UserRatioScope.Book:
                            {
                                ColorizeBookUserRatiosText();
                            }
                            break;
                        default:
                            {
                                // do nothing
                            }
                            break;
                    }
                }
            }

            m_active_textbox.AlignToStart();
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            m_active_textbox.EndUpdate();
            m_active_textbox.SelectionChanged += new System.EventHandler(MainTextBox_SelectionChanged);
            m_active_textbox.TextChanged += new System.EventHandler(MainTextBox_TextChanged);
            this.Cursor = Cursors.Default;
        }
    }
    private void UncolorizeUserRatios()
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            for (int i = 0; i < 3; i++)
                m_active_textbox.TextChanged -= new System.EventHandler(MainTextBox_TextChanged);
            for (int i = 0; i < 3; i++)
                m_active_textbox.SelectionChanged -= new System.EventHandler(MainTextBox_SelectionChanged);
            m_active_textbox.BeginUpdate();

            m_active_textbox.Colorize(MAINTEXTBOX_FORECOLOR);

            m_active_textbox.AlignToStart();
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            m_active_textbox.EndUpdate();
            m_active_textbox.SelectionChanged += new System.EventHandler(MainTextBox_SelectionChanged);
            m_active_textbox.TextChanged += new System.EventHandler(MainTextBox_TextChanged);
            this.Cursor = Cursors.Default;
        }
    }
    private void ColorizeVerseUserRatiosText()
    {
        if (m_client != null)
        {
            List<Verse> verses = GetDisplayedVerses();
            if (verses != null)
            {
                int total_chapter_count = 0;
                int total_verse_count = 0;
                int total_word_count = 0;
                int total_letter_count = 0;
                int total_chapter_number_sum = 0;
                int total_verse_number_sum = 0;
                int total_word_number_sum = 0;
                int total_letter_number_sum = 0;
                long total_value = 0L;
                bool display_statistics = false;

                Chapter current_chapter = null;
                int start = 0;
                int length = 0;
                foreach (Verse verse in verses)
                {
                    start = GetVerseDisplayStart(verse);
                    // skip over address of verse
                    if (m_found_verses_displayed)
                    {
                        if (Globals.EDITION == Edition.Standard)
                        {
                            //                             \t
                            start += verse.Address.Length + 1;
                        }
                        else if (Globals.EDITION == Edition.Research)
                        {
                            start += verse.Chapter.Name.Length + 1 + verse.NumberInChapter.ToString().Length + 1;
                        }
                        else
                        {
                            start += verse.Chapter.Name.Length + 1 + verse.NumberInChapter.ToArabic().Length + 1;
                        }
                    }
                    else
                    {
                        start += 0;
                    }

                    length = verse.Text.Length;

                    int verse_count = 0;
                    int word_count = 0;
                    int letter_count = 0;
                    int verse_number_sum = 0;
                    int word_number_sum = 0;
                    int letter_number_sum = 0;
                    long value = 0L;

                    if (verse != null)
                    {
                        verse_count++;
                        verse_number_sum += verse.NumberInChapter;


                        string text = verse.Text;

                        int colorize_letters = 0;
                        switch (m_user_ratio_type)
                        {
                            case UserRatioType.Text:
                                {
                                    switch (m_user_ratio_length)
                                    {
                                        case UserRatioLength.Short:
                                            {
                                                colorize_letters = (int)Math.Round((double)verse.Letters.Count * m_user_ratio);
                                            }
                                            break;
                                        case UserRatioLength.Long:
                                            {
                                                colorize_letters = (int)Math.Round((double)verse.Letters.Count * (1.0D - m_user_ratio));
                                            }
                                            break;
                                    }

                                    bool done = false;
                                    int current_letter_count = 0;
                                    foreach (Word word in verse.Words)
                                    {
                                        if (word != null)
                                        {
                                            word_count++;
                                            word_number_sum += word.NumberInVerse;

                                            foreach (Letter letter in word.Letters)
                                            {
                                                if (letter != null)
                                                {
                                                    letter_count++;
                                                    letter_number_sum += letter.NumberInWord;

                                                    value += m_client.CalculateValue(letter);

                                                    current_letter_count++;
                                                    if (colorize_letters == current_letter_count)
                                                    {
                                                        done = true;
                                                        break;
                                                    }
                                                }
                                            }
                                            if (done)
                                            {
                                                break;
                                            }
                                        }
                                    }
                                }
                                break;
                            case UserRatioType.Value:
                                {
                                    long verse_value = m_client.CalculateValue(verse);

                                    long colorize_value = 0L;
                                    switch (m_user_ratio_length)
                                    {
                                        case UserRatioLength.Short:
                                            {
                                                colorize_value = (long)Math.Round((double)verse_value * m_user_ratio);
                                            }
                                            break;
                                        case UserRatioLength.Long:
                                            {
                                                colorize_value = (long)Math.Round((double)verse_value * (1.0D - m_user_ratio));
                                            }
                                            break;
                                    }

                                    bool done = false;
                                    long value_sum = 0L;
                                    bool first_word = true;
                                    foreach (Word word in verse.Words)
                                    {
                                        if (word != null)
                                        {
                                            word_count++;
                                            word_number_sum += word.NumberInVerse;

                                            bool first_letter = true;
                                            foreach (Letter letter in word.Letters)
                                            {
                                                if (letter != null)
                                                {
                                                    value_sum += m_client.CalculateValue(letter);
                                                    if (value_sum < colorize_value)
                                                    {
                                                        letter_count++;
                                                        letter_number_sum += letter.NumberInWord;
                                                        value += m_client.CalculateValue(letter);
                                                        colorize_letters++;
                                                    }
                                                    else if (value_sum == colorize_value)
                                                    {
                                                        letter_count++;
                                                        letter_number_sum += letter.NumberInWord;
                                                        value += m_client.CalculateValue(letter);
                                                        colorize_letters++;

                                                        done = true;
                                                        break;
                                                    }
                                                    else if (value_sum > colorize_value)
                                                    {
                                                        if (first_word)
                                                        {
                                                            verse_count--;
                                                            verse_number_sum -= verse.NumberInChapter;
                                                        }
                                                        if (first_letter)
                                                        {
                                                            word_count--;
                                                            word_number_sum -= word.NumberInVerse;
                                                        }
                                                        done = true;
                                                        break;
                                                    }

                                                    first_letter = false;
                                                }
                                            }
                                            if (done)
                                            {
                                                break;
                                            }

                                            first_word = false;
                                        }
                                    }
                                }
                                break;
                        }

                        //double current_ratio = (double)colorize_letters / (double)length;
                        //if (Math.Abs(m_user_ratio - current_ratio) < Numbers.ERROR_MARGIN)
                        {
                            bool colorize = false;
                            int arabic_letter_count = 0;
                            int diacritics_count = 0;
                            for (int i = 0; i < text.Length; i++)
                            {
                                if (Constants.ARABIC_LETTERS.Contains(text[i]))
                                {
                                    arabic_letter_count++;
                                    if (arabic_letter_count == colorize_letters) // boundary found, check if it meets deleimiter type
                                    {
                                        switch (m_user_ratio_delimiter)
                                        {
                                            case UserRatioDelimiter.None:
                                                {
                                                    total_chapter_count = 0;
                                                    total_verse_count = 0;
                                                    total_word_count = 0;
                                                    total_letter_count = 0;
                                                    total_chapter_number_sum = 0;
                                                    total_verse_number_sum = 0;
                                                    total_word_number_sum = 0;
                                                    total_letter_number_sum = 0;
                                                    total_value = 0L;

                                                    colorize = false;
                                                }
                                                break;
                                            case UserRatioDelimiter.Letter:
                                                {
                                                    if (current_chapter != verse.Chapter)
                                                    {
                                                        current_chapter = verse.Chapter;
                                                        total_chapter_count++;
                                                        total_chapter_number_sum += verse.Chapter.SortedNumber;
                                                    }
                                                    total_verse_count += verse_count;
                                                    total_word_count += word_count;
                                                    total_letter_count += letter_count;
                                                    total_verse_number_sum += verse_number_sum;
                                                    total_word_number_sum += word_number_sum;
                                                    total_letter_number_sum += letter_number_sum;
                                                    total_value += value;

                                                    colorize = true;
                                                }
                                                break;
                                            case UserRatioDelimiter.Word:
                                                {
                                                    if (i + 1 < text.Length)
                                                    {
                                                        while (Constants.DIACRITICS.Contains(text[i + 1]))
                                                        {
                                                            diacritics_count++;
                                                            i++; // skip harakaat
                                                        }
                                                        if ((text[i + 1] == ' ') || (text[i + 1] == '\n')) // end of word
                                                        {
                                                            if (current_chapter != verse.Chapter)
                                                            {
                                                                current_chapter = verse.Chapter;
                                                                total_chapter_count++;
                                                                total_chapter_number_sum += verse.Chapter.SortedNumber;
                                                            }
                                                            total_verse_count += verse_count;
                                                            total_word_count += word_count;
                                                            total_letter_count += letter_count;
                                                            total_verse_number_sum += verse_number_sum;
                                                            total_word_number_sum += word_number_sum;
                                                            total_letter_number_sum += letter_number_sum;
                                                            total_value += value;

                                                            colorize = true;
                                                        }
                                                    }
                                                }
                                                break;
                                            case UserRatioDelimiter.Sentence:
                                                {
                                                    if (i + 2 < text.Length)
                                                    {
                                                        while (Constants.DIACRITICS.Contains(text[i + 1]))
                                                        {
                                                            diacritics_count++;
                                                            i++; // skip harakaat
                                                        }
                                                        if (((text[i + 1] == ' ') && Constants.STOPMARKS.Contains(text[i + 2])) || (text[i + 1] == '\n')) // end of sentence
                                                        {
                                                            if ((text[i + 1] == ' ') && Constants.STOPMARKS.Contains(text[i + 2]))
                                                            {
                                                                diacritics_count += 2;
                                                            }

                                                            if (current_chapter != verse.Chapter)
                                                            {
                                                                current_chapter = verse.Chapter;
                                                                total_chapter_count++;
                                                                total_chapter_number_sum += verse.Chapter.SortedNumber;
                                                            }
                                                            total_verse_count += verse_count;
                                                            total_word_count += word_count;
                                                            total_letter_count += letter_count;
                                                            total_verse_number_sum += verse_number_sum;
                                                            total_word_number_sum += word_number_sum;
                                                            total_letter_number_sum += letter_number_sum;
                                                            total_value += value;

                                                            colorize = true;
                                                        }
                                                    }
                                                }
                                                break;
                                            case UserRatioDelimiter.Verse:
                                                {
                                                    // N/A
                                                }
                                                break;
                                            case UserRatioDelimiter.Chapter:
                                                {
                                                    // N/A
                                                }
                                                break;
                                            default:
                                                {
                                                    total_chapter_count = 0;
                                                    total_verse_count = 0;
                                                    total_word_count = 0;
                                                    total_letter_count = 0;
                                                    total_chapter_number_sum = 0;
                                                    total_verse_number_sum = 0;
                                                    total_word_number_sum = 0;
                                                    total_letter_number_sum = 0;
                                                    total_value = 0L;

                                                    colorize = false;
                                                }
                                                break;
                                        }

                                        break; // delimiter found
                                    }
                                }
                                else // non-arabic letter
                                {
                                    diacritics_count++;
                                }
                            }

                            if (colorize)
                            {
                                int user_length = colorize_letters + diacritics_count;
                                if (user_length > 0)
                                {
                                    m_active_textbox.Colorize(start, user_length, GOLDEN_RATIO_COLOR_1);
                                    m_active_textbox.Colorize(start + user_length, text.Length - user_length, GOLDEN_RATIO_COLOR_2);

                                    display_statistics = true;
                                }
                                else
                                {
                                    // uncolorize current verse
                                    m_active_textbox.Colorize(start, length, MAINTEXTBOX_FORECOLOR);
                                }
                            }
                            else
                            {
                                // uncolorize current verse
                                m_active_textbox.Colorize(start, length, MAINTEXTBOX_FORECOLOR);
                            }
                        }
                    }

                    // skip displayed this verse
                    if (m_found_verses_displayed)
                    {
                        if (Globals.EDITION == Edition.Standard)
                        {
                            //                          \n
                            start += verse.Text.Length + 1;
                        }
                        else if (Globals.EDITION == Edition.Research)
                        {
                            start += verse.Text.Length + 1;
                        }
                        else
                        {
                            start += verse.Text.Length + 1;
                        }
                    }
                    else
                    {
                        start += 0;
                    }

                } // foreach verse

                if (display_statistics)
                {
                    DisplayCounts(total_chapter_count, total_verse_count, total_word_count, total_letter_count, total_chapter_number_sum, total_verse_number_sum, total_word_number_sum, total_letter_number_sum);
                    FactorizeValue(total_value, UserRatioPresetLabel.Text);
                }
                else
                {
                    DisplayCounts(0, 0, 0, 0, 0, 0, 0, 0);
                    FactorizeValue(0L, UserRatioPresetLabel.Text);
                }
            }
        }
    }
    private void ColorizeChapterUserRatiosText()
    {
        if (m_client != null)
        {
            if (m_client.Selection != null)
            {
                int total_chapter_count = 0;
                int total_verse_count = 0;
                int total_word_count = 0;
                int total_letter_count = 0;
                int total_chapter_number_sum = 0;
                int total_verse_number_sum = 0;
                int total_word_number_sum = 0;
                int total_letter_number_sum = 0;
                long total_value = 0L;
                bool display_statistics = false;

                foreach (Chapter chapter in m_client.Selection.Chapters)
                {
                    int chapter_count = 0;
                    int verse_count = 0;
                    int word_count = 0;
                    int letter_count = 0;
                    int chapter_number_sum = 0;
                    int verse_number_sum = 0;
                    int word_number_sum = 0;
                    int letter_number_sum = 0;
                    long value = 0L;

                    if (chapter != null)
                    {
                        chapter_count++;
                        chapter_number_sum += chapter.SortedNumber;

                        int start = GetVerseDisplayStart(chapter.Verses[0]);
                        int length = 0;
                        string text = null;
                        foreach (Verse verse in chapter.Verses)
                        {
                            length += GetVerseDisplayLength(verse);
                            text += verse.Text + verse.Endmark;
                        }

                        int colorize_letters = 0;
                        long value_sum = 0L;
                        switch (m_user_ratio_type)
                        {
                            case UserRatioType.Text:
                                {
                                    switch (m_user_ratio_length)
                                    {
                                        case UserRatioLength.Short:
                                            {
                                                colorize_letters = (int)Math.Round((double)chapter.Letters.Count * m_user_ratio);
                                            }
                                            break;
                                        case UserRatioLength.Long:
                                            {
                                                colorize_letters = (int)Math.Round((double)chapter.Letters.Count * (1.0D - m_user_ratio));
                                            }
                                            break;
                                    }

                                    bool done = false;
                                    int current_letter_count = 0;
                                    foreach (Verse verse in chapter.Verses)
                                    {
                                        if (verse != null)
                                        {
                                            verse_count++;
                                            verse_number_sum += verse.NumberInChapter;

                                            foreach (Word word in verse.Words)
                                            {
                                                if (word != null)
                                                {
                                                    word_count++;
                                                    word_number_sum += word.NumberInVerse;

                                                    foreach (Letter letter in word.Letters)
                                                    {
                                                        if (letter != null)
                                                        {
                                                            letter_count++;
                                                            letter_number_sum += letter.NumberInWord;

                                                            value += m_client.CalculateValue(letter);

                                                            current_letter_count++;
                                                            if (colorize_letters == current_letter_count)
                                                            {
                                                                done = true;
                                                                break;
                                                            }
                                                        }
                                                    }
                                                    if (done)
                                                    {
                                                        break;
                                                    }
                                                }
                                            }
                                            if (done)
                                            {
                                                break;
                                            }
                                        }
                                    }
                                }
                                break;
                            case UserRatioType.Value:
                                {
                                    long chapter_value = m_client.CalculateValue(chapter.Verses);
                                    long colorize_value = 0L;
                                    switch (m_user_ratio_length)
                                    {
                                        case UserRatioLength.Short:
                                            {
                                                colorize_value = (long)Math.Round((double)chapter_value * m_user_ratio);
                                            }
                                            break;
                                        case UserRatioLength.Long:
                                            {
                                                colorize_value = (long)Math.Round((double)chapter_value * (1.0D - m_user_ratio));
                                            }
                                            break;
                                    }

                                    bool done = false;
                                    value_sum = 0L;
                                    foreach (Verse verse in chapter.Verses)
                                    {
                                        if (verse != null)
                                        {
                                            verse_count++;
                                            verse_number_sum += verse.NumberInChapter;

                                            bool first_word = true;
                                            foreach (Word word in verse.Words)
                                            {
                                                if (word != null)
                                                {
                                                    word_count++;
                                                    word_number_sum += word.NumberInVerse;

                                                    bool first_letter = true;
                                                    foreach (Letter letter in word.Letters)
                                                    {
                                                        if (letter != null)
                                                        {
                                                            value_sum += m_client.CalculateValue(letter);
                                                            if (value_sum < colorize_value)
                                                            {
                                                                letter_count++;
                                                                letter_number_sum += letter.NumberInWord;
                                                                value += m_client.CalculateValue(letter);
                                                                colorize_letters++;
                                                            }
                                                            else if (value_sum == colorize_value)
                                                            {
                                                                letter_count++;
                                                                letter_number_sum += letter.NumberInWord;
                                                                value += m_client.CalculateValue(letter);
                                                                colorize_letters++;

                                                                done = true;
                                                                break;
                                                            }
                                                            else if (value_sum > colorize_value)
                                                            {
                                                                if (first_word)
                                                                {
                                                                    verse_count--;
                                                                    verse_number_sum -= verse.NumberInChapter;
                                                                }
                                                                if (first_letter)
                                                                {
                                                                    word_count--;
                                                                    word_number_sum -= word.NumberInVerse;
                                                                }
                                                                done = true;
                                                                break;
                                                            }

                                                            first_letter = false;
                                                        }
                                                    }
                                                    if (done)
                                                    {
                                                        break;
                                                    }

                                                    first_word = false;
                                                }
                                            }
                                            if (done)
                                            {
                                                break;
                                            }
                                        }
                                    }
                                }
                                break;
                        }

                        //double current_ratio = (double)colorize_letters / (double)length;
                        //if (Math.Abs(m_user_ratio - current_ratio) < Numbers.ERROR_MARGIN)
                        {
                            bool colorize = false;
                            int arabic_letter_count = 0;
                            int diacritics_count = 0;
                            for (int i = 0; i < text.Length; i++)
                            {
                                if (Constants.ARABIC_LETTERS.Contains(text[i]))
                                {
                                    arabic_letter_count++;
                                    if (arabic_letter_count == colorize_letters) // boundary found, check if it meets deleimiter type
                                    {
                                        switch (m_user_ratio_delimiter)
                                        {
                                            case UserRatioDelimiter.None:
                                                {
                                                    total_chapter_count = 0;
                                                    total_verse_count = 0;
                                                    total_word_count = 0;
                                                    total_letter_count = 0;
                                                    total_chapter_number_sum = 0;
                                                    total_verse_number_sum = 0;
                                                    total_word_number_sum = 0;
                                                    total_letter_number_sum = 0;
                                                    total_value = 0L;

                                                    colorize = false;
                                                }
                                                break;
                                            case UserRatioDelimiter.Letter:
                                                {
                                                    total_chapter_count += chapter_count;
                                                    total_verse_count += verse_count;
                                                    total_word_count += word_count;
                                                    total_letter_count += letter_count;
                                                    total_chapter_number_sum += chapter_number_sum;
                                                    total_verse_number_sum += verse_number_sum;
                                                    total_word_number_sum += word_number_sum;
                                                    total_letter_number_sum += letter_number_sum;
                                                    total_value += value;

                                                    colorize = true;
                                                }
                                                break;
                                            case UserRatioDelimiter.Word:
                                                {
                                                    if (i + 1 < text.Length)
                                                    {
                                                        while (Constants.DIACRITICS.Contains(text[i + 1]))
                                                        {
                                                            diacritics_count++;
                                                            i++; // skip harakaat
                                                        }
                                                        if ((text[i + 1] == ' ') || (text[i + 1] == '\n')) // end of word
                                                        {
                                                            total_chapter_count += chapter_count;
                                                            total_verse_count += verse_count;
                                                            total_word_count += word_count;
                                                            total_letter_count += letter_count;
                                                            total_chapter_number_sum += chapter_number_sum;
                                                            total_verse_number_sum += verse_number_sum;
                                                            total_word_number_sum += word_number_sum;
                                                            total_letter_number_sum += letter_number_sum;
                                                            total_value += value;

                                                            colorize = true;
                                                        }
                                                    }
                                                }
                                                break;
                                            case UserRatioDelimiter.Sentence:
                                                {
                                                    if (i + 2 < text.Length)
                                                    {
                                                        while (Constants.DIACRITICS.Contains(text[i + 1]))
                                                        {
                                                            diacritics_count++;
                                                            i++; // skip harakaat
                                                        }
                                                        if (((text[i + 1] == ' ') && Constants.STOPMARKS.Contains(text[i + 2])) || (text[i + 1] == '\n')) // end of sentence
                                                        {
                                                            if ((text[i + 1] == ' ') && Constants.STOPMARKS.Contains(text[i + 2]))
                                                            {
                                                                diacritics_count += 2;
                                                            }

                                                            total_chapter_count += chapter_count;
                                                            total_verse_count += verse_count;
                                                            total_word_count += word_count;
                                                            total_letter_count += letter_count;
                                                            total_chapter_number_sum += chapter_number_sum;
                                                            total_verse_number_sum += verse_number_sum;
                                                            total_word_number_sum += word_number_sum;
                                                            total_letter_number_sum += letter_number_sum;
                                                            total_value += value;

                                                            colorize = true;
                                                        }
                                                    }
                                                }
                                                break;
                                            case UserRatioDelimiter.Verse:
                                                {
                                                    int verses_letter_count = 0;
                                                    foreach (Verse verse in chapter.Verses)
                                                    {
                                                        verses_letter_count += verse.Letters.Count;
                                                        if (verses_letter_count == colorize_letters)
                                                        {
                                                            total_chapter_count += chapter_count;
                                                            total_verse_count += verse_count;
                                                            total_word_count += word_count;
                                                            total_letter_count += letter_count;
                                                            total_chapter_number_sum += chapter_number_sum;
                                                            total_verse_number_sum += verse_number_sum;
                                                            total_word_number_sum += word_number_sum;
                                                            total_letter_number_sum += letter_number_sum;
                                                            total_value += value;

                                                            colorize = true;
                                                            break;
                                                        }
                                                    }
                                                }
                                                break;
                                            case UserRatioDelimiter.Chapter:
                                                {
                                                    // N/A
                                                }
                                                break;
                                            default:
                                                {
                                                    total_chapter_count = 0;
                                                    total_verse_count = 0;
                                                    total_word_count = 0;
                                                    total_letter_count = 0;
                                                    total_chapter_number_sum = 0;
                                                    total_verse_number_sum = 0;
                                                    total_word_number_sum = 0;
                                                    total_letter_number_sum = 0;
                                                    total_value = 0L;

                                                    colorize = false;
                                                }
                                                break;
                                        }

                                        break; // delimiter found
                                    }
                                }
                                else // non-arabic letter
                                {
                                    diacritics_count++;
                                }
                            }

                            if (colorize)
                            {
                                int user_length = colorize_letters + diacritics_count;
                                if (user_length > 0)
                                {
                                    m_active_textbox.Colorize(start, user_length, GOLDEN_RATIO_COLOR_1);
                                    m_active_textbox.Colorize(start + user_length, text.Length - user_length, GOLDEN_RATIO_COLOR_2);

                                    display_statistics = true;
                                }
                                else
                                {
                                    // uncolorize current chapter
                                    m_active_textbox.Colorize(start, length, MAINTEXTBOX_FORECOLOR);
                                }
                            }
                            else
                            {
                                // uncolorize current chapter
                                m_active_textbox.Colorize(start, length, MAINTEXTBOX_FORECOLOR);
                            }
                        }
                    }
                } // foreach chapter

                if (display_statistics)
                {
                    DisplayCounts(total_chapter_count, total_verse_count, total_word_count, total_letter_count, total_chapter_number_sum, total_verse_number_sum, total_word_number_sum, total_letter_number_sum);
                    FactorizeValue(total_value, UserRatioPresetLabel.Text);
                }
                else
                {
                    DisplayCounts(0, 0, 0, 0, 0, 0, 0, 0);
                    FactorizeValue(0L, UserRatioPresetLabel.Text);
                }
            }
        }
    }
