                                                            total_verse_number_sum += verse_number_sum;
                                                            total_word_number_sum += word_number_sum;
                                                            total_letter_number_sum += letter_number_sum;
                                                            total_value += value;

                                                            colorize = true;
                                                            break;
                                                        }
                                                    }
                                                }
                                                break;
                                            case UserRatioDelimiter.Chapter:
                                                {
                                                    // N/A
                                                }
                                                break;
                                            default:
                                                {
                                                    total_chapter_count = 0;
                                                    total_verse_count = 0;
                                                    total_word_count = 0;
                                                    total_letter_count = 0;
                                                    total_chapter_number_sum = 0;
                                                    total_verse_number_sum = 0;
                                                    total_word_number_sum = 0;
                                                    total_letter_number_sum = 0;
                                                    total_value = 0L;

                                                    colorize = false;
                                                }
                                                break;
                                        }

                                        break; // delimiter found
                                    }
                                }
                                else // non-arabic letter
                                {
                                    diacritics_count++;
                                }
                            }

                            if (colorize)
                            {
                                int user_length = colorize_letters + diacritics_count;
                                if (user_length > 0)
                                {
                                    m_active_textbox.Colorize(start, user_length, GOLDEN_RATIO_COLOR_1);
                                    m_active_textbox.Colorize(start + user_length, text.Length - user_length, GOLDEN_RATIO_COLOR_2);

                                    display_statistics = true;
                                }
                                else
                                {
                                    // uncolorize current chapter
                                    m_active_textbox.Colorize(start, length, MAINTEXTBOX_FORECOLOR);
                                }
                            }
                            else
                            {
                                // uncolorize current chapter
                                m_active_textbox.Colorize(start, length, MAINTEXTBOX_FORECOLOR);
                            }
                        }
                    }
                } // foreach half

                if (display_statistics)
                {
                    DisplayCounts(total_chapter_count, total_verse_count, total_word_count, total_letter_count, total_chapter_number_sum, total_verse_number_sum, total_word_number_sum, total_letter_number_sum);
                    FactorizeValue(total_value, UserRatioPresetLabel.Text);
                }
                else
                {
                    DisplayCounts(0, 0, 0, 0, 0, 0, 0, 0);
                    FactorizeValue(0L, UserRatioPresetLabel.Text);
                }
            }
        }
    }
    private void ColorizeQuarterUserRatiosText()
    {
        if (m_client != null)
        {
            if (m_client.Selection != null)
            {
                int total_chapter_count = 0;
                int total_verse_count = 0;
                int total_word_count = 0;
                int total_letter_count = 0;
                int total_chapter_number_sum = 0;
                int total_verse_number_sum = 0;
                int total_word_number_sum = 0;
                int total_letter_number_sum = 0;
                long total_value = 0L;
                bool display_statistics = false;

                foreach (Quarter quarter in m_client.Selection.Quarters)
                {
                    int chapter_count = 0;
                    int verse_count = 0;
                    int word_count = 0;
                    int letter_count = 0;
                    int chapter_number_sum = 0;
                    int verse_number_sum = 0;
                    int word_number_sum = 0;
                    int letter_number_sum = 0;
                    long value = 0L;

                    if (quarter != null)
                    {
                        int start = GetVerseDisplayStart(quarter.Verses[0]);
                        int length = 0;
                        string text = null;
                        foreach (Verse verse in quarter.Verses)
                        {
                            length += GetVerseDisplayLength(verse);
                            text += verse.Text + verse.Endmark;
                        }

                        int colorize_letters = 0;
                        long value_sum = 0L;
                        switch (m_user_ratio_type)
                        {
                            case UserRatioType.Text:
                                {
                                    switch (m_user_ratio_length)
                                    {
                                        case UserRatioLength.Short:
                                            {
                                                colorize_letters = (int)Math.Round((double)quarter.Letters.Count * m_user_ratio);
                                            }
                                            break;
                                        case UserRatioLength.Long:
                                            {
                                                colorize_letters = (int)Math.Round((double)quarter.Letters.Count * (1.0D - m_user_ratio));
                                            }
                                            break;
                                    }

                                    bool done = false;
                                    int current_letter_count = 0;
                                    Chapter current_chapter = null;
                                    foreach (Verse verse in quarter.Verses)
                                    {
                                        if (verse != null)
                                        {
                                            if (current_chapter != verse.Chapter)
                                            {
                                                current_chapter = verse.Chapter;
                                                chapter_count++;
                                                chapter_number_sum += verse.Chapter.SortedNumber;
                                            }

                                            verse_count++;
                                            verse_number_sum += verse.NumberInChapter;

                                            foreach (Word word in verse.Words)
                                            {
                                                if (word != null)
                                                {
                                                    word_count++;
                                                    word_number_sum += word.NumberInVerse;

                                                    foreach (Letter letter in word.Letters)
                                                    {
                                                        if (letter != null)
                                                        {
                                                            letter_count++;
                                                            letter_number_sum += letter.NumberInWord;

                                                            value += m_client.CalculateValue(letter);

                                                            current_letter_count++;
                                                            if (colorize_letters == current_letter_count)
                                                            {
                                                                done = true;
                                                                break;
                                                            }
                                                        }
                                                    }
                                                    if (done)
                                                    {
                                                        break;
                                                    }
                                                }
                                            }
                                            if (done)
                                            {
                                                break;
                                            }
                                        }
                                    }
                                }
                                break;
                            case UserRatioType.Value:
                                {
                                    long quarter_value = m_client.CalculateValue(quarter.Verses);
                                    long colorize_value = 0L;
                                    switch (m_user_ratio_length)
                                    {
                                        case UserRatioLength.Short:
                                            {
                                                colorize_value = (long)Math.Round((double)quarter_value * m_user_ratio);
                                            }
                                            break;
                                        case UserRatioLength.Long:
                                            {
                                                colorize_value = (long)Math.Round((double)quarter_value * (1.0D - m_user_ratio));
                                            }
                                            break;
                                    }

                                    bool done = false;
                                    value_sum = 0L;
                                    bool first_verse = true;
                                    Chapter current_chapter = null;
                                    foreach (Verse verse in quarter.Verses)
                                    {
                                        if (verse != null)
                                        {
                                            if (current_chapter != verse.Chapter)
                                            {
                                                current_chapter = verse.Chapter;
                                                chapter_count++;
                                                chapter_number_sum += verse.Chapter.SortedNumber;
                                            }
                                            verse_count++;
                                            verse_number_sum += verse.NumberInChapter;

                                            bool first_word = true;
                                            foreach (Word word in verse.Words)
                                            {
                                                if (word != null)
                                                {
                                                    word_count++;
                                                    word_number_sum += word.NumberInVerse;

                                                    bool first_letter = true;
                                                    foreach (Letter letter in word.Letters)
                                                    {
                                                        if (letter != null)
                                                        {
                                                            value_sum += m_client.CalculateValue(letter);
                                                            if (value_sum < colorize_value)
                                                            {
                                                                letter_count++;
                                                                letter_number_sum += letter.NumberInWord;
                                                                value += m_client.CalculateValue(letter);
                                                                colorize_letters++;
                                                            }
                                                            else if (value_sum == colorize_value)
                                                            {
                                                                letter_count++;
                                                                letter_number_sum += letter.NumberInWord;
                                                                value += m_client.CalculateValue(letter);
                                                                colorize_letters++;

                                                                done = true;
                                                                break;
                                                            }
                                                            else if (value_sum > colorize_value)
                                                            {
                                                                if (first_verse)
                                                                {
                                                                    chapter_count--;
                                                                    chapter_number_sum -= current_chapter.SortedNumber;
                                                                }
                                                                if (first_word)
                                                                {
                                                                    verse_count--;
                                                                    verse_number_sum -= verse.NumberInChapter;
                                                                }
                                                                if (first_letter)
                                                                {
                                                                    word_count--;
                                                                    word_number_sum -= word.NumberInVerse;
                                                                }
                                                                done = true;
                                                                break;
                                                            }

                                                            first_letter = false;
                                                        }
                                                    }
                                                    if (done)
                                                    {
                                                        break;
                                                    }

                                                    first_word = false;
                                                }
                                            }
                                            if (done)
                                            {
                                                break;
                                            }

                                            first_verse = false;
                                        }
                                    }
                                }
                                break;
                        }

                        //double current_ratio = (double)colorize_letters / (double)length;
                        //if (Math.Abs(m_user_ratio - current_ratio) < Numbers.ERROR_MARGIN)
                        {
                            bool colorize = false;
                            int arabic_letter_count = 0;
                            int diacritics_count = 0;
                            for (int i = 0; i < text.Length; i++)
                            {
                                if (Constants.ARABIC_LETTERS.Contains(text[i]))
                                {
                                    arabic_letter_count++;
                                    if (arabic_letter_count == colorize_letters) // boundary found, check if it meets deleimiter type
                                    {
                                        switch (m_user_ratio_delimiter)
                                        {
                                            case UserRatioDelimiter.None:
                                                {
                                                    total_chapter_count = 0;
                                                    total_verse_count = 0;
                                                    total_word_count = 0;
                                                    total_letter_count = 0;
                                                    total_chapter_number_sum = 0;
                                                    total_verse_number_sum = 0;
                                                    total_word_number_sum = 0;
                                                    total_letter_number_sum = 0;
                                                    total_value = 0L;

                                                    colorize = false;
                                                }
                                                break;
                                            case UserRatioDelimiter.Letter:
                                                {
                                                    total_chapter_count += chapter_count;
                                                    total_verse_count += verse_count;
                                                    total_word_count += word_count;
                                                    total_letter_count += letter_count;
                                                    total_chapter_number_sum += chapter_number_sum;
                                                    total_verse_number_sum += verse_number_sum;
                                                    total_word_number_sum += word_number_sum;
                                                    total_letter_number_sum += letter_number_sum;
                                                    total_value += value;

                                                    colorize = true;
                                                }
                                                break;
                                            case UserRatioDelimiter.Word:
                                                {
                                                    if (i + 1 < text.Length)
                                                    {
                                                        while (Constants.DIACRITICS.Contains(text[i + 1]))
                                                        {
                                                            diacritics_count++;
                                                            i++; // skip harakaat
                                                        }
                                                        if ((text[i + 1] == ' ') || (text[i + 1] == '\n')) // end of word
                                                        {
                                                            total_chapter_count += chapter_count;
                                                            total_verse_count += verse_count;
                                                            total_word_count += word_count;
                                                            total_letter_count += letter_count;
                                                            total_chapter_number_sum += chapter_number_sum;
                                                            total_verse_number_sum += verse_number_sum;
                                                            total_word_number_sum += word_number_sum;
                                                            total_letter_number_sum += letter_number_sum;
                                                            total_value += value;

                                                            colorize = true;
                                                        }
                                                    }
                                                }
                                                break;
                                            case UserRatioDelimiter.Sentence:
                                                {
                                                    if (i + 2 < text.Length)
                                                    {
                                                        while (Constants.DIACRITICS.Contains(text[i + 1]))
                                                        {
                                                            diacritics_count++;
                                                            i++; // skip harakaat
                                                        }
                                                        if (((text[i + 1] == ' ') && Constants.STOPMARKS.Contains(text[i + 2])) || (text[i + 1] == '\n')) // end of sentence
                                                        {
                                                            if ((text[i + 1] == ' ') && Constants.STOPMARKS.Contains(text[i + 2]))
                                                            {
                                                                diacritics_count += 2;
                                                            }

                                                            total_chapter_count += chapter_count;
                                                            total_verse_count += verse_count;
                                                            total_word_count += word_count;
                                                            total_letter_count += letter_count;
                                                            total_chapter_number_sum += chapter_number_sum;
                                                            total_verse_number_sum += verse_number_sum;
                                                            total_word_number_sum += word_number_sum;
                                                            total_letter_number_sum += letter_number_sum;
                                                            total_value += value;

                                                            colorize = true;
                                                        }
                                                    }
                                                }
                                                break;
                                            case UserRatioDelimiter.Verse:
                                                {
                                                    int verses_letter_count = 0;
                                                    foreach (Verse verse in quarter.Verses)
                                                    {
                                                        verses_letter_count += verse.Letters.Count;
                                                        if (verses_letter_count == colorize_letters)
                                                        {
                                                            total_chapter_count += chapter_count;
                                                            total_verse_count += verse_count;
                                                            total_word_count += word_count;
                                                            total_letter_count += letter_count;
                                                            total_chapter_number_sum += chapter_number_sum;
                                                            total_verse_number_sum += verse_number_sum;
                                                            total_word_number_sum += word_number_sum;
                                                            total_letter_number_sum += letter_number_sum;
                                                            total_value += value;

                                                            colorize = true;
                                                            break;
                                                        }
                                                    }
                                                }
                                                break;
                                            case UserRatioDelimiter.Chapter:
                                                {
                                                    // N/A
                                                }
                                                break;
                                            default:
                                                {
                                                    total_chapter_count = 0;
                                                    total_verse_count = 0;
                                                    total_word_count = 0;
                                                    total_letter_count = 0;
                                                    total_chapter_number_sum = 0;
                                                    total_verse_number_sum = 0;
                                                    total_word_number_sum = 0;
                                                    total_letter_number_sum = 0;
                                                    total_value = 0L;

                                                    colorize = false;
                                                }
                                                break;
                                        }

                                        break; // delimiter found
                                    }
                                }
                                else // non-arabic letter
                                {
                                    diacritics_count++;
                                }
                            }

                            if (colorize)
                            {
                                int user_length = colorize_letters + diacritics_count;
                                if (user_length > 0)
                                {
                                    m_active_textbox.Colorize(start, user_length, GOLDEN_RATIO_COLOR_1);
                                    m_active_textbox.Colorize(start + user_length, text.Length - user_length, GOLDEN_RATIO_COLOR_2);

                                    display_statistics = true;
                                }
                                else
                                {
                                    // uncolorize current chapter
                                    m_active_textbox.Colorize(start, length, MAINTEXTBOX_FORECOLOR);
                                }
                            }
                            else
                            {
                                // uncolorize current chapter
                                m_active_textbox.Colorize(start, length, MAINTEXTBOX_FORECOLOR);
                            }
                        }
                    }
                } // foreach quarter

                if (display_statistics)
                {
                    DisplayCounts(total_chapter_count, total_verse_count, total_word_count, total_letter_count, total_chapter_number_sum, total_verse_number_sum, total_word_number_sum, total_letter_number_sum);
                    FactorizeValue(total_value, UserRatioPresetLabel.Text);
                }
                else
                {
                    DisplayCounts(0, 0, 0, 0, 0, 0, 0, 0);
                    FactorizeValue(0L, UserRatioPresetLabel.Text);
                }
            }
        }
    }
