    private void EnableDisableAddToPositionCheckBoxes()
    {
        try
        {
            for (int i = 0; i < 3; i++)
                AddToLetterLNumberCheckBox.CheckedChanged -= new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            for (int i = 0; i < 3; i++)
                AddToLetterWNumberCheckBox.CheckedChanged -= new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            for (int i = 0; i < 3; i++)
                AddToLetterVNumberCheckBox.CheckedChanged -= new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            for (int i = 0; i < 3; i++)
                AddToLetterCNumberCheckBox.CheckedChanged -= new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            for (int i = 0; i < 3; i++)
                AddToWordWNumberCheckBox.CheckedChanged -= new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            for (int i = 0; i < 3; i++)
                AddToWordVNumberCheckBox.CheckedChanged -= new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            for (int i = 0; i < 3; i++)
                AddToWordCNumberCheckBox.CheckedChanged -= new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            for (int i = 0; i < 3; i++)
                AddToVerseVNumberCheckBox.CheckedChanged -= new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            for (int i = 0; i < 3; i++)
                AddToVerseCNumberCheckBox.CheckedChanged -= new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            for (int i = 0; i < 3; i++)
                AddToChapterCNumberCheckBox.CheckedChanged -= new System.EventHandler(AddToControlCheckBox_CheckedChanged);

            bool is_enabled = m_client.NumerologySystem.AddPositions;
            AddToLetterLNumberCheckBox.Enabled = is_enabled;
            AddToLetterWNumberCheckBox.Enabled = is_enabled;
            AddToLetterVNumberCheckBox.Enabled = is_enabled;
            AddToLetterCNumberCheckBox.Enabled = is_enabled;
            AddToWordWNumberCheckBox.Enabled = is_enabled;
            AddToWordVNumberCheckBox.Enabled = is_enabled;
            AddToWordCNumberCheckBox.Enabled = is_enabled;
            AddToVerseVNumberCheckBox.Enabled = is_enabled;
            AddToVerseCNumberCheckBox.Enabled = is_enabled;
            AddToChapterCNumberCheckBox.Enabled = is_enabled;
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            AddToLetterLNumberCheckBox.CheckedChanged += new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            AddToLetterWNumberCheckBox.CheckedChanged += new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            AddToLetterVNumberCheckBox.CheckedChanged += new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            AddToLetterCNumberCheckBox.CheckedChanged += new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            AddToWordWNumberCheckBox.CheckedChanged += new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            AddToWordVNumberCheckBox.CheckedChanged += new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            AddToWordCNumberCheckBox.CheckedChanged += new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            AddToVerseVNumberCheckBox.CheckedChanged += new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            AddToVerseCNumberCheckBox.CheckedChanged += new System.EventHandler(AddToControlCheckBox_CheckedChanged);
            AddToChapterCNumberCheckBox.CheckedChanged += new System.EventHandler(AddToControlCheckBox_CheckedChanged);
        }
    }
