    private void UpdateNumerologySystemComboBoxs()
    {
        if (m_client != null)
        {
            if (m_client.NumerologySystem != null)
            {
                try
                {
                    for (int i = 0; i < 3; i++)
                        TextModeComboBox.SelectedIndexChanged -= new System.EventHandler(TextModeComboBox_SelectedIndexChanged);
                    for (int i = 0; i < 3; i++)
                        NumerologySystemComboBox.SelectedIndexChanged -= new System.EventHandler(NumerologySystemComboBox_SelectedIndexChanged);

                    TextModeComboBox.SelectedItem = m_client.NumerologySystem.TextMode;
                    PopulateNumerologySystemComboBox();

                    for (int i = 0; i < 3; i++)
                        NumerologySystemComboBox.SelectedIndexChanged -= new System.EventHandler(NumerologySystemComboBox_SelectedIndexChanged);
                    NumerologySystemComboBox.SelectedItem = m_client.NumerologySystem.LetterOrder + "_" + m_client.NumerologySystem.LetterValue;

                    UpdateKeyboard(m_client.NumerologySystem.TextMode);
                    if (TextModeComboBox.Text == "Original")
                    {
                        DoApplyFont(m_quran_font);
                    }
                    else
                    {
                        Font font = new Font("Courier New", m_quran_font.Size, FontStyle.Bold);
                        DoApplyFont(font);
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
                }
                finally
                {
                    TextModeComboBox.SelectedIndexChanged += new System.EventHandler(TextModeComboBox_SelectedIndexChanged);
                    NumerologySystemComboBox.SelectedIndexChanged += new System.EventHandler(NumerologySystemComboBox_SelectedIndexChanged);
                }
            }
        }
    }
