    private void CalculationModeLabel_Click(object sender, EventArgs e)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (ModifierKeys == Keys.Shift)
                {
                    switch (m_client.CalculationMode)
                    {
                        case CalculationMode.SumOfUniqueLetterValues:
                            {
                                SetCalculationMode(CalculationMode.MultiOfWordValueDigitalRoots);
                            }
                            break;
                        case CalculationMode.MultiOfWordValueDigitalRoots:
                            {
                                SetCalculationMode(CalculationMode.MultiOfWordValueDigitSums);
                            }
                            break;
                        case CalculationMode.MultiOfWordValueDigitSums:
                            {
                                SetCalculationMode(CalculationMode.MultiOfWordValues);
                            }
                            break;
                        case CalculationMode.MultiOfWordValues:
                            {
                                SetCalculationMode(CalculationMode.SumOfConcatenatedLetterValueDigitalRoots);
                            }
                            break;
                        case CalculationMode.SumOfConcatenatedLetterValueDigitalRoots:
                            {
                                SetCalculationMode(CalculationMode.SumOfConcatenatedLetterValueDigitSums);
                            }
                            break;
                        case CalculationMode.SumOfConcatenatedLetterValueDigitSums:
                            {
                                SetCalculationMode(CalculationMode.SumOfVerseValueDigitalRoots);
                            }
                            break;
                        case CalculationMode.SumOfVerseValueDigitalRoots:
                            {
                                SetCalculationMode(CalculationMode.SumOfVerseValueDigitSums);
                            }
                            break;
                        case CalculationMode.SumOfVerseValueDigitSums:
                            {
                                SetCalculationMode(CalculationMode.SumOfWordValueDigitalRoots);
                            }
                            break;
                        case CalculationMode.SumOfWordValueDigitalRoots:
                            {
                                SetCalculationMode(CalculationMode.SumOfWordValueDigitSums);
                            }
                            break;
                        case CalculationMode.SumOfWordValueDigitSums:
                            {
                                SetCalculationMode(CalculationMode.SumOfLetterValueDigitalRoots);
                            }
                            break;
                        case CalculationMode.SumOfLetterValueDigitalRoots:
                            {
                                SetCalculationMode(CalculationMode.SumOfLetterValueDigitSums);
                            }
                            break;
                        case CalculationMode.SumOfLetterValueDigitSums:
                            {
                                SetCalculationMode(CalculationMode.SumOfLetterValues);
                            }
                            break;
                        case CalculationMode.SumOfLetterValues:
                            {
                                SetCalculationMode(CalculationMode.SumOfUniqueLetterValues);
                            }
                            break;
                        default:
                            {
                                SetCalculationMode(CalculationMode.SumOfLetterValues);
                            }
                            break;
                    }
                }
                else
                {
                    switch (m_client.CalculationMode)
                    {
                        case CalculationMode.SumOfLetterValues:
                            {
                                SetCalculationMode(CalculationMode.SumOfLetterValueDigitSums);
                            }
                            break;
                        case CalculationMode.SumOfLetterValueDigitSums:
                            {
                                SetCalculationMode(CalculationMode.SumOfLetterValueDigitalRoots);
                            }
                            break;
                        case CalculationMode.SumOfLetterValueDigitalRoots:
                            {
                                SetCalculationMode(CalculationMode.SumOfWordValueDigitSums);
                            }
                            break;
                        case CalculationMode.SumOfWordValueDigitSums:
                            {
                                SetCalculationMode(CalculationMode.SumOfWordValueDigitalRoots);
                            }
                            break;
                        case CalculationMode.SumOfWordValueDigitalRoots:
                            {
                                SetCalculationMode(CalculationMode.SumOfVerseValueDigitSums);
                            }
                            break;
                        case CalculationMode.SumOfVerseValueDigitSums:
                            {
                                SetCalculationMode(CalculationMode.SumOfVerseValueDigitalRoots);
                            }
                            break;
                        case CalculationMode.SumOfVerseValueDigitalRoots:
                            {
                                SetCalculationMode(CalculationMode.SumOfConcatenatedLetterValueDigitSums);
                            }
                            break;
                        case CalculationMode.SumOfConcatenatedLetterValueDigitSums:
                            {
                                SetCalculationMode(CalculationMode.SumOfConcatenatedLetterValueDigitalRoots);
                            }
                            break;
                        case CalculationMode.SumOfConcatenatedLetterValueDigitalRoots:
                            {
                                SetCalculationMode(CalculationMode.MultiOfWordValues);
                            }
                            break;
                        case CalculationMode.MultiOfWordValues:
                            {
                                SetCalculationMode(CalculationMode.MultiOfWordValueDigitSums);
                            }
                            break;
                        case CalculationMode.MultiOfWordValueDigitSums:
                            {
                                SetCalculationMode(CalculationMode.MultiOfWordValueDigitalRoots);
                            }
                            break;
                        case CalculationMode.MultiOfWordValueDigitalRoots:
                            {
                                SetCalculationMode(CalculationMode.SumOfUniqueLetterValues);
                            }
                            break;
                        case CalculationMode.SumOfUniqueLetterValues:
                            {
                                SetCalculationMode(CalculationMode.SumOfLetterValues);
                            }
                            break;
                        default:
                            {
                                SetCalculationMode(CalculationMode.SumOfLetterValues);
                            }
                            break;
                    }
                }

                CalculateCurrentValue();
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void SetCalculationMode(CalculationMode calculation_mode)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (m_client != null)
        {
            m_client.CalculationMode = calculation_mode;

            switch (m_client.CalculationMode)
            {
                case CalculationMode.SumOfLetterValues:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[0];
                    }
                    break;
                case CalculationMode.SumOfLetterValueDigitSums:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[1];
                    }
                    break;
                case CalculationMode.SumOfLetterValueDigitalRoots:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[2];
                    }
                    break;
                case CalculationMode.SumOfWordValueDigitSums:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[3];
                    }
                    break;
                case CalculationMode.SumOfWordValueDigitalRoots:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[4];
                    }
                    break;
                case CalculationMode.SumOfVerseValueDigitSums:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[5];
                    }
                    break;
                case CalculationMode.SumOfVerseValueDigitalRoots:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[6];
                    }
                    break;
                case CalculationMode.SumOfConcatenatedLetterValueDigitSums:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[7];
                    }
                    break;
                case CalculationMode.SumOfConcatenatedLetterValueDigitalRoots:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[8];
                    }
                    break;
                case CalculationMode.MultiOfWordValues:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[9];
                    }
                    break;
                case CalculationMode.MultiOfWordValueDigitSums:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[10];
                    }
                    break;
                case CalculationMode.MultiOfWordValueDigitalRoots:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[11];
                    }
                    break;
                case CalculationMode.SumOfUniqueLetterValues:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[12];
                    }
                    break;
                default:
                    {
                        CalculationModeLabel.BackColor = Numbers.CALCULATION_MODE_COLORS[0];
                    }
                    break;
            }

            ToolTip.SetToolTip(this.CalculationModeLabel, L[l][m_client.CalculationMode.ToString()]);
        }
    }

