    private void UpdateEmlaaeiLabel()
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (m_emlaaei_text)
        {
            if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "stop.png"))
            {
                EmlaaeiTextLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "stop.png");
                ToolTip.SetToolTip(this.EmlaaeiTextLabel, L[l]["Emlaaei Text"]);
            }
        }
        else
        {
            if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "go.png"))
            {
                EmlaaeiTextLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "go.png");
                ToolTip.SetToolTip(this.EmlaaeiTextLabel, L[l]["Uthmani Text"]);
            }
        }

        FindByTextRootSearchTypeLabel.Enabled = !m_emlaaei_text;
        m_text_search_type = TextSearchType.Exact;
        RelatedWordsButton.Enabled = !m_emlaaei_text;
    }
