    private void BuildSimplifiedBookAndDisplaySelection()
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (TextModeComboBox.SelectedItem != null)
            {
                string text_mode = TextModeComboBox.SelectedItem.ToString();

                if (m_client != null)
                {
                    if (m_client.Book != null)
                    {
                        //// ALWAYS rebuild book to support dynamic editing of SimplificationRules
                        //// uncomment to ONLY rebuild ON CHANGE to these variables
                        ////if ((m_client.Book.TextMode != text_mode) ||
                        ////    (m_client.Book.WithBismAllah != m_with_bism_Allah) ||
                        ////    (m_client.Book.WawAsWord != m_waw_as_word) ||
                        ////    (m_client.Book.ShaddaAsLetter != m_shadda_as_letter)
                        ////    (m_client.Book.HamzaAboveHorizontalLineAsLetter != m_hamza_above_horizontal_line_as_letter)
                        ////    (m_client.Book.ElfAboveHorizontalLineAsLetter != m_elf_above_horizontal_line_as_letter)
                        ////    (m_client.Book.YaaAboveHorizontalLineAsLetter != m_yaa_above_horizontal_line_as_letter)
                        ////    (m_client.Book.NoonAboveHorizontalLineAsLetter != m_noon_above_horizontal_line_as_letter)
                        ////   )
                        {
                            if (text_mode == "Original")
                            {
                                m_with_bism_Allah = true;
                                m_waw_as_word = false;
                                m_shadda_as_letter = false;
                                m_hamza_above_horizontal_line_as_letter = false;
                                m_elf_above_horizontal_line_as_letter = false;
                                m_yaa_above_horizontal_line_as_letter = false;
                                m_noon_above_horizontal_line_as_letter = false;
                            }

                            m_client.BuildSimplifiedBook(text_mode, m_with_diacritics, m_with_bism_Allah, m_waw_as_word, m_shadda_as_letter, m_hamza_above_horizontal_line_as_letter, m_elf_above_horizontal_line_as_letter, m_yaa_above_horizontal_line_as_letter, m_noon_above_horizontal_line_as_letter, m_emlaaei_text);

                            bool backup_found_verses_displayed = m_found_verses_displayed;
                            if ((Chapter.CompareBy == ChapterCompareBy.Compilation) && (Chapter.CompareOrder == ChapterCompareOrder.Ascending))
                            {
                                DisplaySelection(false);
                            }
                            else
                            {
                                // book is already created in Compilation Ascending order
                                Chapter.CompareBy = ChapterCompareBy.Compilation;
                                Chapter.CompareOrder = ChapterCompareOrder.Ascending;
                                Chapter.PinChapter1 = false;
                                m_chapter_compare_by = Chapter.CompareBy;
                                m_chapter_compare_order = Chapter.CompareOrder;
                                m_pin_chapter1 = Chapter.PinChapter1;
                                UpdateChapterSortControls();
                                DisplaySortedChapters();
                            }

                            // re-display search result if that was shown when text_mode was changed
                            if (backup_found_verses_displayed)
                            {
                                DisplayFoundVerses(FINDBYTEXT_MATCH_COLOR, false);
                            }
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void NumerologySystemComboBox_SelectedIndexChanged(object sender, EventArgs e)
    {
        if (Chapter.CompareBy == ChapterCompareBy.Value)
            this.Cursor = Cursors.WaitCursor;
        try
        {
            // force close up of NumerologySystemComboBox
            this.Refresh();

            for (int i = 0; i < 3; i++)
                NumerologySystemComboBox.SelectedIndexChanged -= new System.EventHandler(NumerologySystemComboBox_SelectedIndexChanged);

            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    if (m_client.NumerologySystem != null)
                    {
                        if (TextModeComboBox.SelectedItem != null)
                        {
                            if (NumerologySystemComboBox.SelectedItem != null)
                            {
                                string text_mode = TextModeComboBox.SelectedItem.ToString();
                                string valuation_system = NumerologySystemComboBox.SelectedItem.ToString();
                                string numerology_system_name = text_mode + "_" + valuation_system;

                                LoadNumerologySystem(numerology_system_name);
                                NumerologySystemComboBox_MouseHover(null, null);

                                CalculateCurrentValue();

                                // select current numerology system
                                int index = NumerologySystemComboBox.SelectedIndex;
                                if (index != -1)
                                {
                                    SelectValuesSequenceLabel(index);

                                    string name = NumerologySystemComboBox.SelectedItem.ToString();
                                    SelectNumerologyValueLabel(name);
                                }

                                BuildLetterFrequencies();
                                DisplayLetterFrequencies();

                                // re-sort chapters if sorted by Value
                                if (Chapter.CompareBy == ChapterCompareBy.Value)
                                {
                                    if (m_client.Book != null)
                                    {
                                        foreach (Chapter chapter in m_client.Book.Chapters)
                                        {
                                            chapter.Value = m_client.CalculateValue(chapter);
                                        }
                                        m_client.Book.SortChapters(m_chapter_compare_by, m_chapter_compare_order, m_pin_chapter1, m_client.NumerologySystem.AddDistancesWithinChapters, m_with_diacritics);

                                        // display chapters in new order
                                        DisplaySortedChapters();
                                    }
                                }

                                if (m_user_ratio_delimiter != UserRatioDelimiter.None)
                                {
                                    // comment this line as we need to update statistics for Text and Value types
                                    //if (m_user_ratio_type == UserRatioType.Value) 
                                    // comment this line as we need to update statistics for Text and Value types
                                    {
                                        ColorizeUserRatios();
                                    }
                                }

                                RedrawImage();

                                switch (m_search_type)
                                {
                                    case SearchType.Grammar:
                                        {
                                            this.AcceptButton = FindByTextButton;
                                            break;
                                        }
                                    case SearchType.Repetition:
                                        {
                                            this.AcceptButton = FindByTextButton;
                                            break;
                                        }
                                    case SearchType.Text:
                                        {
                                            this.AcceptButton = FindByTextButton;
                                            break;
                                        }
                                    case SearchType.Numbers:
                                        {
                                            this.AcceptButton = FindByNumbersButton;
                                            break;
                                        }
                                    case SearchType.Similarity:
                                        {
                                            this.AcceptButton = FindBySimilarityButton;
                                            break;
                                        }
                                    case SearchType.Frequency:
                                        {
                                            this.AcceptButton = FindByFrequencyButton;
                                            break;
                                        }
                                    default:
                                        {
                                            this.AcceptButton = FindByTextButton;
                                            break;
                                        }
                                }
                            }
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            if (Chapter.CompareBy == ChapterCompareBy.Value)
                this.Cursor = Cursors.Default;
            NumerologySystemComboBox.SelectedIndexChanged += new System.EventHandler(NumerologySystemComboBox_SelectedIndexChanged);
        }
    }
    private void NumerologySystemComboBox_MouseHover(object sender, EventArgs e)
    {
        if (m_client != null)
        {
            if (m_client.NumerologySystem != null)
            {
                StringBuilder str = new StringBuilder();
                foreach (char key in m_client.NumerologySystem.Keys)
                {
                    str.AppendLine(key.ToString() + "\t" + m_client.NumerologySystem[key].ToString());
                }
                ToolTip.SetToolTip(this.NumerologySystemComboBox, str.ToString());
            }
        }
