    private void ValueTextBox_TextChanged(object sender, EventArgs e)
    {
        ClearValueFields();

        long value = 0L;
        try
        {
            value = Radix.Decode(ValueTextBox.Text, m_radix);
        }
        catch
        {
            value = 0;
        }

        int digit_sum = Numbers.DigitSum(ValueTextBox.Text, m_radix);
        DigitSumTextBox.Text = (digit_sum == 0) ? "" : digit_sum.ToString();
        DigitSumTextBox.ForeColor = Numbers.GetNumberTypeColor(digit_sum);
        DigitSumTextBox.Refresh();

        int digital_root = Numbers.DigitalRoot(digit_sum);
        DigitalRootTextBox.Text = (digital_root == 0) ? "" : digital_root.ToString();
        DigitalRootTextBox.ForeColor = Numbers.GetNumberTypeColor(digital_root);
        DigitalRootTextBox.Refresh();

        UpdateNumberKind(value);
        UpdateSumOfDivisors(value);
        UpdateSumOfNumbers(value);
        UpdatePCIndexChains(value);

        UpdateValueNavigator(value);
    }
    private void ValueTextBox_KeyDown(object sender, KeyEventArgs e)
    {
        if (ModifierKeys == Keys.Control)
        {
            if (e.KeyCode == Keys.A)
            {
                if (sender is TextBoxBase)
                {
                    (sender as TextBoxBase).SelectAll();
                }
            }
        }
        else if (e.KeyCode == Keys.Up)
        {
            IncrementValue();
        }
        else if (e.KeyCode == Keys.Down)
        {
            DecrementValue();
        }
        else if (e.KeyCode == Keys.Enter)
        {
            CalculateExpression();
        }
        else
        {
            ValueTextBox.ForeColor = Color.DarkGray;
        }
    }
    private void IncrementValue()
    {
        long value = Radix.Decode(ValueTextBox.Text, m_radix);
        if (value < long.MaxValue)
        {
            value++;
            FactorizeValue(value, "↑");
        }
    }
    private void DecrementValue()
    {
        long value = Radix.Decode(ValueTextBox.Text, m_radix);
        if (value > 0L)
        {
            value--;
            FactorizeValue(value, "↓");
        }
    }
    private double m_double_value = 0.0D;
    private void CalculateExpression()
    {
        if (m_client != null)
        {
            BigInteger big_integer = 0;
            long value = 0L;
            m_double_value = value;

            string input = ValueTextBox.Text;

            if (long.TryParse(input, out value))
            {
                m_double_value = value;
                FactorizeValue(value, "User");
            }
            else if (input.IsArabic())
            {
                value = m_client.CalculateValue(input);
                m_double_value = value;
                FactorizeValue(value, "Text");
            }
            else if ((m_radix == Numbers.DEFAULT_RADIX) && (input.ContainsInside("P")))
            {
                string[] parts = input.ToUpper().Split('P'); // Permutations
                if (parts.Length == 2)
                {
                    int n = 0;
                    if (int.TryParse(parts[0], out n))
                    {
                        int k = 0;
                        if (int.TryParse(parts[1], out k))
                        {
                            big_integer = Numbers.nPk(n, k);
                            FactorizeValue((long)big_integer, n.ToString() + "P" + k.ToString());
                        }
                    }
                }
            }
            else if ((m_radix == Numbers.DEFAULT_RADIX) && (input.ContainsInside("C"))) // Combinations
            {
                string[] parts = input.ToUpper().Split('C');
                if (parts.Length == 2)
                {
                    int n = 0;
                    if (int.TryParse(parts[0], out n))
                    {
                        int k = 0;
                        if (int.TryParse(parts[1], out k))
                        {
                            big_integer = Numbers.nCk(n, k);
                            FactorizeValue((long)big_integer, n.ToString() + "C" + k.ToString());
                        }
                    }
                }
            }
            else // expression or big number
            {
                m_double_value = DoCalculateExpression(input, m_radix);
                if (Math.Abs(m_double_value) < Numbers.ERROR_MARGIN)
                    m_double_value = 0.0D;
                value = (long)Math.Round(m_double_value);

                ValueTextBox.TextChanged -= ValueTextBox_TextChanged;
                ValueTextBox.Text = value.ToString();
                ValueTextBox.TextChanged += ValueTextBox_TextChanged;
                FactorizeValue(value, "Math");
            }

            // if result has fraction, display it as a fraction
            if (Math.Abs((m_double_value - value)) > Numbers.ERROR_MARGIN)
            {
                PrimeFactorsTextBox.Text = m_double_value.ToString();
                PrimeFactorsTextBox.Refresh();
            }
        }
    }
    private double DoCalculateExpression(string expression, int radix)
    {
        double result = 0D;
        if (m_client != null)
        {
            string output = RadixEvaluator.Evaluate(expression, radix);
            if (double.TryParse(output, out result))
            {
                return result;
            }
            else
            {
                if (double.TryParse(output, out result))
                {
                    return result;
                }
                else
                {
                    return m_client.CalculateValue(expression);
                }
            }
        }
        return result;
    }

    private void FactorizeValue(long value)
    {
        FactorizeValue(value, "", false);
    }
    private void FactorizeValue(long value, string caption)
    {
        FactorizeValue(value, caption, false);
    }
    private void FactorizeValue(long value, string caption, bool append)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        try
        {
            if (!String.IsNullOrEmpty(caption))
            {
                if (L[l].ContainsKey(caption))
                {
                    ValueLabel.Text = (m_show_add_controls ? "-- " : "+ ") + L[l][caption];
                }
                else
                {
                    ValueLabel.Text = (m_show_add_controls ? "-- " : "+ ") + caption;
                }
            }

            // if there is a math expression, add to it, don't overwrite it
            if (append &&
                 (
                   (ValueTextBox.Text.EndsWith("+")) ||
                   (ValueTextBox.Text.EndsWith("-")) ||
                   (ValueTextBox.Text.EndsWith("*")) ||
                   (ValueTextBox.Text.EndsWith("/")) ||
                   (ValueTextBox.Text.EndsWith("^")) ||
                   (ValueTextBox.Text.EndsWith("%"))
                 )
               )
            {
                ValueTextBox.Text += Radix.Encode(value, m_radix);

                ValueTextBox.SelectionLength = 0;
                ValueTextBox.SelectionStart = ValueTextBox.Text.Length;
                // focus so user can continue with +, -, *, /, ^, %, Enter
                ValueTextBox.Focus();
            }
            else
            {
                ValueTextBox.Text = Radix.Encode(value, m_radix);
            }

            ValueTextBox.ForeColor = Numbers.GetNumberTypeColor(value);
            ValueTextBox.BackColor = (Numbers.Compare(value, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Window;
            if (value.IsInterestingX(INTERESTINGX_COUNT))
                ValueTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
            if (value.IsInteresting())
                ValueTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
            if (value.IsCarmichaelX())
                ValueTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
            if (value.IsCarmichael())
                ValueTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
            ValueTextBox.SelectionStart = ValueTextBox.Text.Length;
            ValueTextBox.SelectionLength = 0;
            ToolTip.SetToolTip(this.ValueTextBox, value.FindInterestingSums(INTERESTINGX_COUNT));
            ValueTextBox.Refresh();
            DecimalValueTextBox.Text = value.ToString();
            DecimalValueTextBox.Visible = (m_radix != Numbers.DEFAULT_RADIX);
            DecimalValueTextBox.ForeColor = Numbers.GetNumberTypeColor(value);
            DecimalValueTextBox.Refresh();

            bool show_unused_letters_value =
                (m_client.CalculationMode == CalculationMode.SumOfUniqueLetterValues)
                &&
                ((ValueLabel.Text.EndsWith(L[l]["Value"])) || (ValueLabel.Text.EndsWith(L[l]["User"])));

            if (show_unused_letters_value)
            {
                UnusedLettersValueTextBox.Visible = true;
                DecimalUnusedLettersValueTextBox.Visible = (m_radix != Numbers.DEFAULT_RADIX);
                DecimalUnusedLettersValueTextBox.Refresh();

                if (m_client != null)
                {
                    if (m_client.NumerologySystem != null)
                    {
                        long unused_letters_value = m_client.NumerologySystem.LetterValuesSum - value;
                        UnusedLettersValueTextBox.Text = Radix.Encode(unused_letters_value, m_radix);
                        UnusedLettersValueTextBox.ForeColor = Numbers.GetNumberTypeColor(unused_letters_value);
                        UnusedLettersValueTextBox.BackColor = (Numbers.Compare(unused_letters_value, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Window;
                        if (unused_letters_value.IsInterestingX(INTERESTINGX_COUNT))
                            UnusedLettersValueTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                        if (unused_letters_value.IsInteresting())
                            UnusedLettersValueTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                        if (unused_letters_value.IsCarmichaelX())
                            UnusedLettersValueTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                        if (unused_letters_value.IsCarmichael())
                            UnusedLettersValueTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                        ToolTip.SetToolTip(this.UnusedLettersValueTextBox, unused_letters_value.FindInterestingSums(INTERESTINGX_COUNT));
                        UnusedLettersValueTextBox.Refresh();
                        DecimalUnusedLettersValueTextBox.Text = unused_letters_value.ToString();
                        DecimalUnusedLettersValueTextBox.ForeColor = Numbers.GetNumberTypeColor(unused_letters_value);
                        DecimalUnusedLettersValueTextBox.Refresh();
                    }
                }
            }
            else
            {
                UnusedLettersValueTextBox.Visible = false;
                DecimalUnusedLettersValueTextBox.Visible = false;
                DecimalUnusedLettersValueTextBox.Refresh();
            }

            int digit_sum = Numbers.DigitSum(value, m_radix);
            DigitSumTextBox.Text = (digit_sum == 0) ? "" : digit_sum.ToString();
            DigitSumTextBox.ForeColor = Numbers.GetNumberTypeColor(digit_sum);
            DigitSumTextBox.BackColor = (Numbers.Compare(digit_sum, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.ControlLight;
            if (Globals.EDITION != Edition.Standard)
                if (digit_sum.IsInterestingX(INTERESTINGX_COUNT))
                    DigitSumTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
            if (digit_sum.IsInteresting())
                DigitSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
            if (digit_sum.IsCarmichaelX())
                DigitSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
            if (digit_sum.IsCarmichael())
                DigitSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
            ToolTip.SetToolTip(this.DigitSumTextBox, L[l]["Digit sum"] + "\r\n\r\n" + digit_sum.FindInterestingSums(INTERESTINGX_COUNT));
            DigitSumTextBox.Refresh();

            int digital_root = Numbers.DigitalRoot(digit_sum);
            DigitalRootTextBox.Text = (digital_root == 0) ? "" : digital_root.ToString();
            DigitalRootTextBox.ForeColor = Numbers.GetNumberTypeColor(digital_root);
            DigitalRootTextBox.BackColor = (Numbers.Compare(digital_root, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.ControlLight;
            if (Globals.EDITION != Edition.Standard)
                if (digital_root.IsInterestingX(INTERESTINGX_COUNT))
                    DigitalRootTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
            if (digital_root.IsInteresting())
                DigitalRootTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
            if (digital_root.IsCarmichaelX())
                DigitalRootTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
            if (digital_root.IsCarmichael())
                DigitalRootTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
            ToolTip.SetToolTip(this.DigitalRootTextBox, L[l]["Digital root"] + "\r\n\r\n" + digital_root.FindInterestingSums(INTERESTINGX_COUNT));
            DigitalRootTextBox.Refresh();

            List<long> factors = Numbers.Factorize(value);
            if (factors != null)
            {
                m_number_dimension = factors.Count;
                if (value < -1)
                    m_number_dimension--;
                else if (value < 2)
                    m_number_dimension = 0;

                int nth_number_dimension_a_index = Numbers.NumberDimensionIndexOf(m_number_dimension, value) + 1;
                int nth_number_dimension_u_index = Numbers.UniqueNumberDimensionIndexOf(m_number_dimension, value) + 1;
                int nth_number_dimension_d_index = Numbers.DuplicateNumberDimensionIndexOf(m_number_dimension, value) + 1;
                NumberDimensionTextBox.Text = m_number_dimension.ToString() + "D";
                NthANumberDimensionTextBox.Text = (nth_number_dimension_a_index > 0) ? nth_number_dimension_a_index.ToString() : "";
                NthUNumberDimensionTextBox.Text = (nth_number_dimension_u_index > 0) ? nth_number_dimension_u_index.ToString() : "";
                NthDNumberDimensionTextBox.Text = (nth_number_dimension_d_index > 0) ? nth_number_dimension_d_index.ToString() : "";
                //NumberDimensionTextBox.ForeColor = Numbers.GetNumberTypeColor(m_number_dimension);
                NthANumberDimensionTextBox.ForeColor = Numbers.GetNumberTypeColor(nth_number_dimension_a_index);
                NthUNumberDimensionTextBox.ForeColor = Numbers.GetNumberTypeColor(nth_number_dimension_u_index);
                NthDNumberDimensionTextBox.ForeColor = Numbers.GetNumberTypeColor(nth_number_dimension_d_index);

                NumberDimensionTextBox.BackColor = (Numbers.Compare(m_number_dimension, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.ControlLight;
                if (Globals.EDITION != Edition.Standard)
                    if (m_number_dimension.IsInterestingX(INTERESTINGX_COUNT))
                        NumberDimensionTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                if (m_number_dimension.IsInteresting())
                    NumberDimensionTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                if (m_number_dimension.IsCarmichaelX())
                    NumberDimensionTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                if (m_number_dimension.IsCarmichael())
                    NumberDimensionTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                ToolTip.SetToolTip(this.NumberDimensionTextBox, L[l]["Number dimension"] +
                    "\r\n\r\n" + m_number_dimension.FindInterestingSums(INTERESTINGX_COUNT));

                NthANumberDimensionTextBox.BackColor = (Numbers.Compare(nth_number_dimension_a_index, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : Color.FromArgb(((int)(((byte)(240)))), ((int)(((byte)(224)))), ((int)(((byte)(255)))));
                if (Globals.EDITION != Edition.Standard)
                    if (nth_number_dimension_a_index.IsInterestingX(INTERESTINGX_COUNT))
                        NthANumberDimensionTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                if (nth_number_dimension_a_index.IsInteresting())
                    NthANumberDimensionTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                if (nth_number_dimension_a_index.IsCarmichaelX())
                    NthANumberDimensionTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                if (nth_number_dimension_a_index.IsCarmichael())
                    NthANumberDimensionTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                ToolTip.SetToolTip(this.NthANumberDimensionTextBox, L[l]["Any prime factors index"] +
                    "\r\n\r\n" + nth_number_dimension_a_index.FindInterestingSums(INTERESTINGX_COUNT));

                NthUNumberDimensionTextBox.BackColor = (Numbers.Compare(nth_number_dimension_u_index, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : Color.FromArgb(((int)(((byte)(240)))), ((int)(((byte)(224)))), ((int)(((byte)(255)))));
                if (Globals.EDITION != Edition.Standard)
                    if (nth_number_dimension_u_index.IsInterestingX(INTERESTINGX_COUNT))
                        NthUNumberDimensionTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                if (nth_number_dimension_u_index.IsInteresting())
                    NthUNumberDimensionTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                if (nth_number_dimension_u_index.IsCarmichaelX())
                    NthUNumberDimensionTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                if (nth_number_dimension_u_index.IsCarmichael())
                    NthUNumberDimensionTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                ToolTip.SetToolTip(this.NthUNumberDimensionTextBox, L[l]["Unique prime factors index"] +
                    "\r\n\r\n" + nth_number_dimension_u_index.FindInterestingSums(INTERESTINGX_COUNT));

                NthDNumberDimensionTextBox.BackColor = (Numbers.Compare(nth_number_dimension_d_index, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : Color.FromArgb(((int)(((byte)(240)))), ((int)(((byte)(224)))), ((int)(((byte)(255)))));
                if (Globals.EDITION != Edition.Standard)
                    if (nth_number_dimension_d_index.IsInterestingX(INTERESTINGX_COUNT))
                        NthDNumberDimensionTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                if (nth_number_dimension_d_index.IsInteresting())
                    NthDNumberDimensionTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                if (nth_number_dimension_d_index.IsCarmichaelX())
                    NthDNumberDimensionTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                if (nth_number_dimension_d_index.IsCarmichael())
                    NthDNumberDimensionTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                ToolTip.SetToolTip(this.NthDNumberDimensionTextBox, L[l]["Duplicate prime factors index"] +
                    "\r\n\r\n" + nth_number_dimension_d_index.FindInterestingSums(INTERESTINGX_COUNT));

                NumberDimensionTextBox.Refresh();
                NthANumberDimensionTextBox.Refresh();
                NthUNumberDimensionTextBox.Refresh();
                NthDNumberDimensionTextBox.Refresh();
            }

            string factors_str = Numbers.FactorizeToString(value);
            PrimeFactorsTextBox.Text = factors_str;
            PrimeFactorsTextBox.Refresh();

            if (value > 0L)
            {
                long prime_numbers_sum = 0L;
                if (value == 1L)
                {
                    prime_numbers_sum = value;
                    ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l]["1 is neither prime nor composite"]);
                }
                else if ((value >= 2L) && (Numbers.IsPrime(value))) // if prime, sum up primes from 2 to p
                {
                    int index = Numbers.PrimeIndexOf(value);
                    for (int i = 0; i <= index; i++)
                    {
                        prime_numbers_sum += Numbers.Primes[i];
                    }
                    ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l]["Sum of prime numbers from 2 to"] + " " + value.ToString());
                }
                else if ((value >= 4L) && (Numbers.IsComposite(value)))  // if composite, sum up composites from 4 to c
                {
                    int index = Numbers.CompositeIndexOf(value);
                    for (int i = 0; i <= index; i++)
                    {
                        prime_numbers_sum += Numbers.Composites[i];
                    }
                    ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l]["Sum of composite numbers from 4 to"] + " " + value.ToString());
                }
                PrimeNumbersSumTextBox.Text = prime_numbers_sum.ToString();
                PrimeNumbersSumTextBox.ForeColor = Numbers.GetNumberTypeColor(prime_numbers_sum);
                PrimeNumbersSumTextBox.BackColor = (Numbers.Compare(prime_numbers_sum, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Window;
                if (Globals.EDITION != Edition.Standard)
                    if (prime_numbers_sum.IsInterestingX(INTERESTINGX_COUNT))
                        PrimeNumbersSumTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                if (prime_numbers_sum.IsInteresting())
                    PrimeNumbersSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                if (prime_numbers_sum.IsCarmichaelX())
                    PrimeNumbersSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                if (prime_numbers_sum.IsCarmichael())
                    PrimeNumbersSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                if (value == 1L)
                {
                    ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l]["1 is neither prime nor composite"]);
                }
                else if ((value >= 2L) && (Numbers.IsPrime(value))) // if prime, sum up primes from 2 to p
                {
                    ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l]["Sum of prime numbers from 2 to"] + " " + value.ToString() +
                        "\r\n\r\n" + prime_numbers_sum.FindInterestingSums(INTERESTINGX_COUNT));
                }
                else if ((value >= 4L) && (Numbers.IsComposite(value)))  // if composite, sum up composites from 4 to c
                {
                    ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l]["Sum of composite numbers from 4 to"] + " " + value.ToString() +
                        "\r\n\r\n" + prime_numbers_sum.FindInterestingSums(INTERESTINGX_COUNT));
                }
                PrimeNumbersSumTextBox.Refresh();
            }

            int nth_number_index = 0;
            int nth_additive_number_index = 0;
            int nth_non_additive_number_index = 0;
            if (Numbers.IsPrime(value))
            {
                m_index_type = IndexType.Prime;
                nth_number_index = Numbers.PrimeIndexOf(value) + 1;
                nth_additive_number_index = Numbers.AdditivePrimeIndexOf(value) + 1;
                nth_non_additive_number_index = Numbers.NonAdditivePrimeIndexOf(value) + 1;
                NthNumberTextBox.BackColor = (nth_additive_number_index > 0) ? Numbers.NUMBER_TYPE_BACKCOLORS[(int)NumberType.AdditivePrime] : Numbers.NUMBER_TYPE_BACKCOLORS[(int)NumberType.NonAdditivePrime];
                NthAdditiveNumberTextBox.BackColor = Numbers.NUMBER_TYPE_BACKCOLORS[(int)NumberType.AdditivePrime];
                NthNonAdditiveNumberTextBox.BackColor = Numbers.NUMBER_TYPE_BACKCOLORS[(int)NumberType.NonAdditivePrime];
                ToolTip.SetToolTip(this.NthNumberTextBox, L[l]["Prime index"] +
                   "\r\n\r\n" + nth_number_index.FindInterestingSums(INTERESTINGX_COUNT));
                ToolTip.SetToolTip(this.NthAdditiveNumberTextBox, L[l]["Additive prime index"] +
                    "\r\n\r\n" + nth_additive_number_index.FindInterestingSums(INTERESTINGX_COUNT));
                ToolTip.SetToolTip(this.NthNonAdditiveNumberTextBox, L[l]["Non-additive prime index"] +
                    "\r\n\r\n" + nth_non_additive_number_index.FindInterestingSums(INTERESTINGX_COUNT));
            }
            else // any other index type will be treated as IndexNumberType.Composite
            {
                m_index_type = IndexType.Composite;
                nth_number_index = Numbers.CompositeIndexOf(value) + 1;
                nth_additive_number_index = Numbers.AdditiveCompositeIndexOf(value) + 1;
                nth_non_additive_number_index = Numbers.NonAdditiveCompositeIndexOf(value) + 1;
                NthNumberTextBox.BackColor = (nth_additive_number_index > 0) ? Numbers.NUMBER_TYPE_BACKCOLORS[(int)NumberType.AdditiveComposite] : Numbers.NUMBER_TYPE_BACKCOLORS[(int)NumberType.NonAdditiveComposite];
                NthAdditiveNumberTextBox.BackColor = Numbers.NUMBER_TYPE_BACKCOLORS[(int)NumberType.AdditiveComposite];
                NthNonAdditiveNumberTextBox.BackColor = Numbers.NUMBER_TYPE_BACKCOLORS[(int)NumberType.NonAdditiveComposite];
                ToolTip.SetToolTip(this.NthNumberTextBox, L[l]["Composite index"] +
                    "\r\n\r\n" + nth_number_index.FindInterestingSums(INTERESTINGX_COUNT));
                ToolTip.SetToolTip(this.NthAdditiveNumberTextBox, L[l]["Additive composite index"] +
                    "\r\n\r\n" + nth_additive_number_index.FindInterestingSums(INTERESTINGX_COUNT));
                ToolTip.SetToolTip(this.NthNonAdditiveNumberTextBox, L[l]["Non-additive composite index"] +
                    "\r\n\r\n" + nth_non_additive_number_index.FindInterestingSums(INTERESTINGX_COUNT));
            }

            NthNumberTextBox.Text = (nth_number_index > 0) ? nth_number_index.ToString() : "";
            NthNumberTextBox.ForeColor = Numbers.GetNumberTypeColor(nth_number_index);
            if (Numbers.Compare(nth_number_index, m_divisor, ComparisonOperator.DivisibleBy, 0))
                NthNumberTextBox.BackColor = Numbers.DIVISOR_COLOR;
            if (Globals.EDITION != Edition.Standard)
                if (nth_number_index.IsInterestingX(INTERESTINGX_COUNT))
                    NthNumberTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
            if (nth_number_index.IsInteresting())
                NthNumberTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
            if (nth_number_index.IsCarmichaelX())
                NthNumberTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
            if (nth_number_index.IsCarmichael())
                NthNumberTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
