            NthAdditiveNumberTextBox.ForeColor = Numbers.GetNumberTypeColor(nth_additive_number_index);
            if (Numbers.Compare(nth_additive_number_index, m_divisor, ComparisonOperator.DivisibleBy, 0))
                NthAdditiveNumberTextBox.BackColor = Numbers.DIVISOR_COLOR;
            if (Globals.EDITION != Edition.Standard)
                if (nth_additive_number_index.IsInterestingX(INTERESTINGX_COUNT))
                    NthAdditiveNumberTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
            if (nth_additive_number_index.IsInteresting())
                NthAdditiveNumberTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
            if (nth_additive_number_index.IsCarmichaelX())
                NthAdditiveNumberTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
            if (nth_additive_number_index.IsCarmichael())
                NthAdditiveNumberTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
            NthAdditiveNumberTextBox.Refresh();

            NthNonAdditiveNumberTextBox.Text = (nth_non_additive_number_index > 0) ? nth_non_additive_number_index.ToString() : "";
            NthNonAdditiveNumberTextBox.ForeColor = Numbers.GetNumberTypeColor(nth_non_additive_number_index);
            if (Numbers.Compare(nth_non_additive_number_index, m_divisor, ComparisonOperator.DivisibleBy, 0))
                NthNonAdditiveNumberTextBox.BackColor = Numbers.DIVISOR_COLOR;
            if (Globals.EDITION != Edition.Standard)
                if (nth_non_additive_number_index.IsInterestingX(INTERESTINGX_COUNT))
                    NthNonAdditiveNumberTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
            if (nth_non_additive_number_index.IsInteresting())
                NthNonAdditiveNumberTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
            if (nth_non_additive_number_index.IsCarmichaelX())
                NthNonAdditiveNumberTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
            if (nth_non_additive_number_index.IsCarmichael())
                NthNonAdditiveNumberTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
            NthNonAdditiveNumberTextBox.Refresh();

            int plus1_index = -1;
            int minus1_index = -1;
            string plus1_str = "";
            string minus1_str = "";
            if (Numbers.IsUnit(value) || Numbers.IsPrime(value))
            {
                plus1_index = Numbers.Prime4nPlus1IndexOf(value) + 1;
                plus1_str = Numbers.Get4nPlus1EqualsSumOfTwoSquares(value);

                minus1_index = Numbers.Prime4nMinus1IndexOf(value) + 1;
                minus1_str = Numbers.Get4nMinus1EqualsSumOfTwoSquares(value);
            }
            else //if composite
            {
                plus1_index = Numbers.Composite4nPlus1IndexOf(value) + 1;
                plus1_str = Numbers.Get4nPlus1EqualsDiffOfTwoSquares(value);

                minus1_index = Numbers.Composite4nMinus1IndexOf(value) + 1;
                minus1_str = Numbers.Get4nMinus1EqualsSumOfTwoSquares(value);
            }

            SquareSumTextBox.Text = (plus1_index > 0) ? plus1_str : (minus1_index > 0) ? minus1_str : "";
            long n = 0L;
            if (plus1_str.StartsWith("4×")) // 4n+1
            {
                int start = "4×".Length;
                int end = plus1_str.IndexOf("+");
                if ((start >= 0) && (end >= start))
                {
                    string text = plus1_str.Substring(start, end - start);
                    n = long.Parse(text);
                }
            }
            else if (minus1_str.StartsWith("4×")) // 4n-1
            {
                int start = "4×".Length;
                int end = minus1_str.IndexOf("-");
                if ((start >= 0) && (end >= start))
                {
                    string text = minus1_str.Substring(start, end - start);
                    n = long.Parse(text);
                }
            }
            Color n_color = Numbers.GetNumberTypeColor(n);
            //double scale = 0.8D;
            //n_color = Color.FromArgb((int)(n_color.R * scale), (int)(n_color.G * scale), (int)(n_color.B * scale));
            SquareSumTextBox.ForeColor = n_color;
            if (Numbers.IsPrime(n))
            {
                SquareSumTextBox.BackColor = Numbers.NUMBER_TYPE_BACKCOLORS[3];
            }
            else if (Numbers.IsComposite(n))
            {
                SquareSumTextBox.BackColor = Numbers.NUMBER_TYPE_BACKCOLORS[6];
            }
            else
            {
                SquareSumTextBox.BackColor = SystemColors.ControlLight;
            }

            if (Numbers.Compare(n, m_divisor, ComparisonOperator.DivisibleBy, 0))
                SquareSumTextBox.BackColor = Numbers.DIVISOR_COLOR;
            if (Globals.EDITION != Edition.Standard)
                if (n.IsInterestingX(INTERESTINGX_COUNT))
                    SquareSumTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
            if (n.IsInteresting())
                SquareSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
            if (n.IsCarmichaelX())
                SquareSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
            if (n.IsCarmichael())
                SquareSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
            //ToolTip.SetToolTip(this.SquareSumTextBox, n.FindInterestingSums(INTERESTINGX_COUNT));
            SquareSumTextBox.Refresh();

            int _4n1_index = (plus1_index > 0) ? plus1_index : (minus1_index > 0) ? minus1_index : 0;
            Nth4n1NumberTextBox.Text = (_4n1_index > 0) ? _4n1_index.ToString() : "";
            Nth4n1NumberTextBox.ForeColor = Numbers.GetNumberTypeColor(_4n1_index);
            if (Numbers.IsPrime(n))
            {
                Nth4n1NumberTextBox.BackColor = Numbers.NUMBER_TYPE_BACKCOLORS[3];
            }
            else if (Numbers.IsComposite(n))
            {
                Nth4n1NumberTextBox.BackColor = Numbers.NUMBER_TYPE_BACKCOLORS[6];
            }
            else
            {
                Nth4n1NumberTextBox.BackColor = SystemColors.ControlLight;
            }

            if (_4n1_index > 0)
            {
                if (Numbers.Compare(_4n1_index, m_divisor, ComparisonOperator.DivisibleBy, 0))
                    Nth4n1NumberTextBox.BackColor = Numbers.DIVISOR_COLOR;
                if (Globals.EDITION != Edition.Standard)
                    if (_4n1_index.IsInterestingX(INTERESTINGX_COUNT))
                        Nth4n1NumberTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
                if (_4n1_index.IsInteresting())
                    Nth4n1NumberTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                if (_4n1_index.IsCarmichaelX())
                    Nth4n1NumberTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                if (_4n1_index.IsCarmichael())
                    Nth4n1NumberTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                //ToolTip.SetToolTip(this.Nth4n1NumberTextBox, _4n1_index.FindInterestingSums(INTERESTINGX_COUNT));
            }
            UpdateToolTipNth4n1NumberTextBox();

            UpdateNumberKind(value);
            UpdateSumOfDivisors(value);
            UpdateSumOfNumbers(value);
            UpdatePCIndexChains(value);
            UpdateValueNavigator(value);

            DisplayNumerologyValues();
        }
        catch //(Exception ex)
        {
            // silence Microsoft Error in Math.Abs() which throws "2's complement error!" when value = double.MinValue!
            //MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
    }

    private void PrimeNumbersSumTextBox_KeyPress(object sender, KeyPressEventArgs e)
    {
        if (
            (e.KeyChar != (char)Keys.Back) &&
            (e.KeyChar != (char)Keys.Home) &&
            (e.KeyChar != (char)Keys.End) &&
            (e.KeyChar != (char)Keys.Delete) &&
            (e.KeyChar != (char)Keys.Up) &&
            (e.KeyChar != (char)Keys.Down) &&
            (e.KeyChar != (char)Keys.Left) &&
            (e.KeyChar != (char)Keys.Right) &&
            (e.KeyChar != '+') &&  // plus
            (e.KeyChar != '-') &&  // minus
            (!Char.IsDigit(e.KeyChar)) &&
            (ModifierKeys != Keys.Control) &&
            (ModifierKeys != Keys.Shift) &&
            (ModifierKeys != Keys.Alt)
           )
        {
            e.Handled = true;
        }
    }
    private void PrimeNumbersSumTextBox_KeyDown(object sender, KeyEventArgs e)
    {
        if (e.KeyCode == Keys.Up)
        {
            IncrementTargetSum(sender as Control);
            ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, null);
        }
        else if (e.KeyCode == Keys.Down)
        {
            DecrementTargetSum(sender as Control);
            ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, null);
        }
        else if (e.KeyCode == Keys.Enter)
        {
            FindRangeSumsToTarget();
        }
        else if ((ModifierKeys == Keys.Control) && (e.KeyCode == Keys.N))
        {
            this.Cursor = Cursors.WaitCursor;
            try
            {
                FindRangeableNumbers();
            }
            finally
            {
                this.Cursor = Cursors.Default;
            }
        }
        else if ((ModifierKeys == Keys.Control) && (e.KeyCode == Keys.P))
        {
            this.Cursor = Cursors.WaitCursor;
            try
            {
                FindPrimeRangeableNumbers();
            }
            finally
            {
                this.Cursor = Cursors.Default;
            }
        }
        else if ((ModifierKeys == Keys.Control) && (e.KeyCode == Keys.Q))
        {
            this.Cursor = Cursors.WaitCursor;
            try
            {
                FindCompositeRangeableNumbers();
            }
            finally
            {
                this.Cursor = Cursors.Default;
            }
        }
        else if ((ModifierKeys == Keys.Shift) && (e.KeyCode == Keys.N))
        {
            this.Cursor = Cursors.WaitCursor;
            try
            {
                FindNonRangeableNumbers();
            }
            finally
            {
                this.Cursor = Cursors.Default;
            }
        }
        else if ((ModifierKeys == Keys.Shift) && (e.KeyCode == Keys.P))
        {
            this.Cursor = Cursors.WaitCursor;
            try
            {
                FindPrimeNonRangeableNumbers();
            }
            finally
            {
                this.Cursor = Cursors.Default;
            }
        }
        else if ((ModifierKeys == Keys.Shift) && (e.KeyCode == Keys.Q))
        {
            this.Cursor = Cursors.WaitCursor;
            try
            {
                FindCompositeNonRangeableNumbers();
            }
            finally
            {
                this.Cursor = Cursors.Default;
            }
        }
    }
    private void PrimeNumbersSumTextBox_KeyUp(object sender, KeyEventArgs e)
    {
        int prime_number_sum = 0;
        PrimeNumbersSumTextBox.ForeColor = Color.Black;
        PrimeNumbersSumTextBox.BackColor = SystemColors.Window;
        if (int.TryParse(PrimeNumbersSumTextBox.Text, out prime_number_sum))
        {
            PrimeNumbersSumTextBox.ForeColor = Numbers.GetNumberTypeColor(prime_number_sum);
            PrimeNumbersSumTextBox.BackColor = (Numbers.Compare(prime_number_sum, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Window;
            if (Globals.EDITION != Edition.Standard)
                if (prime_number_sum.IsInterestingX(INTERESTINGX_COUNT))
                    PrimeNumbersSumTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
            if (prime_number_sum.IsInteresting())
                PrimeNumbersSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
            if (prime_number_sum.IsCarmichaelX())
                PrimeNumbersSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
            if (prime_number_sum.IsCarmichael())
                PrimeNumbersSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
            //ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, prime_number_sum.FindInterestingSums(INTERESTINGX_COUNT));
            PrimeNumbersSumTextBox.Refresh();
        }
    }
    private void IncrementTargetSum(Control control)
    {
        if (control == PrimeNumbersSumTextBox)
        {
            int target = 0;

            string text = PrimeNumbersSumTextBox.Text;
            if (text.Contains("-"))
            {
                FindRangeSumsToTarget();
                text = PrimeNumbersSumTextBox.Text;
            }

            if (int.TryParse(text, out target))
            {
                if (target < int.MaxValue)
                {
                    target++;
                }
            }

            PrimeNumbersSumTextBox.Text = target.ToString();
        }
    }
    private void DecrementTargetSum(Control control)
    {
        if (control == PrimeNumbersSumTextBox)
        {
            int target = 0;

            string text = PrimeNumbersSumTextBox.Text;
            if (text.Contains("-"))
            {
                FindRangeSumsToTarget();
                text = PrimeNumbersSumTextBox.Text;
            }

            if (int.TryParse(text, out target))
            {
                if (target > 0)
                {
                    target--;
                }
            }

            PrimeNumbersSumTextBox.Text = target.ToString();
        }
    }
    private void FindRangeSumsToTarget()
    {
        string text = PrimeNumbersSumTextBox.Text;
        if (text.Contains("-"))
        {
            CalculateAndDisplaySumOfTypeRange(text);
        }
        else // given target sum, find from_value and to_value
        {
            long target = 0L;
            if (long.TryParse(text, out target))
            {
                if (target > 0L)
                {
                    long from_value = 0L;
                    long to_value = 0L;

                    string find_range_type = "Prime";
                    bool found_prime_range = FindPrimeRangeSumsToTarget(target, ref from_value, ref to_value);
                    if (found_prime_range)
                    {
                        PrimeNumbersSumTextBox.Text = from_value.ToString() + "-" + to_value.ToString();
                        ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l][find_range_type] + " " + L[l]["range"] + " " + L[l]["sum"] + " = " + target.ToString());
                        PrimeNumbersSumTextBox.ForeColor = Numbers.GetNumberTypeColor(from_value);
                        PrimeNumbersSumTextBox.BackColor = (Numbers.Compare(target, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Window;
                        if (target.IsInteresting())
                            PrimeNumbersSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                        if (target.IsCarmichaelX())
                            PrimeNumbersSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                        if (target.IsCarmichael())
                            PrimeNumbersSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                        PrimeNumbersSumTextBox.Refresh();

                        // Version A71
                        if (ModifierKeys == Keys.Control)
                        {
                            VersesPrimeRangeSumsToTarget(target, from_value, to_value);
                        }
                    }

                    find_range_type = "Composite";
                    bool found_composite_range = FindCompositeRangeSumsToTarget(target, ref from_value, ref to_value);
                    if (found_composite_range)
                    {
                        // keep time to view prime range, then display composite range
                        if (found_prime_range)
                        {
                            //this.Cursor = Cursors.WaitCursor;
                            try
                            {
                                // 7 days per week, 12 months per year, 30 days per month
                                // 7*12*30 = 2520 is divisible by all numberrs from 1 to 10
                                Thread.Sleep(2520);
                            }
                            finally
                            {
                                //this.Cursor = Cursors.Default;
                            }
                        }

                        PrimeNumbersSumTextBox.Text = from_value.ToString() + "-" + to_value.ToString();
                        ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l][find_range_type] + " " + L[l]["range"] + " " + L[l]["sum"] + " = " + target.ToString());
                        PrimeNumbersSumTextBox.ForeColor = Numbers.GetNumberTypeColor(from_value);
                        PrimeNumbersSumTextBox.BackColor = (Numbers.Compare(target, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Window;
                        if (target.IsInteresting())
                            PrimeNumbersSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                        if (target.IsCarmichaelX())
                            PrimeNumbersSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                        if (target.IsCarmichael())
                            PrimeNumbersSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                        PrimeNumbersSumTextBox.Refresh();

                        // Version A71
                        if (ModifierKeys == Keys.Control)
                        {
                            VersesCompositeRangeSumsToTarget(target, from_value, to_value);
                        }
                    }
                }
            }
        }
    }
    private void CalculateAndDisplaySumOfTypeRange(string text)
    {
        string[] separators = { "-" };
        string[] parts = text.Split(separators, StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length == 2)
        {
            long from_value = 0L;
            long to_value = 0L;
            if ((long.TryParse(parts[0], out from_value)) && (long.TryParse(parts[1], out to_value)))
            {
                if ((from_value >= 0L) && (to_value > from_value))
                {
                    long sum = 0L;
                    if (from_value <= 1L)
                    {
                        if (to_value == 1L)
                        {
                            sum = to_value;
                            ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l]["1 is neither prime nor composite"]);
                        }
                        else if (Numbers.IsPrime(to_value))
                        {
                            from_value = 2L;
                        }
                        else if (Numbers.IsComposite(to_value))
                        {
                            from_value = 4L;
                        }
                    }

                    if (Numbers.IsPrime(from_value)) // if prime, sum up primes from_value to p <= to_value
                    {
                        int from_index = Numbers.PrimeIndexOf(from_value);
                        int to_index = Numbers.PrimeIndexOf(to_value);
                        while (to_index == -1)
                        {
                            to_value--;
                            to_index = Numbers.PrimeIndexOf(to_value);
                        }
                        if (from_value <= to_value)
                        {
                            for (int i = from_index; i <= to_index; i++)
                            {
                                sum += Numbers.Primes[i];
                            }
                            ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l]["Sum of prime numbers from"] + " " + from_value.ToString() + " " + L[l]["to"] + " " + to_value.ToString());
                        }
                    }
                    else if (Numbers.IsComposite(from_value)) // if composite, sum up composite from_value to c <= to_value
                    {
                        int from_index = Numbers.CompositeIndexOf(from_value);
                        int to_index = Numbers.CompositeIndexOf(to_value);
                        while (to_index == -1)
                        {
                            to_value--;
                            to_index = Numbers.CompositeIndexOf(to_value);
                        }
                        if (from_value <= to_value)
                        {
                            for (int i = from_index; i <= to_index; i++)
                            {
                                sum += Numbers.Composites[i];
                            }
                            ToolTip.SetToolTip(this.PrimeNumbersSumTextBox, L[l]["Sum of composite numbers from"] + " " + from_value.ToString() + " " + L[l]["to"] + " " + to_value.ToString());
                        }
                    }
                    PrimeNumbersSumTextBox.Text = sum.ToString();
                    PrimeNumbersSumTextBox.ForeColor = Numbers.GetNumberTypeColor(sum);
                    PrimeNumbersSumTextBox.BackColor = (Numbers.Compare(sum, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Window;
                    if (sum.IsInteresting())
                        PrimeNumbersSumTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                    if (sum.IsCarmichaelX())
                        PrimeNumbersSumTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                    if (sum.IsCarmichael())
                        PrimeNumbersSumTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                    PrimeNumbersSumTextBox.Refresh();
                }
            }
        }
    }
    private bool FindPrimeRangeSumsToTarget(long target, ref long from_value, ref long to_value)
    {
        long sum = 0L;
        int start_index = 0;
        long start_p = 2L;
        bool found = false;
        do
        {
            int index = start_index;
            if ((index >= 0) && (index < Numbers.Primes.Count))
            {
                sum = Numbers.Primes[index];
                from_value = sum;
                do
                {
                    index++;
                    if ((index >= 0) && (index < Numbers.Primes.Count))
                    {
                        long p = Numbers.Primes[index];

                        sum += p;
                        if (sum == target)
                        {
                            to_value = p;
                            found = true;
                            break;
                        }
                    }
                    else
                        break;
                } while (sum < target);
                if (found)
                    break;
            }
            else
                break;

            start_index++;
            if ((start_index >= 0) && (start_index < Numbers.Primes.Count))
            {
                start_p = Numbers.Primes[start_index];
            }
            else
                break;
        } while (start_p < target);

        return found;
    }
    private bool FindCompositeRangeSumsToTarget(long target, ref long from_value, ref long to_value)
    {
        long sum = 0L;
        int start_index = 0;
        long start_c = 2L;
        bool found = false;
        do
        {
            int index = start_index;
            if ((index >= 0) && (index < Numbers.Composites.Count))
            {
                sum = Numbers.Composites[index];
                from_value = sum;
                do
                {
                    index++;
                    if ((index >= 0) && (index < Numbers.Composites.Count))
                    {
                        long c = Numbers.Composites[index];

                        sum += c;
                        if (sum == target)
                        {
                            to_value = c;
                            found = true;
                            break;
                        }
                    }
                    else
                        break;
                } while (sum < target);
                if (found)
                    break;
            }
            else
                break;

            start_index++;
            if ((start_index >= 0) && (start_index < Numbers.Composites.Count))
            {
                start_c = Numbers.Composites[start_index];
            }
            else
                break;
        } while (start_c < target);

        return found;
    }
    private void VersesPrimeRangeSumsToTarget(long target, long from_value, long to_value)
    {
        if (FindPrimeRangeSumsToTarget(target, ref from_value, ref to_value))
        {
            int from_index = Numbers.PrimeIndexOf(from_value);
            int to_index = Numbers.PrimeIndexOf(to_value);

            StringBuilder str = new StringBuilder();

            int count = 0;
            bool range_within_chapters = false;
            int max = (int)Numbers.Primes[to_index];
            foreach (Chapter chapter in m_client.Book.Chapters)
            {
                if (chapter.Verses.Count >= max)
                {
                    range_within_chapters = true;
                    str.AppendLine("#" + "\t" + "Chapter" + "\t" + "Name" + "\t" + "Verses" + "\t" + "Words" + "\t" + "Letters" + "\t" + "Text");

                    ++count;
                    int verse_sum = 0;
                    int word_sum = 0;
                    int letter_sum = 0;
                    for (int i = from_index; i <= to_index; i++)
                    {
                        int v = (int)Numbers.Primes[i];
                        verse_sum += chapter.Verses[v - 1].NumberInChapter;
                        word_sum += chapter.Verses[v - 1].Words.Count;
                        letter_sum += chapter.Verses[v - 1].Letters.Count;

                        string line =
                            "\t" + chapter.SortedNumber +
                            "\t" + chapter.Name +
                            "\t" + chapter.Verses[v - 1].NumberInChapter +
                            "\t" + chapter.Verses[v - 1].Words.Count +
                            "\t" + chapter.Verses[v - 1].Letters.Count +
                            "\t" + chapter.Verses[v - 1].Text
                            ;
                        str.AppendLine(line);
                    }
                    str.AppendLine(count + "\t" + "Sum" + "\t" + "---" + "\t" + verse_sum + "\t" + word_sum + "\t" + letter_sum + "\t" + "------------");

                    str.AppendLine();
                    str.AppendLine();
                }
            }

            // try verse numbers in Book (not in chapter)
            if (!range_within_chapters)
            {
                if (m_client.Book.Verses.Count >= max)
                {
                    str.AppendLine("Verse" + "\t" + "Chapter" + "\t" + "Name" + "\t" + "Verses" + "\t" + "Words" + "\t" + "Letters" + "\t" + "Text");

                    int book_verse_sum = 0;
                    int verse_sum = 0;
                    int word_sum = 0;
                    int letter_sum = 0;
                    for (int i = from_index; i <= to_index; i++)
                    {
                        int v = (int)Numbers.Primes[i];
                        Verse verse = m_client.Book.Verses[v - 1];
                        book_verse_sum += verse.Number;
                        verse_sum += verse.NumberInChapter;
                        word_sum += verse.Words.Count;
                        letter_sum += verse.Letters.Count;

                        string line = verse.Number +
                            "\t" + verse.Chapter.SortedNumber +
                            "\t" + verse.Chapter.Name +
                            "\t" + verse.NumberInChapter +
                            "\t" + verse.Words.Count +
                            "\t" + verse.Letters.Count +
                            "\t" + verse.Text
                            ;
                        str.AppendLine(line);
                    }
                    str.AppendLine(book_verse_sum + "\t" + "Sum" + "\t" + "---" + "\t" + verse_sum + "\t" + word_sum + "\t" + letter_sum + "\t" + "------------");

                    str.AppendLine();
                    str.AppendLine();
                }
            }

            string path = Globals.STATISTICS_FOLDER + Path.DirectorySeparatorChar + "prime_rangeable" + "_" + target + "_" + ".txt";
            FileHelper.SaveText(path, str.ToString());
            FileHelper.DisplayFile(path);
        }
    }
    private void VersesCompositeRangeSumsToTarget(long target, long from_value, long to_value)
    {
        if (FindCompositeRangeSumsToTarget(target, ref from_value, ref to_value))
        {
            int from_index = Numbers.CompositeIndexOf(from_value);
            int to_index = Numbers.CompositeIndexOf(to_value);

            StringBuilder str = new StringBuilder();

            int count = 0;
            bool range_within_chapters = false;
            int max = (int)Numbers.Composites[to_index];
            foreach (Chapter chapter in m_client.Book.Chapters)
            {
                if (chapter.Verses.Count >= max)
                {
                    range_within_chapters = true;
                    str.AppendLine("#" + "\t" + "Chapter" + "\t" + "Name" + "\t" + "Verses" + "\t" + "Words" + "\t" + "Letters" + "\t" + "Text");

                    ++count;
                    int verse_sum = 0;
                    int word_sum = 0;
                    int letter_sum = 0;
                    for (int i = from_index; i <= to_index; i++)
                    {
                        int v = (int)Numbers.Composites[i];
                        verse_sum += chapter.Verses[v - 1].NumberInChapter;
                        word_sum += chapter.Verses[v - 1].Words.Count;
                        letter_sum += chapter.Verses[v - 1].Letters.Count;

                        string line =
                            "\t" + chapter.SortedNumber +
                            "\t" + chapter.Name +
                            "\t" + chapter.Verses[v - 1].NumberInChapter +
                            "\t" + chapter.Verses[v - 1].Words.Count +
                            "\t" + chapter.Verses[v - 1].Letters.Count +
                            "\t" + chapter.Verses[v - 1].Text
                            ;
                        str.AppendLine(line);
                    }
                    str.AppendLine(count + "\t" + "Sum" + "\t" + "---" + "\t" + verse_sum + "\t" + word_sum + "\t" + letter_sum + "\t" + "------------");

                    str.AppendLine();
                    str.AppendLine();
                }
            }

            // try verse numbers in Book (not in chapter)
            if (!range_within_chapters)
            {
                if (m_client.Book.Verses.Count >= max)
                {
                    str.AppendLine("Verse" + "\t" + "Chapter" + "\t" + "Name" + "\t" + "Verses" + "\t" + "Words" + "\t" + "Letters" + "\t" + "Text");

                    int book_verse_sum = 0;
                    int verse_sum = 0;
                    int word_sum = 0;
                    int letter_sum = 0;
                    for (int i = from_index; i <= to_index; i++)
                    {
                        int v = (int)Numbers.Composites[i];
                        Verse verse = m_client.Book.Verses[v - 1];
                        book_verse_sum += verse.Number;
                        verse_sum += verse.NumberInChapter;
                        word_sum += verse.Words.Count;
                        letter_sum += verse.Letters.Count;

                        string line = verse.Number +
                            "\t" + verse.Chapter.SortedNumber +
                            "\t" + verse.Chapter.Name +
                            "\t" + verse.NumberInChapter +
                            "\t" + verse.Words.Count +
                            "\t" + verse.Letters.Count +
                            "\t" + verse.Text
                            ;
                        str.AppendLine(line);
                    }
                    str.AppendLine(book_verse_sum + "\t" + "Sum" + "\t" + "---" + "\t" + verse_sum + "\t" + word_sum + "\t" + letter_sum + "\t" + "------------");

                    str.AppendLine();
                    str.AppendLine();
                }
            }

            string path = Globals.STATISTICS_FOLDER + Path.DirectorySeparatorChar + "composite_rangeable" + "_" + target + "_" + ".txt";
            FileHelper.SaveText(path, str.ToString());
            FileHelper.DisplayFile(path);
        }
    }
    private void FindRangeableNumbers()
    {
        List<string> result = new List<string>();

        long from_value = 0L;
        long to_value = 0L;
        int limit = (Globals.EDITION == Edition.Standard) ? 1000 :
                    (Globals.EDITION == Edition.Research) ? 10000 :
                    (Globals.EDITION == Edition.Ultimate) ? 100000 :
                    (Globals.EDITION == Edition.BigNumbers) ? 1000000 : 0;
        for (int target = 1; target <= limit; target++)
        {
            string line = null;

            bool found_prime_range = false;
            if (FindPrimeRangeSumsToTarget(target, ref from_value, ref to_value))
            {
                line = target.ToString() + "\t" + from_value.ToString() + "-" + to_value.ToString();
                found_prime_range = true;
            }

            if (FindCompositeRangeSumsToTarget(target, ref from_value, ref to_value))
            {
                if (found_prime_range && (line != null))
                {
                    line += "\t" + from_value.ToString() + "-" + to_value.ToString();
                }
                else
                {
                    line = target.ToString() + "\t" + from_value.ToString() + "-" + to_value.ToString();
                }
            }

            if (line != null)
            {
                result.Add(line);
            }
        }

        string path = Globals.STATISTICS_FOLDER + Path.DirectorySeparatorChar + "rangeable" + ".txt";
        FileHelper.SaveLines(path, result);
        FileHelper.DisplayFile(path);
    }
