    private void UpdateBackColors()
    {
        int chapter_count;
        if (int.TryParse(ChaptersTextBox.Text, out chapter_count))
        {
            ChaptersTextBox.BackColor = (Numbers.Compare(chapter_count, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.ControlLight;
            if (Globals.EDITION != Edition.Standard)
                if (chapter_count.IsInterestingX(INTERESTINGX_COUNT))
                    ChaptersTextBox.BackColor = Numbers.INTERESTINGX_NUMBER_COLOR;
            if (chapter_count.IsInteresting())
                ChaptersTextBox.BackColor = Numbers.INTERESTING_NUMBER_COLOR;
            if (chapter_count.IsCarmichaelX())
                ChaptersTextBox.BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
            if (chapter_count.IsCarmichael())
                ChaptersTextBox.BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
