            ToolTip.SetToolTip(this.LetterNumberSumTextBox, letter_number_sum.FindInterestingSums(INTERESTINGX_COUNT));
            LetterNumberSumTextBox.Refresh();
        }

        long value;
        if (long.TryParse(ValueTextBox.Text, out value))
        {
            ValueTextBox.BackColor = (Numbers.Compare(value, m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : SystemColors.Window;
            if (Globals.EDITION != Edition.Standard)
                if (value.IsInterestingX(INTERESTINGX_COUNT))
