        if (m_current_verse != null)
        {
            UpdateVersePositions(m_current_verse);
        }

        ValuesSequenceScopeComboBox_SelectedIndexChanged(null, null);
    }

    private void CalculateAndDisplayCounts(string text)
    {
        ChapterNumberSumTextBox.Text = "";
        VerseNumberSumTextBox.Text = "";
        WordNumberSumTextBox.Text = "";
        LetterNumberSumTextBox.Text = "";

        if (!String.IsNullOrEmpty(text))
        {
            if (m_client != null)
            {
                // in all cases
                if (m_client.NumerologySystem != null)
                {
                    if (!m_with_diacritics)
                    {
                        text = text.Simplify(m_client.NumerologySystem.TextMode);
                    }

                    text = text.Replace("\t", "");
                    text = text.Replace("_", "");
                    text = text.Replace(Constants.ORNATE_RIGHT_PARENTHESIS, "");
                    text = text.Replace(Constants.ORNATE_LEFT_PARENTHESIS, "");
                    foreach (char character in Constants.INDIAN_DIGITS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    foreach (char character in Constants.ARABIC_DIGITS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    foreach (char character in Constants.SYMBOLS)
                    {
                        text = text.Replace(character.ToString(), "");
                    }
                    if (!m_with_diacritics)
                    {
                        text = text.Simplify(m_client.NumerologySystem.TextMode);
                    }
                    while (text.Contains("  "))
                    {
                        text = text.Replace("  ", " ");
                    }
                    text = text.Replace("\r\n", "\n");

                    int chapter_count = 1;
                    int verse_count = 1;
                    int word_count = 1;
                    int letter_count = 0;
                    for (int i = 0; i < text.Length; i++)
                    {
                        if (text[i] == '\n')
                        {
                            if (i > 0)
                            {
                                if (text[i - 1] != '\n')
                                {
                                    word_count++;
                                }
                            }

                            verse_count++;
                        }
                        else if (text[i] == ' ')
                        {
                            word_count++;
                        }
                        else
                        {
                            letter_count++;
                        }
                    }
                    DisplayCounts(chapter_count, verse_count, word_count, letter_count, 0, 0, 0, 0);
                    DisplayMathsChapterVerseSums(null); // reset C, V, C+V, C-V, C×V, C÷V, etc.
                }
            }
        }
        else
        {
            DisplayCounts(0, 0, 0, 0, 0, 0, 0, 0);
            DisplayMathsChapterVerseSums(null); // reset C, V, C+V, C-V, C×V, C÷V, etc.
        }
    }
    private void CalculateAndDisplayCounts()
    {
        List<Verse> verses = GetDisplayedVerses();
        if (verses != null)
        {
            CalculateAndDisplayCounts(verses);
        }
    }
    private void CalculateAndDisplayCounts(List<Word> words)
    {
        if (words != null)
        {
            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    StringBuilder str = new StringBuilder();
                    foreach (Word word in words)
                    {
                        str.AppendLine(word.Text);
                    }
                    m_current_text = str.ToString();

                    List<Verse> verses = m_client.Book.GetVerses(words);
                    List<Chapter> chapters = m_client.Book.GetChapters(verses);
                    if (chapters != null)
                    {
                        int chapter_count = chapters.Count;
                        int verse_count = verses.Count;
                        int word_count = words.Count;
                        int letter_count = 0;
                        int chapter_number_sum = 0;
                        int verse_number_sum = 0;
                        int word_number_sum = 0;
                        int letter_number_sum = 0;
                        foreach (Chapter chapter in chapters)
                        {
                            if (chapter != null)
                            {
                                chapter_number_sum += chapter.SortedNumber;
                            }
                        }
                        foreach (Verse verse in verses)
                        {
                            if (verse != null)
                            {
                                verse_number_sum += verse.NumberInChapter;
                            }
                        }
                        foreach (Word word in words)
                        {
                            word_number_sum += word.NumberInVerse;
                            if ((word.Letters != null) && (word.Letters.Count > 0))
                            {
                                letter_count += word.Letters.Count;
                                foreach (Letter letter in word.Letters)
                                {
                                    letter_number_sum += letter.NumberInWord;
                                }
                            }
                        }

                        DisplayCounts(chapter_count, verse_count, word_count, letter_count, chapter_number_sum, verse_number_sum, word_number_sum, letter_number_sum);
                        DisplayMathsChapterVerseSums(verses); // update C, V, C+V, C-V, C×V, C÷V, etc.
                    }
                }
            }
        }
        else
        {
            DisplayCounts(0, 0, 0, 0, 0, 0, 0, 0);
            DisplayMathsChapterVerseSums(null); // reset C, V, C+V, C-V, C×V, C÷V, etc.
        }
    }
    private void CalculateAndDisplayCounts(List<Verse> verses)
    {
        if (verses != null)
        {
            if (m_client != null)
            {
                if (m_client.Book != null)
                {
                    StringBuilder str = new StringBuilder();
                    foreach (Verse verse in verses)
                    {
                        str.AppendLine(verse.Text);
                    }
                    if (str.Length > 2)
                    {
                        str.Remove(str.Length - 2, 2); // "\r\n"
                    }
                    m_current_text = str.ToString();

                    List<Chapter> chapters = m_client.Book.GetChapters(verses);
                    if (chapters != null)
                    {
                        int chapter_count = chapters.Count;
                        int verse_count = verses.Count;
                        int word_count = 0;
                        int letter_count = 0;
                        int chapter_number_sum = 0;
                        int verse_number_sum = 0;
                        int word_number_sum = 0;
                        int letter_number_sum = 0;
                        foreach (Chapter chapter in chapters)
                        {
                            if (chapter != null)
                            {
                                chapter_number_sum += chapter.SortedNumber;
                            }
                        }

                        foreach (Verse verse in verses)
                        {
                            word_count += verse.Words.Count;
                            letter_count += verse.Letters.Count;

                            verse_number_sum += verse.NumberInChapter;
                            if (verse.Words != null)
                            {
                                foreach (Word word in verse.Words)
                                {
                                    word_number_sum += word.NumberInVerse;
                                    if ((word.Letters != null) && (word.Letters.Count > 0))
                                    {
                                        foreach (Letter letter in word.Letters)
                                        {
                                            letter_number_sum += letter.NumberInWord;
                                        }
                                    }
                                }
                            }
                        }
                        DisplayCounts(chapter_count, verse_count, word_count, letter_count, chapter_number_sum, verse_number_sum, word_number_sum, letter_number_sum);
                        DisplayMathsChapterVerseSums(verses); // update C, V, C+V, C-V, C×V, C÷V, etc.
                    }
                }
            }
        }
        else
        {
            DisplayCounts(0, 0, 0, 0, 0, 0, 0, 0);
            DisplayMathsChapterVerseSums(null); // reset C, V, C+V, C-V, C×V, C÷V, etc.
        }
    }
    private void CalculateAndDisplayCounts(Verse verse)
