    private int m_original_system_count = 0;
    private Label[] m_numerology_value_labels = null;
    private void CreateNumerologyValueLabels()
    {
        if (m_numerology_value_labels == null) // at startup only
        {
            if (m_client != null)
            {
                if (m_client.NumerologySystem != null)
                {
                    m_original_system_count = 0;
                    foreach (NumerologySystem ns in m_client.LoadedNumerologySystems.Values)
                    {
                        if (ns.TextMode == "Original")
                        {
                            m_original_system_count++;
                        }
                    }

                    if (NumerologyValuesPanel != null)
                    {
                        NumerologyValuesPanel.BackColor = Color.White;
                        int x_shift = FoundMatchesTotalLabel.Left + FoundMatchesTotalLabel.Width + 2;
                        int labels_width = NumerologyValuesPanel.Width - x_shift;
                        int max = m_original_system_count + 1; // +1 for SimplifiedDots

                        int top = 1;
                        int width = labels_width / max;
                        int height = NumerologyValuesPanel.Height - top;
                        // rest tops and heights of existing controls
                        List<Control> controls = GetDescendentControls(NumerologyValuesPanel);
                        foreach (Control control in controls)
                        {
                            control.Top = top;
                            control.Height = height;
                        }

                        m_numerology_value_labels = new Label[max];
                        for (int i = 0; i < max; i++)
                        {
                            m_numerology_value_labels[i] = new Label();

                            int left = x_shift + i * width;
                            m_numerology_value_labels[i].Name = "NumerologyValueLabel" + i.ToString();
                            m_numerology_value_labels[i].BackColor = Color.Transparent;
                            m_numerology_value_labels[i].Font = new Font("Microsoft Sans Serif", 10.0F);
                            m_numerology_value_labels[i].ForeColor = Color.Blue;
                            m_numerology_value_labels[i].Location = new Point(left, top);
                            m_numerology_value_labels[i].Size = new Size(width, height);
                            m_numerology_value_labels[i].TabIndex = 101 + i;
                            m_numerology_value_labels[i].Text = "8317";
                            m_numerology_value_labels[i].TextAlign = ContentAlignment.MiddleCenter;
                            if (i <= max - 1)
                            {
                                m_numerology_value_labels[i].Anchor = ((AnchorStyles)(AnchorStyles.Bottom | AnchorStyles.Left));
                                m_numerology_value_labels[i].Cursor = Cursors.Hand;
                                m_numerology_value_labels[i].Click += new EventHandler(this.NumerologyValueLabel_Click);
                            }
                            else // i > max - 1
                            {
                                m_numerology_value_labels[i].Anchor = ((AnchorStyles)(AnchorStyles.Bottom | AnchorStyles.Left | AnchorStyles.Right));
                                m_numerology_value_labels[i].Cursor = Cursors.Default;
                                m_numerology_value_labels[i].Click += new EventHandler(this.Control_CtrlClick);
                            }

                            NumerologyValuesPanel.Controls.Add(m_numerology_value_labels[i]);
                        }
                    }
                }
            }
        }
    }
    private void ArrangeNumerologyValueLabels()
    {
        if (NumerologyValuesPanel != null)
        {
            int x_shift = FoundMatchesTotalLabel.Left + FoundMatchesTotalLabel.Width + 2;
            int panel_width = NumerologyValuesPanel.Width - x_shift;
            int max = m_original_system_count + 1; // +1 for SimplifiedDots
            if (max > 0)
            {
                int top = 1;
                int width = panel_width / max;
                int height = NumerologyValuesPanel.Height - top;

                if (m_numerology_value_labels != null)
                {
                    if (m_numerology_value_labels.Length == max)
                    {
                        for (int i = 0; i < max; i++)
                        {
                            int left = x_shift + i * width;
                            m_numerology_value_labels[i].Location = new Point(left, top);
                            m_numerology_value_labels[i].Size = new Size(width, height);
                        }
                    }
                }
            }
        }
    }
    private void ClearNumerologyValueLabels()
    {
        if (m_numerology_value_labels != null)
        {
            for (int i = 0; i < m_numerology_value_labels.Length; i++)
            {
                if (m_numerology_value_labels[i] != null)
                {
                    m_numerology_value_labels[i].Text = "";
                    m_numerology_value_labels[i].Font = new Font("Microsoft Sans Serif", 10.0F);
                    m_numerology_value_labels[i].BackColor = Color.Transparent;
                    m_numerology_value_labels[i].BorderStyle = BorderStyle.None;
                }
            }
        }
    }
    private void SelectNumerologyValueLabel(string name)
    {
        if (m_numerology_value_labels != null)
        {
            for (int i = 0; i < m_numerology_value_labels.Length; i++)
            {
                if (m_numerology_value_labels[i] != null)
                {
                    string tag = m_numerology_value_labels[i].Tag.ToString();
                    if (tag == name)
                    {
                        m_numerology_value_labels[i].BorderStyle = BorderStyle.FixedSingle;
                    }
                    else
                    {
                        m_numerology_value_labels[i].BorderStyle = BorderStyle.None;
                    }
                }
            }
        }
    }
    private List<string> m_numerology_system_names = null;
    private void DisplayNumerologyValues()
    {
        if (m_numerology_value_labels != null)
        {
            if (m_numerology_value_labels.Length == m_original_system_count + 1)
            {
                ClearNumerologyValueLabels();

                if (m_client != null)
                {
                    if (m_client.LoadedNumerologySystems != null)
                    {
                        if (m_numerology_system_names == null)
                        {
                            m_numerology_system_names = new List<string>();
                            foreach (NumerologySystem ns in m_client.LoadedNumerologySystems.Values)
                            {
                                if (ns.TextMode == "Original")
                                {
                                    m_numerology_system_names.Add(ns.LetterOrder + "_" + ns.LetterValue);
                                }
                            }
                        }

                        if (m_numerology_system_names != null)
                        {
                            if (m_numerology_system_names.Count >= m_original_system_count)
                            {
                                string text_mode = m_client.NumerologySystem.TextMode;
                                if (text_mode == "SimplifiedDots")
                                    text_mode = "Original"; // restore Original

                                int max = m_original_system_count + 1; // +1 for SimplifiedDots
                                string[] names = new string[max];
                                for (int i = 0; i < max - 1; i++)
                                {
                                    names[i] = text_mode + "_" + m_numerology_system_names[i];
                                    ToolTip.SetToolTip(this.m_numerology_value_labels[i], m_numerology_system_names[i]);
                                    m_numerology_value_labels[i].Tag = m_numerology_system_names[i];

                                    // display default_numerology_system in BOLD
                                    if (m_numerology_system_names[i] == NumerologySystem.DEFAULT_SUB_NAME)
                                    {
                                        m_numerology_value_labels[i].Font = new Font("Microsoft Sans Serif", 10.0F, FontStyle.Bold);
                                    }
                                    else
                                    {
                                        m_numerology_value_labels[i].Font = new Font("Microsoft Sans Serif", 10.0F);
                                    }
                                }
                                names[max - 1] = "SimplifiedDots_Letters_Dots";
                                ToolTip.SetToolTip(this.m_numerology_value_labels[max - 1], "Letters_Dots");
                                m_numerology_value_labels[max - 1].Tag = "Letters_Dots";

                                long[] values = new long[max];
                                for (int i = 0; i < max; i++)
                                {
                                    values[i] = m_client.LoadedNumerologySystems.ContainsKey(names[i]) ? m_client.LoadedNumerologySystems[names[i]].CalculateValue(m_current_text) : 0L;
                                    m_numerology_value_labels[i].Text = values[i].ToString();
                                    m_numerology_value_labels[i].ForeColor = Numbers.GetNumberTypeColor(values[i]);
                                    m_numerology_value_labels[i].BackColor = (Numbers.Compare((int)values[i], m_divisor, ComparisonOperator.DivisibleBy, 0)) ? Numbers.DIVISOR_COLOR : Color.Transparent;
                                    if (values[i].IsInteresting())
                                        m_numerology_value_labels[i].BackColor = Numbers.INTERESTING_NUMBER_COLOR;
                                    if (values[i].IsCarmichaelX())
                                        m_numerology_value_labels[i].BackColor = Numbers.CARMICHAELX_NUMBER_COLOR;
                                    if (values[i].IsCarmichael())
                                        m_numerology_value_labels[i].BackColor = Numbers.CARMICHAEL_NUMBER_COLOR;
                                    m_numerology_value_labels[i].Refresh();
                                }
                            }

                            // select current numerology system
                            int index = NumerologySystemComboBox.SelectedIndex;
                            if (index != -1)
                            {
                                string name = NumerologySystemComboBox.SelectedItem.ToString();
                                SelectNumerologyValueLabel(name);
                            }
                        }
                    }
                }
            }
        }
    }
    private string m_text_mode_backup = null;
    private void NumerologyValueLabel_Click(object sender, EventArgs e)
    {
        if (m_numerology_system_names != null)
        {
            if (m_numerology_system_names.Count >= m_original_system_count)
            {
                Label label = sender as Label;
                if (label != null)
                {
                    if (label.Name.StartsWith("NumerologyValueLabel"))
                    {
                        int pos = "NumerologyValueLabel".Length;
                        string i_str = label.Name.Substring(pos);
                        int i;
                        if (int.TryParse(i_str, out i))
                        {
                            if (i < m_original_system_count)
                            {
                                if (TextModeComboBox.SelectedItem != null)
                                {
                                    if (TextModeComboBox.SelectedItem.ToString() == "SimplifiedDots")
                                    {
                                        TextModeComboBox.SelectedItem = m_text_mode_backup;
                                    }
                                }
                                NumerologySystemComboBox.SelectedItem = m_numerology_system_names[i];
                            }
                            else // i == max - 1
                            {
                                m_text_mode_backup = m_client.NumerologySystem.TextMode;
                                TextModeComboBox.SelectedItem = "SimplifiedDots";
                                NumerologySystemComboBox.SelectedItem = "Letters_Dots";
                            }
                        }
                    }
                }
            }
        }
    }

