    private void UpdateValueNavigator(long value)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (m_client != null)
        {
            if (m_client.Book != null)
            {
                VerseByVerseNumberTextBox.Text = "---:---";
                ToolTip.SetToolTip(this.VerseByVerseNumberTextBox, null);
                VerseByVerseNumberTextBox.Refresh();

                VerseByWordNumberTextBox.Text = "---:---";
                ToolTip.SetToolTip(this.VerseByWordNumberTextBox, null);
                VerseByWordNumberTextBox.Refresh();

                VerseByLetterNumberTextBox.Text = "---:---";
                ToolTip.SetToolTip(this.VerseByLetterNumberTextBox, null);
                VerseByLetterNumberTextBox.Refresh();

                Verse verse = m_client.Book.GetVerseByNumber((int)value);
                if (verse != null)
                {
                    VerseByVerseNumberTextBox.Text = verse.Address;
                    ToolTip.SetToolTip(this.VerseByVerseNumberTextBox, L[l]["Verse number = "] + ValueTextBox.Text + "\r\n" + verse.Text);
                }

                Word word = m_client.Book.GetWordByNumber((int)value);
                if (word != null)
                {
                    verse = word.Verse;
                    if (verse != null)
                    {
                        VerseByWordNumberTextBox.Text = verse.Address;
                        ToolTip.SetToolTip(this.VerseByWordNumberTextBox, L[l]["Verse with word number = "] + ValueTextBox.Text + "\r\n" + verse.Text);
                    }
                }

                Letter letter = m_client.Book.GetLetterByNumber((int)value);
                if (letter != null)
                {
                    word = letter.Word;
                    if (word != null)
                    {
                        verse = word.Verse;
                        if (verse != null)
                        {
                            VerseByLetterNumberTextBox.Text = verse.Address;
                            ToolTip.SetToolTip(this.VerseByLetterNumberTextBox, L[l]["Verse with letter number = "] + ValueTextBox.Text + "\r\n" + verse.Text);
                        }
                    }
                }
            }
        }
    }
    private Stack<int> m_navigation_undo_stack = new Stack<int>();
    private Stack<int> m_navigation_redo_stack = new Stack<int>();
    private void ValueNavigatorTextBox_MouseHover(object sender, EventArgs e)
    {
        TextBox control = (sender as TextBox);
        if (control != null)
        {
            control.Focus();
            control.SelectionLength = 0;
        }
    }
    private void ValueNavigatorTextBox_KeyDown(object sender, KeyEventArgs e)
    {
        if (ModifierKeys == Keys.Control)
        {
            VerseByVerseNumberTextBox.Cursor = Cursors.Hand;
            VerseByWordNumberTextBox.Cursor = Cursors.Hand;
            VerseByLetterNumberTextBox.Cursor = Cursors.Hand;
        }
        else
        {
            VerseByVerseNumberTextBox.Cursor = Cursors.IBeam;
            VerseByWordNumberTextBox.Cursor = Cursors.IBeam;
            VerseByLetterNumberTextBox.Cursor = Cursors.IBeam;
        }
    }
    private void ValueNavigatorTextBox_KeyUp(object sender, KeyEventArgs e)
    {
        ValueNavigatorTextBox_KeyDown(sender, e);
    }
    private void ValueNavigatorTextBox_Click(object sender, EventArgs e)
    {
        if (ModifierKeys == Keys.Control)
        {
            TextBox control = (sender as TextBox);
            if (control != null)
            {
                string verse_address = control.Text;
                if ((verse_address.Length > 0) && (verse_address != "---:---"))
                {
                    Verse verse = GetCurrentVerse();
                    if (verse != null)
                    {
                        int current_verse_number = verse.Number;
                        m_navigation_undo_stack.Push(current_verse_number);
                        m_navigation_redo_stack.Clear();
                        DisplayVerse(verse_address);
                    }
                }

                control.Focus();
                control.SelectionLength = 0;
            }
        }
    }
    private void DisplayVerse(Verse verse)
    {
        if (m_client != null)
        {
            if (m_client.Book != null)
            {
                if (verse != null)
                {
                    if (verse.Chapter != null)
                    {
                        try
                        {
                            int chapter_number = verse.Chapter.SortedNumber;
                            int verse_number_in_chapter = verse.NumberInChapter;
                            int verse_number = m_client.Book.GetVerseNumber(chapter_number, verse_number_in_chapter);
                            if ((verse_number >= VerseNumericUpDown.Minimum) && (verse_number <= VerseNumericUpDown.Maximum))
                            {
                                VerseNumericUpDown.Focus();
                                VerseNumericUpDown.Value = verse_number;
                            }
                        }
                        catch
                        {
                            // ---:--- or any non-numeric text
                            return;
                        }
                    }
                }
            }
        }
    }
    private void DisplayVerse(string verse_address)
    {
        if (m_client != null)
        {
            if (m_client.Book != null)
            {
                int chapter_number = 0;
                int verse_number_in_chapter = 0;
                int verse_number = 0;

                string[] parts = verse_address.Split(':');
                if (parts.Length == 2)
                {
                    try
                    {
                        chapter_number = int.Parse(parts[0]);
                        verse_number_in_chapter = int.Parse(parts[1]);
                        verse_number = m_client.Book.GetVerseNumber(chapter_number, verse_number_in_chapter);
                        if ((verse_number >= VerseNumericUpDown.Minimum) && (verse_number <= VerseNumericUpDown.Maximum))
                        {
                            Verse verse = m_client.Book.GetVerseByNumber(verse_number);
                            if (verse != null)
                            {
                                DisplayVerse(verse);
                            }
                        }
                    }
                    catch
                    {
                        // ---:--- or any non-numeric text
                        return;
                    }
                }
                UndoValueNavigationLabel.ForeColor = (m_navigation_undo_stack.Count > 0) ? Color.Yellow : Color.LightGray;
                RedoValueNavigationLabel.ForeColor = (m_navigation_redo_stack.Count > 0) ? Color.Yellow : Color.LightGray;
            }
        }
    }
    private void UndoGotoVerse()
    {
        if (m_client != null)
        {
            if (m_client.Book != null)
            {
                if (m_client.Book.Verses != null)
                {
                    if (m_navigation_undo_stack.Count > 0)
                    {
                        Verse verse = GetCurrentVerse();
                        if (verse != null)
                        {
                            int current_verse_number = verse.Number;
                            m_navigation_redo_stack.Push(current_verse_number);
                            int verse_number = m_navigation_undo_stack.Pop();
                            string verse_address = m_client.Book.Verses[verse_number - 1].Address;
                            DisplayVerse(verse_address);
                        }
                    }
                }
            }
        }
    }
    private void RedoGotoVerse()
    {
        if (m_client != null)
        {
            if (m_client.Book != null)
            {
                if (m_client.Book.Verses != null)
                {
                    if (m_navigation_redo_stack.Count > 0)
                    {
                        Verse verse = GetCurrentVerse();
                        if (verse != null)
                        {
                            int current_verse_number = verse.Number;
                            m_navigation_undo_stack.Push(current_verse_number);
                            int verse_number = m_navigation_redo_stack.Pop();
                            string verse_address = m_client.Book.Verses[verse_number - 1].Address;
                            DisplayVerse(verse_address);
                        }
                    }
                }
            }
        }
    }
    private void UndoValueNavigationLabel_Click(object sender, EventArgs e)
    {
        UndoGotoVerse();
    }
    private void RedoValueNavigationLabel_Click(object sender, EventArgs e)
    {
        RedoGotoVerse();
    }
