    #region Value Drawings
    ///////////////////////////////////////////////////////////////////////////////
    //public enum DrawingShape { Lines, Spiral, SquareSpiral, Square, HGoldenRect, VGoldenRect, Cube };
    private enum DrawingType { None, LetterValues, WordValues, WordLengths, SearchTerms, AllahWords, WithAllahWords, Primes, AdditivePrimes, NonAdditivePrimes, GeneratePrimeDrawings };
    private DrawingShape m_drawing_shape = DrawingShape.Lines;
    private DrawingType m_current_drawing_type = DrawingType.None;
    private Bitmap m_bitmap = null;
    private void PictureBox_MouseHover(object sender, EventArgs e)
    {
        PictureBox.Focus(); // to enable zooming
    }
    private void PictureBox_MouseMove(object sender, MouseEventArgs e)
    {
        if (m_drawing_shape == DrawingShape.Lines)
        {
            int page_index = e.Y - PictureBox.Image_Y;
            int position = PictureBox.Width - (e.X - PictureBox.Image_X) - 1;

            if (m_client != null)
            {
                List<Verse> verses = GetSearchScopeVerses();
                if (verses != null)
                {
                    List<Page> pages = new List<Page>();
                    if (pages != null)
                    {
                        foreach (Verse verse in verses)
                        {
                            if (!pages.Contains(verse.Page))
                            {
                                pages.Add(verse.Page);
                            }
                        }

                        if ((page_index >= 0) && (page_index < pages.Count))
                        {
                            Page found_page = pages[page_index];

                            List<Letter> page_letters = new List<Letter>();
                            foreach (Verse verse in found_page.Verses)
                            {
                                if (verse != null)
                                {
                                    foreach (Word word in verse.Words)
                                    {
                                        if (word != null)
                                        {
                                            page_letters.AddRange(word.Letters);
                                            page_letters.Add(null); // space
                                        }
                                    }
                                }
                            }

                            if (page_letters != null)
                            {
                                if ((position >= 0) && (position < page_letters.Count))
                                {
                                    m_current_letter = page_letters[position];
                                    if (m_current_letter != null) // not space
                                    {
                                        Word word = m_current_letter.Word;
                                        if (word != null)
                                        {
                                            this.Text = Application.ProductName + " | " + L[l]["Chapter"] + " " + word.Verse.Chapter.SortedNumber;
                                            // diplay word info at application caption
                                            this.Text += SPACE_GAP +
                                            (
                                                word.Verse.Chapter.Name + SPACE_GAP +
                                                L[l]["Verse"] + " " + word.Verse.NumberInChapter + "-" + word.Verse.Number + SPACE_GAP +
                                                L[l]["Word"] + " " + word.NumberInVerse + "-" + word.NumberInChapter + "-" + word.Number + SPACE_GAP +
                                                word.Transliteration + SPACE_GAP +
                                                word.Text + SPACE_GAP +
                                                word.Meaning + SPACE_GAP +
                                                word.Occurrence.ToString() + "/" + word.Frequency.ToString() + SPACE_GAP +
                                                m_client.CalculateValue(word).ToString()
                                            );

                                            ToolTip.SetToolTip(this.PictureBox, GetWordInformation(word));
                                        }
                                        else
                                        {
                                            ToolTip.SetToolTip(this.PictureBox, null);
                                        }
                                    }
                                    else
                                    {
                                        ToolTip.SetToolTip(this.PictureBox, null);
                                    }
                                }
                                else
                                {
                                    ToolTip.SetToolTip(this.PictureBox, null);
                                }
                            }
                            else
                            {
                                ToolTip.SetToolTip(this.PictureBox, null);
                            }
                        }
                        else
                        {
                            ToolTip.SetToolTip(this.PictureBox, null);
                        }
                    }
                }
            }
        }
        else
        {
            ToolTip.SetToolTip(this.PictureBox, null);
        }
    }
    private void PictureBox_DoubleClick(object sender, EventArgs e)
    {
        if (m_current_letter != null)
        {
            Word word = m_current_letter.Word;
            if (word != null)
            {
                try
                {
                    for (int i = 0; i < 3; i++)
                        MainTextBox.TextChanged -= new System.EventHandler(MainTextBox_TextChanged);
                    for (int i = 0; i < 3; i++)
                        MainTextBox.SelectionChanged -= new System.EventHandler(MainTextBox_SelectionChanged);
                    MainTextBox.BeginUpdate();

                    Verse verse = word.Verse;
                    if (verse != null)
                    {
                        GotoVerse(verse);
                        m_found_verses_displayed = false;
                    }
                }
                catch (Exception ex)
                {
                    MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
                }
                finally
                {
                    HidePictureBox();

                    MainTextBox.EndUpdate();
                    MainTextBox.SelectionChanged += new System.EventHandler(MainTextBox_SelectionChanged);
                    MainTextBox.TextChanged += new System.EventHandler(MainTextBox_TextChanged);
                }
            }
        }
    }
    private void ChangeDrawingShapeLabel_Click(object sender, EventArgs e)
    {
        if (ModifierKeys == Keys.Shift)
        {
            GotoPreviousShape();
        }
        else
        {
            GotoNextShape();
        }
        ToolTip.SetToolTip(this.ChangeDrawingShapeLabel, m_drawing_shape.ToString());

        // update graphs as we move between selections
        if (PictureBox.Visible)
        {
            RedrawImage();
        }
    }
    private void GotoNextShape()
    {
        switch (m_drawing_shape)
        {
            case DrawingShape.Lines:
                {
                    m_drawing_shape = DrawingShape.Spiral;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "spiral.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "spiral.png");
                    }
                }
                break;
            case DrawingShape.Spiral:
                {
                    m_drawing_shape = DrawingShape.SquareSpiral;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "squarespiral.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "squarespiral.png");
                    }
                }
                break;
            case DrawingShape.SquareSpiral:
                {
                    m_drawing_shape = DrawingShape.Square;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "square.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "square.png");
                    }
                }
                break;
            case DrawingShape.Square:
                {
                    m_drawing_shape = DrawingShape.HGoldenRect;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "hgoldenrect.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "hgoldenrect.png");
                    }
                }
                break;
            case DrawingShape.HGoldenRect:
                {
                    m_drawing_shape = DrawingShape.VGoldenRect;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "vgoldenrect.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "vgoldenrect.png");
                    }
                }
                break;
            case DrawingShape.VGoldenRect:
                {
                    m_drawing_shape = DrawingShape.Cube;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "cube.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "cube.png");
                    }
                }
                break;
            case DrawingShape.Cube:
                {
                    m_drawing_shape = DrawingShape.Lines;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "lines.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "lines.png");
                    }

                }
                break;
        }
        DrawSearchTermsLabel.Image = ChangeDrawingShapeLabel.Image;
    }
    private void GotoPreviousShape()
    {
        switch (m_drawing_shape)
        {
            case DrawingShape.Lines:
                {
                    m_drawing_shape = DrawingShape.Cube;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "cube.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "cube.png");
                    }
                }
                break;
            case DrawingShape.Spiral:
                {
                    m_drawing_shape = DrawingShape.Lines;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "lines.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "lines.png");
                    }
                }
                break;
            case DrawingShape.SquareSpiral:
                {
                    m_drawing_shape = DrawingShape.Spiral;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "spiral.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "spiral.png");
                    }
                }
                break;
            case DrawingShape.Square:
                {
                    m_drawing_shape = DrawingShape.SquareSpiral;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "squarespiral.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "squarespiral.png");
                    }
                }
                break;
            case DrawingShape.HGoldenRect:
                {
                    m_drawing_shape = DrawingShape.Square;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "square.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "square.png");
                    }
                }
                break;
            case DrawingShape.VGoldenRect:
                {
                    m_drawing_shape = DrawingShape.HGoldenRect;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "hgoldenrect.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "hgoldenrect.png");
                    }
                }
                break;
            case DrawingShape.Cube:
                {
                    m_drawing_shape = DrawingShape.VGoldenRect;
                    if (File.Exists(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "vgoldenrect.png"))
                    {
                        ChangeDrawingShapeLabel.Image = new Bitmap(Globals.IMAGES_FOLDER + Path.DirectorySeparatorChar + "vgoldenrect.png");
                    }
                }
                break;
        }
    }
    private void DrawLetterValuesLabel_Click(object sender, EventArgs e)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                GotoNextShape();

                List<Verse> verses = GetDisplayedVerses();
                if (verses != null)
                {
                    ShowPictureBox();
                    m_current_drawing_type = DrawingType.LetterValues;
                    HeaderLabel.Text = m_current_drawing_type.ToString();
                    HeaderLabel.ForeColor = Numbers.GetNumberTypeColor(0L);
                    HeaderLabel.Refresh();

                    m_bitmap = new Bitmap(PictureBox.Width, PictureBox.Height, PixelFormat.Format24bppRgb);
                    if (m_bitmap != null)
                    {
                        this.PictureBox.Image = m_bitmap;

                        List<long> values = m_client.CalculateLetterValues(verses);
                        if (m_drawing_shape == DrawingShape.Cube)
                        {
                            // cubic-root
                            int width = (int)Math.Floor(Math.Pow(values.Count + 1, 1.0D / 3.0D));
                            int height = width;
                            int layers = width;

                            for (int n = 0; n < layers; n++)
                            {
                                int value_index = n * (width * height);
                                int value_count = (width * height);
                                Drawing.DrawValues(m_bitmap, values.GetRange(value_index, value_count), Color.Pink, m_drawing_shape);
                                PictureBox.Refresh();
                                Thread.Sleep(500);
                            }
                        }
                        else
                        {
                            Drawing.DrawValues(m_bitmap, values, Color.Pink, m_drawing_shape);
                            PictureBox.Refresh();
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
            HidePictureBox();
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
