            //    {
            //        long digit = long.Parse(item.SubItems[2].Text);
            //        position_sum += digit * base10_multiplier;
            //        distance_sum += digit * base19_multiplier;
            //        base10_multiplier *= Numbers.DEFAULT_RADIX;
            //        base19_multiplier *= Numbers.RADIX_NINETEEN;
            //    }
            //}
            //else
            //{
            //    foreach (ListViewItem item in LetterFrequencyListView.Items)
            //    {
            //        long digit = long.Parse(item.SubItems[2].Text);
            //        position_sum += digit * base10_multiplier;
            //        distance_sum += digit * base19_multiplier;
            //        base10_multiplier *= Numbers.DEFAULT_RADIX;
            //        base19_multiplier *= Numbers.RADIX_NINETEEN;
            //    }
            //}

            List<string> texts = new List<string>();
            if (LetterFrequencyListView.SelectedIndices.Count > 0)
            {
                foreach (ListViewItem item in LetterFrequencyListView.SelectedItems)
                {
                    texts.Add(item.SubItems[2].Text);
                }
            }
            else
            {
                foreach (ListViewItem item in LetterFrequencyListView.Items)
                {
                    texts.Add(item.SubItems[2].Text);
                }
            }

            long base_multiplier = 1L;
            for (int i = 0; i < texts.Count; i++)
            {
                long value = 0L;
                if (long.TryParse(texts[i], out value))
                {
                    m_letter_position_sum += value * base_multiplier;
                    base_multiplier *= m_radix;
                }
            }

            base_multiplier = 1L;
            for (int i = texts.Count - 1; i >= 0; i--)
            {
                long value = 0L;
                if (long.TryParse(texts[i], out value))
                {
                    m_letter_distance_sum += value * base_multiplier;
                    base_multiplier *= m_radix;
                }
            }
        }
        else
        {
            if (LetterFrequencyListView.SelectedIndices.Count > 0)
            {
                foreach (ListViewItem item in LetterFrequencyListView.SelectedItems)
                {
                    m_letter_position_sum += long.Parse(item.SubItems[3].Text);
                    m_letter_distance_sum += long.Parse(item.SubItems[4].Text);
                }
            }
            else
            {
                foreach (ListViewItem item in LetterFrequencyListView.Items)
                {
                    m_letter_position_sum += long.Parse(item.SubItems[3].Text);
                    m_letter_distance_sum += long.Parse(item.SubItems[4].Text);
                }
            }
        }

        LetterFrequencyCountLabel.Text = m_letter_count.ToString();
        LetterFrequencyCountLabel.ForeColor = Numbers.GetNumberTypeColor(m_letter_count);
        LetterFrequencyCountLabel.Refresh();

        LetterFrequencySumLabel.Text = m_letter_frequency_sum.ToString();
        LetterFrequencySumLabel.ForeColor = Numbers.GetNumberTypeColor(m_letter_frequency_sum);
        LetterFrequencySumLabel.Refresh();

        LetterFrequencyPositionSumLabel.Text = m_letter_position_sum.ToString();
        LetterFrequencyPositionSumLabel.ForeColor = (Math.Abs(m_letter_position_sum) < 1000000000000L) ? Numbers.GetNumberTypeColor(m_letter_position_sum) : Color.Black;
        LetterFrequencyPositionSumLabel.Refresh();

        LetterFrequencyDistanceSumLabel.Text = m_letter_distance_sum.ToString();
        LetterFrequencyDistanceSumLabel.ForeColor = (Math.Abs(m_letter_distance_sum) < 1000000000000L) ? Numbers.GetNumberTypeColor(m_letter_distance_sum) : Color.Black;
        LetterFrequencyDistanceSumLabel.Refresh();

        if (m_find_by_phrase_letter_frequency)
        {
            ToolTip.SetToolTip(this.LetterFrequencyPositionSumLabel, L[l]["<-- letter frequency concatenation"]);
            ToolTip.SetToolTip(this.LetterFrequencyDistanceSumLabel, L[l]["--> letter frequency concatenation"]);
        }
        else
        {
            ToolTip.SetToolTip(this.LetterFrequencyPositionSumLabel, L[l]["Sum of letter position sums"]);
            ToolTip.SetToolTip(this.LetterFrequencyDistanceSumLabel, L[l]["Sum of letter distance sums"]);
        }
    }

    private void LetterFrequencyInspectLabel_Click(object sender, EventArgs e)
    {
        InspectLetterStatistics();
    }
    private void InspectLetterStatistics()
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (m_client.NumerologySystem != null)
                {
                    string path = DateTime.Now.ToString("yyyy-MM-dd_HH.mm.ss") + "_" + m_client.NumerologySystem.Name + ".txt";

                    string text = m_current_text;
                    if (!String.IsNullOrEmpty(text))
                    {
                        if (m_find_by_phrase_letter_frequency)
                        {
                            m_client.SaveLetterStatistics(path, text, m_current_phrase);
                        }
                        else
                        {
                            m_client.SaveLetterStatistics(path, text, (ModifierKeys == Keys.Control));
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void ValueInspectLabel_Click(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        bool is_value = ValueLabel.Text.EndsWith(L[l]["Value"]);
        InspectValueCalculations(is_value);
    }
    private void InspectValueCalculations(bool is_value)
    {
        this.Cursor = Cursors.WaitCursor;
        try
        {
            if (m_client != null)
            {
                if (m_client.NumerologySystem != null)
                {
                    string path = DateTime.Now.ToString("yyyy-MM-dd_HH.mm.ss") + "_" + m_client.NumerologySystem.Name + ".txt";

                    if (is_value)
                    {
                        m_client.Logging = true;  // log Adjust letter/word/verse/chapter
                        CalculateCurrentValue();  // Calculate value with logging - SLOW but very informative
                    }

                    long value = Radix.Decode(ValueTextBox.Text, m_radix);
                    StringBuilder str = new StringBuilder();

                    if (is_value)
                    {
                        str.AppendLine(m_current_text);
                        str.AppendLine("--------------------------------------------------------------------------------------------------");
                        str.AppendLine();
                        str.AppendLine("Chapters           (" + m_radix + ")\t=\t" + ChaptersTextBox.Text);
                        str.AppendLine("Verses             (" + m_radix + ")\t=\t" + VersesTextBox.Text);
                        str.AppendLine("Words              (" + m_radix + ")\t=\t" + WordsTextBox.Text);
                        str.AppendLine("Letters            (" + m_radix + ")\t=\t" + LettersTextBox.Text);
                    }

                    str.AppendLine();
                    str.AppendLine("Value              (" + m_radix + ")\t=\t" + ValueTextBox.Text);
                    str.AppendLine("Digit Sum          (" + m_radix + ")\t=\t" + DigitSumTextBox.Text);
                    str.AppendLine("Digital Root       (" + m_radix + ")\t=\t" + DigitalRootTextBox.Text);

                    str.AppendLine();
                    str.AppendLine("Prime Factors\t\t=\t" + PrimeFactorsTextBox.Text);
                    str.AppendLine("Prime Factors Sum\t=\t" + PrimeNumbersSumTextBox.Text);

                    str.AppendLine();
                    str.AppendLine("Dimension        \t=\t" + NumberDimensionTextBox.Text);
                    str.AppendLine("Dimension A Index\t=\t" + NthANumberDimensionTextBox.Text);
                    str.AppendLine("Dimension U Index\t=\t" + NthUNumberDimensionTextBox.Text);
                    str.AppendLine("Dimension D Index\t=\t" + NthDNumberDimensionTextBox.Text);
                    str.AppendLine();

                    int nth_number_index = 0;
                    int nth_additive_number_index = 0;
                    int nth_non_additive_number_index = 0;
                    if (Numbers.IsPrime(value))
                    {
                        m_index_type = IndexType.Prime;
                        nth_number_index = Numbers.PrimeIndexOf(value) + 1;
                        nth_additive_number_index = Numbers.AdditivePrimeIndexOf(value) + 1;
                        nth_non_additive_number_index = Numbers.NonAdditivePrimeIndexOf(value) + 1;
                        str.AppendLine("P  Index\t\t=\t" + ((nth_number_index > 0) ? nth_number_index.ToString() : ""));
                        str.AppendLine("AP Index\t\t=\t" + ((nth_additive_number_index > 0) ? nth_additive_number_index.ToString() : ""));
                        str.AppendLine("XP Index\t\t=\t" + ((nth_non_additive_number_index > 0) ? nth_non_additive_number_index.ToString() : ""));
                    }
                    else // any other index type will be treated as IndexNumberType.Composite
                    {
                        m_index_type = IndexType.Composite;
                        nth_number_index = Numbers.CompositeIndexOf(value) + 1;
                        nth_additive_number_index = Numbers.AdditiveCompositeIndexOf(value) + 1;
                        nth_non_additive_number_index = Numbers.NonAdditiveCompositeIndexOf(value) + 1;
                        str.AppendLine("C  Index\t\t=\t" + ((nth_number_index > 0) ? nth_number_index.ToString() : ""));
                        str.AppendLine("AC Index\t\t=\t" + ((nth_additive_number_index > 0) ? nth_additive_number_index.ToString() : ""));
                        str.AppendLine("XC Index\t\t=\t" + ((nth_non_additive_number_index > 0) ? nth_non_additive_number_index.ToString() : ""));
                    }

                    str.AppendLine();
                    int plus1_index = -1;
                    int minus1_index = -1;
                    string plus1_str = "";
                    string minus1_str = "";
                    if (Numbers.IsUnit(value) || Numbers.IsPrime(value))
                    {
                        plus1_index = Numbers.Prime4nPlus1IndexOf(value) + 1;
                        plus1_str = Numbers.Get4nPlus1EqualsSumOfTwoSquares(value);
                        minus1_index = Numbers.Prime4nMinus1IndexOf(value) + 1;
                        minus1_str = Numbers.Get4nMinus1EqualsSumOfTwoSquares(value);
                    }
                    else //if composite
                    {
                        plus1_index = Numbers.Composite4nPlus1IndexOf(value) + 1;
                        plus1_str = Numbers.Get4nPlus1EqualsDiffOfTwoSquares(value);
                        minus1_index = Numbers.Composite4nMinus1IndexOf(value) + 1;
                        minus1_str = Numbers.Get4nMinus1EqualsSumOfTwoSquares(value);
                    }
                    str.AppendLine((plus1_index > 0) ? ("4n+1 Squares\t\t=\t" + plus1_str) : (minus1_index > 0) ? ("4n-1 Squares1\t\t=\t" + minus1_str) : "");
                    str.AppendLine((plus1_index > 0) ? ("4n+1 " + (Numbers.IsComposite(value) ? "Composite" : "Prime") + " Index\t=\t" + plus1_index.ToString()) :
                                  (minus1_index > 0) ? ("4n-1 " + (Numbers.IsComposite(value) ? "Composite" : "Prime") + " Index\t=\t" + minus1_index.ToString()) : "");

                    str.AppendLine();
                    long sum_of_numbers = Numbers.SumOfNumbers(value);
                    str.AppendLine("Sum of Numbers\t\t=\t" + sum_of_numbers + ((ModifierKeys == Keys.Control) ? (" = " + Numbers.GetNumbersString(value)) : ""));
                    long sum_of_number_digit_sums = Numbers.SumOfNumberDigitSums(value);
                    str.AppendLine("Sum of Number DSums\t=\t" + sum_of_number_digit_sums + ((ModifierKeys == Keys.Control) ? (" = " + Numbers.GetNumberDigitSumsString(value)) : ""));
                    long sum_of_number_digital_roots = Numbers.SumNumberDigitalRoots(value);
                    str.AppendLine("Sum of Number DRoots\t=\t" + sum_of_number_digital_roots + ((ModifierKeys == Keys.Control) ? (" = " + Numbers.GetNumberDigitalRootsString(value)) : ""));

                    str.AppendLine();
                    m_number_kind = Numbers.GetNumberKind(value);
                    int number_kind_index = 0;
                    switch (m_number_kind)
                    {
                        case NumberKind.Deficient:
                            {
                                number_kind_index = Numbers.DeficientNumberIndexOf(value) + 1;
                            }
                            break;
                        case NumberKind.Perfect:
                            {
                                number_kind_index = Numbers.PerfectNumberIndexOf(value) + 1;
                            }
                            break;
                        case NumberKind.Abundant:
                            {
                                number_kind_index = Numbers.AbundantNumberIndexOf(value) + 1;
                            }
                            break;
                        default:
                            {
                                number_kind_index = 0;
                            }
                            break;
                    }
                    str.AppendLine(m_number_kind.ToString() + " Index\t\t=\t" + number_kind_index);
                    long sum_of_proper_divisors = Numbers.SumOfProperDivisors(value);
                    str.AppendLine("Sum of Proper Divisors\t=\t" + sum_of_proper_divisors + ((ModifierKeys == Keys.Control) ? (" = " + Numbers.GetProperDivisorsString(value)) : ""));
                    long sum_of_divisors = Numbers.SumOfDivisors(value);
                    str.AppendLine("Sum of Divisors\t\t=\t" + sum_of_divisors + ((ModifierKeys == Keys.Control) ? (" = " + Numbers.GetDivisorsString(value)) : ""));
                    long sum_of_divisor_digit_sums = Numbers.SumOfDivisorDigitSums(value);
                    str.AppendLine("Sum of Divisor DSums\t=\t" + sum_of_divisor_digit_sums + ((ModifierKeys == Keys.Control) ? (" = " + Numbers.GetDivisorDigitSumsString(value)) : ""));
                    long sum_of_divisor_digital_roots = Numbers.SumOfDivisorDigitalRoots(value);
                    str.AppendLine("Sum of Divisor DRoots\t=\t" + sum_of_divisor_digital_roots + ((ModifierKeys == Keys.Control) ? (" = " + Numbers.GetDivisorDigitalRootsString(value)) : ""));

                    str.AppendLine();
                    str.AppendLine("PC Index Chain       \t=\t" + PCIndexChainL2RDashString());
                    str.AppendLine("PC Index Chain Length\t=\t" + IndexChainLength());
                    str.AppendLine("PC Index Chain Sum   \t=\t" + IndexChainSum() + ((ModifierKeys == Keys.Control) ? (" = " + IndexChainSumString()) : ""));
                    string l2r_text = IndexChainL2RString();
                    long l2r_number = 0L;
                    if (long.TryParse(l2r_text, out l2r_number))
                    {
                        str.AppendLine("PC Index Chain L2R\t=\t" + l2r_text + " = " + Numbers.FactorizeToString(l2r_number));
                    }
                    else
                    {
                        str.AppendLine("PC Index Chain L2R\t=\t" + l2r_text);
                    }
                    string r2l_text = IndexChainR2LString();
                    long r2l_number = 0L;
                    if (long.TryParse(r2l_text, out r2l_number))
                    {
                        str.AppendLine("PC Index Chain R2L\t=\t" + r2l_text + " = " + Numbers.FactorizeToString(r2l_number));
                    }
                    else
                    {
                        str.AppendLine("PC Index Chain R2L\t=\t" + r2l_text);
                    }
                    str.AppendLine("PC Index Chain P0C1>\t=\t" + PCIndexChainL2RBinaryString() + " = " + PCIndexChainL2RBinaryValue());
                    str.AppendLine("PC Index Chain P1C0>\t=\t" + CPIndexChainL2RBinaryString() + " = " + CPIndexChainL2RBinaryValue());
                    str.AppendLine("PC Index Chain P0C1<\t=\t" + PCIndexChainR2LBinaryString() + " = " + PCIndexChainR2LBinaryValue());
                    str.AppendLine("PC Index Chain P1C0<\t=\t" + CPIndexChainR2LBinaryString() + " = " + CPIndexChainR2LBinaryValue());

                    str.AppendLine();
                    if (m_client.Book != null)
                    {
                        Verse verse = m_client.Book.GetVerseByNumber((int)value);
                        if (verse != null)
                        {
                            str.AppendLine("VerseByVerseNumber\t=\t" + verse.Address);
                        }
                        else
                        {
                            str.AppendLine("VerseByVerseNumber\t=\t\"---:---\"");
                        }

                        Word word = m_client.Book.GetWordByNumber((int)value);
                        if (word != null)
                        {
                            verse = word.Verse;
                            if (verse != null)
                            {
                                str.AppendLine("VerseByWordNumber\t=\t" + verse.Address);
                            }
                            else
                            {
                                str.AppendLine("VerseByWordNumber\t=\t\"---:---\"");
                            }
                        }

                        Letter letter = m_client.Book.GetLetterByNumber((int)value);
                        if (letter != null)
                        {
                            word = letter.Word;
                            if (word != null)
                            {
                                verse = word.Verse;
                                if (verse != null)
                                {
                                    str.AppendLine("VerseByLetterNumber\t=\t" + verse.Address);
                                }
                                else
                                {
                                    str.AppendLine("VerseByLetterNumber\t=\t\"---:---\"");
                                }
                            }
                        }
                    }
                    str.AppendLine("---------------------------------------------------------------------------------------------------------------------------");
                    str.AppendLine();

                    string interesting_sums = value.FindInterestingSums(INTERESTINGX_COUNT);
                    if (!String.IsNullOrEmpty(interesting_sums))
                    {
                        str.AppendLine("===============================");
                        str.AppendLine("Interesting Numbers: " + value);
                        str.AppendLine("===============================");
                        str.Append(interesting_sums);
                        str.AppendLine("===============================");
                    }

                    m_client.SaveValueCalculations(path, str.ToString(), is_value);

                    m_client.Logging = false;   // return to FAST calculations without logging
                }
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(ex.Message + ".\r\n\r\n" + ex.StackTrace, Application.ProductName);
        }
        finally
        {
            this.Cursor = Cursors.Default;
        }
    }
    private void LetterFrequencyWithDiacriticsCheckBox_CheckStateChanged(object sender, EventArgs e)
    {
        if ((L == null) || (!L.ContainsKey(l)) || (L[l].Count == 0))
            return;

        if (m_client != null)
        {
            if (m_client.Book != null)
            {
                switch (LetterFrequencyWithDiacriticsCheckBox.CheckState)
                {
                    case CheckState.Checked:
                        {
                            m_include_diacritics = true;
                        }
                        break;
                    case CheckState.Indeterminate:
                        {
                            m_include_diacritics = null;
                        }
                        break;
                    case CheckState.Unchecked:
                        {
                            m_include_diacritics = false;
                        }
                        break;
                }

                if (m_include_diacritics == true)
                {
                    ToolTip.SetToolTip(this.LetterFrequencyWithDiacriticsCheckBox, L[l]["with diacritics"]);
                }
                else if (m_include_diacritics == null)
                {
                    ToolTip.SetToolTip(this.LetterFrequencyWithDiacriticsCheckBox, L[l]["diacritics only"]);
                }
                else if (m_include_diacritics == false)
                {
                    ToolTip.SetToolTip(this.LetterFrequencyWithDiacriticsCheckBox, L[l]["no diacritics"]);
                }

                BuildLetterFrequencies();
                DisplayLetterFrequencies();

                if (PictureBox.Visible)
                {
                    if (m_current_drawing_type == DrawingType.SearchTerms)
                    {
                        RedrawImage();
                    }
                }
            }
        }
    }
    private void StatisticsControls_Enter(object sender, EventArgs e)
    {
        if (sender == NthNumberTextBox)
        {
            m_index_subtype = IndexSubType.Any;
        }
        else if (sender == NthAdditiveNumberTextBox)
        {
            m_index_subtype = IndexSubType.Additive;
        }
        else if (sender == NthNonAdditiveNumberTextBox)
        {
            m_index_subtype = IndexSubType.NonAdditive;
        }
        else
        {
            // ignore
        }

        SearchGroupBox_Leave(null, null);
    }
